// Dungeon & Stone interface — single-file bundle.
// Yumina's compiler rewrites local named imports into dynamic import()
// calls, and import() cannot take a destructuring pattern — that is the
// "Unexpected token '{'" error. Everything lives in one module instead.
// Duplicate helpers across the old files were suffixed per source file.

// ==== theme.tsx =================================================
// Dungeon & Stone — grounded material interface for physically lived Rafdonia.
// Charcoal iron, aged paper, leather, stone; restrained brass and blood.
// No arcade glow, no neon, no scanlines. Every token below stays a 6-digit
// hex because screens across the file append alpha suffixes ("88", "99").
var C = {
  void: "#0c0a09",
  panel: "#16130f",
  panelUp: "#221d17",
  rule: "#3a3128",
  ruleLit: "#6e5a3e",
  bone: "#ece3cf",
  boneDim: "#b3a68c",
  boneFaint: "#7d715c",
  blood: "#8e2a22",
  bloodLit: "#d2493a",
  brass: "#b8893b",
  brassLit: "#e2b865",
  glass: "rgba(255,255,255,0.03)",
};
// Body/data face. Palatino-class serif: lining numerals, legible at small
// sizes, native on iOS/macOS (Palatino) and Windows (Palatino Linotype).
var MONO =
  '"Palatino","Palatino Linotype","Book Antiqua","Iowan Old Style",Georgia,"Lora",serif';
// Engraved display capitals for titles, tabs and buttons.
var DISPLAY =
  '"Cinzel","Trajan Pro","Cormorant SC","Palatino","Palatino Linotype",Georgia,"Lora",serif';
// Prose face for descriptions and flavour at readable sizes.
var PROSE =
  '"EB Garamond","Cormorant Garamond","Palatino","Palatino Linotype",Georgia,"Lora",serif';
var R = { sm: 4, md: 7, lg: 12 };
var SH = {
  panel: "0 6px 18px rgba(0,0,0,0.5), inset 0 1px 0 rgba(255,226,170,0.05), inset 0 0 0 1px rgba(0,0,0,0.55)",
  raised: "0 10px 26px rgba(0,0,0,0.6), inset 0 1px 0 rgba(255,226,170,0.07), inset 0 0 0 1px rgba(0,0,0,0.6)",
  glow: "0 0 0 1px rgba(226,184,101,0.35), 0 0 14px rgba(226,184,101,0.18), 0 4px 14px rgba(0,0,0,0.5)",
};

// ---- art slots ---------------------------------------------------------
// Paste hosted image URLs here to replace the drawn sigils with painted art.
// Empty strings fall back to the engraved emblems, so nothing breaks.
var ART = {
  // Hosted https image URLs. Suggested shapes in brackets.
  portrait: "",          // player portrait — HUD + Kit column [2:3, e.g. 600x900]
  splash: "",            // creation backdrop / prologue [16:9]
  floorScene: "",        // HUD place + time box backdrop [3:1 or 16:9]
  races: {               // vessel cards [3:4]
    Barbarian: "", Human: "", Dwarf: "", Elf: "", Beastman: "",
  },
  cards: {               // creation summary cards, shown on the right side [16:9]
    origin: "", circumstances: "", path: "", possessions: "",
  },
};

// ---- materials ---------------------------------------------------------
// Grain is an inline SVG noise tile — no network, no image host.
var GRAIN =
  "url(\"data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'>" +
  "<filter id='g'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2' stitchTiles='stitch'/>" +
  "<feColorMatrix values='0 0 0 0 0.92  0 0 0 0 0.82  0 0 0 0 0.62  0 0 0 0.075 0'/></filter>" +
  "<rect width='100%' height='100%' filter='url(%23g)'/></svg>\")";
var MAT = {
  iron: GRAIN + ",radial-gradient(130% 90% at 50% 0%,rgba(255,214,150,0.055),transparent 62%),linear-gradient(180deg,#1b1713 0%,#120f0c 100%)",
  ironUp: GRAIN + ",linear-gradient(180deg,#2a241c 0%,#1a1611 100%)",
  leather: GRAIN + ",radial-gradient(120% 120% at 20% 0%,rgba(140,70,40,0.10),transparent 60%),linear-gradient(180deg,#1d1712 0%,#130f0b 100%)",
  parchment: GRAIN + ",radial-gradient(140% 110% at 50% 10%,rgba(214,176,112,0.14),transparent 65%),linear-gradient(180deg,#221c13 0%,#15110b 100%)",
  ledger: GRAIN + ",repeating-linear-gradient(0deg,rgba(226,184,101,0.035) 0 1px,transparent 1px 26px),linear-gradient(180deg,#201a12 0%,#14100b 100%)",
  blood: GRAIN + ",radial-gradient(120% 120% at 50% 0%,rgba(210,73,58,0.16),transparent 60%),linear-gradient(180deg,#1f1210 0%,#120b09 100%)",
  backdrop: GRAIN + ",radial-gradient(120% 60% at 50% -10%,rgba(190,110,50,0.14),transparent 60%),radial-gradient(90% 70% at 50% 110%,rgba(120,30,20,0.12),transparent 60%),linear-gradient(180deg,#0f0c0a 0%,#0a0807 100%)",
};
var BTN_BLOOD = "linear-gradient(180deg,#a8362b 0%,#7a221b 55%,#5e1813 100%)";
var BTN_IRON = "linear-gradient(180deg,#2c261e 0%,#1c1813 100%)";

// Shared CSS for hover/focus states, fonts and scrollbars — inline styles
// can't do :hover, so interactive primitives carry a small className.
var GLOBAL_STYLE =
  "@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700&family=EB+Garamond:ital,wght@0,400;0,500;1,400&display=swap');" +
  ".ds-root{font-variant-numeric:lining-nums;-webkit-font-smoothing:antialiased;}" +
  ".ds-btn{transition:background-color .15s ease,border-color .15s ease,box-shadow .2s ease,transform .1s ease,filter .15s ease;-webkit-tap-highlight-color:transparent;}" +
  ".ds-btn:hover:not(:disabled){filter:brightness(1.15);}" +
  ".ds-btn:active:not(:disabled){transform:scale(0.975);}" +
  ".ds-panel{transition:border-color .2s ease,box-shadow .2s ease;}" +
  ".ds-row{transition:background-color .15s ease,box-shadow .15s ease;}" +
  ".ds-row:hover{background-color:rgba(226,184,101,0.05);}" +
  ".ds-field:focus{border-color:" + C.brass + " !important;box-shadow:0 0 0 1px " + C.brass + "55,0 0 12px " + C.brass + "22;}" +
  ".ds-field::placeholder{color:" + C.boneFaint + ";font-style:italic;}" +
  ".ds-scroll::-webkit-scrollbar{width:8px;height:8px;}" +
  ".ds-scroll::-webkit-scrollbar-track{background:transparent;}" +
  ".ds-scroll::-webkit-scrollbar-thumb{background:" + C.rule + ";border-radius:8px;}" +
  ".ds-scroll::-webkit-scrollbar-thumb:hover{background:" + C.ruleLit + ";}" +
  ".ds-rail{scrollbar-width:none;}.ds-rail::-webkit-scrollbar{display:none;}" +
  "@keyframes dsIn{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:none;}}" +
  "@keyframes dsEmber{0%,100%{box-shadow:0 0 0 1px rgba(210,73,58,0.55),0 0 14px rgba(210,73,58,0.35);}50%{box-shadow:0 0 0 1px rgba(210,73,58,0.8),0 0 22px rgba(210,73,58,0.55);}}" +
  ".ds-in{animation:dsIn .22s ease both;}" +
  ".ds-step-label{display:none;}.ds-step-on .ds-step-label{display:block;}" +
  "@media (min-width:620px){.ds-step-label{display:block;}}" +
  ".ds-wide-only{display:none;}@media (min-width:620px){.ds-wide-only{display:block;}}" +
  ".ds-hide-narrow{display:none;}@media (min-width:460px){.ds-hide-narrow{display:inline-flex;}}" +
  ".ds-split{display:grid;grid-template-columns:minmax(0,1fr);gap:12px;}" +
  "@media (min-width:620px){.ds-split{grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);}}" +
  ".ds-vessel{display:grid;grid-template-columns:minmax(0,1fr);gap:8px;}" +
  "@media (min-width:620px){.ds-vessel{grid-template-columns:38% minmax(0,1fr);align-items:stretch;}}" +
  ".ds-kitgrid{display:grid;grid-template-columns:108px minmax(0,1fr);grid-template-areas:'p a' 'p l' 'list list';gap:9px;align-items:stretch;}" +
  "@media (min-width:460px){.ds-kitgrid{grid-template-columns:34% minmax(0,1fr);grid-template-areas:'p a' 'p l' 'p list';}}";

// --- icons ------------------------------------------------------------
// One stroke vocabulary for the whole interface. 24-unit grid.
var ICON_PATHS = {
  sheet: "M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8z M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7",
