function Icon(props) {
  var d = ICON_PATHS[props.name] || ICON_PATHS.box;
  var s = props.size || 18;
  return (
    <svg width={s} height={s} viewBox="0 0 24 24" style={{ display: "block", flexShrink: 0, overflow: "visible" }}
      aria-hidden="true">
      <path d={d} fill={props.fill || "none"} stroke={props.color || "currentColor"}
        strokeWidth={props.stroke || 1.6} strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

// The item's silhouette, read from its name/type/slot. Purely presentational.
function glyphFor(it) {
  if (!it) return "box";
  // The storage slot id "backpack" means "not worn", not "is a backpack" —
  // leave it out or every carried object would draw as a pack.
  var slotTxt = String(it.slot || "") === "backpack" ? "" : String(it.slot || "");
  var n = (String(it.name || "") + " " + String(it.type || "") + " " + slotTxt).toLowerCase();
  function has(re) { return re.test(n); }
  if (has(/\b(sword|blade|sabre|saber|falchion|rapier|scimitar)\b/)) return "sword";
  if (has(/\b(knife|dagger|dirk|stiletto)\b/)) return "knife";
  if (has(/\b(axe|hatchet|cleaver)\b/)) return "axe";
  if (has(/\b(mace|club|hammer|maul|flail|morningstar|cudgel)\b/)) return "mace";
  if (has(/\b(spear|pike|halberd|glaive|lance|polearm|javelin)\b/)) return "spear";
  if (has(/\b(bow|crossbow|longbow|shortbow)\b/)) return "bow";
  if (has(/\b(arrow|arrows|bolt|bolts|quiver)\b/)) return "pierce";
  if (has(/\b(shield|buckler)\b/)) return "shield";
  if (has(/\b(helm|helmet|coif|cap|hood|hat|circlet)\b/)) return "helmet";
  if (has(/\b(boot|boots|shoe|shoes|sandal|sandals|greave|greaves)\b/)) return "boot";
  if (has(/\b(glove|gloves|gauntlet|gauntlets|mitt|mitts)\b/)) return "glove";
  if (has(/\b(backpack|rucksack|pack frame)\b/)) return "backpack";
  if (has(/\b(bag|pouch|purse|satchel|sack)\b/)) return "pouch";
  if (has(/\b(rope|cord|line)\b/)) return "rope";
  if (has(/\b(waterskin|flask|canteen|bottle|water)\b/)) return "flask";
  if (has(/\b(bread|loaf|ration|rations|jerky|meat|food|fruit|cheese|meal|stew)\b/)) return "bread";
  if (has(/\b(potion|elixir|tonic|salve|remedy|draught)\b/)) return "potion";
  if (has(/\b(torch|lantern|lamp|candle)\b/)) return "torch";
  if (has(/\b(ring|amulet|necklace|talisman|pendant|charm)\b/)) return "ring";
  if (has(/\b(scroll|map|letter|note|book|tome|writ)\b/)) return "scroll";
  if (has(/\b(stone|crystal|gem|core)\b/)) return "gem";
  if (has(/\b(mail|plate|gambeson|cuirass|armou?r|brigandine|jack|hauberk|breastplate)\b/)) return "armor";
  if (has(/\b(wrap|shirt|tunic|cloak|coat|robe|apron|trousers|hose|clothes|garment|vest|cape|mantle)\b/)) return "tunic";
  if (has(/\bweapon\b/)) return "sword";
  if (has(/\b(armour|armor)\b/)) return "armor";
  return "box";
}

// A small inset tile holding an item glyph.
function ItemTile(props) {
  var s = props.size || 30;
  var lit = props.lit;
  return (
    <div style={{
      width: s, height: s, flexShrink: 0, borderRadius: R.sm,
      display: "flex", alignItems: "center", justifyContent: "center",
      background: "radial-gradient(circle at 50% 35%,#2d261d,#15110d 75%)",
      border: "1px solid " + (lit ? C.brass : C.rule),
      boxShadow: "inset 0 1px 3px rgba(0,0,0,0.7)" + (lit ? ",0 0 8px " + C.brass + "33" : ""),
      color: lit ? C.brassLit : C.boneDim,
    }}>
      <Icon name={props.glyph || glyphFor(props.item)} size={Math.round(s * 0.6)} stroke={1.5} />
    </div>
  );
}

// Round medallion: painted art when an URL exists, engraved sigil otherwise.
function Medallion(props) {
  var s = props.size || 48;
  var ring = props.ring || C.brass;
  var img = props.src;
  return (
