  var seed = props.seed || 7;
  var hue = [18, 24, 12, 30, 8, 20][seed % 6];
  // Deterministic skyline from the seed.
  var towers = [];
  var x = 0, k = seed * 9301 + 49297;
  function rnd() { k = (k * 9301 + 49297) % 233280; return k / 233280; }
  while (x < 400) {
    var w = 14 + Math.floor(rnd() * 26);
    var th = 18 + Math.floor(rnd() * (h * 0.55));
    towers.push([x, w, th, rnd() > 0.72]);
