    if (t[3]) d += " L" + (t[0] + t[1] / 2 + 3) + " " + (top - 14) + " L" + (t[0] + t[1] / 2 - 3) + " " + (top - 14);
    d += " L" + (t[0] + t[1]) + " " + h;
