    <div
      style={{
        height: h,
        background: "linear-gradient(180deg,hsl(" + hue + ",35%,9%) 0%,hsl(" + hue + ",55%,20%) 62%,hsl(" + (hue + 8) + ",70%,32%) 100%)",
