    if (!validNumber(no)) {
      invalid.push(x.name || "unnamed");
      items.push(Object.assign({}, x, { disputed: "unnumbered" }));
      if (x.disputed !== "unnumbered") changed = true;
      return;
    }

    var n = Math.floor(num_items(no, 0));
    var k = ledgerKey(n);

    // The same physical number cannot be in your pockets twice.
    if (seen[k]) {
      duplicates.push(n);
      changed = true;
      return;
    }
    seen[k] = true;

    var status = claimStatus(ledger, n, who);
    var entry = ledgerEntry(ledger, n);
    var next = Object.assign({}, x, { no: n });

    // Canon name wins over whatever the narration called it in the moment.
    if (entry && entry.name && !x.name) next.name = entry.name;

    if (status === "conflict") {
      next.disputed = "held-elsewhere";
      next.disputedBy = ledgerHolder(ledger, n);
      next.equipped = false;                     // contested kit cannot be worn
      conflicts.push({ no: n, name: next.name, holder: next.disputedBy });
      if (x.disputed !== "held-elsewhere") changed = true;
    } else if (x.disputed) {
      delete next.disputed;
      delete next.disputedBy;
      changed = true;
    }

    items.push(next);
  });

  // One talisman at a time, enforced on read as well as on click.
  var wornTalisman = false;
  items = items.map(function (x) {
    if (x.equipped && x.slot === "talisman") {
      if (wornTalisman) { changed = true; return Object.assign({}, x, { equipped: false }); }
      wornTalisman = true;
    }
    return x;
  });

  return {
    items: items,
    duplicates: duplicates,
    conflicts: conflicts,
    invalid: invalid,
    changed: changed,
  };
}

// ==== combat.tsx ================================================
// Shortcuts, not a move list. Violence here is fast, ugly and resolved by the
// GM — these buttons only phrase an intent the player could have typed.

function obj_combat(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }
function arr_combat(v) { return Array.isArray(v) ? v : []; }
function num_combat(v, d) { return typeof v === "number" ? v : d; }

// Enemy condition as far as eyes can judge it. Never a health bar on something
// the interface has no right to measure.
function look(e) {
  var w = String(e.condition || "").toLowerCase();
  if (w) return w;
  return "still standing";
}

var ACTS = [
  ["STRIKE", "I commit to an attack, and I take the opening I actually have."],
  ["GUARD", "I cover up and give ground, keeping my guard between us."],
  ["SKILL", "I use what my essence and training give me, whatever fits this moment."],
  ["ITEM", "I go for something I am carrying."],
  ["SHIFT", "I break the distance and reposition."],
  ["RUN", "I disengage and run, and I do not look back."],
];
function Combat(props) {
  var api = useYumina();
  var v = api.variables || {};
  var enc = obj_combat(v["encounter-state"]);

  var c = React.useState(false);
  var collapsed = c[0], setCollapsed = c[1];

  // A new encounter always opens expanded. A panel collapsed during the last
  // fight must never hide the next one.
  var sig = String(enc.active === true) + "|" + String(enc.environment || "") + "|" +
    arr_combat(enc.enemies).map(function (e) { return e && e.name; }).join(",");
  React.useEffect(function () { setCollapsed(false); }, [sig]);

  if (enc.active !== true) return null;

  var cond = num_combat(v["condition"], 100);
  var hurt = arr_combat(v["injuries"]);
  var enemies = arr_combat(enc.enemies);
  // Party authority is the persistent party roster. encounter-state.allies is only
  // the narrator's visible condition overlay for other temporary allies.
  var partyRoster = arr_combat(v["party"]).map(function(m,i){ return normalizePartyCombatMember(m,i); });
  var encounterAllies = arr_combat(enc.allies);
  var party = partyRoster.map(function(m){
    var seen=encounterAllies.find(function(a){return a && String(a.name||"")===String(m.name||"");});
    return Object.assign({},m,{conditionBand:(seen&&seen.conditionBand)||partyConditionBand(m.combat)});
  });
  var stam = num_combat(v["stamina"], 100);
  var spirit = num_combat(v["spirit"], 0);
  var manaNow = num_combat(v["spirit-current"], spirit);
  var mp = spirit > 0 ? Math.min(100, Math.round((manaNow / spirit) * 100)) : 0;

  var combatInventory = normalizeList(v["inventory"]);
  var equippedWeapons = combatInventory.filter(function (it) {
    return it && it.equipped === true &&
      (it.slot === "main-hand" || it.slot === "off-hand") &&
      weaponGameplayProfile(it);
  });
  var mainWeaponItem = null;
  for (var wi = 0; wi < equippedWeapons.length; wi++) {
    if (equippedWeapons[wi].slot === "main-hand") { mainWeaponItem = equippedWeapons[wi]; break; }
  }
  if (!mainWeaponItem && equippedWeapons.length) mainWeaponItem = equippedWeapons[0];
  var mainWeaponProfile = mainWeaponItem ? weaponGameplayProfile(mainWeaponItem) : null;
  var equippedArmorProfiles = combatInventory
    .filter(function (it) { return it && it.equipped === true && armorGameplayProfile(it); })
    .map(function (it) { return armorGameplayProfile(it); });
  var equippedShieldProfiles = equippedArmorProfiles.filter(function (a) {
    return a && a.shieldType;
  });
  if (!mainWeaponProfile) mainWeaponProfile = Object.assign({}, WEAPON_ARCHETYPES_items.fist, {
    id:"unarmed", name:"unarmed", archetype:"fist", className:"Unarmed",
    armorPenetration:0, ammoType:"", ranged:false, reloadCost:0,
  });

  function hiddenEquipmentContext(actionKind) {
    var wp = mainWeaponProfile;
    var payload = {
      action: actionKind,
      weapon: wp,
      armor: equippedArmorProfiles,
      shields: equippedShieldProfiles,
      staminaBefore: num_combat(v["stamina"], 100),
      strength: num_combat(obj_combat(v["substats"]).strength, 0),
      flexibility: num_combat(obj_combat(v["substats"]).flexibility, 0),
      accuracy: num_combat(obj_combat(v["substats"]).accuracy, 0),
      vision: num_combat(obj_combat(v["substats"]).vision, 0),
      injuries: arr_combat(v["injuries"]),
      carryState: physicalCarryProfile(v, combatInventory),
      accessibleItems: combatInventory.filter(function(it){var a=itemAccessTier(it,combatInventory);return a==="immediate"||a==="quick"||a==="ready";})
        .map(function(it){return {id:it.id,name:it.name,access:itemAccessTier(it,combatInventory)};}),
    };
    api.injectContext(
      "[UI INTERNAL — DO NOT RECITE THESE NUMBERS] Equipped combat profile: " +
      JSON.stringify(payload) +
      ". Resolve the physical action using these actual equipment/body inputs. " +
      "Resolve hit region, relevant armor layers and shield interception from these actual objects. Describe only what happens in-world; do not make the player state or repeat hidden equipment numbers.",
      { role:"system" }
    );
  }

  function act(line, kind) {
    var k = kind || "action";
    hiddenEquipmentContext(k);

    // Every committed player combat action advances one companion action cycle.
    // Companion resource costs and support healing are deterministic here; attack
    // impact still resolves against the physical scene because enemies currently
    // use condition bands rather than hidden numeric HP.
    var partyTurn=partyCombatPacket(partyRoster,enemies,k);
    if(partyTurn.roster.length){
      api.setVariable("party",partyTurn.roster);
      api.injectContext(
        "[UI INTERNAL — PARTY COMBAT TURN] " + JSON.stringify(partyTurn.packets) +
        ". These companions are physically present and acted this exchange. Their resource costs/healing are already applied. " +
        "Resolve their attacks, blocks, support, control, positioning, injuries, and enemy reactions as part of the SAME combat exchange. " +
        "Do not ignore them, do not make the player command every action, and do not charge their resources again. " +
        "An attack packet is not an automatic hit: use rank, role, actual skills/equipment if known, enemy capability, terrain, and established scene state.",
        {role:"system"}
      );
    }

    // Button STRIKE pays the equipped weapon's physical stamina cost immediately.
    // This is not a hit/damage roll; the narrator still decides whether the attack
    // lands from the actual scene, but it cannot ignore the weapon's burden.
    if (k === "strike") {
      var carryNow=physicalCarryProfile(v,combatInventory);
      var cost=Math.max(0,num_combat(mainWeaponProfile.staminaCost,0))*carryNow.staminaMult;
      cost=Math.max(0,Math.round(cost));
      var now=Math.max(0,num_combat(v["stamina"],100));
      if(cost>0)api.setVariable("stamina",Math.max(0,now-cost));
    } else if (k === "guard") {
      var guardCost = 2;
      equippedArmorProfiles.forEach(function (a) {
        if (a.stamina < 0) guardCost += Math.abs(a.stamina);
      });
      equippedShieldProfiles.forEach(function (s) {
        if (s.block > 0) guardCost += Math.max(0, Math.round((s.weight || 0) / 8));
      });
      var guardNow = Math.max(0, num_combat(v["stamina"], 100));
      api.setVariable("stamina", Math.max(0, guardNow - guardCost));
    }
    api.sendMessage(line);
  }

  // If the GM forgets to close a finished fight, the player is not stuck with a
  // panel that lies. Standing down is a claim, not a fact — the GM corrects it.
  function standDown() {
    api.setVariable("encounter-state", { active: false });
    api.injectContext(
      "[UI] The player treated this encounter as finished and closed the combat panel. " +
      "If anything hostile is still on its feet, say so plainly and reopen it."
    );
  }

  if (collapsed) {
    return (
      <button
        className="ds-btn"
        onClick={function () { setCollapsed(false); }}
        style={{
          position: "absolute", right: 8, top: 8, zIndex: 33,
          fontFamily: MONO, fontSize: 10, letterSpacing: "0.1em",
          padding: "7px 12px", minHeight: 34,
          borderRadius: R.md,
          background: C.blood, color: "#f5f0e2",
          border: "1px solid " + C.bloodLit, cursor: "pointer",
          boxShadow: "0 3px 14px rgba(178,59,59,0.4)",
        }}
      >
        ▸ ENGAGED
      </button>
    );
  }

  return (
    <div className="ds-scroll" style={{
      // Anchored to the TOP. The text field below it must never be covered —
      // typing "I kick the table over" has to stay possible mid-fight.
          // Capped well short of the bottom edge. Typing "I kick the table over"
          // has to stay possible on a phone with four things in the water.
          position: "absolute", left: 8, right: 8, top: 8, zIndex: 33,
          maxHeight: "55%", overflowY: "auto",
      background: C.panel,
      borderRadius: R.lg,
      border: "1px solid " + C.blood,
      boxShadow: SH.raised + ", 0 0 22px rgba(178,59,59,0.18)",
      fontFamily: MONO, color: C.bone,
    }}>
      {/* header */}
      <div style={{
        display: "flex", alignItems: "center", gap: 8,
        padding: "7px 12px",
        background: "linear-gradient(180deg, rgba(178,59,59,0.22), rgba(178,59,59,0.06))",
        borderBottom: "1px solid " + C.rule,
      }}>
        <span style={{ fontSize: 10, letterSpacing: "0.2em", color: C.bloodLit, fontWeight: 600 }}>
          ● ENGAGED
        </span>
        <span style={{ fontSize: 9, color: C.boneFaint }}>
          {enc.environment || (num_combat(v["current-floor"], 0) > 0
            ? "floor " + num_combat(v["current-floor"], 0)
            : String(v["location"] || ""))}
        </span>
        <span style={{ flex: 1 }} />
        <button
          className="ds-btn"
          onClick={function () { setCollapsed(true); }}
          style={{
            fontFamily: MONO, fontSize: 10, padding: "3px 8px",
            borderRadius: R.sm,
            background: C.panelUp, color: C.boneFaint,
            border: "1px solid " + C.rule, cursor: "pointer",
          }}
        >
          ▾
        </button>
      </div>

      {/* your body */}
      <div style={{
        display: "flex", gap: 8, padding: "6px 8px", flexWrap: "wrap",
        borderBottom: "1px solid " + C.rule,
      }}>
        <div style={{ flex: "1 1 88px", minWidth: 78 }}>
          <Band label="BODY" pct={cond} color={cond < 25 ? C.bloodLit : C.blood} />
        </div>
        <div style={{ flex: "1 1 88px", minWidth: 78 }}>
          <Band label="SPRT" pct={mp} color={C.brass} />
        </div>
        <div style={{ flex: "1 1 88px", minWidth: 78 }}>
          <Band label="STAM" pct={stam} color={C.ruleLit} />
        </div>
      </div>

      {hurt.length ? (
        <div style={{ padding: "5px 8px 0" }}>
          {hurt.slice(0, 3).map(function (x, i) {
            return (
              <Chip key={i} color={C.bloodLit} border={C.blood}>
                {x && x.what ? x.what : String(x)}
              </Chip>
            );
          })}
        </div>
      ) : null}

      {/* what is in front of you */}
      <div style={{ padding: "6px 8px" }}>
        {enemies.length === 0 ? (
          <Empty>Nothing you can see clearly yet.</Empty>
        ) : (
          enemies.map(function (e, i) {
            return (
              <div
                key={i}
                style={{
                  display: "flex", alignItems: "baseline", gap: 6,
                  padding: "3px 0",
                  borderBottom: i < enemies.length - 1 ? "1px dotted " + C.rule : "none",
                }}
              >
                <span style={{ fontSize: 11 }}>{e.name || "something"}</span>
                {e.count && num_combat(e.count, 1) > 1 ? (
                  <span style={{ fontSize: 10, color: C.boneFaint }}>×{e.count}</span>
                ) : null}
                <span style={{ flex: 1 }} />
                <span style={{ fontSize: 10, color: C.boneDim }}>{look(e)}</span>
              </div>
            );
          })
        )}

        {party.length ? (
          <div style={{ marginTop: 6, paddingTop: 5, borderTop: "1px solid " + C.rule }}>
            <div style={{ fontSize: 9, letterSpacing: "0.16em", color: C.boneFaint }}>
              WITH YOU
            </div>
            <div style={{ marginTop: 4 }}>
              {party.map(function (p, i) {
                return (
                  <Chip key={i}>
                    {(p.name || String(p)) + (p.condition ? " · " + p.condition : "")}
                  </Chip>
                );
              })}
            </div>
          </div>
        ) : null}
      </div>

      <div style={{
        padding:"5px 8px", borderTop:"1px solid " + C.rule,
        fontSize:9, color:C.boneFaint, display:"flex", gap:8, flexWrap:"wrap"
      }}>
        <span style={{color:C.boneDim}}>{mainWeaponProfile.name}</span>
        <span>{mainWeaponProfile.className}</span>
        <span>reach {mainWeaponProfile.reach}</span>
        <span>stamina {mainWeaponProfile.staminaCost}</span>
        <span>armor {equippedArmorProfiles.length}</span>
        {equippedShieldProfiles.length?<span>shield {equippedShieldProfiles[0].className}</span>:null}
      </div>

      {/* shortcuts */}
      <div style={{
        display: "grid",
        gridTemplateColumns: "repeat(3,1fr)",
        gap: 4, padding: 6,
        borderTop: "1px solid " + C.rule,
      }}>
        {ACTS.map(function (a) {
          return (
            <button
              key={a[0]}
              className="ds-btn"
              onClick={function () { act(a[1], String(a[0] || "").toLowerCase()); }}
              style={{
                fontFamily: MONO, fontSize: 10, letterSpacing: "0.1em",
                padding: "9px 0", minHeight: 38,
                borderRadius: R.sm,
                background: a[0] === "RUN" ? C.void : C.panelUp,
                color: a[0] === "RUN" ? C.boneDim : C.bone,
                border: "1px solid " + (a[0] === "RUN" ? C.rule : C.ruleLit),
                cursor: "pointer",
              }}
            >
              {a[0]}
            </button>
          );
        })}
      </div>

        <div style={{ display: "flex", gap: 6, padding: "0 6px 6px" }}>
          <button
            onClick={standDown}
            style={{
              flex: 1, fontFamily: MONO, fontSize: 9, letterSpacing: "0.14em",
              padding: "6px 0", minHeight: 30,
              background: "transparent", color: C.boneFaint,
              border: "1px solid " + C.rule, cursor: "pointer",
            }}
          >
            STAND DOWN
          </button>
        </div>

        <div style={{ padding: "0 8px 6px" }}>
          <Empty>
            Or describe what you actually do. Kicking the table over is a real
            option and always was.
          </Empty>
        </div>
    </div>
  );
}

// ==== creation.tsx ==============================================
