  };

  var helpS = React.useState(false);
  var helpOn = helpS[0], setHelpOn = helpS[1];
  var STEPS = flow.map(function (k2) { return STEP_META[k2]; });

  function reachable(i) {
    for (var j = 0; j < i - 1; j++) if (!okKey[flow[j]]) return false;
    return true;
  }
  var BLOCK_HINT = {
    origin: "Choose how well you remember the game.",
    vessel: "Choose the body you woke in.",
    identity: "The body needs a name.",
    circumstances: "Choose the body's social circumstances.",
    body: "Spend all " + POOL + " points.",
    track: "Choose where this body begins.",
    weapon: "Choose one weapon from the chief's rack.",
    possessions: "Choose what is physically on you.",
  };
  var BG_ICON = {
    "Independent": "sheet", "Laborer": "strength", "Trade Worker": "fence", "Temple-Connected": "spirit",
    "Clan-Connected": "party", "Smith or Builder": "fence", "Gnome Tree Farmhand": "strength",
    "Spirit-arts Trained": "spirit", "Livestock Worker": "strength",
  };
  var WEAPON_ICON = {
    sword: "sword", greatsword: "sword", mace: "mace", flail: "mace", spear: "spear", harpoon: "spear",
    greataxe: "axe", scythe: "spear", hammer: "mace", shield: "shield",
  };
  var TRACK_INTRO = {
    Human: "A track is where this body begins, not a destiny. Aura is not on this list: about one body in a hundred has the talent, and it is found by trying, never chosen.",
    Dwarf: "The Blessing of Arms is already yours. This is what the body did with it.",
    Elf: "A contract is signed with a spirit, not learned. Your first is listed here, and an elf can sign more later. Nothing on this list is a lock.",
    Beastman: "The Soul Tree chooses. You do not. Nothing on this list can buy or promise a contract; a good line only makes it more likely to notice you.",
  };

  function Stepper() {
    return (
      <div style={{ position: "relative", padding: "4px 2px 2px" }}>
        <div style={{ position: "absolute", left: "6%", right: "6%", top: 17, height: 1,
          background: "linear-gradient(90deg,transparent," + C.ruleLit + " 8%," + C.ruleLit + " 92%,transparent)" }} />
        <div style={{ display: "flex", justifyContent: "space-between", position: "relative" }}>
          {STEPS.map(function (s, idx) {
            var i = idx + 1;
            var on = step === i;
            var done = step > i || (i < step);
            var can = reachable(i) && step > 0;
            return (
              <button key={s[0]} className={"ds-btn" + (on ? " ds-step-on" : "")}
                onClick={function () { if (can) setStep(i); }}
                style={{
                  flex: 1, minWidth: 0, background: "none", border: "none", padding: 0,
                  cursor: can ? "pointer" : "default", display: "flex", flexDirection: "column",
                  alignItems: "center", gap: 5, fontFamily: DISPLAY,
                }}>
                <span style={{
                  width: on ? 30 : 26, height: on ? 30 : 26, borderRadius: "50%",
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: on ? 13 : 11, fontWeight: 600,
                  background: on ? "radial-gradient(circle at 50% 35%,#c2412f,#6e1d16)" : done ? "radial-gradient(circle at 50% 35%,#3a2e1f,#1a150f)" : "#0f0d0b",
                  color: on ? "#fff4e2" : done ? C.brassLit : C.boneFaint,
                  border: "1px solid " + (on ? C.bloodLit : done ? C.brass : C.rule),
                  animation: on ? "dsEmber 2.4s ease-in-out infinite" : "none",
                  transition: "all .2s ease",
                }}>{done && !on ? "✓" : i}</span>
                <span className="ds-step-label" style={{
                  fontSize: 8, letterSpacing: "0.12em", whiteSpace: "nowrap",
                  color: on ? C.brassLit : done ? C.boneDim : C.boneFaint,
                }}>{s[0]}</span>
              </button>
            );
          })}
        </div>
      </div>
    );
  }

  // Selectable card used by every choice step.
  function Choice(cp) {
    var on = cp.on;
    return (
      <button className="ds-btn ds-row" onClick={cp.onClick}
        style={{
          position: "relative", width: "100%", textAlign: "left", cursor: "pointer",
          padding: cp.pad || "11px 13px", borderRadius: R.md, fontFamily: MONO, color: C.bone,
          background: on ? "linear-gradient(180deg,rgba(142,42,34,0.28),rgba(40,18,14,0.6))" : MAT.ironUp,
          border: "1px solid " + (on ? C.brass : C.rule),
          boxShadow: on ? SH.glow : "inset 0 1px 0 rgba(255,226,170,0.05), 0 2px 8px rgba(0,0,0,0.4)",
        }}>
        {on ? <Corners color={C.brassLit} opacity={0.9} len={8} /> : null}
        {cp.children}
      </button>
    );
  }
  function ChoiceTitle(tp) {
    return <div style={{ fontFamily: DISPLAY, fontSize: 13, fontWeight: 600, letterSpacing: "0.08em", color: tp.on ? C.brassLit : C.bone }}>{tp.children}</div>;
  }
  function ChoiceNote(np) {
    return <div style={{ fontFamily: PROSE, fontSize: 13.5, lineHeight: 1.45, color: C.boneDim, marginTop: 4 }}>{np.children}</div>;
  }

  var raceArt = function (id) { return (ART.races && ART.races[id]) || ""; };

  // What has been decided so far, each with a way back to change it.
  var editBtn = {
    fontFamily: DISPLAY, fontSize: 8.5, letterSpacing: "0.14em", padding: "4px 9px", flexShrink: 0,
    background: "rgba(12,10,9,0.6)", color: C.brassLit, border: "1px solid " + C.ruleLit, borderRadius: 3, cursor: "pointer",
  };

  // The selected-vessel strip from the reference sheet: the chosen body large,
  // all six beside it. Tapping any of them goes back to Vessel — it never
  // silently swaps race and wipes the allocation.
  function vesselPanel() {
    if (!race) return null;
    var art = raceArt(race.id);
    return (
      <Frame title="SELECTED VESSEL (RACE)" icon={"race-" + race.id}>
        <div className="ds-vessel">
          <div style={{ position: "relative", minHeight: 150, borderRadius: R.sm, overflow: "hidden",
            border: "1px solid " + C.ruleLit, background: "radial-gradient(120% 100% at 25% 35%,#3c2b1a,#100c09 70%)" }}>
            {art ? (
              <img src={art} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
            ) : (
              <div style={{ position: "absolute", left: 4, top: "50%", transform: "translateY(-50%)", color: C.brass, opacity: 0.4 }}>
                <Icon name={"race-" + race.id} size={130} stroke={0.8} />
              </div>
            )}
            <div style={{ position: "absolute", inset: 0, background: "linear-gradient(90deg,transparent 25%,rgba(10,8,7,0.88) 68%)" }} />
            <div style={{ position: "relative", marginLeft: "45%", padding: "14px 12px 12px 0", display: "flex", flexDirection: "column", gap: 4 }}>
              <div style={{ fontFamily: DISPLAY, fontSize: 21, fontWeight: 600, letterSpacing: "0.08em", color: "#f0e2c4" }}>{race.id}</div>
              <div style={{ fontFamily: PROSE, fontSize: 14, color: C.boneDim, lineHeight: 1.35 }}>{RACE_TAG[race.id]}</div>
              <div style={{ marginTop: 4 }}><Chip color={C.brassLit} border={C.brass}>SPIRIT {race.spirit}</Chip></div>
              <button className="ds-btn" onClick={function () { setStep(2); }}
                style={Object.assign({}, editBtn, { alignSelf: "flex-start", marginTop: 4, padding: "7px 10px", fontSize: 9 })}>
                CHANGE VESSEL ›
              </button>
            </div>
          </div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(5,minmax(0,1fr))", gap: 5 }}>
            {RACES.map(function (x) {
              var on = x.id === race.id;
              var a = raceArt(x.id);
              return (
                <button key={x.id} className="ds-btn" onClick={function () { setStep(2); }}
                  style={{
                    position: "relative", padding: 0, overflow: "hidden", borderRadius: R.sm, cursor: "pointer",
                    display: "flex", flexDirection: "column", textAlign: "center", fontFamily: MONO, color: C.bone,
                    background: MAT.ironUp, border: "1px solid " + (on ? C.brassLit : C.rule),
                    boxShadow: on ? SH.glow : "none",
                  }}>
                  <div style={{ position: "relative", height: 64, background: "radial-gradient(circle at 50% 40%,#33271a,#110d0a 75%)",
                    display: "flex", alignItems: "center", justifyContent: "center", color: on ? C.brassLit : C.boneFaint }}>
                    {a ? <img src={a} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
                      : <Icon name={"race-" + x.id} size={28} stroke={1.3} />}
                  </div>
                  <div style={{ padding: "5px 2px 6px", borderTop: "1px solid " + C.rule }}>
                    <div style={{ fontFamily: DISPLAY, fontSize: 8.5, fontWeight: 600, letterSpacing: "0.02em", color: on ? C.brassLit : C.bone,
                      whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{x.id}</div>
                    <div className="ds-wide-only" style={{ fontFamily: PROSE, fontSize: 11, color: C.boneFaint, lineHeight: 1.25, marginTop: 2 }}>{RACE_TAG[x.id]}</div>
                  </div>
                </button>
