            })}
          </div>
        </div>
      </Frame>
    );
  }

  // Summary cards down the right side, each a way back to that decision.
  function sideCard(key, jump, icon, title, heading, text, extra) {
    var img = ART.cards && ART.cards[key];
    var fade = "linear-gradient(90deg,transparent,#000 60%)";
    return (
      <div key={key} style={{ position: "relative", border: "1px solid " + C.ruleLit, borderRadius: R.sm, background: MAT.iron, boxShadow: SH.panel, overflow: "hidden" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "7px 10px", borderBottom: "1px solid " + C.rule,
          background: "linear-gradient(180deg,rgba(255,220,160,0.05),transparent)" }}>
          <span style={{ color: C.brass }}><Icon name={icon} size={15} /></span>
          <span style={{ flex: 1, fontFamily: DISPLAY, fontSize: 10.5, fontWeight: 600, letterSpacing: "0.13em", color: C.brassLit,
