              <Plate seed={String(jump).length * 5 + 1} height={120} />
            </div>
          )}
          <div style={{ position: "relative", maxWidth: "80%" }}>
            <div style={{ fontFamily: PROSE, fontSize: 18, color: heading ? "#f0e2c4" : C.boneFaint, fontStyle: heading ? "normal" : "italic",
              textShadow: "0 1px 5px #000" }}>{heading || "Not chosen yet"}</div>
            {text ? <div style={{ fontFamily: PROSE, fontSize: 13.5, color: C.boneDim, lineHeight: 1.4, marginTop: 3, textShadow: "0 1px 5px #000" }}>{text}</div> : null}
          </div>
          {extra ? <div style={{ position: "relative", marginTop: 8 }}>{extra}</div> : null}
        </div>
      </div>
    );
  }
  function sideCards() {
    var fam = FAMILIARITY.filter(function (f) { return f[0] === familiarity; })[0];
    var poss = null;
    if (kitObj) {
      var loadTxt = "";
      try {
        if (race) {
          var subsNow = {};
          SUBS.forEach(function (r0) { subsNow[r0[0]] = race.base[r0[0]] + (spend[r0[0]] || 0); });
          var physNow = SUBS.reduce(function (t, r0) { return t + subsNow[r0[0]]; }, 0);
          var lp = physicalCarryProfile({ physique: physNow, substats: subsNow, race: race.id }, kitObj.items);
          loadTxt = lp.carried + " / " + lp.comfortable + " load";
        }
      } catch (e) { loadTxt = ""; }
      poss = (
        <div>
          <div style={{ display: "flex", gap: 5, flexWrap: "wrap" }}>
            {kitObj.items.map(function (it0) { return <ItemTile key={it0.id} item={it0} size={40} lit />; })}
          </div>
          <div style={{ fontSize: 12.5, color: C.boneDim, marginTop: 6 }}>
            {kitObj.items.length} starting item{kitObj.items.length === 1 ? "" : "s"}
            {loadTxt ? <span>{"  •  " + loadTxt}</span> : null}
            <span style={{ color: kitObj.stones ? C.brassLit : C.boneFaint }}>{"  •  ◆ " + kitObj.stones.toLocaleString()}</span>
          </div>
        </div>
      );
    }
    var cards = [];
    if (key !== "origin") cards.push(sideCard("origin", "origin", "journal", "ORIGIN", familiarity, fam ? fam[1] : "", null));
    if (isBarb) {
      if (key !== "ceremony") cards.push(sideCard("circumstances", "ceremony", "guild", "STARTING CIRCUMSTANCES", "The coming-of-age ceremony", "You leave the sacred land as a warrior. No city job, no tax loan, and no road but the Labyrinth.", null));
      if (key !== "weapon") cards.push(sideCard("path", "weapon", "skills", "WEAPON", rackObj ? rackObj.label : null, rackObj ? rackObj.note : "", poss));
    } else {
      if (key !== "circumstances") cards.push(sideCard("circumstances", "circumstances", "guild", "STARTING CIRCUMSTANCES", background, bgObj ? bgObj.note : "", null));
      if (key !== "track") cards.push(sideCard("path", "track", "skills", "TRACK", trackObj ? trackObj.label : null, trackObj ? trackObj.note : "", null));
      if (key !== "possessions") cards.push(sideCard("possessions", "possessions", "bags", "PHYSICAL POSSESSIONS", kitObj ? kitObj.id : null, null, poss));
    }
    return <div style={{ display: "grid", gap: 9, alignContent: "start" }}>{cards}</div>;
  }

  var RACE_TAG = {};
  RACES.forEach(function (r0) { RACE_TAG[r0.id] = r0.tag; });
  var STAT_ICON = { strength: "strength", flexibility: "flexibility", vision: "vision", smell: "smell", accuracy: "accuracy" };

  function kitWeight(x) {
    return x.items.reduce(function (t, it) { return t + (Number(it.weight) || 0) * Math.max(1, Number(it.qty) || 1); }, 0);
  }

  function reviewRow(label, value, jump, icon) {
    return (
      <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 0", borderBottom: "1px solid rgba(110,90,62,0.28)" }}>
        <span style={{ color: C.brass }}><Icon name={icon} size={16} /></span>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontFamily: DISPLAY, fontSize: 8.5, letterSpacing: "0.14em", color: C.boneFaint }}>{label}</div>
