        {jump ? (
          <button className="ds-btn" onClick={function () { jumpTo(jump); }}
            style={{ fontFamily: DISPLAY, fontSize: 8.5, letterSpacing: "0.12em", padding: "5px 8px",
              background: "transparent", color: C.brassLit, border: "1px solid " + C.ruleLit, borderRadius: 3, cursor: "pointer" }}>
            EDIT
          </button>
        ) : null}
      </div>
    );
  }

  var showSide = ["identity", "circumstances", "ceremony", "body", "track", "weapon", "possessions"].indexOf(key) >= 0;
  var canGo = step > 0 && step < total && okKey[key];

  return (
    <div className="ds-root" style={{
      position: "relative",
      minHeight: "100vh",
      background: MAT.backdrop,
      fontFamily: MONO,
      color: C.bone,
      overflowY: "auto",
    }}>
      <GlobalStyle />

      {/* the city behind the title */}
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 170, opacity: 0.55, pointerEvents: "none",
        WebkitMaskImage: "linear-gradient(180deg,#000 30%,transparent)", maskImage: "linear-gradient(180deg,#000 30%,transparent)" }}>
        <Plate seed={5} height={170} src={ART.splash} />
      </div>

      <div style={{ position: "relative", maxWidth: 760, margin: "0 auto", padding: "12px 12px 0" }}>
        {/* title */}
        <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "4px 0 10px" }}>
          <button className="ds-btn" aria-label="Back"
            onClick={function () { if (step > 0) setStep(step - 1); }}
            style={{
              width: 36, height: 36, borderRadius: "50%", flexShrink: 0, visibility: step > 0 ? "visible" : "hidden",
              display: "flex", alignItems: "center", justifyContent: "center",
              background: "rgba(12,10,9,0.7)", color: C.brassLit, border: "1px solid " + C.ruleLit, cursor: "pointer",
            }}>
            <Icon name="back" size={16} stroke={2} />
          </button>
          <div style={{ flex: 1, textAlign: "center", minWidth: 0 }}>
            <div style={{ fontFamily: DISPLAY, fontSize: "clamp(15px, 4.7vw, 26px)", fontWeight: 600, letterSpacing: "0.1em", color: "#f0dcb0",
              textShadow: "0 2px 10px rgba(0,0,0,0.9), 0 0 24px rgba(226,184,101,0.2)", lineHeight: 1.15, whiteSpace: "nowrap" }}>
              AWAKEN <span style={{ fontSize: "0.68em" }}>IN</span> RAFDONIA
