            <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, marginTop: 4 }}>
              <span style={{ width: 28, height: 1, background: "linear-gradient(90deg,transparent," + C.brass + ")" }} />
              <span style={{ fontFamily: DISPLAY, fontSize: 9, letterSpacing: "0.26em", color: C.boneDim, whiteSpace: "nowrap" }}>
                CHARACTER CREATION <span style={{ color: C.brassLit }}>· {step === 0 ? "PROLOGUE" : "STEP " + step + " / " + total}</span>
              </span>
              <span style={{ width: 28, height: 1, background: "linear-gradient(90deg," + C.brass + ",transparent)" }} />
            </div>
          </div>
          <div style={{ width: 36, flexShrink: 0 }} />
        </div>

        {step > 0 ? <Stepper /> : null}
        {step > 0 ? (
          <div style={{ textAlign: "center", margin: "10px 0 12px" }}>
            <span style={{ fontFamily: DISPLAY, fontSize: 12, letterSpacing: "0.18em", color: C.bloodLit, fontWeight: 600 }}>
              {ROMAN[step - 1]}. {STEP_META[key][0]}
            </span>
            <span style={{ fontFamily: PROSE, fontStyle: "italic", fontSize: 14, color: C.boneDim }}>
              {" — "}{STEP_META[key][1]}
            </span>
          </div>
        ) : null}

        <div key={step} className="ds-in" style={{ paddingBottom: 96 }}>

        {step === 0 ? (
          <Frame pad={false} lit>
            <Plate seed={2} height={190} label="THE MOMENT AFTER" src={ART.splash} />
            <div style={{ padding: "16px 16px 18px" }}>
              <div style={{ fontFamily: DISPLAY, fontSize: 12, fontWeight: 600, color: C.bloodLit, letterSpacing: "0.18em", marginBottom: 10 }}>
                THIS IS NOT THE COMPUTER GAME ANYMORE
              </div>
              <p style={{ margin: "0 0 10px", color: C.boneDim, fontFamily: PROSE, fontSize: 16, lineHeight: 1.55 }}>
                Dungeon &amp; Stone's mechanics still govern this world, but Rafdonia is now physical reality:
                bodies tire, wounds hurt, objects have weight, people remember, and death is permanent.
              </p>
              <p style={{ margin: "0 0 16px", fontFamily: PROSE, fontSize: 16, lineHeight: 1.55 }}>
                You are not Bjorn Yandel. You are another independent player from Earth who has awakened in
                this same historical era. What happens next is not a prescribed plot.
              </p>
              <GrandButton onClick={function () { setStep(1); }}>ENTER RAFDONIA</GrandButton>
            </div>
          </Frame>
        ) : null}

        {key === "origin" ? (
          <div style={{ display: "grid", gap: 12 }}>
            <Frame title="WHAT CROSSED OVER" icon="soul" lit>
              <div style={{ display: "flex", gap: 12, alignItems: "center", marginBottom: 8 }}>
                <Medallion size={52} icon="soul" glow />
                <div>
                  <div style={{ fontFamily: DISPLAY, fontSize: 15, letterSpacing: "0.08em" }}>Evil Spirit</div>
                  <div style={{ fontFamily: PROSE, fontStyle: "italic", fontSize: 14, color: C.boneDim }}>A transmigrated player from Earth</div>
                </div>
              </div>
              <Stat label="Historical era" value="Bjorn Yandel era" rule />
              <Stat label="Relationship to Bjorn" value="Independent; no guaranteed meeting" />
              <Empty>Your origin is fixed by this campaign premise. It does not make NPCs know what you are.</Empty>
            </Frame>
            <div>
              <SectionHead icon="journal" flush>Remembered Dungeon &amp; Stone experience</SectionHead>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(160px,1fr))", gap: 8, marginTop: 9 }}>
                {FAMILIARITY.map(function (x) {
                  var on = familiarity === x[0];
                  return (
                    <Choice key={x[0]} on={on} onClick={function () { setFamiliarity(x[0]); }}>
                      <ChoiceTitle on={on}>{x[0]}</ChoiceTitle>
                      <ChoiceNote>{x[1]}</ChoiceNote>
                    </Choice>
                  );
                })}
              </div>
            </div>
          </div>
        ) : null}

        {key === "vessel" ? (
          <div>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(108px,1fr))", gap: 8 }}>
              {RACES.map(function (x) {
                var on = race && race.id === x.id;
                return (
                  <button key={x.id} className="ds-btn"
                    onClick={function () { pickRace(x); }}
                    style={{
                      position: "relative", cursor: "pointer", padding: "12px 6px 10px", borderRadius: R.md,
                      display: "flex", flexDirection: "column", alignItems: "center", gap: 7, textAlign: "center",
                      background: on ? "linear-gradient(180deg,rgba(142,42,34,0.3),rgba(22,16,12,0.9))" : MAT.ironUp,
                      border: "1px solid " + (on ? C.brassLit : C.rule),
                      boxShadow: on ? SH.glow : "0 2px 8px rgba(0,0,0,0.4)", color: C.bone, fontFamily: MONO,
                    }}>
                    {on ? <Corners color={C.brassLit} opacity={0.95} len={8} /> : null}
                    <Medallion size={54} src={raceArt(x.id)} icon={"race-" + x.id} glow={on} ring={on ? C.brassLit : C.ruleLit}
                      color={on ? C.brassLit : C.boneDim} />
                    <div style={{ fontFamily: DISPLAY, fontSize: 12.5, fontWeight: 600, letterSpacing: "0.06em", color: on ? C.brassLit : C.bone }}>{x.id}</div>
                    <div style={{ fontFamily: PROSE, fontSize: 12.5, lineHeight: 1.3, color: C.boneDim }}>{RACE_TAG[x.id]}</div>
                  </button>
                );
              })}
            </div>
            {race ? (
              <div style={{ marginTop: 12 }}>
                <Frame pad={false} lit>
                  <div style={{ display: "flex", gap: 14, padding: 14, alignItems: "center",
                    background: "linear-gradient(90deg,rgba(142,42,34,0.18),transparent 70%)", borderBottom: "1px solid " + C.rule }}>
                    <Medallion size={70} src={raceArt(race.id)} icon={"race-" + race.id} glow />
                    <div style={{ minWidth: 0 }}>
                      <div style={{ fontFamily: DISPLAY, fontSize: 20, fontWeight: 600, letterSpacing: "0.1em" }}>{race.id}</div>
                      <div style={{ fontFamily: PROSE, fontStyle: "italic", fontSize: 14.5, color: C.boneDim }}>{RACE_TAG[race.id]}</div>
                      <div style={{ marginTop: 5 }}>
                        <Chip color={C.brassLit} border={C.brass}>SPIRIT {race.spirit}</Chip>
                        <Chip>PHYSIQUE {SUBS.reduce(function (t, r0) { return t + race.base[r0[0]]; }, 0)}</Chip>
                      </div>
                    </div>
                  </div>
                  <div style={{ padding: 14 }}>
                    <SectionHead icon="skills" flush>Racial trait</SectionHead>
                    <div style={{ fontFamily: PROSE, fontSize: 15, lineHeight: 1.5, margin: "6px 0 12px" }}>{race.ability}</div>
                    <SectionHead icon="coin" flush color={C.bloodLit}>What it costs</SectionHead>
                    <div style={{ fontFamily: PROSE, fontSize: 15, lineHeight: 1.5, margin: "6px 0 12px", color: "#e8a898" }}>{race.cost}</div>
                    <SectionHead icon="body" flush>Base body</SectionHead>
                    <div style={{ display: "grid", gap: 6, margin: "8px 0 12px" }}>
                      {SUBS.map(function (row) {
                        var val = race.base[row[0]];
                        return (
                          <div key={row[0]} style={{ display: "grid", gridTemplateColumns: "18px 104px 1fr 22px", alignItems: "center", gap: 8 }}>
                            <span style={{ color: C.bloodLit }}><Icon name={STAT_ICON[row[0]]} size={15} /></span>
                            <span style={{ fontSize: 12.5, color: C.boneDim }}>{row[1]}</span>
                            <Band pct={val * 10} color={C.brass} thin />
                            <span style={{ fontSize: 13, textAlign: "right" }}>{val}</span>
                          </div>
                        );
                      })}
                    </div>
                    <SectionHead icon="skills" flush>{race.id === "Barbarian" ? "The chief's rack" : "Where this body can begin"}</SectionHead>
                    <div style={{ marginTop: 8 }}>
                      {race.id === "Barbarian"
                        ? CEREMONY_WEAPONS.map(function (w0) { return <Chip key={w0.id}>{w0.label}</Chip>; })
                        : Object.keys(TRACKS).filter(function (id0) { return TRACKS[id0].race === race.id; }).map(function (id0) { return <Chip key={id0}>{TRACKS[id0].label}</Chip>; })}
                    </div>
                  </div>
                </Frame>
              </div>
            ) : (
              <div style={{ marginTop: 12 }}><Empty>Race determines the body's physical baseline, spirit, racial mechanics, social position, and which paths make sense at the beginning.</Empty></div>
            )}
          </div>
        ) : null}

        {showSide ? <div style={{ marginBottom: 12 }}>{vesselPanel()}</div> : null}
        <div className={showSide ? "ds-split" : ""}>
        <div style={{ minWidth: 0 }}>
        {key === "identity" ? (
          <Frame title="THE LIFE THIS BODY ALREADY HAD" icon="sheet" lit>
            {race ? (
              <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 12 }}>
                <Medallion size={50} src={raceArt(race.id)} icon={"race-" + race.id} />
                <div style={{ fontFamily: PROSE, fontSize: 15, lineHeight: 1.45, color: C.boneDim }}>
                  A twenty-year-old <span style={{ color: C.bone }}>{race.id}</span> body. It had a name before you.
                </div>
              </div>
            ) : null}
            <p style={{ fontFamily: PROSE, fontSize: 14.5, color: C.boneDim, margin: "0 0 14px", lineHeight: 1.5 }}>
              You did not spawn into an empty avatar. This body existed in the world before you woke in it.
              Its history creates real witnesses, expectations, routines, and risks.
              {race && race.id === "Barbarian" ? " Barbarian naming customs still apply." : ""}
            </p>
            <Field label="Name" value={name} set={setName} ph="the name this body answers to" />
            <Field label="Previous work / routine" value={hist} set={setHist}
              ph="occupation, daily routine, debts, habits, or leave blank if genuinely unknown" area />
            <Field label="People likely to notice a change" value={wit} set={setWit}
              ph="comma-separated names/roles, or leave blank if none are established" area />
          </Frame>
        ) : null}

        {key === "circumstances" && race ? (
          <div style={{ display: "grid", gap: 12 }}>
            <Empty>Who this body was decides who can still find it. Each life below opens different tracks on the next step.</Empty>
            <div style={{ display: "grid", gap: 8 }}>
              {bgList.map(function (x) {
                var on = background === x.id;
                return (
                  <Choice key={x.id} on={on} onClick={function () { pickBackground(x); }}>
                    <div style={{ display: "flex", gap: 12, alignItems: "flex-start" }}>
                      <span style={{ color: on ? C.brassLit : C.brass, marginTop: 1 }}>
                        <Icon name={BG_ICON[x.id] || "guild"} size={20} />
                      </span>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <ChoiceTitle on={on}>{x.id}</ChoiceTitle>
                        <ChoiceNote>{x.note}</ChoiceNote>
                        <div style={{ marginTop: 8, display: "flex", flexWrap: "wrap", alignItems: "center" }}>
                          <span style={{ fontFamily: DISPLAY, fontSize: 8.5, letterSpacing: "0.14em", color: C.boneFaint, marginRight: 7, marginBottom: 5 }}>OPENS</span>
                          {x.tracks.map(function (tid) {
                            return <Chip key={tid} color={on ? C.brassLit : C.boneDim} border={on ? C.brass : C.rule}>{TRACKS[tid].label}</Chip>;
                          })}
                        </div>
                      </div>
                    </div>
                  </Choice>
                );
              })}
            </div>
            <Frame title="KNOWN STARTING FACTS" icon="map" material="parchment">
              <Field label="Starting district / locality" value={district} set={setDistrict}
                ph="optional — leave blank and the body's established circumstances decide" />
              <Field label="Existing affiliation(s)" value={affiliation} set={setAffiliation}
                ph="optional, comma-separated; only enter ties the body genuinely has" />
              <Field label="Obligations / debts" value={obligations} set={setObligations}
                ph="optional, comma-separated; these become real claims in the simulation" area />
              <Empty>
                Explorer status begins unregistered. These fields seed the world; they do not grant free rank,
                wealth, authority, or relationships.
              </Empty>
            </Frame>
          </div>
        ) : null}

        {key === "ceremony" && race ? (
          <Frame pad={false} lit>
            <Plate seed={3} height={130} label="THE COMING-OF-AGE CEREMONY" src={ART.splash} />
            <div style={{ padding: "14px 14px 16px" }}>
              <div style={{ fontFamily: PROSE, fontSize: 16, lineHeight: 1.55, color: C.boneDim }}>
                Barbarian warriors are made in the sacred land, one name at a time. The chief tells the young
                that from today they leave it and are reborn as true warriors. Then he calls each of them forward
                to choose a weapon.
              </div>
              <div style={{ fontFamily: PROSE, fontSize: 16, lineHeight: 1.55, marginTop: 10 }}>
                This is not a scene you can skip past. If your body's name is called and you do not step forward,
                or you speak nonsense, you are treated as an Evil Spirit and killed where you stand.
              </div>
              <div style={{ marginTop: 12 }}>
                <Chip color={C.bloodLit} border={C.blood}>NO CITY JOB</Chip>
                <Chip color={C.bloodLit} border={C.blood}>NO TAX LOAN</Chip>
                <Chip color={C.bloodLit} border={C.blood}>CANNOT SWIM</Chip>
              </div>
              <SectionHead icon="map">What follows</SectionHead>
              <Stat label="Where you start" value="The sacred land" rule />
              <Stat label="Who calls the names" value="The chief" rule />
              <Stat label="After the weapon" value="Rafdonia, then the Labyrinth" rule />
              <Stat label="Odds, from canon" value="half die on the first entry" rule accent={C.bloodLit} />
              <Stat label="" value="nine in ten dead by six months" accent={C.bloodLit} />
              <Empty>
                There is no background to pick. This ceremony is your circumstance, and it has no debts,
                trade, or contacts in the city. Choose the weapon next.
              </Empty>
            </div>
          </Frame>
        ) : null}

        {key === "body" && race ? (
          <div style={{ display: "grid", gap: 12 }}>
            <Frame pad={false} lit>
              <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 14px",
                borderBottom: "1px solid " + C.rule, background: "linear-gradient(180deg,rgba(255,220,160,0.05),transparent)" }}>
                <span style={{ color: C.brassLit }}><Icon name="skills" size={26} /></span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontFamily: DISPLAY, fontSize: 18, fontWeight: 600, letterSpacing: "0.12em" }}>Body</div>
                  <div style={{ fontFamily: DISPLAY, fontSize: 9.5, letterSpacing: "0.16em", color: C.brass }}>ALLOCATE {POOL} POINTS</div>
                </div>
                <div style={{ display: "flex", alignItems: "center", gap: 7 }}>
                  <span style={{ fontFamily: DISPLAY, fontSize: 34, fontWeight: 600, lineHeight: 1,
                    color: left === 0 ? C.brassLit : C.bloodLit, textShadow: "0 0 14px " + (left === 0 ? C.brass : C.bloodLit) + "66" }}>{left}</span>
                  <span style={{ fontFamily: DISPLAY, fontSize: 8.5, letterSpacing: "0.14em", color: left === 0 ? C.brass : C.bloodLit, lineHeight: 1.3 }}>
                    POINTS<br />REMAINING
                  </span>
                  <button className="ds-btn" onClick={function () { setHelpOn(!helpOn); }} aria-label="How allocation works"
                    style={{ width: 26, height: 26, borderRadius: "50%", marginLeft: 4, cursor: "pointer", fontFamily: MONO, fontSize: 13,
                      background: "transparent", color: C.boneDim, border: "1px solid " + C.ruleLit }}>?</button>
                </div>
              </div>
              {helpOn ? (
                <div style={{ padding: "9px 14px", borderBottom: "1px solid " + C.rule, fontFamily: PROSE, fontSize: 13.5, lineHeight: 1.45, color: C.boneDim, background: "rgba(0,0,0,0.25)" }}>
                  Each point raises one attribute above the value your vessel gives you. Obsession draws from the same pool.
                  Race sets the base and it cannot be lowered. All {POOL} points must be spent to continue.
                </div>
              ) : null}
              <div style={{ padding: "4px 12px 8px" }}>
                {SUBS.map(function (row) {
                  var key = row[0];
                  var add = spend[key] || 0;
                  var val = race.base[key] + add;
                  return (
                    <AllocRow key={key} icon={STAT_ICON[key]} name={row[1]} note={row[2]} value={val}
                      sub={"base " + race.base[key] + (add ? " · +" + add : "")} lit={add > 0}
                      minus={function () { bump(key, -1); }} plus={function () { bump(key, 1); }}
                      canMinus={add > 0} canPlus={left > 0} />
                  );
                })}
                <AllocRow icon="obsession" name="Obsession" note="existing simulation stat; no free narrative effect"
                  value={obs} sub={obs ? "spent" : "none"} lit={obs > 0} last
                  minus={function () { if (obs > 0) setObs(obs - 1); }} plus={function () { if (left > 0) setObs(obs + 1); }}
                  canMinus={obs > 0} canPlus={left > 0} />
              </div>
            </Frame>
            <Frame title="SPIRIT" icon="spirit">
              <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                <div style={{ flex: 1, border: "1px solid " + C.rule, borderRadius: R.sm, padding: "10px 12px", background: "rgba(0,0,0,0.28)" }}>
                  <div style={{ fontFamily: PROSE, fontSize: 16, color: C.bone }}>Derived from your vessel (race).</div>
                  <div style={{ fontFamily: PROSE, fontSize: 13.5, color: C.boneFaint, lineHeight: 1.4, marginTop: 5 }}>
                    Spirit is the size of your mana pool and cannot be manually allocated during creation.
                  </div>
                </div>
                <div style={{ width: 88, flexShrink: 0, textAlign: "center" }}>
                  <div style={{ fontFamily: DISPLAY, fontSize: 8.5, letterSpacing: "0.14em", color: C.boneFaint }}>{race.id.toUpperCase()}</div>
                  <div style={{ display: "flex", justifyContent: "center", margin: "5px 0" }}><Medallion size={54} icon="spirit" glow /></div>
                  <div style={{ fontFamily: PROSE, fontSize: 12.5, color: C.boneDim }}>Base Spirit</div>
                  <div style={{ fontFamily: DISPLAY, fontSize: 19, fontWeight: 600, color: C.brassLit, lineHeight: 1.1 }}>{race.spirit}</div>
                </div>
              </div>
              <div style={{ marginTop: 10 }}>
                <Stat label="Resulting physique" value={SUBS.reduce(function (t, r0) { return t + race.base[r0[0]] + (spend[r0[0]] || 0); }, 0)} rule />
              </div>
            </Frame>
          </div>
        ) : null}

        {key === "track" && race ? (
          <div>
            <Empty>{TRACK_INTRO[race.id]}</Empty>
            <div style={{ display: "grid", gap: 8, marginTop: 6 }}>
              {trackOptions.map(function (t) {
                var on = track === t.id;
                return (
                  <Choice key={t.id} on={on} onClick={function () { pickTrack(t.id); }} pad="13px">
                    <div style={{ display: "flex", alignItems: "flex-start", gap: 11 }}>
                      <span style={{ color: on ? C.brassLit : C.brass, marginTop: 1 }}><Icon name="skills" size={19} /></span>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <ChoiceTitle on={on}>{t.label}</ChoiceTitle>
                        <ChoiceNote>{t.note}</ChoiceNote>
                        {t.needs ? <div style={{ marginTop: 6 }}><Chip color={C.brassLit} border={C.brass}>OPENED BY {String(t.needs).toUpperCase()}</Chip></div> : null}
                      </div>
                    </div>
                  </Choice>
                );
              })}
            </div>
            {trackOptions.length === 0 ? <Empty>Choose the body's circumstances first.</Empty> : null}
          </div>
        ) : null}

        {key === "weapon" && race ? (
          <div>
            <Empty>
              The chief calls each name in turn, and you choose one weapon. Bows and staffs are not on the rack;
              barbarians do not train for finesse. The list in canon ends with "and so on", so this is a fair
              selection of it, not the whole rack.
            </Empty>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(158px,1fr))", gap: 8, marginTop: 6 }}>
              {CEREMONY_WEAPONS.map(function (w) {
                var on = weapon === w.id;
                var arch = w.arch && WEAPON_ARCHETYPES_items ? WEAPON_ARCHETYPES_items[w.arch] : null;
                return (
                  <Choice key={w.id} on={on} onClick={function () { pickWeapon(w.id); }} pad="12px">
                    <div style={{ display: "flex", alignItems: "flex-start", gap: 10 }}>
                      <span style={{ color: on ? C.brassLit : C.brass, marginTop: 1 }}><Icon name={WEAPON_ICON[w.id] || "sword"} size={22} /></span>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <ChoiceTitle on={on}>{w.label}</ChoiceTitle>
                        <ChoiceNote>{w.note}</ChoiceNote>
                        <div style={{ marginTop: 7 }}>
                          <Chip>{(w.id === "shield" ? "Off hand" : (arch && arch.hands === 2) || w.id === "hammer" ? "Two hands" : "One hand")}</Chip>
                          <Chip>{w.weight} wt</Chip>
                        </div>
                      </div>
                    </div>
                  </Choice>
                );
              })}
            </div>
            {rackObj ? (
              <div style={{ marginTop: 10 }}>
                <Empty>You leave with the {rackObj.label.toLowerCase()}, sandals, and a waist cloth. No stones.</Empty>
              </div>
            ) : null}
          </div>
        ) : null}

        {key === "possessions" && race ? (
          <div>
            <Empty>
              These are persistent physical objects, not abstract starter bonuses. They can be equipped,
              damaged, sold, stolen, lost, or transferred.
            </Empty>
            <div style={{ display: "grid", gap: 10, marginTop: 6 }}>
              {kitList.map(function (x, i) {
                var on = kit === i;
                return (
                  <Choice key={x.id} on={on} onClick={function () { setKit(i); }} pad="13px">
                    <ChoiceTitle on={on}>{x.id}</ChoiceTitle>
                    <ChoiceNote>{x.detail}</ChoiceNote>
                    <div style={{ display: "flex", flexWrap: "wrap", gap: 7, marginTop: 10 }}>
                      {x.items.map(function (it) {
                        return (
                          <div key={it.id} style={{ display: "flex", alignItems: "center", gap: 7, padding: "4px 8px 4px 4px",
                            borderRadius: R.sm, border: "1px solid " + C.rule, background: "rgba(0,0,0,0.25)" }}>
                            <ItemTile item={it} size={28} lit={on} />
                            <span style={{ fontSize: 12 }}>{it.name}</span>
                          </div>
                        );
                      })}
                    </div>
                    <div style={{ display: "flex", gap: 14, marginTop: 9, fontSize: 12, color: C.boneDim }}>
                      <span>{x.items.length} object{x.items.length === 1 ? "" : "s"}</span>
                      <span>{kitWeight(x).toFixed(1)} wt</span>
                      <span style={{ color: x.stones ? C.brassLit : C.boneFaint }}>◆ {x.stones.toLocaleString()} stones</span>
                    </div>
                  </Choice>
                );
              })}
            </div>
            {kitList.length === 0 ? <Empty>Choose a track first. It decides what the trade kit is.</Empty> : null}
          </div>
        ) : null}

        </div>
        {showSide ? sideCards() : null}
        </div>
        {key === "review" && race && kitObj && (isBarb ? weapon : (background && track)) ? (
          <Frame pad={false} lit>
            <div style={{ display: "flex", alignItems: "center", gap: 14, padding: 14,
              background: "linear-gradient(90deg,rgba(142,42,34,0.2),transparent 70%)", borderBottom: "1px solid " + C.rule }}>
              <Medallion size={64} src={raceArt(race.id)} icon={"race-" + race.id} glow />
              <div style={{ minWidth: 0 }}>
                <div style={{ fontFamily: DISPLAY, fontSize: 19, fontWeight: 600, letterSpacing: "0.1em" }}>{name}</div>
                <div style={{ fontFamily: PROSE, fontStyle: "italic", fontSize: 14.5, color: C.boneDim }}>
                  {race.id} · age 20 · {pathLabel}
                </div>
              </div>
            </div>
            <div style={{ padding: "4px 14px 14px" }}>
              {reviewRow("ORIGIN", "Independent Evil Spirit · " + familiarity + " familiarity", "origin", "soul")}
              {reviewRow("VESSEL", race.id + " — Spirit " + race.spirit, "vessel", "race-" + race.id)}
              {reviewRow("IDENTITY", name + (hist.trim() ? " — " + hist.trim() : ""), "identity", "sheet")}
              {isBarb
                ? reviewRow("CEREMONY", "Coming-of-age ceremony in the sacred land", "ceremony", "guild")
                : reviewRow("CIRCUMSTANCES", background + " · " + (district.trim() || "locality derived from body/background"), "circumstances", "guild")}
              {reviewRow("BODY", SUBS.map(function (r0) { return r0[1] + " " + (race.base[r0[0]] + (spend[r0[0]] || 0)); }).join(" · ") + " · Obsession " + obs, "body", "body")}
              {isBarb
                ? reviewRow("WEAPON", rackObj.label + " — from the chief", "weapon", WEAPON_ICON[rackObj.id] || "sword")
                : reviewRow("TRACK", trackObj.label, "track", "skills")}
              {reviewRow("POSSESSIONS", kitObj.id + " · ◆ " + kitObj.stones.toLocaleString() + " stones", isBarb ? "weapon" : "possessions", "bags")}
              {reviewRow("EXPLORER REGISTRY", "Unregistered", null, "codex")}
              <Empty>
                {isBarb
                  ? "You begin at the ceremony itself. No main quest will be assigned; the ceremony, the road, and the Labyrinth are the world's own terms."
                  : "No main quest will be assigned. These choices become initial facts in the same living world occupied by Bjorn Yandel and every other persistent person."}
              </Empty>
              <div style={{ marginTop: 12 }}>
                <GrandButton onClick={commit}>{isBarb ? "STEP FORWARD" : "WAKE UP IN RAFDONIA"}</GrandButton>
              </div>
            </div>
          </Frame>
        ) : null}
        </div>
      </div>

      {step > 0 && step < total ? (
        <div style={{
          position: "sticky", bottom: 0, zIndex: 5,
          padding: "10px 12px calc(10px + env(safe-area-inset-bottom, 0px))",
          background: "linear-gradient(180deg,rgba(10,8,7,0) 0%,rgba(10,8,7,0.92) 30%,#0a0807 100%)",
        }}>
          <div style={{ maxWidth: 760, margin: "0 auto" }}>
            {!canGo && BLOCK_HINT[key] ? (
              <div style={{ textAlign: "center", fontFamily: PROSE, fontStyle: "italic", fontSize: 13, color: C.boneFaint, marginBottom: 6 }}>
                {BLOCK_HINT[key]}
              </div>
            ) : null}
            <div style={{ display: "flex", gap: 10, alignItems: "stretch" }}>
              <button className="ds-btn" onClick={function () { setStep(Math.max(0, step - 1)); }}
                style={{
                  flex: "0 0 32%", display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
                  fontFamily: DISPLAY, fontSize: 12, fontWeight: 600, letterSpacing: "0.18em",
                  padding: "13px 0", borderRadius: R.md, cursor: "pointer",
                  background: BTN_IRON, color: C.boneDim, border: "1px solid " + C.ruleLit,
                }}>
                <Icon name="back" size={14} stroke={2} /> BACK
              </button>
              <div style={{ flex: 1 }}>
                <GrandButton disabled={!canGo} onClick={function () { setStep(Math.min(total, step + 1)); }}>CONTINUE</GrandButton>
              </div>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  );
}

// The one ornate control on each screen: the step forward.
function GrandButton(props) {
  var dead = props.disabled;
  var clip = "polygon(18px 0,calc(100% - 18px) 0,100% 50%,calc(100% - 18px) 100%,18px 100%,0 50%)";
  return (
    <button className="ds-btn" onClick={dead ? undefined : props.onClick} disabled={dead}
      style={{
        position: "relative", width: "100%", padding: 1.5, border: "none", cursor: dead ? "not-allowed" : "pointer",
        background: dead ? C.rule : "linear-gradient(180deg,#f0cf85,#9a6f2c 55%,#c9974a)",
        clipPath: clip, WebkitClipPath: clip,
      }}>
      <span style={{
        display: "flex", alignItems: "center", justifyContent: "center", gap: 12, padding: "14px 24px",
        clipPath: clip, WebkitClipPath: clip,
        background: dead ? "linear-gradient(180deg,#221c17,#15110e)" : "radial-gradient(120% 140% at 50% 0%,#c8483a 0%,#8a271e 45%,#56140f 100%)",
        fontFamily: DISPLAY, fontSize: 14.5, fontWeight: 600, letterSpacing: "0.24em",
        color: dead ? C.boneFaint : "#fbecd0", textShadow: dead ? "none" : "0 1px 3px rgba(0,0,0,0.6)",
      }}>
        <span style={{ opacity: 0.7, fontSize: 10 }}>◆</span>
        {props.children}
        <span style={{ opacity: 0.85 }}>→</span>
      </span>
    </button>
  );
}

// One allocatable attribute, − value +.
function AllocRow(props) {
  function step(label, fn, can) {
    return (
      <button className="ds-btn" onClick={fn} disabled={!can} aria-label={label}
        style={{
          width: 34, height: 34, borderRadius: R.sm, flexShrink: 0,
          display: "flex", alignItems: "center", justifyContent: "center",
          fontSize: 18, lineHeight: 1, fontFamily: MONO, cursor: can ? "pointer" : "not-allowed",
          background: BTN_IRON, color: can ? C.bone : C.boneFaint,
          border: "1px solid " + (can ? "#4a3d2e" : "#2a231c"), opacity: can ? 1 : 0.5,
        }}>{label === "decrease" ? "−" : "+"}</button>
    );
  }
  return (
    <div style={{
      display: "flex", alignItems: "center", gap: 11, padding: "10px 2px",
      borderBottom: props.last ? "none" : "1px solid rgba(110,90,62,0.28)",
    }}>
      <span style={{ color: props.lit ? C.bloodLit : "#a8433a", width: 24, display: "flex", justifyContent: "center" }}>
        <Icon name={props.icon} size={22} />
      </span>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontFamily: DISPLAY, fontSize: 13, fontWeight: 600, letterSpacing: "0.04em" }}>{props.name}</div>
        <div style={{ fontFamily: PROSE, fontSize: 13, color: C.boneFaint, lineHeight: 1.3 }}>{props.note}</div>
      </div>
      {step("decrease", props.minus, props.canMinus)}
      <div style={{ width: 38, textAlign: "center" }}>
        <div style={{ fontSize: 19, color: props.lit ? C.brassLit : C.bone, lineHeight: 1.1 }}>{props.value}</div>
        <div style={{ fontSize: 8.5, color: C.boneFaint, whiteSpace: "nowrap" }}>{props.sub}</div>
      </div>
      {step("increase", props.plus, props.canPlus)}
    </div>
  );
}

function Field(props) {
