// ==== guild.tsx =================================================
// The registry counts essence on the soul and nothing else. It is a credential,
// not a measure of what you can survive. Rank 9 is the floor; Rank 1 is the apex.

function arr_guild(v) { return Array.isArray(v) ? v : []; }
function obj_guild(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }
function num_guild(v, d) { return typeof v === "number" ? v : d; }

var TABS_guild = ["REGISTRY", "EXCHANGE", "REQUESTS", "STANDING"];

// Exchange value, in STONES (the currency), of one physical MANA STONE by the
// rank of the thing it came out of. Two hard canon anchors pin this table:
// a Rank 9 mana stone grades at 20 stones (one loaf of bread), and a Death
// Fiend's (Rank 8) at 100. Everything above is extrapolated from those two.
// Same table the Oracle and the grind resolver estimate against, so the
// counter can never quote a number the pouch disagrees with.
var GUILD_STONE_VALUE = { 9: 20, 8: 100, 7: 420, 6: 1300, 5: 4200, 4: 15000, 3: 50000, 2: 210000, 1: 850000 };
// The Guild does not exchange at face value. Nobody does.
var GUILD_FEE_RATE = 0.12;

var RANK_NOTE = {
  9: "Registered. Permitted floors one and two. Nobody will look at you twice.",
  8: "Permitted through floor three. Small clans will take a meeting.",
  7: "Permitted through floor four. Contract work starts paying above tax.",
  6: "Permitted through floor five. Clans recruit at this line.",
  5: "Mid-registry. Party leadership is assumed of you.",
  4: "Senior. Rift contracts become available through guild channels.",
  3: "Rare. Your name circulates whether you want it to or not.",
  2: "Almost nobody. The ministry knows your face.",
  1: "Apex. There is no privacy at this rank.",
};

function guildText(x:any){return String(x==null?"":x).toLowerCase();}
function guildInsideRafdonia(n:any){
  var s=guildText([n.locality,n.location,n.district,n.title,n.detail,n.cause].filter(Boolean).join(" "));
  if(s.indexOf("labyrinth")>=0||s.indexOf("outside rafdonia")>=0||s.indexOf("wasteland")>=0)return false;
  return s.indexOf("district ")>=0||s.indexOf("rafdonia")>=0||s.indexOf("sewer")>=0||s.indexOf("street")>=0||s.indexOf("market")>=0||s.indexOf("gnome tree")>=0||s.indexOf("karnon")>=0||s.indexOf("kommelby")>=0||s.indexOf("ravigion")>=0||s.indexOf("bifron")>=0;
}
function guildLooksMonsterRelated(n:any){
  var s=guildText([n.kind,n.category,n.title,n.detail,n.cause,n.targetType,n.targetSpecies,n.species].filter(Boolean).join(" "));
  return s.indexOf("monster")>=0||s.indexOf("ghoul")>=0||s.indexOf("goblin")>=0||s.indexOf("orc")>=0||s.indexOf("troll")>=0||s.indexOf("blade wolf")>=0||s.indexOf("mana stone")>=0;
}
function guildIncidentAllows(n:any,incidents:any[]){
  var species=guildText(n.targetSpecies||n.species||n.title||n.detail),loc=guildText(n.locality||n.location||n.district||n.title||n.detail);
  return (Array.isArray(incidents)?incidents:[]).some(function(x){
    if(!x||String(x.status||"active")!=="active"||!String(x.cause||"").trim())return false;
    var xs=guildText(x.species),xl=guildText(x.location);
    return (!xs||species.indexOf(xs)>=0||xs.indexOf(species)>=0)&&(!xl||loc.indexOf(xl)>=0||xl.indexOf(loc)>=0);
  });
}
function validateGuildWorldLaw(n:any,v:any){
  if(!n)return {ok:false,reason:"missing request/need"};
  if(guildInsideRafdonia(n)&&guildLooksMonsterRelated(n)&&!guildIncidentAllows(n,Array.isArray(v["city-monster-incidents"])?v["city-monster-incidents"]:[]))
    return {ok:false,reason:"protected-city monster contradiction: no established extraordinary incident permits this monster threat inside Rafdonia"};
  return {ok:true,reason:"world-law valid"};
}

function Guild(props) {
  var api = useYumina();
  var v = api.variables || {};

  var rank = num_guild(v["explorer-rank"], 0);
  var ess = arr_guild(v["essences"]);
  var cap = num_guild(v["essence-capacity"], 3);
  var log = arr_guild(v["quest-log"]);
  var rep = obj_guild(v["reputation"]);
  var fame = num_guild(v["fame"], 0);
  var status = v["citizen-status"] || "citizen";
  var stones = num_guild(v["mana-stones"], 0);
  var loc = String(v["location"] || "");

  var t = React.useState("REGISTRY");
  var tab = t[0], setTab = t[1];

  var guildReqs = log.filter(function (q) {
    return q && (q.formal === true || q.kind === "formal") &&
      String(q.source || "").toLowerCase().indexOf("guild") !== -1 &&
      (q.status === "active" || q.status === "accepted" || q.status === "offered");
  });
  var guildBoard = arr_guild(v["guild-board"]);

  var atGuild = loc.toLowerCase().indexOf("district 9") !== -1 ||
    loc.toLowerCase().indexOf("guild") !== -1;

  function goRegister() {
    api.sendMessage(
      "I go to the Explorers' Guild headquarters in District 9 to register, and stand in whatever line they make me stand in."
    );
    if (props.onClose) props.onClose();
  }

  function goAssess() {
    api.sendMessage(
      "I present myself at the Explorers' Guild for reassessment of my registry rank."
    );
    if (props.onClose) props.onClose();
  }

  function goBoard() {
    if (rank === 0 || !atGuild) return;

    // Passive board lookup: no chat turn, no panel close.
    function rngGuild(seed) {
      var x = seed >>> 0;
      return function () {
        x = (x * 1103515245 + 12345) >>> 0;
        return x / 4294967296;
      };
    }

    var day = num_guild(v["cycle-day"], 1);
    var month = num_guild(v["cycle-month"], 1);
    var rnd = rngGuild(((month * 65537) ^ (day * 3571) ^ (rank * 811)) >>> 0);

    var rejectedNeeds=[];
    var needs=arr_guild(v["world-needs"]).filter(function(n){
      if(!(n&&n.status!=="resolved"&&n.status!=="cancelled"&&n.guildEligible!==false))return false;
      var verdict=validateGuildWorldLaw(n,v);
      if(!verdict.ok)rejectedNeeds.push({id:n.id,title:n.title,reason:verdict.reason});
      return verdict.ok;
    });
    function rewardFromNeed(n){
      var stake=Math.max(0,Number(n.economicStake||0)),urgency=Math.max(0.6,Math.min(2.5,Number(n.urgency||1))),danger=Math.max(0.7,Math.min(3,Number(n.dangerMult||1)));
      var duration=Math.max(0.5,Math.min(10,Number(n.durationDays||1))),floorRisk=Math.max(1,10-Math.max(1,Number(n.minRank||9)));
      return Math.max(1000,Math.round((2500+stake*0.04+duration*2500+floorRisk*3000)*urgency*danger));
    }
    var rows=[];
    needs.slice(0,5).forEach(function(n,i){var reward=rewardFromNeed(n);rows.push({
      id:"guild-need-"+String(n.id||("m"+month+"d"+day+"-"+i)),needId:String(n.id||""),title:String(n.title||n.requestTitle||"Procurement / Expedition Request"),
      detail:String(n.detail||n.requestDetail||("A real unresolved need exists: "+String(n.cause||n.kind||"specified work")+". Completion must physically change that need.")),
      reward:reward+" stones",rewardValue:reward,rewardBasis:{economicStake:Number(n.economicStake||0),urgency:Number(n.urgency||1),danger:Number(n.dangerMult||1),durationDays:Number(n.durationDays||1)},
      deadline:n.deadline||("day "+Math.min(30,day+Math.max(2,Math.round(Number(n.durationDays||2)+Number(n.urgency||1))))),minRank:Number(n.minRank||9),
      employer:String(n.employer||"Guild-contracted client"),source:"Explorers' Guild",status:"offered",formal:true,causal:true
    });});
    var routine=[
      {min:9,title:"Rank 9 Mana-Stone Procurement",kind:"labyrinth-procurement",cat:"monster_materials",stake:40000,detail:"The Guild exchange needs a verified lot of low-rank Labyrinth mana stones above ordinary counter flow."},
      {min:8,title:"Labyrinth Route Verification",kind:"labyrinth-route",cat:"services",stake:90000,detail:"Verify a known Labyrinth route, hazards and landmarks. The work is inside the Labyrinth, not monster control within Rafdonia."},
      {min:7,title:"Monster Byproduct Procurement",kind:"labyrinth-procurement",cat:"monster_materials",stake:140000,detail:"A licensed buyer needs a specified intact Labyrinth monster byproduct. Species/source requirements are released with the contract."},
      {min:7,title:"Missing Explorer Recovery",kind:"labyrinth-recovery",cat:"services",stake:180000,detail:"An explorer party failed to report from the Labyrinth. Confirm status and recover tags/effects or reliable information."},
      {min:6,title:"Labyrinth Hazard Clearance",kind:"labyrinth-hazard",cat:"services",stake:300000,detail:"A repeatedly used Labyrinth approach has become dangerous. Remove/verify the actual hazard and return proof."}
    ];
    var eligible=routine.filter(function(t){return rank<=t.min;});
    while(rows.length<5&&eligible.length){
      var ix=Math.floor(rnd()*eligible.length),t=eligible.splice(ix,1)[0],needId="routine-m"+month+"d"+day+"-"+rows.length,urgency=0.85+rnd()*0.5;
      var need={id:needId,kind:t.kind,category:t.cat,locality:"Rafdonia / Labyrinth interface",cause:"routine city demand for Labyrinth output",economicStake:t.stake,urgency:urgency,
        dangerMult:1+(9-t.min)*0.15,minRank:t.min,durationDays:1+Math.floor(rnd()*4),status:"open",guildEligible:true,title:t.title,detail:t.detail,employer:"Explorers' Guild / licensed client",createdDay:day,linkedRequestIds:[]};
      needs.push(need);var reward=rewardFromNeed(need);rows.push({id:"guild-need-"+needId,needId:needId,title:t.title,detail:t.detail,reward:reward+" stones",rewardValue:reward,
        rewardBasis:{economicStake:t.stake,urgency:urgency,danger:need.dangerMult,durationDays:need.durationDays},deadline:"day "+Math.min(30,day+2+Math.floor(rnd()*6)),minRank:t.min,
        employer:need.employer,source:"Explorers' Guild",status:"offered",formal:true,causal:true});
    }
    var validRows=rows.filter(function(q){var verdict=validateGuildWorldLaw(q,v);if(!verdict.ok)rejectedNeeds.push({id:q.id,title:q.title,reason:verdict.reason});return verdict.ok;});
    var existingNeeds=arr_guild(v["world-needs"]),existingIds={};existingNeeds.forEach(function(n){if(n&&n.id)existingIds[n.id]=true;});
    var additions=needs.filter(function(n){return n&&n.id&&!existingIds[n.id]&&validateGuildWorldLaw(n,v).ok;});
    if(additions.length)api.setVariable("world-needs",existingNeeds.concat(additions).slice(-120));
    api.setVariable("guild-board",validRows);
    api.injectContext("[UI] Refreshed the Explorers' Guild public board from unresolved world/economic needs. "+validRows.length+
      " world-law-valid offers are visible. "+rejectedNeeds.length+" contradictory request(s) were suppressed before display. "+
      "Routine monster threats inside protected Rafdonia are impossible unless a causally established active city-monster-incidents exception already exists. No narrated scene was consumed.");
  }

  function acceptBoardRequest(id) {
    var board = arr_guild(v["guild-board"]);
    var ix = -1;
    for (var i = 0; i < board.length; i++) if (board[i] && board[i].id === id) { ix = i; break; }
    if (ix < 0) return;
    var q = board[ix];
    var qVerdict=validateGuildWorldLaw(q,v);
    if(!qVerdict.ok){
      api.setVariable("guild-board",board.filter(function(x){return x&&x.id!==q.id;}));
      api.injectContext("[WORLD-LAW VALIDATOR] Rejected stale/impossible Guild request '"+String(q.title||q.id)+"': "+qVerdict.reason+". It cannot become campaign state.",{role:"system"});
      return;
    }
    var logNow = arr_guild(v["quest-log"]);
    if (logNow.some(function (x) { return x && x.id === q.id; })) return;
    api.setVariable("quest-log", logNow.concat([Object.assign({}, q, {kind:"formal",formal:true,status:"accepted",acceptedClock:v["clock"]})]));
    var nextBoard = board.slice();
    nextBoard[ix] = Object.assign({}, q, {status:"accepted"});
    api.setVariable("guild-board", nextBoard);
    var grl=arr_guild(v["guild-request-ledger"]);
    if(!grl.some(function(x){return x&&x.requestId===q.id;}))api.setVariable("guild-request-ledger",grl.concat([{requestId:q.id,needId:q.needId||"",employer:q.employer||"Explorers' Guild",rewardBasis:q.rewardBasis||{},status:"accepted",acceptedBy:"player",acceptedClock:v["clock"]}]).slice(-120));
    if(q.needId){api.setVariable("world-needs",arr_guild(v["world-needs"]).map(function(n){if(!n||n.id!==q.needId)return n;var links=Array.isArray(n.linkedRequestIds)?n.linkedRequestIds.slice():[];if(links.indexOf(q.id)<0)links.push(q.id);return Object.assign({},n,{linkedRequestIds:links,status:n.status==="open"?"contracted":n.status});}));}
    api.injectContext("[UI PHYSICAL/LEGAL ACTION — ALREADY APPLIED] Accepted Guild request: "+q.title+". It is linked to need "+String(q.needId||"none")+". Acceptance does not solve the underlying problem.");
  }

  // --- registry ---------------------------------------------------------
  function Registry() {
    if (rank === 0) {
      return (
        <div>
          <div style={{ fontSize: 12, letterSpacing: "0.18em", color: C.boneDim }}>
