  // --- exchange ---------------------------------------------------------
  // The whole point of the two-step economy lives here. A pouch of rock is
  // worth nothing until it crosses this counter, and the counter takes a cut.
  function Exchange() {
    var bag = obj_guild(v["raw-stones"]);
    var names = Object.keys(bag).filter(function (n) {
      return num_guild(obj_guild(bag[n]).qty, 0) > 0;
    });

    var gross = 0, count = 0;
    for (var i = 0; i < names.length; i++) {
      var row = obj_guild(bag[names[i]]);
      var q = num_guild(row.qty, 0);
      var r = num_guild(row.rank, 9);
      gross += (GUILD_STONE_VALUE[r] || GUILD_STONE_VALUE[9]) * q;
      count += q;
    }
    var fee = Math.round(gross * GUILD_FEE_RATE);
    var net = Math.max(0, gross - fee);

    function processHaul() {
      if (!count || !atGuild) return;
      api.setVariable("mana-stones", stones + net);
      api.setVariable("raw-stones", {});
      api.injectContext(
        "[UI] The Guild counter graded, weighed and processed the player's haul — " +
        count + " mana stone(s) — at " + gross + " stones gross, less a " + fee +
        " stone exchange fee, paying out " + net + " stones in coin. The pouch is empty now. " +
        "Narrate the counter, the weighing, and the clerk. Do not re-apply any numbers."
      );
      if (props.onClose) props.onClose();
    }

    return (
      <div>
        <div style={{ fontSize: 12, letterSpacing: "0.18em", color: C.boneDim }}>
          STONE EXCHANGE
        </div>

        {!names.length ? (
          <Empty>
            The pouch is empty. Mana stones are cut out of corpses in the
            Labyrinth; they are worth nothing until they reach this counter,
            and you are not carrying any.
          </Empty>
        ) : (
          <div>
            <div style={{ marginTop: 10 }}>
              {names.map(function (n) {
                var row = obj_guild(bag[n]);
                var q = num_guild(row.qty, 0);
                var r = num_guild(row.rank, 9);
                var each = GUILD_STONE_VALUE[r] || GUILD_STONE_VALUE[9];
                return (
                  <Stat
                    key={n}
                    label={n + " ×" + q}
                    value={"~" + (each * q)}
                    rule
                  />
                );
              })}
            </div>

            <div style={{ marginTop: 12 }}>
              <Stat label="mana stones carried" value={String(count)} rule />
              <Stat label="gross appraisal" value={"~" + gross + " stones"} rule />
              <Stat label="guild fee" value={"−" + fee + " stones"} accent={C.bloodLit} rule />
              <Stat label="payout" value={net + " stones"} accent={C.brass} />
            </div>

            <div style={{ marginTop: 12 }}>
              <Btn wide onClick={processHaul} disabled={!atGuild}>
                {atGuild ? "PROCESS THE HAUL" : "NOT AT A GUILD BRANCH"}
              </Btn>
            </div>

            <Empty>
              {atGuild
                ? "The counter's offer is the real number. Your panel only estimates."
                : "Mana stones can only be exchanged for stones at an Explorers' Guild branch on the surface. Until then they are just weight in your pouch."}
            </Empty>
          </div>
        )}
      </div>
    );
  }

  return (
    <Screen
      title="EXPLORERS' GUILD"
      onClose={props.onClose}
      tabs={TABS_guild}
      tab={tab}
      onTab={function (x) { setTab(x); }}
    >
      {tab === "REGISTRY" ? <Registry /> : null}
      {tab === "EXCHANGE" ? <Exchange /> : null}
      {tab === "REQUESTS" ? <Requests /> : null}
      {tab === "STANDING" ? <Standing /> : null}
    </Screen>
  );
}

// ==== vault.tsx =================================================
// Alminus Bank. The only place in this city where money is genuinely out of
// reach of whatever happens to the body carrying it. A purse can be cut off a
// corpse on floor three; a vault balance cannot.
//
// Two account shapes, both canon, and the choice between them is a real one:
// a REGISTERED account is filed under a name and can be willed to an heir —
// and is also a record with that name on it. An UNREGISTERED box needs only a
// password and no identity at all, which is exactly why it is deniable and
// exactly why losing the password loses the money.

function num_vault(v, d) { return typeof v === "number" && isFinite(v) ? v : d; }
function obj_vault(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }

// ==== fence ================================================================
// Optional. Selling gear already works by walking into a shop and arguing, and
// that path is untouched. This screen exists for the one case prose handles
// badly: a piece taken off a person, where the question is not "what is it
// worth" but "who is willing to not ask." It quotes each venue, states plainly
// what each one costs you in questions, and then hands off to the SAME haggle
// machinery a merchant uses — it never settles a sale itself.
function f_num(v, d) { return typeof v === "number" && isFinite(v) ? v : d; }
function f_obj(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }
function f_arr(v) { return Array.isArray(v) ? v : []; }

var FENCE_VENUES = [
  {
    id: "smithy",
    label: "SMITHY",
    who: "the smith",
    place: "Kommelby smithy",
    where: ["kommelby", "smith", "ravigion"],
    blurb: "Best straight price for arms and armour. He can also strip a piece " +
      "to material, which genuinely breaks the trail — for a good part of what " +
      "it was worth.",
    questions: "A smith knows work. Large smithies are clan-affiliated, and they keep records.",
    reforge: true,
  },
  {
    id: "variety",
    label: "VARIETY STORE",
    who: "the shopkeeper",
    place: "a variety store",
    where: ["kommelby", "ravigion", "market", "kiarbis"],
    blurb: "Routine loot resale. Fast, unremarkable, mediocre price.",
    questions: "None worth minding — but no appetite for anything conspicuous either.",
  },
  {
    id: "consignment",
    label: "ALMINUS CONSIGNMENT",
    who: "the exchange clerk",
    place: "the Alminus Central Exchange",
    where: ["kommelby", "alminus", "exchange"],
    blurb: "Higher realised price, and slow. Appraisal available if you want to " +
      "know what you actually have.",
    questions: "A RECORDED sale. Findable by anyone who pays the 3,000-stone search fee.",
  },
  {
    id: "auction",
    label: "SKY AUCTION",
    who: "the auction agent",
    place: "the Sky Auction House",
    where: ["karnon", "sky", "auction"],
    blurb: "Sealed anonymous bidding through the armrest terminal. Prices stay " +
      "secret until the day.",
    questions: "Anonymity is structural here — the one legitimate room that suits a piece with a history.",
    launders: true,
  },
  {
    id: "black",
    label: "BLACK MARKET",
    who: "the buyer behind the numbered door",
    place: "the black market",
    where: null,
    blurb: "No questions at all. Worst price by a distance.",
    questions: "None. Being known here is its own permanent liability.",
    launders: true,
  },
];

// Arms and armour are what a smith actually wants; everything else is scrap to
// him. Distinctiveness is what closes doors, not value.
function fenceQuote(venue, it, distinct) {
  var base = Math.max(0, Math.floor(f_num(it.value, 0)));
  if (base <= 0) base = 40;
  var slot = String(it.slot || "");
  var martial = slot === "main-hand" || slot === "off-hand" ||
    /^head:|^torso:|^arms:|^hands:|^legs:|^feet:/.test(slot);

  var mult;
  if (venue.id === "smithy") mult = martial ? 0.65 : 0.30;
  else if (venue.id === "variety") mult = 0.35;
  else if (venue.id === "consignment") mult = 0.75;
  else if (venue.id === "auction") mult = 0.90;
  else mult = 0.25;

  var refuse = null;
  if (venue.id === "variety" && (distinct === "high" || base > 30000)) {
    refuse = "Too conspicuous for a counter like this. He will not touch it.";
  }
  if (venue.id === "auction" && base < 30000) {
    refuse = "Under the floor. Sky does not take lots this small.";
  }

  return { price: Math.max(1, Math.round(base * mult)), refuse: refuse };
}

function FenceScreen(props) {
  var api = useYumina();
  var v = api.variables || {};

  var bag = normalizeList(v["inventory"]);
  var hot = f_arr(v["hot-goods"]);
  var loc = String(v["location"] || "").toLowerCase();
  var shop = f_obj(v["shop-state"]);
  var atCounter = shop.active === true;

  var sS = React.useState(null);
  var sel = sS[0], setSel = sS[1];
  var rS = React.useState(false);
  var strip = rS[0], setStrip = rS[1];

  var sellable = bag.filter(function (x) { return isSellable(x); });

  function provenance(name) {
    for (var i = 0; i < hot.length; i++) {
      var h = f_obj(hot[i]);
      if (String(h.item || "") === String(name || "")) return h;
    }
    return null;
  }

  var chosen = null;
  for (var i = 0; i < sellable.length; i++) {
    if (String(sellable[i].id) === String(sel)) chosen = sellable[i];
  }
  var prov = chosen ? provenance(chosen.name) : null;
  var distinct = prov ? String(prov.distinct || "low") : null;
  var laundered = prov ? prov.laundered === true : false;

  function here(venue) {
    if (!venue.where) return true;
    for (var j = 0; j < venue.where.length; j++) {
      if (loc.indexOf(venue.where[j]) !== -1) return true;
    }
    return false;
  }

  // Hand the argument to the merchant path. The interface quotes an opening
  // number and nothing else — the price is still won or lost in conversation,
  // and HaggleWatch is what finally moves stones and goods.
  function take(venue, quote) {
    if (!chosen) return;
    var stripping = venue.reforge && strip;
    var opening = stripping ? Math.max(1, Math.round(quote * 0.62)) : quote;

    api.setVariable("shop-state", {
      active: false,
      merchantName: venue.who,
      location: venue.place,
      shopType: "fence",
      items: [],
      haggling: {
        active: true,
        mode: "SELL",
        name: chosen.name,
        ref: String(chosen.id),
        listed: opening,
        round: 0,
      },
      "haggle-result": null,
    });

    api.injectContext(
      "[UI] FENCE OPENED. The player is trying to move " + chosen.name +
      " at " + venue.place + ". Opening figure " + opening + " stones" +
      (stripping ? ", on the understanding it gets stripped to material first" : "") +
      ". " +
      (prov
        ? "PROVENANCE: this came off " + (prov.from || "a person") +
          ", distinctiveness " + distinct + ", witnesses: " +
          (prov.witnesses || "unrecorded") + ". "
        : "This was not taken off a person as far as the ledger knows. ") +
      "How this room reacts is yours: " + venue.questions + " " +
      (distinct === "high"
        ? "A piece this identifiable is exactly how plunderers get caught — the " +
          "Elbis precedent. Let the buyer notice, or not, honestly. "
        : "") +
      "The buyer may refuse flatly, meet partway, or take it. THREE OUTCOMES, " +
      "scalars only, no arrays: " +
      "[shop-state.haggle-result: set {\"outcome\":\"countered\",\"price\":N}] when " +
      "they name a different number — this does NOT end the scene; " +
      "[shop-state.haggle-result: set {\"outcome\":\"accepted\",\"price\":N}] when a " +
      "number is genuinely agreed; " +
      "[shop-state.haggle-result: set {\"outcome\":\"refused\"}] when they are done. " +
      (stripping || venue.launders
        ? "If this sale completes, the trail is broken — set laundered true on " +
          "the matching hot-goods entry. "
        : "If this sale completes, the trail is NOT broken; leave hot-goods " +
          "laundered false. ") +
      "The interface moves the stones and the goods itself — never narrate them " +
      "changing hands and never state a purse total.",
      { role: "system" }
    );
    api.sendMessage(
      "[I take the " + chosen.name + " to " + venue.place +
      (stripping ? " to have it stripped down" : "") + ".]"
    );
    if (props.onClose) props.onClose();
  }

  // The half-measure, kept deliberately: the trade-offs should be learnable by
  // asking a person, not only by reading a panel.
  function askAround() {
    api.injectContext(
      "[UI] The player is asking around about where to move " +
      (chosen ? chosen.name : "goods they would rather not explain") + ". " +
      "Answer IN WORLD, as dialogue from whoever is plausibly nearby — another " +
      "explorer at the pub, a stallholder, a bored guild clerk. Nobody lays out " +
      "five options like a list. One person knows one or two rooms, has an " +
      "opinion about them, and may be wrong or fishing. Venues that exist: a " +
      "Kommelby smithy (best for arms, can strip a piece to material, keeps " +
      "records), a variety store (ordinary kit, no appetite for anything " +
      "conspicuous), Alminus consignment (better price, recorded sale, findable " +
      "for a 3,000-stone search fee), the Sky Auction House in Karnon (sealed " +
      "anonymous bidding, high floor), and the black market (no questions, worst " +
      "price, being known there is permanent). Do not quote exact figures unless " +
      "the person would actually know them.",
      { role: "system" }
    );
    api.sendMessage(
      chosen
        ? "[I ask around about where I could move the " + chosen.name + ".]"
        : "[I ask around about where a person moves goods they would rather not explain.]"
    );
    if (props.onClose) props.onClose();
  }

  return (
    <Screen title="MOVING GOODS" onClose={props.onClose}>
      {atCounter ? (
        <Empty>
          You are already standing at a counter. Sell it there — close this and
          use the shop in front of you.
        </Empty>
      ) : !sellable.length ? (
        <Empty>
          Nothing in your pack you could put on a counter. Equipped gear has to
          come off first, and Numbered Items do not sell.
        </Empty>
      ) : (
        <div>
          <div style={{ fontSize: 10, color: C.boneFaint, lineHeight: 1.7, marginBottom: 10 }}>
            You never have to use this. Walking into a shop and arguing works
            exactly the same. This is only here for the pieces where the price
            is not the problem.
          </div>

          <div style={{ fontSize: 10, letterSpacing: "0.14em", color: C.boneDim, marginBottom: 6 }}>
            WHAT ARE YOU MOVING
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 5, marginBottom: 14 }}>
            {sellable.map(function (it) {
              var p = provenance(it.name);
              var on = String(it.id) === String(sel);
              return (
                <Btn
                  key={String(it.id)}
                  wide
                  active={on}
                  onClick={function () {
                    setSel(String(it.id));
                    setStrip(false);
                  }}
                >
                  <span>{it.name}</span>
                  {p ? (
                    <span style={{ color: on ? "#f5f0e2" : C.blood, marginLeft: 6 }}>
                      · off a person
                      {p.laundered === true ? ", trail broken" : ""}
                    </span>
                  ) : null}
                </Btn>
              );
            })}
          </div>

          {chosen ? (
            <div>
              {prov ? (
                <div
                  style={{
                    marginBottom: 12, padding: "9px 11px", borderRadius: 8,
                    border: "1px dashed " + (distinct === "high" ? C.bloodLit : C.brass),
                    background: distinct === "high"
                      ? "rgba(178,59,59,0.08)" : "rgba(150,110,45,0.07)",
                    fontSize: 10, lineHeight: 1.7, color: C.boneDim,
                  }}
                >
                  <span style={{ color: distinct === "high" ? C.bloodLit : C.brassLit, letterSpacing: "0.12em" }}>
                    {distinct === "high"
                      ? "THIS PIECE IS IDENTIFIABLE"
                      : distinct === "medium"
                        ? "A SMITH MIGHT KNOW THIS WORK"
                        : "COMMON ENOUGH"}
                  </span>
                  <div style={{ marginTop: 4 }}>
                    Came off {String(prov.from || "a person")}.
                    {prov.witnesses ? " Witnesses: " + String(prov.witnesses) + "." : ""}
                    {laundered ? " The trail on it has already been broken." : ""}
                  </div>
                </div>
              ) : null}

              <div style={{ fontSize: 10, letterSpacing: "0.14em", color: C.boneDim, marginBottom: 6 }}>
                WHERE
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {FENCE_VENUES.map(function (venue) {
                  var q = fenceQuote(venue, chosen, distinct || "low");
                  var reachable = here(venue);
                  var dead = !!q.refuse || !reachable;
                  return (
                    <Frame key={venue.id} title={venue.label}>
                      <div style={{ fontSize: 10, lineHeight: 1.7, color: C.boneDim }}>
                        {venue.blurb}
                      </div>
                      <div style={{ fontSize: 10, lineHeight: 1.7, color: C.boneFaint, marginTop: 5 }}>
                        {venue.questions}
                      </div>

                      <div style={{ marginTop: 8, marginBottom: 8 }}>
                        <Stat
                          label="opening figure"
                          value={dead ? "—" : q.price + " stones"}
                          accent={dead ? undefined : C.brassLit}
                          dim={dead}
                        />
                      </div>

                      {venue.reforge && !dead ? (
                        <div style={{ marginBottom: 8 }}>
                          <Btn
                            wide
                            active={strip}
                            onClick={function () { setStrip(!strip); }}
                          >
                            {strip
                              ? "STRIPPING IT TO MATERIAL — trail broken, " +
                                Math.max(1, Math.round(q.price * 0.62)) + " stones"
                              : "HAVE IT STRIPPED TO MATERIAL FIRST"}
                          </Btn>
                        </div>
                      ) : null}

                      <Btn
                        wide
                        disabled={dead}
                        onClick={function () { if (!dead) take(venue, q.price); }}
                      >
                        {!reachable
                          ? "YOU ARE NOT WHERE THIS IS"
                          : q.refuse
                            ? q.refuse
                            : "TAKE IT THERE AND ARGUE"}
                      </Btn>
                    </Frame>
                  );
                })}
              </div>
            </div>
          ) : (
            <Empty>Pick something first.</Empty>
          )}

          <div style={{ marginTop: 14 }}>
            <Btn wide onClick={askAround}>ASK AROUND INSTEAD</Btn>
            <div style={{ fontSize: 9, color: C.boneFaint, lineHeight: 1.6, marginTop: 6 }}>
              A panel is not the only way to learn where things go. Someone at
              the next table has an opinion, and it may be wrong.
            </div>
          </div>
        </div>
      )}
    </Screen>
  );
}

function Vault(props) {
  var api = useYumina();
  var v = api.variables || {};

  function arrVault(x) { return Array.isArray(x) ? x : []; }
  function cloneVaultItem(x) {
    var o = obj_vault(x);
    var y = {};
    Object.keys(o).forEach(function (k) { y[k] = o[k]; });
    return y;
  }
  function hashVaultPassword(text) {
    // Deliberately stores no plaintext. This is an in-world access check, not
    // cryptographic account security; the narrator never receives either value.
    var s = String(text || "");
    var h = 2166136261;
    for (var i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    return "v1-" + (h >>> 0).toString(16) + "-" + s.length;
  }

  var purseNow = Math.max(0, num_vault(v["mana-stones"], 0));
  var accessNow = obj_vault(v["vault-access"]);
  var legacyAcct = obj_vault(v["bank-account"]);

  // One-time compatibility import for saves made before dual boxes existed.
  var regBalNow = Math.max(0, num_vault(v["registered-vault-balance"], 0));
  var anonBalNow = Math.max(0, num_vault(v["unregistered-vault-balance"], 0));
  var regItemsNow = arrVault(v["registered-vault-items"]);
  var anonItemsNow = arrVault(v["unregistered-vault-items"]);
  var legacyBal = Math.max(0, num_vault(v["bank-balance"], 0));
  var legacyItems = arrVault(v["vault-items"]);
  var dualEmpty = regBalNow === 0 && anonBalNow === 0 && regItemsNow.length === 0 && anonItemsNow.length === 0;
  var legacyHas = legacyBal > 0 || legacyItems.length > 0;

  if (dualEmpty && legacyHas) {
    if (String(legacyAcct.type || "") === "unregistered") {
      anonBalNow = legacyBal;
      anonItemsNow = legacyItems.slice();
    } else {
      regBalNow = legacyBal;
      regItemsNow = legacyItems.slice();
    }
  }

  var packNow = normalizeList(v["inventory"]);
  var n = obj_vault(v["current-npc"]);
  var loc = String(v["location"] || "").toLowerCase();
  var npcText = (
    String(n.name || "") + " " +
    String(n.affiliation || "") + " " +
    String(n.notes || "")
  ).toLowerCase();

  var atBank = loc.indexOf("bank") !== -1 || loc.indexOf("alminus") !== -1 ||
    loc.indexOf("vault") !== -1 || loc.indexOf("kommelby") !== -1;
  var withClerk = n.active === true &&
    (npcText.indexOf("alminus") !== -1 || npcText.indexOf("bank") !== -1 ||
     npcText.indexOf("vault") !== -1 || npcText.indexOf("clerk") !== -1 ||
     npcText.indexOf("teller") !== -1);

  var initialized = React.useRef(false);

  var boxState = React.useState("registered");
  var box = boxState[0], setBox = boxState[1];

  var purseState = React.useState(purseNow);
  var purse = purseState[0], setPurse = purseState[1];

  var regBalState = React.useState(regBalNow);
  var regBal = regBalState[0], setRegBal = regBalState[1];

  var anonBalState = React.useState(anonBalNow);
  var anonBal = anonBalState[0], setAnonBal = anonBalState[1];

  var packState = React.useState(packNow);
  var pack = packState[0], setPack = packState[1];

  var regItemsState = React.useState(regItemsNow);
  var regItems = regItemsState[0], setRegItems = regItemsState[1];

  var anonItemsState = React.useState(anonItemsNow);
  var anonItems = anonItemsState[0], setAnonItems = anonItemsState[1];

  var accessState = React.useState({
    registeredOpen: accessNow.registeredOpen === true || legacyAcct.type === "registered",
    registeredHeir: String(accessNow.registeredHeir || legacyAcct.heir || ""),
    unregisteredOpen: accessNow.unregisteredOpen === true || legacyAcct.type === "unregistered",
    unregisteredPasswordHash: String(accessNow.unregisteredPasswordHash || ""),
  });
  var access = accessState[0], setAccess = accessState[1];

  var unlockedState = React.useState(false);
  var anonUnlocked = unlockedState[0], setAnonUnlocked = unlockedState[1];

  var amountState = React.useState("");
  var amtRaw = amountState[0], setAmtRaw = amountState[1];

  var passState = React.useState("");
  var passRaw = passState[0], setPassRaw = passState[1];

  var pass2State = React.useState("");
  var pass2Raw = pass2State[0], setPass2Raw = pass2State[1];

  var heirState = React.useState("");
  var heirRaw = heirState[0], setHeirRaw = heirState[1];

  var logState = React.useState([]);
  var sessionLog = logState[0], setSessionLog = logState[1];

  var errorState = React.useState("");
  var error = errorState[0], setError = errorState[1];

  React.useEffect(function () {
    if (initialized.current) return;
    initialized.current = true;
    if (dualEmpty && legacyHas) {
      // Commit compatibility migration immediately; this is bookkeeping, not a
      // narrated player action.
      api.setVariable("registered-vault-balance", regBalNow);
      api.setVariable("unregistered-vault-balance", anonBalNow);
      api.setVariable("registered-vault-items", regItemsNow);
      api.setVariable("unregistered-vault-items", anonItemsNow);
    }
  }, []);

  function addLog(text) {
    setSessionLog(function (old) { return old.concat([text]); });
  }

  function currentBalance() { return box === "registered" ? regBal : anonBal; }
  function currentItems() { return box === "registered" ? regItems : anonItems; }
  function boxOpen() { return box === "registered" ? access.registeredOpen : access.unregisteredOpen; }
  function boxUnlocked() { return box === "registered" ? true : anonUnlocked; }

  var amt = Math.max(0, Math.floor(num_vault(parseInt(amtRaw, 10), 0)));

  var lodgeable = pack.filter(function (it) {
    return it && it.name && it.equipped !== true;
  });

  function openRegistered() {
    if (access.registeredOpen) return;
    setAccess(Object.assign({}, access, { registeredOpen: true }));
    addLog("opened a registered Alminus account under the body's legal identity");
  }

  function setUnregisteredPassword() {
    var p1 = String(passRaw || "");
    var p2 = String(pass2Raw || "");
    if (p1.length < 4) { setError("Use at least four characters."); return; }
    if (p1 !== p2) { setError("The two password entries do not match."); return; }
    var h = hashVaultPassword(p1);
    setAccess(Object.assign({}, access, {
      unregisteredOpen: true,
      unregisteredPasswordHash: h,
    }));
    setAnonUnlocked(true);
    setPassRaw("");
    setPass2Raw("");
    setError("");
    addLog("opened an unregistered password-only deposit box");
  }

  function unlockUnregistered() {
    if (!access.unregisteredOpen) return;
    if (!passRaw) { setError("Enter the box password."); return; }
    if (hashVaultPassword(passRaw) !== String(access.unregisteredPasswordHash || "")) {
      setError("That password does not open this box.");
      setPassRaw("");
      return;
    }
    setAnonUnlocked(true);
    setPassRaw("");
    setError("");
    // Unlocking is intentionally not put in the narration log.
  }

  function depositMoney() {
    if (!boxOpen() || !boxUnlocked() || amt <= 0 || amt > purse) return;
    setPurse(purse - amt);
    if (box === "registered") setRegBal(regBal + amt);
    else setAnonBal(anonBal + amt);
    addLog("deposited " + amt + " stones into the " + (box === "registered" ? "registered account" : "unregistered box"));
    setAmtRaw("");
  }

  function withdrawMoney() {
    var bal = currentBalance();
    if (!boxOpen() || !boxUnlocked() || amt <= 0 || amt > bal) return;
    setPurse(purse + amt);
    if (box === "registered") setRegBal(regBal - amt);
    else setAnonBal(anonBal - amt);
    addLog("withdrew " + amt + " stones from the " + (box === "registered" ? "registered account" : "unregistered box"));
    setAmtRaw("");
  }

  function lodgeItem(id) {
    if (!boxOpen() || !boxUnlocked()) return;
    var found = null;
    var rest = [];
    pack.forEach(function (it) {
      if (!found && String(it.id) === String(id)) found = it;
      else rest.push(it);
    });
    if (!found || found.equipped === true) return;

    setPack(rest);
    if (box === "registered") setRegItems(regItems.concat([cloneVaultItem(found)]));
    else setAnonItems(anonItems.concat([cloneVaultItem(found)]));
    addLog('lodged "' + found.name + '" in the ' + (box === "registered" ? "registered box" : "unregistered box"));
  }

  function withdrawItem(id) {
    if (!boxOpen() || !boxUnlocked()) return;
    var list = currentItems();
    var found = null;
    var rest = [];
    list.forEach(function (it) {
      if (!found && String(it.id) === String(id)) found = it;
      else rest.push(it);
    });
    if (!found) return;

    setPack(pack.concat([cloneVaultItem(found)]));
    if (box === "registered") setRegItems(rest);
    else setAnonItems(rest);
    addLog('withdrew "' + found.name + '" from the ' + (box === "registered" ? "registered box" : "unregistered box"));
  }

  function changeHeir() {
    var nm = heirRaw.trim();
    if (!access.registeredOpen || !nm) return;
    setAccess(Object.assign({}, access, { registeredHeir: nm }));
    setHeirRaw("");
    addLog('named "' + nm + '" as heir on the registered account');
  }

  function finish() {
    if (!withClerk || !atBank) return;

    // Commit the staged visit atomically from the player's point of view.
    api.setVariable("mana-stones", purse);
    api.setVariable("inventory", pack);
    api.setVariable("registered-vault-balance", regBal);
    api.setVariable("unregistered-vault-balance", anonBal);
    api.setVariable("registered-vault-items", regItems);
    api.setVariable("unregistered-vault-items", anonItems);
    api.setVariable("vault-access", access);

    // Compatibility views for older rules/tools.
    api.setVariable("bank-balance", regBal + anonBal);
    api.setVariable("vault-items", regItems.concat(anonItems));
    api.setVariable("bank-account", {
      open: access.registeredOpen || access.unregisteredOpen,
      type: access.registeredOpen && access.unregisteredOpen ? "both" :
        access.unregisteredOpen ? "unregistered" :
        access.registeredOpen ? "registered" : "none",
      heir: access.registeredHeir || "",
    });

    var summary = sessionLog.length
      ? sessionLog.join("; ")
      : "made no transfers or account changes";

    api.injectContext(
      "[UI] ALMINUS COUNTER SESSION COMPLETE. The player " + summary + ". " +
      "Every money/item/account change listed here has ALREADY been applied by the interface. " +
      "Respond as the current bank clerk and surrounding world would naturally respond. Do not apply any transfer again. " +
      "Never mention or reveal the unregistered-box password or its stored hash.",
      { role: "system" }
    );
    api.sendMessage(
      sessionLog.length
        ? "[I finish at the Alminus counter after handling my vault business.]"
        : "[I finish at the Alminus counter without changing anything.]"
    );
    if (props.onClose) props.onClose();
  }

  function cancel() {
    // Nothing was committed. Closing the UI is equivalent to stepping away from
    // the paperwork before finalizing the counter session.
    if (props.onClose) props.onClose();
  }

  if (!atBank || !withClerk) {
    return (
      <Screen title="ALMINUS BANK / VAULT" onClose={props.onClose}>
        <Empty>
          This is not remote banking. Go to an Alminus counter and speak to a
          clerk or vault attendant first. Once they are the person in front of
          you, the counter interface opens for the visit.
        </Empty>
      </Screen>
    );
  }

  var activeBal = currentBalance();
  var activeItems = currentItems();
  var activeOpen = boxOpen();
  var activeUnlocked = boxUnlocked();

  return (
    <Screen title="ALMINUS COUNTER" onClose={cancel}>
      <div style={{ marginBottom: 10 }}>
        <div style={{ fontSize: 10, color: C.boneFaint, lineHeight: 1.65 }}>
          The clerk is in front of you. Use the counter controls for everything
          you want to do during this visit, then press FINISH AT COUNTER once.
        </div>
      </div>

      <Stat label="on your person" value={purse + " stones"} accent={C.brass} rule />
      <Stat label="registered vault" value={regBal + " stones"} rule />
      <Stat label="unregistered vault" value={access.unregisteredOpen ? anonBal + " stones" : "not opened"} rule />
      <Stat label="registered heir" value={access.registeredHeir || "none named"} dim={!access.registeredHeir} />

      <div style={{ display: "flex", gap: 8, marginTop: 13, marginBottom: 12 }}>
        <div style={{ flex: 1 }}>
          <Btn wide active={box === "registered"} onClick={function () { setBox("registered"); setError(""); }}>
            REGISTERED
          </Btn>
        </div>
        <div style={{ flex: 1 }}>
          <Btn wide active={box === "unregistered"} onClick={function () { setBox("unregistered"); setError(""); }}>
            UNREGISTERED
          </Btn>
        </div>
      </div>

      {box === "registered" && !access.registeredOpen ? (
        <Frame title="REGISTERED ACCOUNT">
          <div style={{ fontSize: 10, color: C.boneDim, lineHeight: 1.7, marginBottom: 9 }}>
            Filed under this body's legal identity. It can name an heir and it
            leaves an official record.
          </div>
          <Btn wide onClick={openRegistered}>OPEN REGISTERED ACCOUNT</Btn>
        </Frame>
      ) : null}

      {box === "unregistered" && !access.unregisteredOpen ? (
        <Frame title="CREATE UNREGISTERED BOX PASSWORD">
          <div style={{ fontSize: 10, color: C.boneDim, lineHeight: 1.7, marginBottom: 8 }}>
            This password is the only key. It is checked inside the interface
            and is never sent into narration.
          </div>
          <input
            type="password"
            value={passRaw}
            onChange={function (e) { setPassRaw(e.target.value); setError(""); }}
            placeholder="set password"
            autoComplete="new-password"
            style={{
              width:"100%", boxSizing:"border-box", fontFamily:MONO, fontSize:12,
              padding:"9px 11px", borderRadius:R.sm, background:C.void, color:C.bone,
              border:"1px solid "+C.rule, outline:"none", marginBottom:7,
            }}
          />
          <input
            type="password"
            value={pass2Raw}
            onChange={function (e) { setPass2Raw(e.target.value); setError(""); }}
            placeholder="type it again"
            autoComplete="new-password"
            style={{
              width:"100%", boxSizing:"border-box", fontFamily:MONO, fontSize:12,
              padding:"9px 11px", borderRadius:R.sm, background:C.void, color:C.bone,
              border:"1px solid "+C.rule, outline:"none", marginBottom:7,
            }}
          />
          {error ? <div style={{ color:C.bloodLit, fontSize:10, marginBottom:7 }}>{error}</div> : null}
          <Btn wide onClick={setUnregisteredPassword}>CREATE BOX &amp; SET PASSWORD</Btn>
        </Frame>
      ) : null}

      {box === "unregistered" && access.unregisteredOpen && !anonUnlocked ? (
        <Frame title="UNREGISTERED BOX — PASSWORD REQUIRED">
          <div style={{ fontSize: 10, color: C.boneDim, lineHeight: 1.7, marginBottom: 8 }}>
            Enter the same password you created for this box. A wrong entry
            unlocks nothing and changes nothing.
          </div>
          <input
            type="password"
            value={passRaw}
            onChange={function (e) { setPassRaw(e.target.value); setError(""); }}
            placeholder="box password"
            autoComplete="off"
            onKeyDown={function (e) { if (e.key === "Enter") unlockUnregistered(); }}
            style={{
              width:"100%", boxSizing:"border-box", fontFamily:MONO, fontSize:12,
              padding:"9px 11px", borderRadius:R.sm, background:C.void, color:C.bone,
              border:"1px solid "+C.rule, outline:"none", marginBottom:7,
            }}
          />
          {error ? <div style={{ color:C.bloodLit, fontSize:10, marginBottom:7 }}>{error}</div> : null}
          <Btn wide onClick={unlockUnregistered}>UNLOCK BOX</Btn>
        </Frame>
      ) : null}

      {activeOpen && activeUnlocked ? (
        <div>
          <div style={{ marginTop: 13 }}>
            <Frame title={box === "registered" ? "REGISTERED MONEY" : "UNREGISTERED MONEY"}>
              <Stat label="available here" value={activeBal + " stones"} accent={C.brassLit} rule />
              <div style={{ fontSize: 10, letterSpacing:"0.12em", color:C.boneFaint, margin:"9px 0 5px" }}>
                AMOUNT
              </div>
              <input
                value={amtRaw}
                onChange={function(e){setAmtRaw(e.target.value.replace(/[^0-9]/g,""));}}
                inputMode="numeric"
                placeholder="0"
                style={{
                  width:"100%", boxSizing:"border-box", fontFamily:MONO, fontSize:13,
                  padding:"9px 11px", borderRadius:R.sm, background:C.void, color:C.bone,
                  border:"1px solid "+C.rule, outline:"none", marginBottom:7,
                }}
              />
              <div style={{ display:"flex", gap:5, flexWrap:"wrap", marginBottom:8 }}>
                <Btn onClick={function(){setAmtRaw(String(purse));}}>ALL ON ME</Btn>
                <Btn onClick={function(){setAmtRaw(String(activeBal));}}>ALL IN THIS BOX</Btn>
                <Btn onClick={function(){setAmtRaw("");}}>CLEAR</Btn>
              </div>
              <div style={{ display:"flex", gap:8 }}>
                <div style={{ flex:1 }}>
                  <Btn wide onClick={depositMoney} disabled={amt<=0 || amt>purse}>DEPOSIT</Btn>
                </div>
                <div style={{ flex:1 }}>
                  <Btn wide onClick={withdrawMoney} disabled={amt<=0 || amt>activeBal}>WITHDRAW</Btn>
                </div>
              </div>
            </Frame>
          </div>

          {box === "registered" ? (
            <div style={{ marginTop:10 }}>
              <Frame title="REGISTERED HEIR">
                <input
                  value={heirRaw}
                  onChange={function(e){setHeirRaw(e.target.value);}}
                  placeholder={access.registeredHeir || "name an heir"}
                  style={{
                    width:"100%", boxSizing:"border-box", fontFamily:MONO, fontSize:12,
                    padding:"8px 11px", borderRadius:R.sm, background:C.void, color:C.bone,
                    border:"1px solid "+C.rule, outline:"none", marginBottom:7,
                  }}
                />
                <Btn wide onClick={changeHeir} disabled={!heirRaw.trim()}>SET HEIR</Btn>
              </Frame>
            </div>
          ) : null}

          <div style={{ marginTop:10 }}>
            <Frame title={box === "registered" ? "REGISTERED DEPOSIT BOX" : "UNREGISTERED DEPOSIT BOX"}>
              <div style={{ fontSize:10, color:C.boneDim, lineHeight:1.65, marginBottom:8 }}>
                Items move by stable physical id. Worn equipment cannot be lodged until you remove it.
              </div>

              {activeItems.length === 0 ? <Empty>This box is empty.</Empty> :
                activeItems.map(function(it, ix){
                  var x=obj_vault(it);
                  return <div key={String(x.id || ix)}
                    style={{display:"flex",alignItems:"center",gap:8,padding:"7px 0",borderBottom:"1px solid "+C.rule}}>
                    <span style={{flex:1,fontSize:11,color:C.bone}}>
                      {String(x.name||"—")}{num_vault(x.qty,1)>1?" ×"+num_vault(x.qty,1):""}
                    </span>
                    <Btn onClick={function(){withdrawItem(x.id);}}>WITHDRAW ITEM</Btn>
                  </div>;
                })
              }

              {lodgeable.length ? (
                <div style={{ marginTop:11 }}>
                  <div style={{fontSize:10,letterSpacing:"0.12em",color:C.boneFaint,marginBottom:5}}>YOUR INVENTORY</div>
                  {lodgeable.map(function(it, ix){
                    return <div key={String(it.id || ix)}
                      style={{display:"flex",alignItems:"center",gap:8,padding:"7px 0",borderBottom:"1px solid "+C.rule}}>
                      <span style={{flex:1,fontSize:11,color:C.boneDim}}>
                        {it.name}{num_vault(it.qty,1)>1?" ×"+num_vault(it.qty,1):""}
                      </span>
                      <Btn onClick={function(){lodgeItem(it.id);}}>DEPOSIT ITEM</Btn>
                    </div>;
                  })}
                </div>
              ) : null}
            </Frame>
          </div>
        </div>
      ) : null}

      <div style={{ marginTop:13 }}>
        <Frame title="THIS COUNTER VISIT">
          {sessionLog.length === 0 ? (
            <div style={{ fontSize:10, color:C.boneFaint }}>No changes yet.</div>
          ) : (
            sessionLog.map(function(line, ix){
              return <div key={ix} style={{fontSize:10,color:C.boneDim,lineHeight:1.6,borderBottom:"1px dotted "+C.rule,padding:"3px 0"}}>
                {ix+1}. {line}
              </div>;
            })
          )}
        </Frame>
      </div>

      <div style={{ display:"flex", gap:8, marginTop:12 }}>
        <div style={{ flex:1 }}>
          <Btn wide onClick={cancel}>CANCEL VISIT</Btn>
        </div>
        <div style={{ flex:2 }}>
          <Btn wide onClick={finish}>FINISH AT COUNTER</Btn>
        </div>
      </div>

      <div style={{ marginTop:8, fontSize:9, color:C.boneFaint, lineHeight:1.55 }}>
        Nothing is committed until FINISH AT COUNTER. Cancel closes the visit
        without moving money, items, heirs, or account state.
      </div>
    </Screen>
  );
}

// ==== party.tsx =================================================
// Five is the number. Dungeon & Stone was built around a full party of five,
// and the optimal five is mixed — a wall, something that kills, something that
// keeps everyone breathing, someone who can read the ground. Five of the same
// thing works right up until the thing it cannot do turns up.

var PARTY_MAX = 5;

function arr_party(v) { return Array.isArray(v) ? v : []; }
function obj_party(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }
function num_party(v, d) { return typeof v === "number" && isFinite(v) ? v : d; }

var TABS_party = ["PARTY", "BOARD", "AROUND"];

// Rank is a credential, not a measure of what someone can survive. Shown as
// the registry shows it, 9 up to 1, with the registry's own plain reading.
function rankWord(r) {
  var n = num_party(r, 9);
  if (n <= 2) return "apex — the registry barely has these";
  if (n <= 4) return "established";
  if (n <= 6) return "seasoned";
  if (n === 7) return "working explorer";
  if (n === 8) return "past the first year";
  return "newly registered";
}

function MemberRow(props) {
  var m = obj_party(props.member);
  var c = m.combat && typeof m.combat==="object" ? m.combat : {};
  var hasCombat = !!m.combat;
  var essence=partyEssenceTotals(m.essences);
  var gear=partyEquippedProfiles(m);
  return (
    <div
      className="ds-panel"
      style={{
        border: "1px solid " + (props.self ? C.brass : C.rule),
        borderRadius: R.md,
        background: props.self ? "rgba(201,162,39,0.06)" : C.panel,
        boxShadow: SH.panel,
        padding: 10,
        marginBottom: 8,
      }}
    >
      <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
        <span style={{ fontSize: 12, color: props.self ? C.brassLit : C.bone }}>
          {m.name || "—"}
        </span>
        <span style={{ flex: 1 }} />
        <span style={{ fontSize: 10, color: C.boneFaint }}>
          {props.self ? "you" : "rank " + num_party(m.rank, 9)}
        </span>
      </div>
      <div style={{ marginTop: 6 }}>
        <Chip>{m.race || "—"}</Chip>
        <Chip>{m.class || m.path || "—"}</Chip>
        {!props.self?<Chip>{m.combatRole||partyRoleKind(m)}</Chip>:null}
        {!props.self?<Chip>{partyPersonalityTags(normalizePartyPersonality(m)).slice(0,2).join(" · ")||"mixed"}</Chip>:null}
        <Chip>{"age " + (m.age === 0 || m.age ? m.age : "—")}</Chip>
      </div>

      {hasCombat ? (
        <div style={{marginTop:8,paddingTop:7,borderTop:"1px dotted "+C.rule}}>
          {partyResourceBar("CONDITION",c.condition,c.conditionMax,C.bloodLit)}
          {partyResourceBar("STAMINA",c.stamina,c.staminaMax,C.brass)}
          {(Number(c.manaMax)||0)>0 ? partyResourceBar("SPIRIT / MANA",c.mana,c.manaMax,C.boneDim) : null}
          <div style={{display:"flex",gap:6,flexWrap:"wrap",marginTop:6}}>
            <Chip color={String(c.status||"ready").toLowerCase()==="ready"?C.bone:C.bloodLit} border={C.rule}>
              {String(c.status||"ready").toUpperCase()}
            </Chip>
            {!props.self?<Chip>{gear.worn.length+" equipped"}</Chip>:null}
            {!props.self?<Chip>{essence.weight+" / "+Math.max(1,Number(m.essenceCapacity)||1)+" essence"}</Chip>:null}
          </div>
          {!props.self && Array.isArray(c.injuries) && c.injuries.length ? (
            <div style={{fontSize:9,color:C.bloodLit,marginTop:5}}>
              injuries — {c.injuries.join(", ")}
            </div>
          ) : null}
        </div>
      ) : null}

      {m.notes ? (
        <div style={{ fontSize: 10, lineHeight: 1.6, color: C.boneDim, marginTop: 6 }}>
          {m.notes}
        </div>
      ) : null}
      {m.fee ? (
        <div style={{ fontSize: 10, color: C.boneFaint, marginTop: 4 }}>
          terms — {m.fee}
        </div>
      ) : null}
      {!props.self && props.onManage ? (
        <div style={{ marginTop: 8, display:"flex", gap:6, flexWrap:"wrap" }}>
          <Btn onClick={props.onManage}>OPEN SHEET</Btn>
          {props.onDrop ? <Btn onClick={props.onDrop}>PART WAYS</Btn> : null}
        </div>
      ) : props.onDrop ? (
        <div style={{ marginTop: 8 }}><Btn onClick={props.onDrop}>PART WAYS</Btn></div>
      ) : null}
    </div>
  );
}


function partyStableId(m, i) {
  if (m && m.id) return String(m.id);
  var base = String((m && m.name) || "member").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  return "party-" + (base || "member") + "-" + String(i == null ? 0 : i);
}
function partyRoleKind(m) {
  var s = String(((m && m.role) || "") + " " + ((m && m.class) || "") + " " + ((m && m.notes) || "")).toLowerCase();
  if (/healer|healing|priest|cleric|support|divine|medic/.test(s)) return "support";
  if (/tank|shield|guardian|defender|frontline|protector/.test(s)) return "tank";
  if (/mage|wizard|sorcer|caster|spell|elemental/.test(s)) return "caster";
  if (/archer|ranger|bow|crossbow|marksman/.test(s)) return "ranged";
  if (/scout|rogue|assassin|skirmish/.test(s)) return "skirmisher";
  return "damage";
}
function partyRankPower(rank) {
  var r=Math.max(1,Math.min(9,Number(rank)||9));
  return 10-r; // rank 9 -> 1, rank 1 -> 9. Simulation scale only.
}
function normalizePartyCombatMember(m, i) {
  var r=Object.assign({},m||{});
  r.id=partyStableId(r,i);
  var kind=partyRoleKind(r);
  r.combatRole=String(r.combatRole||kind);
  var p=partyRankPower(r.rank);
  var c=(r.combat && typeof r.combat==="object")?Object.assign({},r.combat):{};
  var manaClass=(kind==="support"||kind==="caster");
  c.conditionMax=Math.max(1,Number(c.conditionMax)||100);
  c.condition=Math.max(0,Math.min(c.conditionMax,Number(c.condition==null?c.conditionMax:c.condition)));
  c.staminaMax=Math.max(1,Number(c.staminaMax)||100);
  c.stamina=Math.max(0,Math.min(c.staminaMax,Number(c.stamina==null?c.staminaMax:c.stamina)));
  c.manaMax=Math.max(0,Number(c.manaMax==null?(manaClass ? 30+p*5 : 0):c.manaMax));
  c.mana=Math.max(0,Math.min(c.manaMax,Number(c.mana==null?c.manaMax:c.mana)));
  c.status=String(c.status || (c.condition<=0?"down":"ready"));
  c.injuries=Array.isArray(c.injuries)?c.injuries:[];
  r.inventory=normalizeList(Array.isArray(r.inventory)?r.inventory:(Array.isArray(r.equipment)?r.equipment:[]));
  r.essences=Array.isArray(r.essences)?r.essences:[];
  r.personality=normalizePartyPersonality(r);
  r.personalStones=Math.max(0,Number(r.personalStones==null?(2500+partyRankPower(r.rank)*4500):r.personalStones)||0);
  r.lifeState=normalizeCompanionLife(r);
  var et=partyEssenceTotals(r.essences);
  r.essenceCapacity=Math.max(1,Number(r.essenceCapacity)||Math.max(1,et.weight));
  // Essence-granted spirit is a live addition to this member's mana ceiling.
  var baseManaMax=Math.max(0,Number(c.baseManaMax==null?c.manaMax:c.baseManaMax)||0);
  if(c.baseManaMax==null)c.baseManaMax=baseManaMax;
  c.manaMax=Math.max(0,baseManaMax+et.mods.spiritFlat);
  c.mana=Math.max(0,Math.min(c.manaMax,Number(c.mana==null?c.manaMax:c.mana)));
  r.combat=c;
  return r;
}


function stablePartyHash(s){
  s=String(s||"member");var h=2166136261>>>0;
  for(var i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)>>>0;}
  return h>>>0;
}
function defaultPartyPersonality(m){
  var seed=stablePartyHash(String((m&&m.id)||"")+"|"+String((m&&m.name)||"")+"|"+String((m&&m.race)||"")+"|"+String((m&&m.class)||""));
  function val(shift){return 20+((seed>>>shift)%61);} // 20..80, stable per person.
  var p={
    aggression:val(0), caution:val(3), discipline:val(6), altruism:val(9),
    independence:val(12), frugality:val(15), ambition:val(18), loyalty:val(21)
  };
  var role=partyRoleKind(m);
  if(role==="tank"){p.caution=Math.max(p.caution,55);p.discipline=Math.max(p.discipline,55);}
  if(role==="support"){p.altruism=Math.max(p.altruism,60);p.aggression=Math.min(p.aggression,55);}
  if(role==="skirmisher"){p.independence=Math.max(p.independence,55);}
  if(/barbar|berserk/.test(String((m&&m.class)||"").toLowerCase()))p.aggression=Math.max(p.aggression,70);
  return p;
}
function normalizePartyPersonality(m){
  var raw=m&&m.personality&&typeof m.personality==="object"?m.personality:{};
  var d=defaultPartyPersonality(m), p={};
  Object.keys(d).forEach(function(k){p[k]=Math.max(0,Math.min(100,Number(raw[k]==null?d[k]:raw[k])||0));});
  p.traits=Array.isArray(raw.traits)?raw.traits.slice(0,5):[];
  p.fears=Array.isArray(raw.fears)?raw.fears.slice(0,4):[];
  p.likes=Array.isArray(raw.likes)?raw.likes.slice(0,4):[];
  p.dislikes=Array.isArray(raw.dislikes)?raw.dislikes.slice(0,4):[];
  p.combatStyle=String(raw.combatStyle||"");
  return p;
}
function partyPersonalityTags(p){
  var tags=[];
  if(p.aggression>=70)tags.push("aggressive"); else if(p.aggression<=35)tags.push("reserved");
  if(p.caution>=70)tags.push("cautious"); else if(p.caution<=35)tags.push("reckless");
  if(p.discipline>=70)tags.push("disciplined"); else if(p.discipline<=35)tags.push("impulsive");
  if(p.altruism>=70)tags.push("selfless"); else if(p.altruism<=35)tags.push("self-interested");
  if(p.independence>=70)tags.push("independent");
  if(p.frugality>=70)tags.push("frugal"); else if(p.frugality<=35)tags.push("spendthrift");
  if(p.ambition>=70)tags.push("ambitious");
  if(p.loyalty>=70)tags.push("loyal");
  return tags.slice(0,4);
}

function companionGoalDefaults(m){
  var p=normalizePartyPersonality(m), role=partyRoleKind(m);
  var goals=[];
  if(p.ambition>=55)goals.push({id:"gear-upgrade",kind:"gear",horizon:"medium",title:"Improve expedition equipment",priority:55+p.ambition*0.3,status:"active",progress:0});
  if(p.discipline>=55)goals.push({id:"training",kind:"training",horizon:"long",title:"Improve combat readiness",priority:45+p.discipline*0.35,status:"active",progress:0});
  if(p.frugality>=55)goals.push({id:"savings",kind:"finance",horizon:"medium",title:"Build personal savings",priority:40+p.frugality*0.35,status:"active",progress:0});
  if(p.altruism>=65)goals.push({id:"party-care",kind:"relationship",horizon:"short",title:"Keep the party safe and supplied",priority:45+p.altruism*0.35,status:"active",progress:0});
  if(!goals.length)goals.push({id:"stability",kind:"life",horizon:"medium",title:"Maintain a stable explorer life",priority:50,status:"active",progress:0});
  return goals;
}
function normalizeCompanionLife(m){
  var ls=m&&m.lifeState&&typeof m.lifeState==="object"?Object.assign({},m.lifeState):{};
  ls.lastSurfaceDay=String(ls.lastSurfaceDay||"");
  ls.lastActivity=String(ls.lastActivity||"");
  ls.personalGoal=String(ls.personalGoal||"");
  ls.available=ls.available!==false;
  ls.goals=Array.isArray(ls.goals)&&ls.goals.length?ls.goals:companionGoalDefaults(m);
  ls.plans=Array.isArray(ls.plans)?ls.plans:[];
  ls.obligations=Array.isArray(ls.obligations)?ls.obligations:[];
  ls.relationships=ls.relationships&&typeof ls.relationships==="object"?ls.relationships:{};
  ls.privateKnowledge=Array.isArray(ls.privateKnowledge)?ls.privateKnowledge:[];
  ls.knownToPlayer=Array.isArray(ls.knownToPlayer)?ls.knownToPlayer:[];
  ls.history=Array.isArray(ls.history)?ls.history.slice(-60):[];
  ls.lastProcessedOrdinal=Number(ls.lastProcessedOrdinal||0);
  return ls;
}
function companionDayOrdinal(v){
  var st=v["surface-time"]||{};
  if(st.absoluteMinute!=null) return Math.max(1,Math.floor(Number(st.absoluteMinute)/1440));
  var y=Math.max(1,Number(st.year||1)),m=Math.max(1,Number(st.month||v["cycle-month"]||1)),d=Math.max(1,Number(st.day||v["cycle-day"]||1));
  return (((y*13)+m)*40)+d;
}
function companionGoalScore(g,m){
  var p=normalizePartyPersonality(m), score=Number(g.priority||50);
  if(g.kind==="gear")score+=p.ambition*.25+p.aggression*.08;
  if(g.kind==="finance")score+=p.frugality*.3;
  if(g.kind==="training")score+=p.discipline*.3+p.ambition*.12;
  if(g.kind==="relationship")score+=p.altruism*.25+p.loyalty*.2;
  return score;
}
function chooseCompanionGoal(m){
  var ls=normalizeCompanionLife(m), active=ls.goals.filter(function(g){return g&&g.status!=="complete"&&g.status!=="abandoned";});
  active.sort(function(a,b){return companionGoalScore(b,m)-companionGoalScore(a,m);});
  return active[0]||null;
}
function processCompanionLifeDay(m,v,ordinal){
  m=normalizePartyCombatMember(m,0);
  var ls=normalizeCompanionLife(m), p=normalizePartyPersonality(m), goal=chooseCompanionGoal(m);
  var seed=stablePartyHash(String(m.id)+"|life|"+ordinal), event={ordinal:ordinal,private:true,summary:""};
  var life=partySurfaceLifeCandidate(m,v), purchase=null;

  // Due obligations take precedence.
  var due=ls.obligations.find(function(o){return o&&o.status!=="complete"&&Number(o.dueOrdinal||0)>0&&Number(o.dueOrdinal)<=ordinal;});
  if(due){
    due.status="complete";
    event.summary="Handled obligation: "+String(due.title||due.kind||"personal business");
    if(due.cost){m.personalStones=Math.max(0,Number(m.personalStones||0)-Math.max(0,Number(due.cost)||0));}
  } else if(goal&&goal.kind==="gear"&&life.budget>0){
    var kind=life.preferWeapon?"weapon":"armor";
    purchase=makeCompanionPurchase(m,v,kind,"o"+ordinal);
    if(purchase){
      m.personalStones=Math.max(0,life.purse-purchase.price);
      m.inventory=addItem(m.inventory,purchase.item);
      try{m.inventory=setEquipped(m.inventory,purchase.item.id,true);}catch(_e){}
      goal.progress=Math.min(100,Number(goal.progress||0)+55);
      if(goal.progress>=100)goal.status="complete";
      event.summary="Bought "+purchase.item.name+" for "+purchase.price+" stones";
    }
  }
  if(!event.summary&&goal&&goal.kind==="training"){
    goal.progress=Math.min(100,Number(goal.progress||0)+(4+seed%8));
    event.summary="Trained toward "+goal.title;
    if(goal.progress>=100)goal.status="complete";
  }
  if(!event.summary&&goal&&goal.kind==="finance"){
    var earned=1000+(seed%5000);
    m.personalStones=Math.max(0,Number(m.personalStones||0)+earned);
    goal.progress=Math.min(100,Number(goal.progress||0)+5);
    event.summary="Took personal work and saved "+earned+" stones";
  }
  if(!event.summary&&goal&&goal.kind==="relationship"){
    goal.progress=Math.min(100,Number(goal.progress||0)+4);
    event.summary="Spent time helping or checking on people they care about";
  }
  if(!event.summary){
    var choices=p.independence>=65?["handled private errands","visited personal contacts","spent time alone on personal business"]:
      p.discipline>=60?["maintained equipment and trained","rested and prepared carefully"]:
      ["rested, ate, socialized, and handled ordinary errands"];
    event.summary=choices[seed%choices.length];
  }

  // Re-evaluate completed goals instead of freezing.
  ls.goals=ls.goals.map(function(g){return g&&g.id===goal?.id?goal:g;});
  if(goal&&goal.status==="complete"){
    ls.history.push({ordinal:ordinal,private:true,summary:"Completed goal: "+goal.title});
    ls.goals=ls.goals.concat([{id:"next-"+ordinal+"-"+(seed%9999),kind:p.frugality>=p.ambition?"finance":"training",
      horizon:"medium",title:p.frugality>=p.ambition?"Strengthen personal finances":"Continue personal improvement",
      priority:45+(seed%30),status:"active",progress:0}]);
  }
  ls.lastActivity=event.summary;
  ls.history.push(event); ls.history=ls.history.slice(-60);
  ls.lastProcessedOrdinal=ordinal;
  m.lifeState=ls;
  return m;
}

function partySurfaceLifeCandidate(m,v){
  var p=normalizePartyPersonality(m), rank=partyRankPower(m.rank), inv=normalizeList(m.inventory);
  var gear=partyEquippedProfiles(m), purse=Math.max(0,Number(m.personalStones)||0);
  var weapon=gear.weapon, armor=gear.armor||[];
  var currentWeaponValue=weapon?Math.max(1,Number(weapon.referenceValue||weapon.value||weapon.power*5000)||0):0;
  var currentArmorValue=armor.reduce(function(s,a){return s+Math.max(1,Number(a.value||a.referenceValue||0));},0);
  var saveFloor=Math.round(purse*(0.15+0.55*(p.frugality/100)));
  var budget=Math.max(0,purse-saveFloor);
  var wantWeapon=!weapon || (p.aggression+p.ambition>115 && budget>8000);
  var wantArmor=armor.length<2 || (p.caution+p.discipline>115 && budget>10000);
  var preferWeapon=wantWeapon && (!wantArmor || p.aggression>=p.caution);
  return {personality:p,purse:purse,budget:budget,wantWeapon:wantWeapon,wantArmor:wantArmor,preferWeapon:preferWeapon,
    currentWeaponValue:currentWeaponValue,currentArmorValue:currentArmorValue,rankPower:rank};
}
function makeCompanionPurchase(m,v,kind,dayKey){
  var life=partySurfaceLifeCandidate(m,v), p=life.personality;
  if(life.budget<=0)return null;
  var rp=life.rankPower;
  var quality=p.ambition>=70?"fine":p.frugality>=70?"serviceable":"standard";
  var base=kind==="weapon"?(9000+rp*6500):(11000+rp*7000);
  var market=marketMultiplier(v,kind==="weapon"?"weapons":"armor",String(v["location"]||""));
  var price=Math.max(1000,Math.round(base*market*(quality==="fine"?1.35:quality==="serviceable"?0.8:1)));
  if(price>life.budget)return null;
  var seed=stablePartyHash(String(m.id)+"|"+dayKey+"|"+kind);
  var weaponNames=["Sword","Axe","Spear","Mace","Dagger","Bow","Warhammer"];
  var armorNames=["Padded Coat","Leather Jack","Mail Shirt","Iron Helm","Round Shield","Brigandine Vest"];
  var name=(kind==="weapon"?weaponNames:armorNames)[seed%(kind==="weapon"?weaponNames.length:armorNames.length)];
  var item={
    id:"companion-buy-"+String(m.id)+"-"+String(dayKey)+"-"+kind,
    name:quality.charAt(0).toUpperCase()+quality.slice(1)+" "+name,
    type:kind==="weapon"?"weapon":"armor",
    qty:1,value:price,price:price,quality:quality,ownerId:m.id,ownerName:m.name,
    description:"Purchased independently by "+m.name+" during surface life.",
    slot: kind==="weapon" ? "main-hand" : (/shield/i.test(name)?"off-hand":/helm/i.test(name)?"head":"torso"),
    equipped:false
  };
  return {item:item,price:price,kind:kind};
}

function partyEssenceWeight(e) {
  if (!e) return 0;
  if (e.weight != null) return Math.max(0, Number(e.weight)||0);
  var rank=Math.max(1,Math.min(9,Number(e.rank)||9));
  var base=rank>=8?1:rank>=6?2:rank>=4?3:rank>=2?4:5;
  return base + (e.guardian===true?1:0);
}
function partyEssenceTotals(list) {
  var es=Array.isArray(list)?list:[];
  var mods={strength:0,flexibility:0,vision:0,smell:0,accuracy:0,spiritFlat:0};
  var weight=0;
  es.forEach(function(e){
    weight+=partyEssenceWeight(e);
    var m=e&&e.statMods&&typeof e.statMods==="object"?e.statMods:{};
    Object.keys(mods).forEach(function(k){ mods[k]+=Number(m[k])||0; });
  });
  return {weight:weight,mods:mods};
}
function partyEquippedProfiles(m) {
  var inv=normalizeList((m&&m.inventory)||[]);
  var worn=inv.filter(function(it){return it&&it.equipped===true;});
  var weapons=worn.map(function(it){return weaponGameplayProfile(it);}).filter(Boolean);
  var armor=worn.map(function(it){return armorGameplayProfile(it);}).filter(Boolean);
  var main=null;
  for(var i=0;i<weapons.length;i++){ if(weapons[i].slot==="main-hand"){main=weapons[i];break;} }
  if(!main&&weapons.length)main=weapons[0];
  return {inventory:inv,worn:worn,weapon:main,armor:armor};
}
function partyProtectionScore(profiles) {
  var total=0;
  (profiles&&profiles.armor||[]).forEach(function(a){
    var p=a&&a.protection&&typeof a.protection==="object"?a.protection:{};
    Object.keys(p).forEach(function(k){ total+=Number(p[k])||0; });
    total+=Number(a.block)||0;
  });
  return Math.round(total);
}
function partyGearPower(m) {
  var p=partyEquippedProfiles(m);
  return p.weapon ? Math.max(0,Number(p.weapon.power)||0) : 3;
}
function partyResourceBar(label, cur, max, accent) {
  max=Math.max(1,Number(max)||1); cur=Math.max(0,Math.min(max,Number(cur)||0));
  var pct=Math.round(cur/max*100);
  return (
    <div style={{marginTop:5}}>
      <div style={{display:"flex",justifyContent:"space-between",fontSize:9,color:C.boneFaint}}>
        <span>{label}</span><span style={{fontVariantNumeric:"tabular-nums"}}>{Math.round(cur)+" / "+Math.round(max)}</span>
      </div>
      <div style={{height:5,background:C.void,border:"1px solid "+C.rule,marginTop:2}}>
        <div style={{height:"100%",width:pct+"%",background:accent||C.brass}} />
      </div>
    </div>
  );
}

function partyConditionBand(c) {
  var cur=Number(c && c.condition)||0, max=Math.max(1,Number(c && c.conditionMax)||100);
  var p=cur/max;
  if(p<=0)return "down";
  if(p<=0.25)return "reeling";
  if(p<=0.5)return "badly hurt";
  if(p<=0.75)return "wounded";
  return "unharmed";
}
function partyCombatPacket(roster, enemies, playerKind) {
  var next=(Array.isArray(roster)?roster:[]).map(function(m,i){return normalizePartyCombatMember(m,i);});
  var packets=[];
  var livingEnemies=(Array.isArray(enemies)?enemies:[]).filter(function(e){
    var b=String((e&&(e.conditionBand||e.condition))||"").toLowerCase();
    return b!=="down" && b!=="dead" && b!=="killed";
  });
  next.forEach(function(m,idx){
    var c=m.combat||{};
    if(c.condition<=0 || /dead|down|unconscious/.test(String(c.status).toLowerCase())){
      packets.push({memberId:m.id,name:m.name,role:m.combatRole,action:"unable",reason:c.status||"down"});
      return;
    }
    var role=partyRoleKind(m), p=partyRankPower(m.rank);
    var personality=normalizePartyPersonality(m);
    var essence=partyEssenceTotals(m.essences);
    var gear=partyEquippedProfiles(m);
    var weaponPower=partyGearPower(m);
    var protection=partyProtectionScore(gear);
    var physicalBonus=(Number(essence.mods.strength)||0)+(Number(essence.mods.accuracy)||0)*0.35;
    var target=livingEnemies.length?livingEnemies[idx%livingEnemies.length]:null;
    var condRatio=(Number(c.condition)||0)/Math.max(1,Number(c.conditionMax)||100);
    var staminaRatio=(Number(c.stamina)||0)/Math.max(1,Number(c.staminaMax)||100);
    var personalityIntent =
      (condRatio<0.35 && personality.caution>=60) ? "survive/withdraw" :
      (role==="tank" && personality.altruism>=65 && condRatio>0.3) ? "protect ally" :
      (personality.aggression>=70 && staminaRatio>0.2) ? "press attack" :
      (personality.discipline>=70 && staminaRatio<0.35) ? "conserve resources" :
      "role default";

    if(role==="support"){
      var hurtIndex=-1, hurtRatio=2;
      next.forEach(function(x,j){
        var xc=x.combat||{}, ratio=(Number(xc.condition)||0)/Math.max(1,Number(xc.conditionMax)||100);
        if((Number(xc.condition)||0)>0 && ratio<hurtRatio){hurtRatio=ratio;hurtIndex=j;}
      });
      if(hurtIndex>=0 && hurtRatio<0.82 && c.mana>=8){
        var heal=10+Math.min(10,p*2);
        var hc=next[hurtIndex].combat;
        hc.condition=Math.min(hc.conditionMax,hc.condition+heal);
        c.mana=Math.max(0,c.mana-8);
        packets.push({memberId:m.id,name:m.name,role:"support",action:"heal",target:next[hurtIndex].name,
          amount:heal,manaSpent:8,remainingMana:c.mana,essenceMods:essence.mods,
          essences:(m.essences||[]).map(function(e){return {source:e.source||e.name,abilities:e.abilities||[]};})});
      }else if(c.mana>=4){
        c.mana=Math.max(0,c.mana-4);
        packets.push({memberId:m.id,name:m.name,role:"support",action:"support",target:target&&target.name,
          manaSpent:4,remainingMana:c.mana,detail:"buff, control, ward, or assistance appropriate to actual skills"});
      }else{
        var scost=4;
        c.stamina=Math.max(0,c.stamina-scost);
        packets.push({memberId:m.id,name:m.name,role:"support",action:"fallback attack",target:target&&target.name,
          staminaSpent:scost,remainingStamina:c.stamina});
      }
    }else if(role==="caster"){
      if(c.mana>=8){
        c.mana=Math.max(0,c.mana-8);
        packets.push({memberId:m.id,name:m.name,role:"caster",action:"cast",target:target&&target.name,
          manaSpent:8,remainingMana:c.mana,powerBand:p,essenceMods:essence.mods,
          essences:(m.essences||[]).map(function(e){return {source:e.source||e.name,rank:e.rank,abilities:e.abilities||[]};})});
      }else{
        c.stamina=Math.max(0,c.stamina-4);
        packets.push({memberId:m.id,name:m.name,role:"caster",action:"fallback physical action",target:target&&target.name,
          staminaSpent:4,remainingStamina:c.stamina,powerBand:p});
      }
    }else if(role==="tank"){
      var tcost=Math.max(2,Math.round(4+(gear.weapon?Number(gear.weapon.staminaCost||0)*0.25:0)));
      c.stamina=Math.max(0,c.stamina-tcost);
      packets.push({memberId:m.id,name:m.name,role:"tank",action:"guard/intercept",target:target&&target.name,
        staminaSpent:tcost,remainingStamina:c.stamina,powerBand:p,protectionScore:protection,
        equippedArmor:gear.armor,equippedWeapon:gear.weapon,essenceMods:essence.mods,
        detail:"protect allies, hold space, intercept attacks when physically plausible"});
    }else{
      var baseCost=gear.weapon?Math.max(1,Number(gear.weapon.staminaCost)||1):(role==="ranged"?5:role==="skirmisher"?6:7);
      var cost=Math.max(1,Math.round(baseCost));
      c.stamina=Math.max(0,c.stamina-cost);
      packets.push({memberId:m.id,name:m.name,role:role,action:"attack",target:target&&target.name,
        staminaSpent:cost,remainingStamina:c.stamina,powerBand:p,
        weaponPower:weaponPower,physicalBonus:physicalBonus,equippedWeapon:gear.weapon,
        essenceMods:essence.mods,essenceAbilities:(m.essences||[]).map(function(e){return e.abilities||[];})});
    }
  });
  packets=packets.map(function(pkt){
    var mm=next.find(function(x){return x&&pkt&&String(x.id)===String(pkt.memberId);});
    var pp=normalizePartyPersonality(mm||{});
    return Object.assign({},pkt,{
      personalityIntent: pkt.action==="unable" ? "unable" : (
        ((mm&&mm.combat&&Number(mm.combat.condition)<35)&&pp.caution>=60)?"survive/withdraw":
        (pp.aggression>=70?"press advantage":
        (pp.discipline>=70?"controlled/efficient":
        (pp.altruism>=70?"protective/team-first":"role default")))
      ),
      personality: {aggression:pp.aggression,caution:pp.caution,discipline:pp.discipline,
        altruism:pp.altruism,independence:pp.independence,loyalty:pp.loyalty,
        traits:partyPersonalityTags(pp),combatStyle:pp.combatStyle}
    });
  });
  return {roster:next,packets:packets};
}


function PartyMemberSheet(props) {
  var api=useYumina();
  var v=api.variables||{};
  var roster=arr_party(v["party"]);
  var index=props.index;
  if(index==null||index<0||index>=roster.length)return null;
  var member=normalizePartyCombatMember(roster[index],index);
  var c=member.combat||{};
  var inv=normalizeList(member.inventory);
  var playerInv=normalizeList(v["inventory"]);
  var es=Array.isArray(member.essences)?member.essences:[];
  var et=partyEssenceTotals(es);
  var gear=partyEquippedProfiles(member);
  var s=React.useState("STATUS"), tab=s[0],setTab=s[1];

  function writeMember(next, note){
    var nr=roster.slice();
    nr[index]=normalizePartyCombatMember(next,index);
    api.setVariable("party",nr);
    if(note)api.injectContext("[UI PHYSICAL ACTION — ALREADY APPLIED] "+note+" Do not duplicate the transfer or equipment change.",{role:"system"});
  }
  function giveItem(id){
    var item=byId(playerInv,id);
    if(!item)return;
    if(item.equipped===true){api.injectContext("[UI] Unequip "+item.name+" before giving it away.",{role:"system"});return;}
    if(item.soulbound===true){api.injectContext("[UI] "+item.name+" is bound and cannot be transferred.",{role:"system"});return;}
    var nextPlayer=removeItem(playerInv,id,item.qty||1);
    var nextMember=Object.assign({},member,{inventory:addItem(inv,Object.assign({},item,{equipped:false,placement:{kind:"loose"}}))});
    api.setVariable("inventory",nextPlayer);
    writeMember(nextMember,"The player handed "+item.name+" to "+member.name+". Ownership and physical possession moved to that companion.");
  }
  function takeItem(id){
    var item=byId(inv,id);
    if(!item)return;
    if(item.equipped===true){api.injectContext("[UI] "+member.name+" must unequip "+item.name+" before handing it over.",{role:"system"});return;}
    if(item.soulbound===true){api.injectContext("[UI] "+item.name+" is bound to "+member.name+" and cannot be transferred.",{role:"system"});return;}
    var nextInv=removeItem(inv,id,item.qty||1);
    var nextMember=Object.assign({},member,{inventory:nextInv});
    api.setVariable("inventory",addItem(playerInv,Object.assign({},item,{equipped:false,placement:{kind:"loose"}})));
    writeMember(nextMember,member.name+" handed "+item.name+" to the player. Physical possession moved; no copy remains.");
  }
  function toggleEquip(id){
    var item=byId(inv,id); if(!item)return;
    if(!isWearable(item.slot)&&item.slot!=="talisman"){
      api.injectContext("[UI] "+item.name+" is not wearable equipment.",{role:"system"});return;
    }
    var nextInv=setEquipped(inv,id,item.equipped!==true);
    writeMember(Object.assign({},member,{inventory:nextInv}),
      member.name+" "+(item.equipped===true?"unequipped ":"equipped ")+item.name+".");
  }
  function askUse(id){
    var item=byId(inv,id); if(!item)return;
    api.injectContext("[UI] "+member.name+" physically possesses "+item.name+". If its use is valid, resolve the real effect and file any resulting companion damage/heal/status/resource change through party-combat-events. If consumed, also file an item-loss through party-progression-events.",{role:"system"});
    api.sendMessage("[I tell "+member.name+" to use "+item.name+" if it makes sense here.]");
  }

  return (
    <div>
      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
        <Btn onClick={props.onBack}>← PARTY</Btn>
        <div style={{fontSize:13,color:C.brassLit,letterSpacing:"0.08em"}}>{member.name}</div>
      </div>
      <div style={{display:"flex",gap:5,flexWrap:"wrap",marginBottom:10}}>
        {["STATUS","GOALS","PERSONALITY","EQUIPMENT","PACK","ESSENCES"].map(function(x){return <Btn key={x} onClick={function(){setTab(x);}} active={tab===x}>{x}</Btn>;})}
      </div>

      {tab==="STATUS"?<div>
        {partyResourceBar("CONDITION",c.condition,c.conditionMax,C.bloodLit)}
        {partyResourceBar("STAMINA",c.stamina,c.staminaMax,C.brass)}
        {(Number(c.manaMax)||0)>0?partyResourceBar("SPIRIT / MANA",c.mana,c.manaMax,C.boneDim):<Stat label="spirit / mana" value="none established" />}
        <Stat label="status" value={String(c.status||"ready")} rule />
        <Stat label="combat role" value={member.combatRole||partyRoleKind(member)} />
        <Stat label="personality" value={partyPersonalityTags(normalizePartyPersonality(member)).join(", ")||"mixed"} />
        <Stat label="personal purse" value={Math.round(Number(member.personalStones)||0)+" stones"} />
        <Stat label="last personal activity" value={String(member.lifeState&&member.lifeState.lastActivity||"none recorded")} />
        <Stat label="equipped pieces" value={String(gear.worn.length)} />
        <Stat label="essence load" value={et.weight+" / "+Math.max(1,Number(member.essenceCapacity)||1)} />
        {c.injuries&&c.injuries.length?<div style={{marginTop:8,fontSize:10,color:C.bloodLit}}>INJURIES — {c.injuries.join(", ")}</div>:<Empty>No persistent injury recorded.</Empty>}
      </div>:null}

      {tab==="GOALS"?<div>
        {(member.lifeState&&Array.isArray(member.lifeState.goals)?member.lifeState.goals:[]).map(function(g,i){
          return <div key={g.id||i} style={{border:"1px solid "+C.rule,padding:8,marginBottom:6,background:C.panel}}>
            <div style={{display:"flex",gap:8}}><span style={{color:C.bone}}>{g.title||"Personal goal"}</span><span style={{flex:1}}/><span style={{fontSize:9,color:C.boneFaint}}>{g.horizon||"—"}</span></div>
            <div style={{fontSize:9,color:C.boneDim,marginTop:4}}>{String(g.status||"active")+" · "+Math.round(Number(g.progress)||0)+"%"}</div>
          </div>;
        })}
        <Empty>This sheet is an engine/debug view of persistent companion goals. In narration, private goals and history remain unknown until the player actually learns them.</Empty>
      </div>:null}

      {tab==="PERSONALITY"?<div>
        {Object.entries(normalizePartyPersonality(member)).filter(function(x){return typeof x[1]==="number";}).map(function(x){
          return <div key={x[0]} style={{marginBottom:7}}>
            <div style={{display:"flex",justifyContent:"space-between",fontSize:9,color:C.boneFaint}}><span>{String(x[0]).toUpperCase()}</span><span>{Math.round(Number(x[1]))}</span></div>
            <div style={{height:5,background:C.void,border:"1px solid "+C.rule,marginTop:2}}><div style={{height:"100%",width:Math.max(0,Math.min(100,Number(x[1])))+"%",background:C.brass}} /></div>
          </div>;
        })}
        <Empty>These traits influence independent spending, risk tolerance, resource conservation, protection of allies, and combat style. They are persistent personality simulation values, not public canon statistics.</Empty>
      </div>:null}

      {tab==="EQUIPMENT"?<div>
        {inv.filter(function(it){return isWearable(it.slot)||it.slot==="talisman";}).length===0?<Empty>{member.name+" carries no wearable equipment."}</Empty>:
        inv.filter(function(it){return isWearable(it.slot)||it.slot==="talisman";}).map(function(it){
          var wp=weaponGameplayProfile(it), ap=armorGameplayProfile(it);
          return <div key={it.id} style={{border:"1px solid "+(it.equipped?C.brass:C.rule),padding:8,marginBottom:6,background:C.panel}}>
            <div style={{display:"flex",gap:8}}><span style={{color:C.bone}}>{it.name}</span><span style={{flex:1}}/><span style={{fontSize:9,color:C.boneFaint}}>{it.slot}</span></div>
            {wp?<div style={{fontSize:9,color:C.boneDim,marginTop:4}}>power {wp.power} · stamina {wp.staminaCost} · {wp.damageType}</div>:null}
            {ap?<div style={{fontSize:9,color:C.boneDim,marginTop:4}}>protection/block profile active when worn</div>:null}
            <div style={{marginTop:6}}><Btn onClick={function(){toggleEquip(it.id);}} active={it.equipped}>{it.equipped?"UNEQUIP":"EQUIP"}</Btn></div>
          </div>;
        })}
        <Empty>Equipped weapon and armor profiles are passed into this companion's combat turns. They are not cosmetic.</Empty>
      </div>:null}

      {tab==="PACK"?<div>
        <div style={{fontSize:10,color:C.boneDim,letterSpacing:"0.12em",marginBottom:6}}>THEIR PACK</div>
        {inv.length===0?<Empty>Nothing carried.</Empty>:inv.map(function(it){return <div key={it.id} style={{border:"1px solid "+C.rule,padding:7,marginBottom:5}}>
          <div style={{display:"flex",gap:8}}><span>{it.name}{it.qty>1?" ×"+it.qty:""}</span><span style={{flex:1}}/><span style={{fontSize:9,color:C.boneFaint}}>{it.equipped?"equipped":"carried"}</span></div>
          <div style={{marginTop:5,display:"flex",gap:5,flexWrap:"wrap"}}>
            <Btn onClick={function(){askUse(it.id);}}>USE</Btn>
            <Btn onClick={function(){takeItem(it.id);}} disabled={it.equipped===true||it.soulbound===true}>TAKE BACK</Btn>
          </div>
        </div>;})}
        <div style={{fontSize:10,color:C.boneDim,letterSpacing:"0.12em",margin:"12px 0 6px"}}>GIVE FROM YOUR INVENTORY</div>
        {playerInv.filter(function(it){return !it.equipped&&!it.soulbound;}).length===0?<Empty>No transferable unequipped item.</Empty>:
        playerInv.filter(function(it){return !it.equipped&&!it.soulbound;}).map(function(it){return <div key={it.id} style={{border:"1px solid "+C.rule,padding:7,marginBottom:5,display:"flex",alignItems:"center",gap:6}}>
          <span style={{fontSize:10}}>{it.name}{it.qty>1?" ×"+it.qty:""}</span><span style={{flex:1}}/><Btn onClick={function(){giveItem(it.id);}}>GIVE</Btn>
        </div>;})}
      </div>:null}

      {tab==="ESSENCES"?<div>
        <Stat label="capacity" value={et.weight+" / "+Math.max(1,Number(member.essenceCapacity)||1)} rule />
        {es.length===0?<Empty>No essence currently recorded on this companion's soul.</Empty>:es.map(function(e,i){return <div key={i} style={{border:"1px solid "+C.rule,padding:8,marginTop:6,background:C.panel}}>
          <div style={{display:"flex",gap:8}}><span style={{color:C.bone}}>{e.source||e.name||"Unknown Essence"}</span><span style={{flex:1}}/><span style={{fontSize:9,color:C.boneFaint}}>rank {e.rank||"?"} · wt {partyEssenceWeight(e)}</span></div>
          {e.statBoost?<div style={{fontSize:9,color:C.boneDim,marginTop:4}}>{e.statBoost}</div>:null}
          {Array.isArray(e.abilities)&&e.abilities.length?<div style={{fontSize:9,color:C.brass,marginTop:4}}>{e.abilities.join(" · ")}</div>:null}
        </div>;})}
        <Empty>Absorbed essences are not transferable inventory. New companion essences must come from a real absorption event; their statMods and spiritFlat feed directly into combat.</Empty>
      </div>:null}
    </div>
  );
}

function Party(props) {
  var api = useYumina();
  var v = api.variables || {};

  var roster = arr_party(v["party"]);
  var rec = obj_party(v["recruit-state"]);
  var listings = arr_party(rec.listings);
  var prospect = obj_party(rec.prospect);
  var loc = String(v["location"] || "").toLowerCase();
  var atGuildHall = loc.indexOf("guild") !== -1 || loc.indexOf("district 9") !== -1 ||
    rec.boardActive === true;

  var t = React.useState("PARTY");
  var tab = t[0], setTab = t[1];
  var ms = React.useState(null);
  var memberSheet = ms[0], setMemberSheet = ms[1];

  var slotsUsed = roster.length + 1; // you occupy one
  var slotsFree = Math.max(0, PARTY_MAX - slotsUsed);

  // You, as the party sees you. Age is twenty — every body an Evil Spirit
  // wakes in is twenty, and nobody in this world knows why.
  var self = {
    name: String(v["char-name"] || "unnamed"),
    rank: num_party(v["explorer-rank"], 0),
    race: String(v["race"] || "unset"),
    age: 20,
    class: String(v["path"] || "unset"),
    combat: {
      condition: num_party(v["condition"],100), conditionMax:100,
      stamina: num_party(v["stamina"],100), staminaMax:100,
      mana: num_party(v["spirit-current"],num_party(v["spirit"],0)),
      manaMax: num_party(v["spirit"],0), status:"ready", injuries:arr_party(v["injuries"])
    }
  };

  function recruit(person) {
    if (slotsFree <= 0) return;
    var next = roster.concat([{
      name: String(person.name || "unnamed"),
      rank: num_party(person.rank, 9),
      race: String(person.race || "unknown"),
      age: num_party(person.age, 20),
      class: String(person.class || "unspecified"),
      role: String(person.role || person.class || "unspecified"),
      fee: String(person.fee || "unsettled"),
      notes: String(person.notes || ""),
      wayfinding: person.wayfinding === true,
      skills: Array.isArray(person.skills) ? person.skills : [],
      equipment: Array.isArray(person.equipment) ? person.equipment : [],
      inventory: Array.isArray(person.inventory) ? person.inventory : (Array.isArray(person.equipment) ? person.equipment : []),
      essences: Array.isArray(person.essences) ? person.essences : [],
      essenceCapacity: Number(person.essenceCapacity || 0) || undefined,
      actorId: String(person.actorId || person.id || ""),
      background: person.background && typeof person.background==="object" ? person.background : undefined,
      stats: person.stats && typeof person.stats==="object" ? person.stats : undefined,
      personality: person.personality && typeof person.personality==="object" ? person.personality : undefined,
      personalStones: Number(person.personalStones==null?0:person.personalStones) || undefined,
      lifeState: person.lifeState && typeof person.lifeState==="object" ? person.lifeState : undefined,
      combatRole: String(person.combatRole || partyRoleKind(person)),
      combat: person.combat && typeof person.combat === "object" ? person.combat : undefined,
    }]).map(function(m,i){ return normalizePartyCombatMember(m,i); });
    api.setVariable("party", next);
    api.setVariable("party-registered", false);
    var ledRecruit=npcObj(v["npc-ledger"]);
    var actorKeyRecruit=String(person.actorId||"")||Object.keys(ledRecruit).find(function(k){return ledRecruit[k]&&String(ledRecruit[k].name||"").toLowerCase()===String(person.name||"").toLowerCase();})||"";
    if(actorKeyRecruit){
      var ledNextRecruit=Object.assign({},ledRecruit);
      var actorRecruit=normalizeNpcActor(ledNextRecruit[actorKeyRecruit]||person,actorKeyRecruit,v);
      actorRecruit.recruitment=Object.assign({},npcObj(actorRecruit.recruitment),{status:"recruited",terms:String(person.fee||((actorRecruit.recruitment&&actorRecruit.recruitment.terms)||"")),lastChangedClock:String(v["clock"]||"")});
      ledNextRecruit[actorKeyRecruit]=actorRecruit;
      api.setVariable("npc-ledger",ledNextRecruit);
    }
    var recAfterRecruit=Object.assign({},obj_party(v["recruit-state"]));
    recAfterRecruit.prospect={active:false,status:"recruited",eligible:false,actorId:actorKeyRecruit,name:String(person.name||"")};
    api.setVariable("recruit-state",recAfterRecruit);
    api.injectContext(
      "[UI] " + person.name + " (rank " + num_party(person.rank, 9) + ", " +
      (person.race || "unknown") + ", " + (person.class || "unspecified") +
      ") has joined the player's party. Terms: " + (person.fee || "unsettled") +
      ". The party is now " + (next.length + 1) + " of " + PARTY_MAX + ". They are already " +
      "on the roster — do not re-add them. Narrate the handshake, the terms, and what " +
      "they think of the party they have just joined. They are a person with their own " +
      "tax and their own opinion, not a hireling.",
      { role: "system" }
    );
    api.sendMessage("[I take " + person.name + " on.]");
    if (props.onClose) props.onClose();
  }

  function drop(i) {
    var m = roster[i];
    var next = roster.slice(0, i).concat(roster.slice(i + 1));
    api.setVariable("party", next);
    api.injectContext(
      "[UI] " + (m && m.name ? m.name : "A member") + " has left the player's party. " +
      "Already removed from the roster. Narrate the parting — it is rarely clean, and " +
      "they will remember how it went.",
      { role: "system" }
    );
    api.sendMessage("[I part ways with " + (m && m.name ? m.name : "them") + ".]");
  }

  function askBoard() {
    api.sendMessage(
      "[I go to the search board at the Explorers' Guild and read what is posted — who is looking for a party.]"
    );
    if (props.onClose) props.onClose();
  }

  function askAround() {
    api.sendMessage(
      "[I ask around — quietly, wherever I am — about anyone willing to go down into the Labyrinth with me.]"
    );
    if (props.onClose) props.onClose();
  }

  function Roster() {
    return (
      <div>
        <div style={{ marginBottom: 10 }}>
