        })}

        {prospect && prospect.name && (prospect.eligible===true || String(prospect.status||"")==="eligible") &&
         !roster.some(function(m){return m&&(String(m.actorId||"")===String(prospect.actorId||"") || String(m.name||"").toLowerCase()===String(prospect.name||"").toLowerCase());}) ? (
          <div className="ds-panel" style={{border:"1px solid "+C.brass,borderRadius:R.md,background:C.panel,boxShadow:SH.raised,padding:10,marginBottom:8}}>
            <div style={{fontSize:9,letterSpacing:"0.16em",color:C.brass,marginBottom:5}}>READY TO JOIN</div>
            <div style={{display:"flex",alignItems:"baseline",gap:8}}>
              <span style={{fontSize:12,color:C.bone}}>{prospect.name}</span><span style={{flex:1}}/>
              <span style={{fontSize:9,color:C.boneFaint}}>{rankWord(prospect.rank)}</span>
            </div>
            <div style={{marginTop:6}}>
              <Chip color={C.brass} border={C.brass}>{"rank "+num_party(prospect.rank,9)}</Chip>
              <Chip>{prospect.race||"—"}</Chip><Chip>{prospect.class||prospect.role||"—"}</Chip>
            </div>
            {prospect.fee?<div style={{fontSize:10,color:C.boneFaint,marginTop:5}}>terms — {prospect.fee}</div>:null}
            <div style={{marginTop:8}}>
              <Btn onClick={function(){recruit(prospect);}} disabled={slotsFree<=0}>
                {slotsFree<=0?"PARTY IS FULL":"RECRUIT"}
              </Btn>
            </div>
          </div>
        ) : null}

        {slotsFree > 0
          ? Array.apply(null, new Array(slotsFree)).map(function (_, i) {
              return (
                <div
                  key={"empty" + i}
                  style={{
                    border: "1px dashed " + C.rule,
                    borderRadius: R.md,
                    padding: "14px 10px",
                    marginBottom: 8,
                    textAlign: "center",
                    fontSize: 10,
                    letterSpacing: "0.14em",
                    color: C.boneFaint,
                  }}
                >
                  EMPTY SLOT
                </div>
              );
            })
          : null}

        <Empty>
          Five is the number the Labyrinth is built for. Five of the same thing
          works right up until it meets the thing that thing cannot do — a wall
          with nothing behind it, four blades and nobody to stop the bleeding.
          Mix it if you want to come back up.
        </Empty>
      </div>
    );
  }

  function Board() {
    return (
      <div>
        <div style={{ fontSize: 12, letterSpacing: "0.18em", color: C.boneDim }}>
          SEARCH BOARD
        </div>
        <Empty>
          The formal route. Every Guild hall keeps a board of people advertising
          for work. A listing is a stranger's own account of themselves, and the
          board does not check it.
        </Empty>

        {!atGuildHall ? (
          <div style={{ marginTop: 10 }}>
            <Btn wide onClick={askBoard}>GO TO THE GUILD AND READ THE BOARD</Btn>
          </div>
        ) : !listings.length ? (
          <div style={{ marginTop: 10 }}>
            <Btn wide onClick={askBoard}>READ WHAT IS POSTED</Btn>
          </div>
        ) : (
          <div style={{ marginTop: 10 }}>
            {listings.map(function (p, i) {
              var full = slotsFree <= 0;
              return (
                <div
                  key={(p && p.id ? p.id : "l") + i}
                  className="ds-panel"
                  style={{
                    border: "1px solid " + C.rule,
                    borderRadius: R.md,
                    background: C.panel,
                    boxShadow: SH.panel,
                    padding: 10,
                    marginBottom: 8,
                  }}
                >
                  <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                    <span style={{ fontSize: 12, color: C.bone }}>{p.name || "unnamed"}</span>
                    <span style={{ flex: 1 }} />
                    <span style={{ fontSize: 9, color: C.boneFaint }}>
                      {rankWord(p.rank)}
                    </span>
                  </div>
                  <div style={{ marginTop: 6 }}>
                    <Chip color={C.brass} border={C.brass}>{"rank " + num_party(p.rank, 9)}</Chip>
                    <Chip>{p.race || "—"}</Chip>
                    <Chip>{p.class || "—"}</Chip>
                    <Chip>{"age " + (p.age === 0 || p.age ? p.age : "—")}</Chip>
                  </div>
                  {p.notes ? (
                    <div style={{ fontSize: 10, lineHeight: 1.6, color: C.boneDim, marginTop: 6 }}>
