                    >
                      TALK FIRST
                    </Btn>
                  </div>
                </div>
              );
            })}
            <Empty>
              Nobody rank 5 or better advertises on a district board. The clans
              take them before the ink dries.
            </Empty>
          </div>
        )}
      </div>
    );
  }

  function Around() {
    var live = !!(prospect.name && (prospect.active !== false || prospect.eligible === true || String(prospect.status||"")==="eligible"));
    var full = slotsFree <= 0;
    return (
      <div>
        <div style={{ fontSize: 12, letterSpacing: "0.18em", color: C.boneDim }}>
          ASKING AROUND
        </div>
