        ) : (
          <div style={{ marginTop: 10 }}>
            <div
              className="ds-panel"
              style={{
                border: "1px solid " + C.ruleLit,
                borderRadius: R.md,
                background: C.panel,
                boxShadow: SH.raised,
                padding: 10,
              }}
            >
              <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                <span style={{ fontSize: 12, color: C.bone }}>{prospect.name || "unnamed"}</span>
                <span style={{ flex: 1 }} />
                <span style={{ fontSize: 9, color: C.boneFaint }}>{rankWord(prospect.rank)}</span>
              </div>
              <div style={{ marginTop: 6 }}>
                <Chip color={C.brass} border={C.brass}>{"rank " + num_party(prospect.rank, 9)}</Chip>
                <Chip>{prospect.race || "—"}</Chip>
                <Chip>{prospect.class || "—"}</Chip>
                <Chip>{"age " + (prospect.age === 0 || prospect.age ? prospect.age : "—")}</Chip>
              </div>
              {prospect.notes ? (
                <div style={{ fontSize: 10, lineHeight: 1.6, color: C.boneDim, marginTop: 6 }}>
                  {prospect.notes}
                </div>
              ) : null}
              {prospect.fee ? (
                <div style={{ fontSize: 10, color: C.boneFaint, marginTop: 4 }}>
                  wants — {prospect.fee}
                </div>
              ) : null}
              <div style={{ marginTop: 8, display: "flex", gap: 6, flexWrap: "wrap" }}>
                <Btn onClick={function () { recruit(prospect); }} disabled={full}>
                  {full ? "PARTY IS FULL" : "RECRUIT"}
                </Btn>
                <Btn
                  onClick={function () {
                    api.sendMessage("[I keep talking to " + (prospect.name || "them") + " before deciding.]");
                    if (props.onClose) props.onClose();
                  }}
                >
                  KEEP TALKING
                </Btn>
              </div>
            </div>
            <div style={{ marginTop: 8 }}>
              <Btn wide onClick={askAround}>ASK SOMEONE ELSE</Btn>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <Screen
      title="PARTY"
      onClose={props.onClose}
      tabs={TABS_party}
      tab={tab}
      onTab={function (x) { setTab(x); }}
    >
      {tab === "PARTY" ? (memberSheet==null ? <Roster /> :
        <PartyMemberSheet index={memberSheet} onBack={function(){setMemberSheet(null);}} />) : null}
      {tab === "BOARD" ? <Board /> : null}
      {tab === "AROUND" ? <Around /> : null}
    </Screen>
  );
}

var SKILL_STAGES = ["Barely Formed", "Novice", "Intermediate", "Adept", "Master", "Sovereign"];
var SKILL_STAGE_DESC = {
  "Barely Formed": "High failure risk. Severe inefficiency. Real chance of backlash.",
  "Novice": "Usable — but unreliable the moment real pressure shows up.",
  "Intermediate": "Dependable, as long as conditions stay favourable.",
  "Adept": "Dependable even under real pressure.",
  "Master": "Near second nature.",
  "Sovereign": "Total mastery. Exceedingly rare — most explorers never see one, on anyone.",
};

function skillStageIndex(stage) {
  var i = SKILL_STAGES.indexOf(stage);
  return i < 0 ? 0 : i;
}
// Which Physique substats actually bear on each trained skill, grounded in
// what the substats themselves are canon-confirmed to govern: Strength is
// carry weight and physical attack power, Flexibility is dodge/crit,
// Vision is ranged reach and visible range, Smell gates certain abilities,
// Accuracy Rate is accuracy. Divine Power and Necromancy get no substat tie
// at all — nothing in canon makes spellwork or dark ritual depend on a
// physical stat, and forcing one would be inventing texture, not reading it.
var SKILL_SUBSTATS = {
  "Auror": ["strength", "accuracy"],
  "Navigation": ["vision", "smell"],
  "Spellcraft": ["vision"],
};

var SKILL_TIERS = [
  [0, "struggling"], [25, "uneven"], [50, "solid"],
  [75, "strong"], [100, "exceptional"], [125, "overwhelming"],
];

// Combines trained stage/proficiency with whatever substats actually bear on
// this skill into one real, checkable tier. This decides how GOOD a use of
// the skill is, never whether a fight is won — that stays entirely narrated.
function skillEffect(sk, subs) {
  var stage = SKILL_STAGES.indexOf(sk.stage) >= 0 ? sk.stage : "Barely Formed";
  var stageIdx = skillStageIndex(stage);
  var prof = num_party(sk.proficiency, 0);
  var relevant = SKILL_SUBSTATS[sk.name] || [];
  var subBonus = 0;
  for (var i = 0; i < relevant.length; i++) {
    var val = num_party(subs[relevant[i]], 0);
    if (val >= 50) subBonus += 20;
    else if (val >= 36) subBonus += 15;
    else if (val >= 21) subBonus += 10;
    else if (val >= 11) subBonus += 5;
  }
  var score = stageIdx * 20 + prof * 0.15 + subBonus;
  var word = SKILL_TIERS[0][1];
  for (var t = 0; t < SKILL_TIERS.length; t++) {
    if (score >= SKILL_TIERS[t][0]) word = SKILL_TIERS[t][1];
  }
  return { score: Math.round(score), word: word, substats: relevant };
}

function Skills(props) {
  var api = useYumina();
  var v = api.variables || {};
  var learned = arr_party(v["skills"]);
  var subs = obj_party(v["substats"]);

  var sel = React.useState(null);
