  function Row(sk, i) {
    var stage = SKILL_STAGES.indexOf(sk.stage) >= 0 ? sk.stage : "Barely Formed";
    var prof = num_party(sk.proficiency, 0);
    var isOpen = open === i;
    var atSovereignGate = stage === "Master" && prof >= 100;
