            </span>
          </div>
          {(function () {
            var eff = skillEffect(sk, subs);
            return (
              <div style={{ marginTop: 4, fontSize: 9, color: C.brass }}>
                effectiveness — {eff.word}
                {eff.substats.length ? " (" + eff.substats.join(", ") + ")" : ""}
              </div>
            );
          })()}
        </div>
        {isOpen ? (
          <div style={{ marginTop: 8, paddingTop: 8, borderTop: "1px dotted " + C.rule }}>
            <div style={{ fontSize: 10, lineHeight: 1.6, color: C.boneDim }}>
              {SKILL_STAGE_DESC[stage]}
            </div>
            {sk.discipline && arr_party(sk.discipline).length ? (
              <div style={{ marginTop: 8 }}>
                <div style={{ fontSize: 9, color: C.boneFaint, marginBottom: 4 }}>DISCIPLINE LADDER</div>
                {arr_party(sk.discipline).map(function (rung, ri) {
                  return (
                    <div key={ri} style={{ display: "flex", gap: 6, alignItems: "baseline", padding: "2px 0" }}>
                      <span style={{ fontSize: 9, color: rung.unlocked ? C.brass : C.boneFaint }}>
                        {rung.unlocked ? "●" : "○"}
                      </span>
                      <span style={{ fontSize: 10, color: rung.unlocked ? C.bone : C.boneFaint }}>
                        {rung.name}
                      </span>
                      {rung.unlocked && rung.desc ? (
                        <span style={{ fontSize: 9, color: C.boneFaint }}>— {rung.desc}</span>
                      ) : null}
                    </div>
