              <div style={{ fontSize: 9, color: C.boneFaint, marginTop: 8 }}>training began — {sk.trainedAt}</div>
            ) : null}
          </div>
        ) : null}
      </div>
    );
  }

  var earned = arr_party(v["titles"]);

  return (
    <Screen title="SKILLS" onClose={props.onClose}>
      <div style={{ padding: 10 }}>
        {learned.length === 0 ? (
          <div style={{ fontSize: 11, color: C.boneDim, lineHeight: 1.7 }}>
            Nothing trained yet. Auror, Spellcraft, Divine Power, Necromancy, Navigation — these are
            learned, not found, and each one costs real weeks and real stones before it shows up here
            at all.
