          learned.map(function (sk, i) { return Row(sk, i); })
        )}
        {earned.length ? (
          <div style={{ marginTop: 14, paddingTop: 10, borderTop: "1px solid " + C.rule }}>
            <div style={{ fontSize: 9, color: C.boneFaint, marginBottom: 6, letterSpacing: "0.1em" }}>
              TITLES
            </div>
            {earned.map(function (t, i) {
              return (
                <div key={i} style={{ marginBottom: 8 }}>
                  <div style={{ fontSize: 11, color: C.brass }}>{t.name}</div>
                  {t.note ? (
                    <div style={{ fontSize: 9, color: C.boneDim, lineHeight: 1.5, marginTop: 2 }}>
                      {t.note}
                    </div>
                  ) : null}
                  {t.earnedAt ? (
                    <div style={{ fontSize: 9, color: C.boneFaint, marginTop: 2 }}>{t.earnedAt}</div>
                  ) : null}
                </div>
              );
            })}
          </div>
        ) : null}
      </div>
    </Screen>
  );
}
// ==== hud.tsx ===================================================
function num_hud(v, d) { return typeof v === "number" ? v : d; }
function arr_hud(v) { return Array.isArray(v) ? v : []; }

// Every bound the world can violate, in one place. The HUD is mounted for the
// whole of play, so this is the reliable spot for it.
//   [id, floor, ceiling]  — a ceiling of null means "read it from `spirit`".
var BOUNDS = [
  ["condition", 0, 100],
  ["stamina", 0, 100],
  ["thirst", 0, 100],
  ["suspicion", 0, 100],
  ["fame", 0, 100],
  ["mana-stones", 0, null],      // currency floors at zero, no ceiling
  ["tax-owed", 0, null],
  ["soul-power", 0, null],
  ["achievements", 0, null],
  ["level", 0, null],
  ["physique", 0, 200],
  ["spirit", 0, 200],
  ["explorer-rank", 0, 9],       // 0 = unregistered, 9 lowest, 1 apex
  ["current-floor", 0, 10],
  ["cycle-day", 1, 31],
  ["cycle-month", 1, 13],     // 13-month calendar: months 1-12 are 30 days, month 13 is 5
  ["essence-capacity", 1, null],
  ["obsession", 0, null],
  ["hunger", 0, 100],
];

var MENU = [
  ["SHEET", "Character"],
  ["SKILLS", "Skills"],
  ["PARTY", "Party"],
  ["MAP", "Map"],
  ["WORLD", "World"],
  ["JOURNAL", "Journal"],
  ["GUILD", "Guild"],
  ["VAULT", "Bank"],
  ["HOME", "Home"],
  ["FENCE", "Goods"],
  ["GRIND", "Commit"],
];
// Emblem and label for each rail entry. Keys are unchanged screen ids.
var MENU_ICON = { SHEET:"sheet", SKILLS:"skills", PARTY:"party", MAP:"map", WORLD:"world", JOURNAL:"journal",
  GUILD:"guild", VAULT:"vault", HOME:"home", FENCE:"fence", GRIND:"commit" };
var MENU_LABEL = { GRIND: "COMMIT" };

// The persistent readout. Two lines on a phone, one on a desk.
// HH:MM, 24h, wraps cleanly even if minutes ever land outside 0-1439.
function clockLabel(mins) {
  var m = ((Math.round(mins) % 1440) + 1440) % 1440;
  var hh = Math.floor(m / 60);
  var mm = m % 60;
  return (hh < 10 ? "0" : "") + hh + ":" + (mm < 10 ? "0" : "") + mm;
}

// Pouch breakdown modal — shows every raw mana stone lot by source species/rank.
// Pure read of raw-stones; never writes anything.
function PouchDetail(props) {
  var v = props.v;
  var pouchRaw = v["raw-stones"];
  var bag = pouchRaw && typeof pouchRaw === "object" && !Array.isArray(pouchRaw) ? pouchRaw : {};
  var rows = Object.keys(bag).map(function (name) {
    var row = bag[name] && typeof bag[name] === "object" ? bag[name] : {};
    var qty = typeof row.qty === "number" && isFinite(row.qty) ? row.qty : 0;
    var rank = typeof row.rank === "number" && isFinite(row.rank) ? row.rank : null;
    return { name: name, qty: qty, rank: rank };
  }).filter(function (r) { return r.qty > 0; })
    .sort(function (a, b) {
      var ra = a.rank == null ? 99 : a.rank;
      var rb = b.rank == null ? 99 : b.rank;
      if (ra !== rb) return ra - rb;
      return a.name.localeCompare(b.name);
    });

  var total = rows.reduce(function (a, r) { return a + r.qty; }, 0);

  return (
    <div
      style={{
        position: "fixed", inset: 0, zIndex: 70,
        background: "rgba(6,7,9,0.86)", backdropFilter: "blur(3px)",
        display: "flex", alignItems: "center", justifyContent: "center", padding: 16,
      }}
      onClick={props.onClose}
    >
      <div
        onClick={function (ev) { ev.stopPropagation(); }}
        style={{
          width: "100%", maxWidth: 440, maxHeight: "80vh", overflowY: "auto",
          background: "linear-gradient(180deg," + C.panelUp + " 0%," + C.void + " 100%)",
          border: "1px solid " + C.rule, borderRadius: 14,
          boxShadow: "0 18px 50px rgba(0,0,0,0.6)",
          padding: 18, color: C.bone, fontFamily: MONO,
        }}
      >
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
          <div style={{ fontFamily: DISPLAY, fontSize: 13, fontWeight: 600, letterSpacing: "0.12em", color: C.brassLit }}>
            POUCH — {total.toLocaleString()} MANA STONE{total === 1 ? "" : "S"}
          </div>
          <button
            onClick={props.onClose}
            style={{ background: "none", border: "none", color: C.boneFaint, cursor: "pointer", fontSize: 18 }}
          >×</button>
        </div>

        {rows.length === 0 ? (
          <div style={{ fontSize: 11, color: C.boneFaint, lineHeight: 1.6 }}>
            The pouch is empty. Nothing cut out of a corpse yet, or it has already been
            exchanged at a Guild counter.
          </div>
        ) : (
          <div>
            {rows.map(function (r) {
              return (
                <div
                  key={r.name}
                  style={{
                    display: "flex", justifyContent: "space-between", alignItems: "center",
                    padding: "7px 0", borderBottom: "1px solid " + C.rule, fontSize: 11,
                  }}
                >
                  <span style={{ color: C.bone }}>
                    {r.name}
                    <span style={{ color: C.boneFaint, marginLeft: 6 }}>
                      {r.rank != null ? "rank " + r.rank : "unranked"}
                    </span>
                  </span>
                  <span style={{ color: C.brassLit, fontVariantNumeric: "tabular-nums" }}>
                    x{r.qty}
                  </span>
                </div>
              );
            })}
          </div>
        )}

        <div style={{ fontSize: 10, color: C.boneFaint, lineHeight: 1.6, marginTop: 14 }}>
          Physical loot only — worth nothing until a Guild exchange counter grades and
          weighs it. This list updates the instant a new mana stone lands in the pouch.
        </div>
      </div>
    </div>
  );
}

function Hud(props) {
  var api = props.api;
  var v = api.variables || {};
  var pouchOpenS = React.useState(false);
  var pouchOpen = pouchOpenS[0], setPouchOpen = pouchOpenS[1];

  var cond = num_hud(v["condition"], 100);
  var spirit = num_hud(v["spirit"], 0);
  var phys = num_hud(v["physique"], 0);
  // Hydration is the canonical reserve. `thirst` is a legacy compatibility
  // mirror retained for older rules/saves. The HUD must never display stale
  // thirst when hydration has already changed.
  var thirst = num_hud(v["hydration"], num_hud(v["thirst"], 100));
  var hunger = num_hud(v["hunger"], 100);
  var floor = num_hud(v["current-floor"], 0);
  var hurt = arr_hud(v["injuries"]);
  var rank = num_hud(v["explorer-rank"], 0);
  var stones = num_hud(v["mana-stones"], 0);
  var status = v["citizen-status"] || "citizen";

  // Raw haul rides in a separate pouch. Showing it beside the purse is the
  // whole point: heavy and broke at the same time.
  var pouchRaw = v["raw-stones"];
  var pouchBag = pouchRaw && typeof pouchRaw === "object" && !Array.isArray(pouchRaw) ? pouchRaw : {};
  var pouchCount = Object.keys(pouchBag).reduce(function (a, k) {
    var row = pouchBag[k];
    var q = row && typeof row === "object" ? row.qty : 0;
    return a + (typeof q === "number" && isFinite(q) ? q : 0);
  }, 0);

  // Spirit is the size of the pool; spirit-current is what is left in it.
  var manaNow = num_hud(v["spirit-current"], spirit);
  var mp = spirit > 0 ? Math.min(100, Math.round((manaNow / spirit) * 100)) : 0;
  var stam = num_hud(v["stamina"], 100);

  // --- deterministic bounds --------------------------------------------
  // The GM writes state in prose and will eventually write something out of
  // range — 130 condition, -40 stones, floor 12. Correct it once, here, rather
  // than hoping every panel remembers to defend itself. Only writes when a
  // value is genuinely out of bounds, so this cannot loop.
  React.useEffect(function () {
    BOUNDS.forEach(function (b) {
      var raw = v[b[0]];
      if (typeof raw !== "number" || !isFinite(raw)) return;
      var lo = b[1];
      var hi = b[2];
      var fixed = raw;
      if (typeof lo === "number" && fixed < lo) fixed = lo;
      if (typeof hi === "number" && fixed > hi) fixed = hi;
      if (fixed !== raw) api.setVariable(b[0], fixed);
    });
    // Mana is the one ceiling the engine cannot express: the pool's SIZE is
    // another variable. You can never be carrying more mana than you can hold.
    // Keep the old thirst variable synchronized with canonical hydration.
    // This prevents legacy survival rules or old saves from making the bar lie.
    var hydRaw = v["hydration"];
    var thirstRaw = v["thirst"];
    if (typeof hydRaw === "number" && isFinite(hydRaw)) {
      var fixedHyd = Math.max(0, Math.min(100, hydRaw));
      if (fixedHyd !== hydRaw) api.setVariable("hydration", fixedHyd);
      if (thirstRaw !== fixedHyd) api.setVariable("thirst", fixedHyd);
    } else if (typeof thirstRaw === "number" && isFinite(thirstRaw)) {
      api.setVariable("hydration", Math.max(0, Math.min(100, thirstRaw)));
    }

    var poolRaw = v["spirit"];
    var nowRaw = v["spirit-current"];
    if (typeof nowRaw === "number" && isFinite(nowRaw)) {
      var pool = typeof poolRaw === "number" && isFinite(poolRaw) ? Math.max(0, poolRaw) : 0;
      var fixedMana = nowRaw < 0 ? 0 : nowRaw > pool ? pool : nowRaw;
      if (fixedMana !== nowRaw) api.setVariable("spirit-current", fixedMana);
    }
  }, [v]);

  var compactS = React.useState(false);
  var compact = compactS[0], setCompact = compactS[1];
  var name = v["char-name"] || "unnamed";
  var raceId = v["race"] || "";
  var portraitSrc = ART.portrait || (ART.races && ART.races[raceId]) || "";
  var injured = hurt.length > 0;
  var ringCol = injured ? C.bloodLit : C.brass;
  var whereLabel = floor === 0 ? String(v["location"] || "the surface") : "Floor " + floor;
  var whenLabel = "m" + num_hud(v["cycle-month"], 1) + " d" + num_hud(v["cycle-day"], 1) + " · " + clockLabel(num_hud(v["clock"], 420));

  function bar(label, pct, col) {
    return <Band label={label} pct={pct} color={col} labelWidth={34} />;
  }

  // Money and loot, side by side and never confused: ◆ Stones spend,
  // mana stones in the pouch do not until the Guild exchanges them.
  var purse = (
    <div style={{
      display: "flex", alignItems: "stretch", borderRadius: R.sm, overflow: "hidden",
      border: "1px solid " + C.ruleLit, background: "linear-gradient(180deg,#221c15,#120f0c)",
      boxShadow: "inset 0 1px 0 rgba(255,226,170,0.07), 0 2px 8px rgba(0,0,0,0.45)",
    }}>
      <div title="Stones — spendable currency" style={{ flex: "1 1 0%", display: "flex", alignItems: "center", gap: 4, padding: "5px 5px", minWidth: 0 }}>
        <span style={{ color: C.brassLit }}><Icon name="coin" size={14} fill={C.brass + "66"} /></span>
        <div style={{ lineHeight: 1.1, minWidth: 0 }}>
          <div style={{ fontFamily: PROSE, fontSize: 9, color: C.boneDim }}>Stones</div>
          <div style={{ fontSize: 13.5, color: C.brassLit, fontVariantNumeric: "tabular-nums lining-nums", whiteSpace: "nowrap" }}>{stones.toLocaleString()}</div>
        </div>
      </div>
      <span style={{ width: 1, background: C.rule }} />
      <button className="ds-btn" onClick={function () { setPouchOpen(true); }}
        title="Mana stones in your pouch — physical loot, not money. Tap for the breakdown."
        style={{ flex: "1 1 0%", display: "flex", alignItems: "center", gap: 4, padding: "5px 5px", minWidth: 0,
          background: "transparent", border: "none", cursor: "pointer", textAlign: "left", fontFamily: MONO, color: C.bone }}>
        <span style={{ color: pouchCount > 0 ? C.bloodLit : C.boneFaint }}><Icon name="gem" size={14} fill={pouchCount > 0 ? C.blood + "aa" : "none"} /></span>
        <div style={{ lineHeight: 1.1, minWidth: 0 }}>
          <div style={{ fontFamily: PROSE, fontSize: 9, color: C.boneDim, whiteSpace: "nowrap" }}>Mana Stones</div>
          <div style={{ fontSize: 13.5, color: pouchCount > 0 ? C.bone : C.boneFaint, fontVariantNumeric: "tabular-nums lining-nums" }}>{pouchCount.toLocaleString()}</div>
        </div>
      </button>
    </div>
  );

  // Place and time, over a small scene of where you are.
  var placeBox = (
    <div style={{
      position: "relative", overflow: "hidden", borderRadius: R.sm, minHeight: 44,
      border: "1px solid " + (floor > 0 ? C.blood : C.ruleLit),
      display: "flex", flexDirection: "column", justifyContent: "center", padding: "4px 8px",
      background: floor > 0 ? "linear-gradient(90deg,#1d0f0c,#2c1611)" : "linear-gradient(90deg,#15110c,#261d13)",
    }}>
      {ART.floorScene ? (
        <img src={ART.floorScene} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", opacity: 0.55 }} />
      ) : (
        <div style={{ position: "absolute", top: 0, bottom: 0, right: 0, width: "75%", opacity: 0.6, pointerEvents: "none",
          WebkitMaskImage: "linear-gradient(90deg,transparent,#000 70%)", maskImage: "linear-gradient(90deg,transparent,#000 70%)" }}>
          <Plate seed={floor + 3} height={52} />
        </div>
      )}
      <div style={{ position: "relative", fontFamily: DISPLAY, fontSize: 11.5, fontWeight: 600, letterSpacing: "0.05em",
        color: C.bone, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", textShadow: "0 1px 4px #000" }}>
        {whereLabel}
      </div>
      <div style={{ position: "relative", fontSize: 11.5, color: C.boneDim, whiteSpace: "nowrap", textShadow: "0 1px 4px #000",
        fontVariantNumeric: "tabular-nums lining-nums" }}>
        {whenLabel}{v["labyrinth-open"] ? "" : " · shut"}
      </div>
    </div>
  );

  return (
    <div
      className="ds-root"
      style={{
        position: "relative",
        background: MAT.backdrop,
        borderBottom: "1px solid " + C.ruleLit,
        fontFamily: MONO,
        color: C.bone,
        boxShadow: "0 6px 18px rgba(0,0,0,0.55)",
