    >
      {compact ? (
        <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "6px 10px" }}>
          <button className="ds-btn" onClick={function () { setCompact(false); }} aria-label="Expand status"
            style={{ background: "none", border: "none", padding: 0, cursor: "pointer" }}>
            <Medallion size={28} src={portraitSrc} icon={raceId ? "race-" + raceId : "sheet"} glow={injured} ring={ringCol} />
          </button>
          <div style={{ flex: 1, minWidth: 0, display: "grid", gap: 3 }}>
            <Band pct={cond} color={cond < 25 ? C.bloodLit : "#c0392f"} thin />
            <Band pct={mp} color={C.brass} thin />
            <Band pct={stam} color="#8a8474" thin />
          </div>
          <span style={{ fontSize: 13, color: C.brassLit, fontVariantNumeric: "tabular-nums lining-nums" }}>◆ {stones.toLocaleString()}</span>
          {pouchCount > 0 ? <span onClick={function () { setPouchOpen(true); }} style={{ fontSize: 12, color: C.bloodLit, cursor: "pointer" }}>⛏ {pouchCount}</span> : null}
          <span style={{ fontSize: 11, color: C.boneDim }}>{clockLabel(num_hud(v["clock"], 420))}</span>
        </div>
      ) : (
        <div>
          <div style={{
            display: "grid", gridTemplateColumns: "60px minmax(0,1fr) 164px",
            columnGap: 9, rowGap: 6, padding: "9px 10px 7px", alignItems: "stretch",
          }}>
            {/* portrait */}
            <button className="ds-btn" onClick={function () { setCompact(true); }} aria-label="Collapse status"
              style={{
                gridRow: "1 / span 2", padding: 0, width: 60, minHeight: 72, position: "relative", overflow: "hidden",
                borderRadius: R.sm, cursor: "pointer", color: C.brassLit,
                display: "flex", alignItems: "center", justifyContent: "center",
                background: "radial-gradient(circle at 50% 30%,#3a2e20,#15110c 72%)",
                border: "1px solid " + ringCol,
                boxShadow: "0 0 0 2px #0c0a09, 0 0 0 3px " + ringCol + "55" + (injured ? ", 0 0 14px " + C.bloodLit + "55" : ""),
              }}>
              {portraitSrc ? (
                <img src={portraitSrc} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
              ) : (
                <Icon name={raceId ? "race-" + raceId : "sheet"} size={30} stroke={1.4} />
              )}
            </button>

            {/* name */}
            <div style={{ minWidth: 0, alignSelf: "center" }}>
              <div style={{ display: "flex", alignItems: "baseline", gap: 6, minWidth: 0 }}>
                <span style={{
                  fontFamily: DISPLAY, fontSize: 16, fontWeight: 600, letterSpacing: "0.08em",
                  whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", color: "#f0e2c4",
                  textShadow: "0 2px 6px rgba(0,0,0,0.9)",
                }}>{name}</span>
                {status !== "citizen" ? (
                  <span style={{ fontFamily: DISPLAY, color: "#fff", background: BTN_BLOOD, fontSize: 7.5, letterSpacing: "0.1em",
                    padding: "2px 5px", borderRadius: 3, border: "1px solid " + C.bloodLit, whiteSpace: "nowrap" }}>
                    {String(status).toUpperCase()}
                  </span>
