              </div>
              <div style={{ fontSize: 11.5, color: C.boneDim, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                {raceId || "—"}<span style={{ color: C.brass, margin: "0 4px" }}>•</span>
                {rank === 0 ? "Unregistered" : "Rank " + rank}<span style={{ color: C.brass, margin: "0 4px" }}>•</span>
