                <span style={{ color: "#6fa3c7" }}><Icon name="drop" size={14} /></span>
                <span style={{ fontFamily: PROSE, fontSize: 12.5, color: C.boneDim }}>Hydration</span>
                <div style={{ flex: 1 }}><Band pct={thirst} color={thirst < 25 ? C.bloodLit : "#4f86ad"} thin /></div>
              </div>
