// ==== journal.tsx ===============================================
// The journal is a record, not a quest marker system. Half of what is in here
// is a rumor someone repeated in a tavern and may simply be false.

function arr_journal(v) { return Array.isArray(v) ? v : []; }

var TABS_journal = ["OPEN", "RUMOR", "CLOSED"];

// The GM writes this variable in prose-time and has historically used two
// different field vocabularies for it (type/description/rewardStones vs
// formal/detail/reward). Normalise BOTH into one shape so nothing the AI
// legitimately pushed is silently invisible. Object.assign keeps the original
// keys, so persisting a normalised row is lossless and quietly repairs it.
function norm_journal(q) {
  if (!q || typeof q !== "object") return null;
  var kind = q.kind || q.type || (q.formal === true ? "formal" : "personal");
  var isFormal = q.formal === true || kind === "formal" || kind === "request" || kind === "contract";
  var status = String(q.status || "active").toLowerCase();
  var reward = q.reward;
  if (reward == null && q.rewardStones != null && q.rewardStones !== "") {
    reward = Number(q.rewardStones).toLocaleString() + " stones";
  }
  var deadline = q.deadline || q.due || null;
  return Object.assign({}, q, {
    kind: kind,
    formal: isFormal,
    status: status,
    title: q.title || q.name || "(untitled)",
    detail: q.detail || q.description || q.notes || "",
    reward: reward != null && reward !== "" ? reward : null,
    deadline: deadline,
  });
}

function bucket(q) {
  var s = (q && q.status) || "active";
  var k = (q && q.kind) || "";
  // Closed states win over kind: a rumor the player actually chased down and
  // settled belongs in CLOSED, not sitting in RUMOR forever looking live.
  if (s === "complete" || s === "completed" || s === "failed" ||
      s === "expired" || s === "abandoned") return "CLOSED";
  // A rumor is a KIND, not a status — the GM files it with status "active",
  // so bucketing on status alone left the RUMOR tab permanently empty.
  if (k === "rumor" || k === "lead" || s === "rumor" || s === "lead") return "RUMOR";
  if (s === "active" || s === "accepted" || s === "open") return "OPEN";
  return "CLOSED";
}

function statusColor(s) {
  if (s === "failed" || s === "expired" || s === "abandoned") return C.bloodLit;
  if (s === "complete" || s === "completed") return C.brass;
  return C.boneDim;
}
function Journal(props) {
  var api = useYumina();
  var v = api.variables || {};
  var rawLog = arr_journal(v["quest-log"]);
  var log = React.useMemo(function () {
    var out = [];
    for (var i = 0; i < rawLog.length; i++) {
      var n = norm_journal(rawLog[i]);
      if (n) {
        if (!n.id) n.id = "entry-" + i;
        out.push(n);
      }
    }
    return out;
  }, [rawLog]);

  var t = React.useState("OPEN");
  var tab = t[0], setTab = t[1];
  var o = React.useState(null);
  var open = o[0], setOpen = o[1];
  var d = React.useState("");
  var draft = d[0], setDraft = d[1];
  var w = React.useState(false);
  var writing = w[0], setWriting = w[1];

  var rows = log.filter(function (q) { return bucket(q) === tab; });

  // --- mutation ---------------------------------------------------------
  // Writing a personal objective is legal: it is the player's own notebook.
  // Anything FORMAL (a guild contract, a signed request) can only be created
  // by the world, so this only ever mints kind:"personal".
  function addPersonal() {
    var text = draft.trim();
    if (!text) return;
    var next = log.concat([{
      id: "personal-" + Date.now(),
      source: "self",
      kind: "personal",
      formal: false,
      title: text.slice(0, 60),
      detail: text,
      status: "active",
      reward: null,
    }]);
    api.setVariable("quest-log", next);
    api.injectContext(
      "[UI] The player wrote a personal objective in their own journal: \"" +
      text + "\". This is not a formal request and no NPC knows about it."
    );
    setDraft("");
    setWriting(false);
  }

  function dropPersonal(q) {
    var next = log.filter(function (x) { return x.id !== q.id; });
    api.setVariable("quest-log", next);
    api.injectContext("[UI] The player struck their own objective out of the journal: \"" + q.title + "\".");
    setOpen(null);
  }

  function askAbout(q) {
    api.sendMessage(
      "I go over what I actually know about this: " + q.title +
      (q.source && q.source !== "self" ? " — the one from " + q.source + "." : ".")
    );
    if (props.onClose) props.onClose();
  }

  // --- detail -----------------------------------------------------------
  if (open) {
    var q = open;
    return (
      <Screen title="JOURNAL" onClose={function () { setOpen(null); }}>
        <div style={{ fontSize: 12, letterSpacing: "0.06em", color: C.bone }}>
          {q.title}
        </div>
        <div style={{ marginTop: 6 }}>
          {q.formal
            ? <Chip color={C.brass} border={C.brass}>FORMAL REQUEST</Chip>
            : <Chip>PERSONAL</Chip>}
          <Chip color={statusColor(q.status)}>{String(q.status || "active").toUpperCase()}</Chip>
          {q.source && q.source !== "self" ? <Chip>{q.source}</Chip> : null}
          {q.deadline ? <Chip color={C.bloodLit} border={C.blood}>DUE {q.deadline}</Chip> : null}
        </div>

        <div style={{
          marginTop: 12, fontSize: 11, lineHeight: 1.8, color: C.boneDim,
          borderTop: "1px solid " + C.rule, paddingTop: 10,
        }}>
          {q.detail || "You did not write much down."}
        </div>

        {q.reward ? (
          <div style={{ marginTop: 10, fontSize: 11, color: C.brass }}>
            Stated payment: {q.reward}
          </div>
        ) : null}

        {q.kind === "rumor" || q.status === "rumor" ? (
          <Empty>
            Heard, not verified. People in Kommelby repeat things because
            repeating things is free.
          </Empty>
        ) : null}

        <div style={{ marginTop: 14, display: "flex", flexDirection: "column", gap: 6 }}>
          <Btn wide onClick={function () { askAbout(q); }}>THINK ON IT</Btn>
          {!q.formal ? (
            <Btn wide onClick={function () { dropPersonal(q); }}>STRIKE IT OUT</Btn>
          ) : (
            <Empty>
              A formal request cannot be torn out of the record. It is closed by
              the guild, or by failing it.
            </Empty>
          )}
        </div>
      </Screen>
    );
  }

  // --- list -------------------------------------------------------------
  return (
    <Screen
      title="JOURNAL"
      onClose={props.onClose}
      tabs={TABS_journal}
      tab={tab}
      onTab={function (x) { setTab(x); }}
    >
      {rows.length === 0 ? (
        <Empty>
          {tab === "OPEN"
            ? "Nothing owed and nothing promised. The tax is still the only deadline you have."
            : tab === "RUMOR"
              ? "You have not heard anything worth writing down."
              : "Nothing finished, nothing failed. Yet."}
        </Empty>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
          {rows.map(function (q, i) {
            return (
              <button
                key={q.id || i}
                className="ds-btn"
                onClick={function () { setOpen(q); }}
                style={{
                  fontFamily: MONO,
                  textAlign: "left",
                  background: C.panel,
                  borderRadius: R.sm,
                  border: "1px solid " + (q.formal ? C.brass : C.rule),
                  color: C.bone,
                  padding: "9px 12px",
                  cursor: "pointer",
                  minHeight: 42,
                }}
              >
                <div style={{ fontSize: 11 }}>{q.title || "(untitled)"}</div>
                <div style={{ marginTop: 4, fontSize: 9, color: C.boneFaint, letterSpacing: "0.1em" }}>
                  {(q.formal ? "REQUEST" : "PERSONAL") +
                    (q.source && q.source !== "self" ? " · " + q.source : "") +
                    (q.deadline ? " · due " + q.deadline : "")}
                </div>
              </button>
            );
          })}
        </div>
      )}

      {tab !== "CLOSED" ? (
        <div style={{ marginTop: 14, borderTop: "1px solid " + C.rule, paddingTop: 10 }}>
          {writing ? (
            <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
              <textarea
                value={draft}
                onChange={function (e) { setDraft(e.target.value); }}
                placeholder="what you mean to do"
                rows={3}
                style={{
                  fontFamily: MONO, fontSize: 11, padding: 8,
                  background: C.void, color: C.bone,
                  border: "1px solid " + C.rule, outline: "none", resize: "vertical",
                }}
              />
              <div style={{ display: "flex", gap: 6 }}>
                <Btn onClick={addPersonal}>WRITE IT DOWN</Btn>
                <Btn onClick={function () { setWriting(false); setDraft(""); }}>NEVER MIND</Btn>
              </div>
            </div>
          ) : (
            <Btn wide onClick={function () { setWriting(true); }}>+ OWN OBJECTIVE</Btn>
          )}
          <Empty>
            Your own notes only. Contracts get entered by whoever hands them to
            you, and they get closed the same way.
          </Empty>
        </div>
      ) : null}
    </Screen>
  );
}

