// Discovery-based geography. It draws map-knowledge and NOTHING else.
// A node the player has never reached does not exist on this screen.

var TYPE = {
  district:   { mark: "▣", color: "#c9c5b8", word: "district" },
  landmark:   { mark: "◈", color: "#8a7a3f", word: "landmark" },
  portal:     { mark: "◉", color: "#a83232", word: "dimensional square" },
  rift:       { mark: "✶", color: "#a83232", word: "rift" },
  settlement: { mark: "⌂", color: "#8b877c", word: "settlement" },
  danger:     { mark: "✕", color: "#7d1f1f", word: "known danger" },
  altar:      { mark: "△", color: "#8a7a3f", word: "altar" },
};

function num_map(v, d) { return typeof v === "number" ? v : d; }
function arr_map(v) { return Array.isArray(v) ? v : []; }
function obj_map(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }
function MapScreen(props) {
  var api = useYumina();
  var v = api.variables || {};
  var mk = obj_map(v["map-knowledge"]);
  var floor = num_map(v["current-floor"], 0);
  var seen = arr_map(v["floors-seen"]);
  var here = String(v["location"] || "");

  var startLayer = floor === 0 ? "surface" : "floor" + floor;
  var ls = React.useState(startLayer);
  var layer = ls[0], setLayer = ls[1];
  var ns = React.useState(null);
  var node = ns[0], setNode = ns[1];

  // Layers you may look at: the city, plus any floor you have walked.
  var layers = [["surface", "CITY"]];
  seen.slice().sort(function (a, b) { return a - b; }).forEach(function (f) {
    layers.push(["floor" + f, "F" + f]);
  });
  if (floor > 0 && seen.indexOf(floor) < 0) layers.push(["floor" + floor, "F" + floor]);

  var nodes = arr_map(mk[layer]);
  var sel = node !== null && node !== undefined ? nodes[node] : null;

  function travel(n) {
    if (props.onClose) props.onClose();
    api.sendMessage("I set out for " + n.name + ", and travel there.");
  }

  return (
    <Screen title="MAP" onClose={props.onClose}>
      <div style={{ display: "flex", gap: 3, flexWrap: "wrap", marginBottom: 10 }}>
        {layers.map(function (l) {
          var on = layer === l[0];
          return (
            <button key={l[0]}
              className="ds-btn"
              onClick={function () { setLayer(l[0]); setNode(null); }}
              style={{
                fontFamily: MONO, fontSize: 9, letterSpacing: "0.14em",
                padding: "7px 14px", minHeight: 32,
                borderRadius: 999,
                background: on ? C.blood : C.panel,
                color: on ? "#f5f0e2" : C.boneDim,
                border: "1px solid " + (on ? C.bloodLit : C.rule),
                cursor: "pointer",
              }}>
              {l[1]}
            </button>
          );
        })}
      </div>

      {nodes.length === 0 ? (
        <div style={{ border: "1px solid " + C.rule, borderRadius: R.md, background: C.panel, padding: 16 }}>
          <Empty>
            {layer === "surface"
              ? "You have walked almost none of this city. Streets you have not been down are not streets you know."
              : "You have not seen enough of this floor to draw it. Nobody hands out maps of the Labyrinth; the ones for sale are wrong on purpose."}
          </Empty>
        </div>
      ) : (
        <div style={{
          position: "relative", width: "100%", paddingTop: "72%",
          borderRadius: R.lg, overflow: "hidden",
          background: C.panel, border: "1px solid " + C.rule,
          boxShadow: SH.panel,
          backgroundImage:
            "repeating-linear-gradient(0deg,rgba(58,58,64,0.28) 0px,rgba(58,58,64,0.28) 1px,transparent 1px,transparent 26px)," +
            "repeating-linear-gradient(90deg,rgba(58,58,64,0.28) 0px,rgba(58,58,64,0.28) 1px,transparent 1px,transparent 26px)",
        }}>
          {nodes.map(function (n, i) {
            var t = TYPE[n.type] || TYPE.landmark;
            var on = node === i;
            var youAreHere = here && n.name && here.toLowerCase().indexOf(String(n.name).toLowerCase()) >= 0;
            return (
              <button key={n.id || i}
                className="ds-btn"
                onClick={function () { setNode(on ? null : i); }}
                style={{
                  position: "absolute",
                  left: num_map(n.x, 50) + "%",
                  top: num_map(n.y, 50) + "%",
                  transform: "translate(-50%,-50%)",
                  borderRadius: R.sm,
                  background: on ? C.panelUp : "transparent",
                  border: "1px solid " + (on ? C.ruleLit : "transparent"),
                  boxShadow: on ? SH.glow : "none",
                  padding: "3px 5px",
                  minWidth: 34, minHeight: 34,
                  cursor: "pointer", fontFamily: MONO,
                  display: "flex", flexDirection: "column", alignItems: "center", gap: 1,
                }}>
                <span style={{ fontSize: 15, lineHeight: 1, color: t.color }}>{t.mark}</span>
                <span style={{
                  fontSize: 8, letterSpacing: "0.06em", whiteSpace: "nowrap",
                  color: youAreHere ? C.bone : C.boneDim,
                  textShadow: "0 0 4px " + C.void + ",0 0 4px " + C.void,
                }}>
                  {n.name}
                </span>
                {youAreHere ? (
                  <span style={{ fontSize: 7, color: C.bloodLit, letterSpacing: "0.1em" }}>HERE</span>
                ) : null}
              </button>
            );
          })}
        </div>
      )}

      {sel ? (
        <div style={{ marginTop: 10, borderRadius: R.md, border: "1px solid " + C.ruleLit, background: C.panel, padding: 12, boxShadow: SH.panel }}>
          <div style={{ fontSize: 12, letterSpacing: "0.08em" }}>{sel.name}</div>
          <div style={{ fontSize: 10, color: C.boneFaint, marginBottom: 6 }}>
            {(TYPE[sel.type] || TYPE.landmark).word}
          </div>
          {sel.notes ? (
            <div style={{ fontSize: 10, color: C.boneDim, lineHeight: 1.7, marginBottom: 8 }}>
              {sel.notes}
            </div>
          ) : (
            <Empty>You have been here. You did not learn much.</Empty>
          )}
          <Btn wide onClick={function () { travel(sel); }}>
            TRAVEL — {sel.name}
          </Btn>
          <div style={{ fontSize: 9, color: C.boneFaint, marginTop: 6, lineHeight: 1.6 }}>
            Walking there takes as long as walking there takes, and the road is
            not empty.
          </div>
        </div>
      ) : null}

      <div style={{ marginTop: 14, paddingTop: 8, borderTop: "1px solid " + C.rule }}>
        <Stat label="Standing on" value={floor === 0 ? (here || "the surface") : "floor " + floor} dim />
        <Stat label="Floors walked" value={seen.length ? seen.join(", ") : "none"} dim />
        <div style={{ marginTop: 8, display: "flex", gap: 8, flexWrap: "wrap" }}>
          {Object.keys(TYPE).map(function (k) {
            return (
              <span key={k} style={{ fontSize: 9, color: C.boneFaint }}>
                <span style={{ color: TYPE[k].color }}>{TYPE[k].mark}</span> {TYPE[k].word}
              </span>
            );
          })}
        </div>
      </div>
    </Screen>
  );
}

// ==== npc.tsx ===================================================
// Who you are talking to. Openers are shortcuts, never the whole conversation —
// the text field underneath remains the real interface.


// ==== persistent-npc-actors.ts ===============================================
// Any named person who becomes materially interactive receives a stable actor
// record. The record is hidden simulation state; current-npc remains only the
// player's perceptible/learned slice.

function npcStableSlug(name, extra){
  var raw=(String(name||"person")+"|"+String(extra||"")).toLowerCase()
    .replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,52);
  return raw||("npc-"+stablePartyHash(String(name||"person")+"|"+String(extra||"")));
}
function npcNum(v,d){return typeof v==="number"&&isFinite(v)?v:d;}
function npcArr(v){return Array.isArray(v)?v:[];}
function npcObj(v){return v&&typeof v==="object"&&!Array.isArray(v)?v:{};}

function defaultNpcPersonality(seedText, role){
  var seed=stablePartyHash(String(seedText||"npc")+"|"+String(role||""));
  function n(shift){return 20+((seed>>>shift)%61);}
  var p={
    aggression:n(0),caution:n(3),discipline:n(6),altruism:n(9),
    independence:n(12),frugality:n(15),ambition:n(18),loyalty:n(21),
    sociability:n(2),patience:n(5),honesty:n(8),curiosity:n(11)
  };
  var r=String(role||"").toLowerCase();
  if(/merchant|shop|trader|clerk/.test(r)){p.patience=Math.max(50,p.patience);p.frugality=Math.max(45,p.frugality);}
  if(/guard|soldier|explorer|fighter/.test(r)){p.discipline=Math.max(50,p.discipline);}
  if(/priest|healer|medic/.test(r)){p.altruism=Math.max(60,p.altruism);}
  return p;
}
function normalizeNpcPersonality(raw, seedText, role){
  var d=defaultNpcPersonality(seedText,role),r=npcObj(raw),p={};
  Object.keys(d).forEach(function(k){p[k]=Math.max(0,Math.min(100,npcNum(r[k],d[k])));});
  p.traits=npcArr(r.traits).slice(0,6);
  p.likes=npcArr(r.likes).slice(0,5);
  p.dislikes=npcArr(r.dislikes).slice(0,5);
  p.fears=npcArr(r.fears).slice(0,5);
  p.values=npcArr(r.values).slice(0,5);
  return p;
}
function defaultNpcStats(seedText, role, rank){
  var seed=stablePartyHash(String(seedText||"npc")+"|stats|"+String(role||""));
  var rp=partyRankPower(rank);
  function stat(shift,base){return Math.max(1,base+((seed>>>shift)%9)-4);}
  var martial=/explorer|fighter|guard|soldier|mercenary|hunter|warrior|barbar|knight/.test(String(role||"").toLowerCase());
  var social=/merchant|clerk|broker|innkeeper|noble|official/.test(String(role||"").toLowerCase());
  return {
    strength:stat(0,martial?10+rp:7),flexibility:stat(4,martial?10:8),
    vision:stat(8,9),smell:stat(12,7),accuracy:stat(16,martial?10+Math.floor(rp/2):7),
    spirit:Math.max(0,stat(20,/mage|wizard|priest|healer|caster/.test(String(role||"").toLowerCase())?10+rp:4)),
    socialPresence:stat(24,social?11:7)
  };
}
function npcDefaultGoals(actor){
  var p=actor.personality||{},role=String(actor.role||actor.occupation||"person").toLowerCase(),goals=[];
  if(/merchant|shop|trader|innkeeper/.test(role))goals.push({id:"business-stability",kind:"work",title:"Keep the business viable",priority:70,status:"active",progress:0});
  if(/explorer|fighter|mercenary|hunter/.test(role))goals.push({id:"survive-and-improve",kind:"survival",title:"Survive and improve their prospects",priority:70,status:"active",progress:0});
  if(Number(p.ambition||0)>=60)goals.push({id:"advance",kind:"ambition",title:"Improve status, wealth, or capability",priority:55+Number(p.ambition||0)*.25,status:"active",progress:0});
  if(Number(p.frugality||0)>=60)goals.push({id:"save",kind:"finance",title:"Protect and grow personal resources",priority:50+Number(p.frugality||0)*.2,status:"active",progress:0});
  if(!goals.length)goals.push({id:"ordinary-life",kind:"life",title:"Maintain an ordinary workable life",priority:50,status:"active",progress:0});
  return goals;
}
function inferNpcSimLevel(actor){
  if(actor&&Number(actor.simLevel)>=1)return Math.max(1,Math.min(3,Math.floor(Number(actor.simLevel))));
  var role=String(actor&&actor.role||actor&&actor.occupation||"").toLowerCase();
  if(actor&&actor.major===true||actor&&actor.canon===true)return 3;
  if(/merchant|shop|innkeeper|guild|clerk|landlord|neighbor|rival|explorer|priest|healer|smith|broker/.test(role))return 2;
  return 1;
