        })}

        <SectionHead icon="soul">Soul Succession</SectionHead>
        {note("The six-month training called quenching makes your body a vessel. After it you may pass one essence to a future warrior. It can be done once, and the one who inherits it must die.")}
        {fact("Quenching", rc.quenching && rc.quenching.done ? "completed" : "not begun")}
        {fact("Succession", rc.succession && rc.succession.used ? "used" : "unused")}

        {rack ? (
          <div>
            <SectionHead icon="sword">From the ceremony</SectionHead>
            {fact("The chief's weapon", rack.label)}
          </div>
        ) : null}

        <SectionHead icon="shield" color={C.bloodLit}>What your race costs you</SectionHead>
        {fact("Swimming", "you sink", C.bloodLit)}
        {fact("The church of Tovera", "will not heal you", C.bloodLit)}
        {fact("City work", "none open", C.bloodLit)}
        {fact("Tax loan", "none exists", C.bloodLit)}
      </div>
    );
  }

  if (race === "Human") {
    var au = rc.aura && typeof rc.aura === "object" ? rc.aura : {};
    var awake = !!(au.talent && au.revealed);
    var trainKind = rc.training ? String(rc.training) : null;
    var TRAIN_TXT = {
      wizard: "You are a wizard's student. The training costs more than most families see in a decade, and wizards cannot absorb essences.",
      priest: "You serve a temple. Clergy of the Three Gods pay no tax at all.",
      spiritist: "You work with spirits. Every contract has to be found in the world, not handed over.",
    };
    return (
      <div>
        <Frame title="TRAINING" icon="skills" lit>
          <div style={{ fontFamily: DISPLAY, fontSize: 16, fontWeight: 600, letterSpacing: "0.08em" }}>{String(v["path"] || "No track")}</div>
          {note(trainKind ? TRAIN_TXT[trainKind] : "Humans have no racial ability, and every career in the city is open to them. What you become is decided by what you do.")}
        </Frame>

        <SectionHead icon="sword" color={awake ? C.brassLit : C.brass}>Aura</SectionHead>
        {awake ? (
          <Frame lit>
            <div style={{ fontFamily: DISPLAY, fontSize: 15, letterSpacing: "0.1em", color: C.brassLit }}>AWAKENED</div>
            {note("When you use mana, an aura flickers on the blade" + (au.colour ? " — " + String(au.colour) + ", in your case" : "") + ". It ignores 90% of defence and 90% of magic resistance. It needs a sword.")}
          </Frame>
        ) : (
          <div>
            {note("Nothing marks this body out. Only humans can use aura, it needs a sword, and about one in a hundred can. You find out by trying, not by choosing.")}
            {fact("Effect, in canon", "ignores 90% defence & magic resistance")}
          </div>
        )}
        <SectionHead icon="coin">Your tax</SectionHead>
        {fact("Tax owed", num_panel(v["tax-owed"], 0).toLocaleString() + " stones", num_panel(v["tax-owed"], 0) > 0 ? C.bloodLit : C.boneFaint)}
        {note(num_panel(v["tax-owed"], 0) === 0 ? "Clergy of the Three Gods pay no tax at all." : "Lighter than every other race's except clergy of the Three Gods. Not light.")}
      </div>
    );
  }

  if (race === "Dwarf") {
    var numbered = arr_panel(v["numbered-items"]);
    var invItems = normalizeList(v["inventory"]);
    var wornValue = invItems.reduce(function (t, x) { return t + (x.equipped ? num_panel(x.value, 0) * Math.max(1, num_panel(x.qty, 1)) : 0); }, 0);
    var tradeName = rc.trade === "smith" ? "Blacksmith" : rc.trade === "builder" ? "Builder" : "Explorer";
    return (
      <div>
        <Frame title="BLESSING OF ARMS" icon="armor" lit>
          <div style={{ fontFamily: DISPLAY, fontSize: 16, fontWeight: 600, letterSpacing: "0.08em" }}>Innate</div>
          {note("Numbered items work about one and a half times as well in your hands. The old dwarven tricks for gear are passed down inside the race; ask around before you assume you have them.")}
        </Frame>
        <SectionHead icon="ring">Numbered items</SectionHead>
        {numbered.length === 0 ? <Empty>None yet. This is where the blessing counts most.</Empty>
          : numbered.map(function (x, i) {
            return <div key={i} style={{ fontSize: 13.5, padding: "3px 0" }}><span style={{ color: C.bloodLit }}>No. {x.no}</span> {x.name}</div>;
          })}
        <SectionHead icon="fence">Your trade</SectionHead>
        {fact("What the body did", tradeName)}
        {rc.trade === "smith" ? note("A blacksmith's taxes are reduced.") : null}
        <SectionHead icon="shield" color={C.bloodLit}>Worth robbing</SectionHead>
        {note("The best item builds in the world are dwarven, and everyone knows it.")}
        {fact("Value worn on your body", wornValue.toLocaleString() + " stones", wornValue > 0 ? C.brassLit : C.boneFaint)}
      </div>
    );
  }

  if (race === "Elf") {
    var held = Array.isArray(rc.contracts) ? rc.contracts : [];
    function signed(id) { return held.filter(function (c) { return c && c.spirit === id; })[0] || null; }
    return (
      <div>
        <Frame title="CONTRACTS" icon="world" lit>
          <div style={{ fontFamily: DISPLAY, fontSize: 16, fontWeight: 600, letterSpacing: "0.08em" }}>
            {held.length} of 4 great spirits
          </div>
          {note("A contract is signed with a spirit, not learned. A talented elf can hold all four great spirits. The resources used to deal with them are elementals and natural forces.")}
        </Frame>
        <SectionHead icon="spirit">Spirits</SectionHead>
        {ELF_SPIRITS.map(function (sp0) {
          var c = signed(sp0[0]);
          var rare = sp0[0] === "darkness" || sp0[0] === "light";
          return (
            <div key={sp0[0]} style={{ display: "flex", alignItems: "center", gap: 10, padding: "9px 10px", marginBottom: 5, borderRadius: R.sm,
              border: "1px solid " + (c ? C.brassLit : C.rule), background: c ? "rgba(226,184,101,0.07)" : MAT.iron, boxShadow: c ? SH.glow : "none" }}>
              <span style={{ color: c ? C.brassLit : C.boneFaint }}><Icon name="spirit" size={20} /></span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontFamily: DISPLAY, fontSize: 13, letterSpacing: "0.06em", color: c ? C.brassLit : C.bone }}>{sp0[1]}</div>
                <div style={{ fontFamily: PROSE, fontSize: 13, color: C.boneFaint }}>{sp0[2]}</div>
              </div>
              <span style={{ fontFamily: DISPLAY, fontSize: 9.5, letterSpacing: "0.12em", color: c ? C.brassLit : C.boneFaint }}>
                {c ? "SIGNED" : rare ? "RARE" : "UNSIGNED"}
              </span>
            </div>
          );
        })}
        <SectionHead icon="vision">Senses</SectionHead>
        {note("Elves feel presence and traps from a long way off, and move through bushes without a sound.")}
        {fact("Vision", num_panel(subs["vision"], 0))}
      </div>
    );
  }

  if (race === "Beastman") {
    var st0 = rc.soulTree && typeof rc.soulTree === "object" ? rc.soulTree : {};
    var chosen = !!(st0.chosen && st0.revealed);
    var KIND = { summon: "Summon", reinforcement: "Reinforcement", blessing: "Blessing" };
    return (
      <div>
        <Frame title="SOUL TREE" icon="smell" lit>
          {chosen ? (
            <div>
              <div style={{ fontFamily: DISPLAY, fontSize: 16, fontWeight: 600, letterSpacing: "0.08em", color: C.brassLit }}>
                {KIND[st0.kind] || "Chosen"}{st0.beast ? " — " + String(st0.beast) : ""}
              </div>
              {note("An ancient beast chose you. The contract grows over time, and eating the beast's blood shortens the wait.")}
            </div>
          ) : (
            <div>
              <div style={{ fontFamily: DISPLAY, fontSize: 16, fontWeight: 600, letterSpacing: "0.08em" }}>No contract</div>
              {note("The Soul Tree has not spoken to you. It chooses; you do not. Most beastmen are never chosen, and a good line only improves the odds.")}
            </div>
          )}
        </Frame>
        <SectionHead icon="spirit">What it can grant</SectionHead>
        {fact("Summon", "a portal opens and it fights beside you")}
        {fact("Reinforcement", "your body rises a grade")}
        {fact("Blessing", "the beast's special ability is yours")}
        {note("Exactly one of the three. Never a mix.")}
        <SectionHead icon="smell">Your senses</SectionHead>
        {note("Sense of smell gates abilities no other race can use.")}
        {fact("Sense of Smell", num_panel(subs["smell"], 0))}
      </div>
    );
  }

  return <Empty>This body has no racial system.</Empty>;
}

function Sheet(props) {
  var api = useYumina();
  var v = api.variables || {};
  // Only the character's own race gets a racial tab.
  var raceTab = RACIAL_TAB[String(v["race"] || "")] || null;
  var tabsList = raceTab ? ["SOUL", raceTab, "BODY", "KIT", "BAGS", "CODEX"] : TABS_panel;

  var ts = React.useState("SOUL");
  var tab = ts[0], setTab = ts[1];
  var sel = React.useState(null);
  var bagPickS = React.useState(null);
  var bagPick = bagPickS[0], setBagPick = bagPickS[1];
  // `pick` is an item ID, never an array index. Two Iron Daggers are two
  // objects, and the world can reorder the pack between render and click.
  var pick = sel[0], setPick = sel[1];
  var regionFocusS = React.useState(null);
  var regionFocus = regionFocusS[0], setRegionFocus = regionFocusS[1];
  var dollS = React.useState(false);
  var dollOn = dollS[0], setDollOn = dollS[1];
  var fullRecS = React.useState(false);
  var fullRec = fullRecS[0], setFullRec = fullRecS[1];

  // One canonical reading of the pack for every tab on this screen.
  var items = normalizeList(v["inventory"]);
  var numbered = arr_panel(v["numbered-items"]);
  var ledger = obj_panel(v["numbered-item-ledger"]);

  // --- migration --------------------------------------------------------
  // Old saves hold rows with no id, `desc` instead of `description`, or an
  // equipped flag on a backpack good. Stamp permanent ids on them ONCE and
  // write the canonical shape back. Deterministic, and it never drops an item.
  React.useEffect(function () {
    var raw = arr_panel(v["inventory"]);
    if (!raw.length) return;
    if (!needsMigration(raw)) return;
    api.setVariable("inventory", migrateInventory(raw).list);
  }, [v["inventory"]]);

  // --- numbered item reconciliation ------------------------------------
  // The ledger is authoritative about who physically holds a number. If the
  // pack claims a number the ledger records elsewhere, the row is flagged
  // disputed and un-equipped rather than deleted — the GM settles it in
  // fiction. A number carried twice is impossible and the copy is dropped.
  React.useEffect(function () {
    var held = arr_panel(v["numbered-items"]);
    if (!held.length) return;
    var r = reconcileNumbered(held, ledger, v["char-name"]);
    if (!r.changed) return;
    api.setVariable("numbered-items", r.items);
    var notes = [];
    if (r.duplicates.length) {
      notes.push("Duplicate Numbered Item numbers were carried and the copies removed: " +
        r.duplicates.join(", ") + ". Only one physical instance of a number exists.");
    }
    if (r.conflicts.length) {
      notes.push(r.conflicts.map(function (c) {
        return "No. " + c.no + " (" + c.name + ") is recorded as held by " +
          (c.holder || "someone else") + ", not the player";
      }).join("; ") + ". Treat the player's as unverified — a forgery, a mistake, " +
        "or a transfer the record has not caught up with. Resolve it in fiction; " +
        "do not simply let two exist.");
    }
    if (r.invalid.length) {
      notes.push("Carried as a Numbered Item without a valid 1-10000 number: " +
        r.invalid.join(", ") + ". It is not one.");
    }
    if (notes.length) api.injectContext("[UI/LEDGER] " + notes.join(" "));
  }, [v["numbered-items"], v["numbered-item-ledger"]]);
  var ess = arr_panel(v["essences"]);
  var cap = num_panel(v["essence-capacity"], 3);
  var weight = ess.reduce(function (a, e) { return a + num_panel(e.weight, 1); }, 0);
  var lvl = num_panel(v["level"], 0);
  var ach = num_panel(v["achievements"], 0);
  var nextT = THRESH[lvl] || null;
  var cond = num_panel(v["condition"], 100);
  var stones = num_panel(v["mana-stones"], 0);
  var hurt = arr_panel(v["injuries"]);
  var know = obj_panel(v["knowledge"]);

  // --- real state mutation ---------------------------------------------
  // Equipping is a physical act. Write the array, then tell the GM it
  // happened so narration and state never disagree.
  function commit(next, note) {
    api.setVariable("inventory", next);
    if (note) api.injectContext(note);
  }

  // Equip/unequip is a FLAG REWRITE on the one existing object — it never
  // concats, so no path here can produce a second copy. setEquipped() owns the
  // one-per-slot rule (accessories take two, oldest yields).
  function toggleEquip(id) {
    var it = byId(items, id);
    if (!it || !it.slot || it.slot === "backpack") return;
    var wasOn = it.equipped === true;
    commit(
      setEquipped(items, id, !wasOn),
      wasOn
        ? "[UI] The player removed their " + it.name + "."
        : "[UI] The player equipped their " + it.name + " in " +
          it.slot + "."
    );
  }

  function drop(id) {
    var it = byId(items, id);
    // The world may have taken it already — never delete a row the player is no
    // longer actually looking at.
    if (!it) { setPick(null); return; }
    setPick(null);
    // Drops one unit of a stack, the whole row when it is the last one. An
    // equipped item comes off the body as it leaves the pack; removeItem drops
    // the object entirely, so no ghost equipped copy can survive it.
    var dropped=Object.assign({},it,{qty:1,equipped:false,placement:{kind:"world",location:String(v["location"]||"unknown")}});
    api.setVariable("ground-items",arr_panel(v["ground-items"]).concat([dropped]).slice(-120));
    commit(removeItem(items,id,1),
      "[UI PHYSICAL ACTION — ALREADY APPLIED] The player dropped one "+it.name+" at "+String(v["location"]||"the current location")+
      ". The exact object is now in ground-items and no longer follows the player.");
  }


  function ingestKind(it) {
    if (!it) return "";
    var n=(String(it.name||"")+" "+String(it.type||"")).toLowerCase();
    if (it.container && it.container.resource === "water") return "drink";
    var ef=it.effects&&typeof it.effects==="object"?it.effects:{};
    var per=ef.effectPerPortion&&typeof ef.effectPerPortion==="object"?ef.effectPerPortion:ef;
    if (typeof per.hydration==="number" && typeof per.hunger!=="number") return "drink";
    if (typeof per.hunger==="number") return "eat";
    if (/\b(food|bread|loaf|ration|rations|meat|jerky|fruit|vegetable|stew|soup|meal|cheese|fish|mushroom)\b/.test(n)) return "eat";
    if (/\b(water|waterskin|drink|juice|tea|coffee|milk|broth|ale|beer|wine|cider)\b/.test(n)) return "drink";
    return "";
  }

  function inferredIngestEffect(it) {
    if (!it) return null;
    var n=(String(it.name||"")+" "+String(it.type||"")).toLowerCase();
    // Canon-silent numerical fills are simulation defaults. Authored/canon
    // effects always win over these legacy/generic fallbacks.
    if (/\b(loaf|bread)\b/.test(n)) return {hunger:20};
    if (/\b(ration|rations)\b/.test(n)) return {hunger:25};
    if (/\b(jerky|dried meat)\b/.test(n)) return {hunger:18};
    if (/\b(meal|stew)\b/.test(n)) return {hunger:40};
    if (/\b(fruit)\b/.test(n)) return {hunger:12,hydration:4};
    if (/\b(soup|broth)\b/.test(n)) return {hunger:20,hydration:12};
    if (/\b(water)\b/.test(n) && !(it.container&&it.container.resource==="water")) return {hydration:20};
    if (/\b(juice|milk|tea)\b/.test(n)) return {hydration:18};
    return null;
  }

  function ingestButtonLabel(it) {
    var k=ingestKind(it);
    return k==="eat"?"EAT":k==="drink"?"DRINK":"USE";
  }

  function resolveIngestState(v,items,id,requestedKind) {
    var it=byId(items,id);
    if(!it) return {ok:false,reason:"item not carried",items:items};
    var kind=ingestKind(it);
    if(requestedKind && kind!==requestedKind) return {ok:false,reason:"item is not valid for "+requestedKind,items:items};

    var access=itemAccessTier(it,items);
    var combatActive=obj_panel(v["encounter-state"]).active===true;
    if(combatActive&&(access==="buried"||access==="slow"||access==="awkward"||access==="none"))
      return {ok:false,reason:"item is "+access+" access and must be retrieved first",items:items};

    var effects=it.effects&&typeof it.effects==="object"?it.effects:{};
    var inferred=inferredIngestEffect(it);
    var nextItems=items.slice();
    var idx=indexOfId(nextItems,id);
    if(idx<0) return {ok:false,reason:"item identity missing",items:items};
    var live=Object.assign({},nextItems[idx]);
    var hungerNow=num_panel(v["hunger"],100);
    var hydNow=num_panel(v["hydration"],num_panel(v["thirst"],100));
    var staminaNow=num_panel(v["stamina"],100);
    var condNow=num_panel(v["condition"],100);
    var changed=[],consumed=false;

    if(live.container&&live.container.resource==="water"){
      var c=Object.assign({},live.container);
      var available=Math.max(0,num_panel(c.current,0));
      var need=Math.max(0,100-hydNow);
      var drink=Math.min(available,need);
      if(drink>0){
        hydNow=Math.min(100,hydNow+drink);
        c.current=Math.max(0,available-drink);
        live.container=c;nextItems[idx]=live;
        changed.push({var:"hydration",value:hydNow});
        changed.push({var:"thirst",value:hydNow});
        consumed=true;
      } else return {ok:false,reason:available<=0?"container is empty":"hydration is already full",items:items};
    } else {
      var per=effects.effectPerPortion&&typeof effects.effectPerPortion==="object"?effects.effectPerPortion:effects;
      if((!per||Object.keys(per).length===0)&&inferred)per=inferred;
      var portions=effects.portionsCurrent!=null?Math.max(0,Math.floor(num_panel(effects.portionsCurrent,0))):null;
      if(portions!==null){
        if(portions<=0)return {ok:false,reason:"no portions remain",items:items};
        live.effects=Object.assign({},effects,{portionsCurrent:portions-1});nextItems[idx]=live;consumed=true;
      } else {
        nextItems=removeItem(nextItems,id,1);consumed=true;
      }
      if(consumed){
        if(typeof per.hunger==="number"){hungerNow+=Math.max(0,Math.min(per.hunger,100-hungerNow));changed.push({var:"hunger",value:hungerNow});}
        if(typeof per.hydration==="number"){hydNow+=Math.max(0,Math.min(per.hydration,100-hydNow));changed.push({var:"hydration",value:hydNow});changed.push({var:"thirst",value:hydNow});}
        if(typeof per.stamina==="number"){staminaNow+=Math.max(0,Math.min(per.stamina,100-staminaNow));changed.push({var:"stamina",value:staminaNow});}
        if(typeof per.condition==="number"){condNow+=Math.max(0,Math.min(per.condition,100-condNow));changed.push({var:"condition",value:condNow});}
      }
    }

    return {ok:consumed,reason:"",items:nextItems,changed:changed,item:it,kind:kind};
  }

  function use(id) {
    var it = byId(items, id);
    if (!it) return;
    var access = itemAccessTier(it, items);
    var combatActive = obj_panel(v["encounter-state"]).active === true;
    if (combatActive && (access==="buried"||access==="slow"||access==="awkward"||access==="none")) {
      api.injectContext("[UI] "+it.name+" is "+access+" access from its actual placement. It cannot be used instantly in combat; retrieve it first.",{role:"system"});
      return;
    }
    var effects = it.effects && typeof it.effects === "object" ? it.effects : {};
    var ingest = ingestKind(it);
    var inferred = inferredIngestEffect(it);
    var nextItems = items.slice();
    var idx = indexOfId(nextItems, id);
    if (idx < 0) return;
    var live = Object.assign({}, nextItems[idx]);
    function clamp100(x) { return Math.max(0, Math.min(100, x)); }
    function setNum(name, value) { api.setVariable(name, clamp100(value)); }
    var hungerNow = num_panel(v["hunger"], 100);
    var hydNow = num_panel(v["hydration"], num_panel(v["thirst"], 100));
    var staminaNow = num_panel(v["stamina"], 100);
    var condNow = num_panel(v["condition"], 100);
    var changed = [];
    var consumed = false;

    if (live.container && live.container.resource === "water") {
      var c = Object.assign({}, live.container);
      var available = Math.max(0, num_panel(c.current, 0));
      var drink = Math.min(available, Math.max(0, 100 - hydNow));
      if (drink > 0) {
        hydNow += drink;
        c.current = available - drink;
        live.container = c;
        nextItems[idx] = live;
        setNum("hydration", hydNow);
        setNum("thirst", hydNow);
        changed.push("hydration +" + drink);
        consumed = true;
      }
    } else {
      var per = effects.effectPerPortion && typeof effects.effectPerPortion === "object" ? effects.effectPerPortion : effects;
      if ((!per || Object.keys(per).length===0) && inferred) per=inferred;
      var portions = effects.portionsCurrent != null ? Math.max(0, Math.floor(num_panel(effects.portionsCurrent, 0))) : null;
      if (portions !== null && portions > 0) {
        live.effects = Object.assign({}, effects, { portionsCurrent: portions - 1 });
        nextItems[idx] = live;
        consumed = true;
      } else if (live.type === "consumable" || ingest==="eat" || ingest==="drink") {
        nextItems = removeItem(nextItems, id, 1);
        consumed = true;
      }
      if (consumed) {
        if (typeof per.hunger === "number") { var ah=Math.max(0,Math.min(per.hunger,100-hungerNow)); hungerNow+=ah; setNum("hunger",hungerNow); changed.push("hunger +"+ah); }
        if (typeof per.hydration === "number") { var ay=Math.max(0,Math.min(per.hydration,100-hydNow)); hydNow+=ay; setNum("hydration",hydNow); setNum("thirst",hydNow); changed.push("hydration +"+ay); }
        if (typeof per.stamina === "number") { var as=Math.max(0,Math.min(per.stamina,100-staminaNow)); staminaNow+=as; setNum("stamina",staminaNow); changed.push("stamina +"+as); }
        if (typeof per.condition === "number") { var ac=Math.max(0,Math.min(per.condition,100-condNow)); condNow+=ac; setNum("condition",condNow); changed.push("condition +"+ac); }
      }
    }

    if (!consumed) {
      setPick(null);
      if (props.onClose) props.onClose();
      api.sendMessage("I use the " + it.name + ".");
      return;
    }

    api.setVariable("inventory", nextItems);
    var ledger = arr_panel(v["item-use-ledger"]);
    api.setVariable("item-use-ledger", ledger.concat([{itemId:id,itemName:it.name,effects:changed,clock:v["clock"]}]).slice(-30));
    // EAT / DRINK buttons are intentionally silent: no chat message and no
    // narration-triggering context. The state and item-use ledger are the record.
    // Ordinary USE can still supply hidden context because non-food tools may
    // require narrative interpretation.
    if (ingest !== "eat" && ingest !== "drink") {
      api.injectContext("[UI PHYSICAL ACTION — ALREADY APPLIED] The player used " + it.name + ". " +
        (changed.length ? changed.join(", ") : "The item was consumed.") +
        " The state already reflects this use; do not apply it twice.");
    }
    setPick(null);
  }

  // Talismans: canon allows exactly one worn at a time.
  function toggleTalisman(i) {
    var it = numbered[i];
    if (!it) return;
    var wasOn = it.equipped === true;
    var next = numbered.map(function (x, j) {
      if (j === i) return Object.assign({}, x, { equipped: !wasOn });
      if (!wasOn && x.slot === "talisman" && it.slot === "talisman") {
        return Object.assign({}, x, { equipped: false });
      }
      return x;
    });
    api.setVariable("numbered-items", next);
    api.injectContext(
      wasOn
        ? "[UI] The player stopped wearing No. " + it.no + " " + it.name + "."
        : "[UI] The player is now wearing No. " + it.no + " " + it.name + "."
    );
  }

  // --- views ------------------------------------------------------------

  function soul() {
    var rankNo = num_panel(v["explorer-rank"], 0);
    var soulPct = nextT ? Math.min(100, Math.round((ach / nextT) * 100)) : 100;
    var raceId = v["race"] || "";
    return (
      <div>
        <Frame pad={false} lit>
          <div style={{ display: "flex", gap: 14, alignItems: "center", padding: 14,
            background: "linear-gradient(90deg,rgba(142,42,34,0.18),transparent 70%)" }}>
            <Medallion size={66} src={ART.portrait || (ART.races && ART.races[raceId]) || ""} icon={raceId ? "race-" + raceId : "sheet"} glow />
            <div style={{ minWidth: 0, flex: 1 }}>
              <div style={{ fontFamily: DISPLAY, fontSize: 19, fontWeight: 600, letterSpacing: "0.1em" }}>{v["char-name"] || "unnamed"}</div>
              <div style={{ fontFamily: PROSE, fontStyle: "italic", fontSize: 14.5, color: C.boneDim }}>
                {(raceId || "—") + " · " + (v["path"] || "no path set")}
              </div>
              <div style={{ marginTop: 6 }}>
                <Chip color={C.brassLit} border={C.brass}>{rankNo === 0 ? "UNREGISTERED" : "RANK " + rankNo}</Chip>
                <Chip color={v["citizen-status"] === "citizen" || !v["citizen-status"] ? C.boneDim : C.bloodLit}
                  border={v["citizen-status"] === "citizen" || !v["citizen-status"] ? C.rule : C.blood}>
                  {String(v["citizen-status"] || "citizen").toUpperCase()}
                </Chip>
              </div>
            </div>
          </div>
          <div style={{ padding: "0 14px 14px" }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", margin: "4px 0 5px" }}>
              <span style={{ fontFamily: DISPLAY, fontSize: 10.5, letterSpacing: "0.14em", color: C.brassLit }}>DIGNITY OF SOUL {lvl}</span>
              <span style={{ fontSize: 12, color: C.boneDim }}>{nextT ? ach + " / " + nextT + " achievement" : ach + " achievement"}</span>
            </div>
            <Band pct={soulPct} color={C.brass} />
          </div>
        </Frame>

        <div style={{ marginTop: 12 }}>
          <Stat label="Body's name" value={v["char-name"] || "unnamed"} rule />
          <Stat label="Race" value={v["race"] || "—"} rule />
          <Stat label="Path" value={v["path"] || "unset"} rule />
          <Stat
            label="Registry rank"
            value={rankNo === 0 ? "unregistered" : String(v["explorer-rank"])}
            rule
          />
          <Stat label="Standing" value={String(v["citizen-status"] || "citizen")} rule
            accent={v["citizen-status"] === "citizen" ? C.bone : C.bloodLit} />
          <Stat label="Dignity of Soul" value={lvl} rule />
          <Stat label="Achievement points" value={nextT ? ach + " / " + nextT : String(ach)} rule />
          <Stat label="Soul power" value={num_panel(v["soul-power"], 0)} rule />
          <Stat label="Days lived inside" value={num_panel(v["labyrinth-days"], 0)} rule dim />
        </div>

        <SectionHead icon="soul" right={weight + " / " + cap}>Essence engraved</SectionHead>
        <div style={{ display: "flex", gap: 8, margin: "4px 0 8px", flexWrap: "wrap" }}>
          {Array.from({ length: cap }).map(function (_, i) {
            var filled = i < weight;
            return (
              <div key={i} style={{
                width: 30, height: 30, transform: "rotate(45deg)", borderRadius: 4,
                background: filled ? "radial-gradient(circle at 40% 35%,#e0554f,#7a1d17 70%)" : "linear-gradient(180deg,#120f0c,#1c1813)",
                border: "1px solid " + (filled ? C.bloodLit : C.rule),
                boxShadow: filled ? "0 0 12px rgba(210,73,58,0.45), inset 0 1px 0 rgba(255,200,180,0.3)" : "inset 0 1px 3px rgba(0,0,0,0.8)",
                margin: "4px",
              }} />
            );
          })}
        </div>
        {weight >= cap ? (
          <div style={{ color: C.bloodLit, fontFamily: PROSE, fontSize: 14, lineHeight: 1.5 }}>
            Full. Nothing else fits until your soul grows. Erasure is done at a
            church, for a fee that doubles each time — and never for criminals.
          </div>
        ) : (
          <Empty>
            Room for {cap - weight} more. What you burn in early, you live with.
          </Empty>
        )}

        {ess.length === 0 ? (
          <Empty>Nothing has been burned into you yet.</Empty>
        ) : ess.map(function (e, i) {
          return (
            <div key={i} style={{ border: "1px solid " + C.rule, borderRadius: R.sm, padding: "9px 11px", marginTop: 7, background: MAT.iron }}>
              <div style={{ display: "flex", justifyContent: "space-between", gap: 8, alignItems: "baseline" }}>
                <span style={{ fontFamily: DISPLAY, fontSize: 13, fontWeight: 600, letterSpacing: "0.05em" }}>{e.source}</span>
                <span style={{ fontSize: 11.5, color: C.boneFaint }}>
                  rank {e.rank} · {e.color} · weight {num_panel(e.weight, 1)}
                </span>
              </div>
              <div style={{ color: C.boneDim, fontSize: 12.5, lineHeight: 1.6, marginTop: 3 }}>
                {arr_panel(e.abilities).join("   ·   ") || "no recorded abilities"}
              </div>
            </div>
          );
        })}

        {numbered.filter(function (x) { return x.soulbound; }).length ? (
          <div>
            <SectionHead icon="ring" color={C.bloodLit}>Soulbound</SectionHead>
            {numbered.filter(function (x) { return x.soulbound; }).map(function (x, i) {
              return (
                <div key={i} style={{ fontSize: 13, padding: "3px 0" }}>
                  <span style={{ color: C.bloodLit }}>No. {x.no}</span> {x.name}
                </div>
              );
            })}
          </div>
        ) : null}

        {v["ghost-busters-contact"] ? (
          <div style={{
            marginTop: 14, padding: 10, border: "1px solid " + C.blood, borderRadius: R.sm,
            background: "rgba(125,31,31,0.1)", fontFamily: PROSE, fontSize: 14, lineHeight: 1.55, color: C.boneDim,
          }}>
            You have a way to reach the others. The channel is not safe. Nothing
            about it is written down anywhere but in your own head.
          </div>
        ) : null}
      </div>
    );
  }

  function body() {
    var subs = obj_panel(v["substats"]);
    var phys = num_panel(v["physique"], 0);
    var thirst = num_panel(v["thirst"], 100);
    var floor = num_panel(v["current-floor"], 0);
    var stam = num_panel(v["stamina"], 100);
    var spiritMax = num_panel(v["spirit"], 0);
    var manaNow = num_panel(v["spirit-current"], spiritMax);
    var mp = spiritMax > 0 ? Math.min(100, Math.round((manaNow / spiritMax) * 100)) : 0;
    var passives = [];
    // Live essence bonuses — summed fresh every render from whatever is
    // CURRENTLY in the essences array. An essence never taken contributes
    // nothing; one erased (row removed via repair-log) stops contributing
    // the instant it's gone. Nothing to invalidate by hand, ever.
    var essMods = { strength: 0, flexibility: 0, vision: 0, smell: 0, accuracy: 0, spiritFlat: 0 };
    ess.forEach(function (e) {
      arr_panel(e.abilities).forEach(function (a) {
        if (String(a).indexOf("(P)") === 0) passives.push([e.source, a]);
      });
      var mods = obj_panel(e.statMods);
      Object.keys(essMods).forEach(function (k) {
        if (typeof mods[k] === "number") essMods[k] += mods[k];
      });
    });
    var essAny = Object.keys(essMods).some(function (k) { return essMods[k] !== 0; });
    var SUBROWS = [
      ["strength", "Strength", "strength"],
      ["flexibility", "Flexibility", "flexibility"],
      ["vision", "Vision", "vision"],
      ["smell", "Sense of Smell", "smell"],
      ["accuracy", "Accuracy Rate", "accuracy"],
    ];
    function subRow(row) {
      var base = num_panel(subs[row[0]], 0);
      var mod = essMods[row[0]] || 0;
      return (
        <div key={row[0]} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 2px", borderBottom: "1px solid rgba(110,90,62,0.25)" }}>
          <span style={{ color: "#b8483c", width: 22, display: "flex", justifyContent: "center" }}><Icon name={row[2]} size={19} /></span>
          <span style={{ flex: 1, fontFamily: DISPLAY, fontSize: 12.5, fontWeight: 600, letterSpacing: "0.04em" }}>{row[1]}</span>
          {mod ? <span style={{ fontSize: 11, color: C.brassLit }}>{(mod > 0 ? "+" : "") + mod} essence</span> : null}
          <span style={{ fontSize: 17, minWidth: 30, textAlign: "right", color: mod ? C.brassLit : C.bone }}>{base + mod}</span>
        </div>
      );
    }
    function condCard(label, pct, col, text, icon) {
      return (
        <div style={{ border: "1px solid " + C.rule, borderRadius: R.sm, padding: "9px 11px", background: MAT.iron }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
            <span style={{ color: col }}><Icon name={icon} size={15} /></span>
            <span style={{ fontFamily: DISPLAY, fontSize: 10.5, letterSpacing: "0.14em", color: C.boneDim, flex: 1 }}>{label}</span>
          </div>
          <Band pct={pct} color={col} />
          {text ? <div style={{ fontFamily: PROSE, fontStyle: "italic", fontSize: 13.5, color: C.boneFaint, marginTop: 5, lineHeight: 1.4 }}>{text}</div> : null}
        </div>
      );
    }
    return (
      <div>
        <Frame title={"PHYSIQUE  ·  " + phys + "  (" + bandWord(phys) + ")"} icon="strength">
          {SUBROWS.map(subRow)}
          <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 2px 2px" }}>
            <span style={{ color: C.brassLit, width: 22, display: "flex", justifyContent: "center" }}><Icon name="spirit" size={19} /></span>
            <span style={{ flex: 1, fontFamily: DISPLAY, fontSize: 12.5, fontWeight: 600, letterSpacing: "0.04em" }}>Spirit <span style={{ fontFamily: MONO, fontWeight: 400, fontSize: 11.5, color: C.boneFaint }}>(mana pool)</span></span>
            <span style={{ fontSize: 15, color: C.brassLit }}>{manaNow + " / " + (spiritMax + essMods.spiritFlat)}</span>
          </div>
          <div style={{ fontSize: 11.5, color: C.boneFaint, textAlign: "right" }}>{bandWord(spiritMax + essMods.spiritFlat)}</div>
          <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 2px 0", borderTop: "1px solid rgba(110,90,62,0.25)", marginTop: 6 }}>
            <span style={{ color: "#b8483c", width: 22, display: "flex", justifyContent: "center" }}><Icon name="obsession" size={19} /></span>
            <span style={{ flex: 1, fontFamily: DISPLAY, fontSize: 12.5, fontWeight: 600, letterSpacing: "0.04em" }}>Obsession</span>
            <span style={{ fontSize: 17 }}>{num_panel(v["obsession"], 0)}</span>
          </div>
          {essAny ? (
            <Empty>Numbers above include bonuses from essences currently absorbed. Erase one and its share leaves with it.</Empty>
          ) : null}
        </Frame>

        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(160px,1fr))", gap: 8, marginTop: 12 }}>
          {condCard("BODY", cond, cond < 25 ? C.bloodLit : "#c0392f",
            cond >= 80 ? "Whole. Stiff in the mornings, nothing more."
              : cond >= 50 ? "Hurt. You are favouring one side and you know it."
              : cond >= 20 ? "Badly injured. Everything costs more than it should."
              : "Dying. You can feel exactly how this ends.", "body")}
          {condCard("STAMINA", stam, stam < 25 ? C.bloodLit : "#8a8474",
            stam >= 70 ? "Breathing easy."
              : stam >= 40 ? "Winded. You would rather not run just now."
              : stam >= 15 ? "Your guard is dropping and you can feel it drop."
              : "Spent. Whatever happens next happens without you moving much.", "flexibility")}
          {spiritMax > 0 ? condCard("MANA", mp, mp < 25 ? C.bloodLit : C.brass, null, "spirit") : null}
          {floor > 0 ? condCard("THIRST", thirst, thirst < 25 ? C.bloodLit : "#4f86ad", null, "drop") : null}
        </div>

        <SectionHead icon="body" color={C.bloodLit}>Not healed</SectionHead>
        {hurt.length === 0 ? <Empty>Nothing that will not close on its own.</Empty>
          : hurt.map(function (x, i) {
            return (
              <div key={i} style={{ color: C.bloodLit, fontSize: 13, padding: "4px 0" }}>
                · {x && x.what ? x.what : String(x)}
                {x && x.since ? <span style={{ color: C.boneFaint }}> — since m{x.since}</span> : null}
              </div>
            );
          })}

        <SectionHead icon="soul">What the essence did to you</SectionHead>
        {passives.length === 0 ? <Empty>Your body is still only your body.</Empty>
          : passives.map(function (p, i) {
            return (
              <div key={i} style={{ fontSize: 13, padding: "3px 0", color: C.boneDim }}>
                {p[1]} <span style={{ color: C.boneFaint }}>— {p[0]}</span>
              </div>
            );
          })}
      </div>
    );
  }

  function kit() {
    var equippedBy = {};
    items.forEach(function (x) {
      if (x.equipped && isWearable(x.slot)) {
        if (!equippedBy[x.slot]) equippedBy[x.slot] = [];
        equippedBy[x.slot].push(x);
      }
    });

    // Like the reference sheet, the detail card is always showing something:
    // the tapped item, else the weapon in hand, else the first thing worn.
    var chosen = pick ? byId(items, pick) : null;
    var it = chosen || (equippedBy["main-hand"] || [])[0] ||
      items.filter(function (x) { return x.equipped; })[0] || items[0] || null;
    var itId = it ? it.id : null;

    var wornWeight = items.reduce(function (sum, x) {
      return sum + (x.equipped ? num_panel(x.weight, 0) * Math.max(1, num_panel(x.qty, 1)) : 0);
    }, 0);
    var totalWeight = items.reduce(function (sum, x) {
      return sum + num_panel(x.weight, 0) * Math.max(1, num_panel(x.qty, 1));
    }, 0);

    var protection = {};
    items.forEach(function (x) {
      if (!x.equipped || !x.armor || typeof x.armor !== "object") return;
      var pr = obj_panel(x.armor.protection);
      Object.keys(pr).forEach(function (k) {
        protection[k] = num_panel(protection[k], 0) + num_panel(pr[k], 0);
      });
    });

    var load = physicalCarryProfile(v, items);
    var bandCol = load.band === "comfortable" ? "#6f9a4c" : load.band === "heavy" ? C.brass : C.bloodLit;

    var pouchRawK = v["raw-stones"];
    var pouchBagK = pouchRawK && typeof pouchRawK === "object" && !Array.isArray(pouchRawK) ? pouchRawK : {};
    var pouchN = Object.keys(pouchBagK).reduce(function (a, k2) {
      var row = pouchBagK[k2];
      var q = row && typeof row === "object" ? row.qty : 0;
      return a + (typeof q === "number" && isFinite(q) ? q : 0);
    }, 0);
    var taxOwed = num_panel(v["tax-owed"], 0);

    function cap1(s) { s = String(s || ""); return s.charAt(0).toUpperCase() + s.slice(1); }
    var AUX_SHORT = { "main-hand": "Weapon (main)", "off-hand": "Off hand", head: "Head", shoulders: "Shoulders", torso: "Torso",
      arms: "Arms", hands: "Hands", legs: "Legs", feet: "Feet", waist: "Waist", back: "Back", accessory: "Accessory", clothes: "Clothes" };
    function slotLabel(x) {
      if (x.equipped) {
        if (AUX_SHORT[x.slot]) return AUX_SHORT[x.slot];
        return cap1(x.slot || "worn");
      }
      var p = physicalPlacement(x);
      if (p.kind === "container") {
        var c = byId(items, p.containerId);
        return "In " + (c ? c.name : "container");
      }
      if (storageProfileFor(x)) return "Storage";
      return cap1(x.type || "carried");
    }

    function slotRow(slot, label) {
      var here = equippedBy[slot] || [];
      return (
        <div key={slot} style={{
          display:"grid", gridTemplateColumns:"104px minmax(0,1fr)", gap:8, alignItems:"center",
          minHeight:36, padding:"6px 10px", borderTop:"1px solid rgba(110,90,62,0.22)",
          background: here.length ? "rgba(226,184,101,0.05)" : "transparent",
        }}>
          <div style={{fontFamily:DISPLAY,fontSize:8.5,letterSpacing:"0.1em",color:here.length?C.brass:C.boneFaint}}>{label}</div>
          <div>
            {here.length === 0 ? <span style={{fontSize:12,color:C.boneFaint}}>—</span> :
              here.map(function (w) {
                return <div key={w.id} onClick={function(){setPick(w.id);}}
                  style={{fontSize:13,color:C.bone,cursor:"pointer",padding:"2px 0",display:"flex",alignItems:"center",gap:7}}>
                  <span style={{color:C.brass}}><Icon name={glyphFor(w)} size={14} /></span>
                  <span style={{whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>{cap1(w.name)}</span></div>;
              })}
          </div>
        </div>
      );
    }
    function slotCard(slot, label) {
      var here = equippedBy[slot] || [];
      return (
        <div style={{border:"1px solid " + (here.length ? C.brassLit : C.rule),borderRadius:R.sm,background:MAT.iron,boxShadow:SH.glow,overflow:"hidden"}}>
          {slotRow(slot, label)}
        </div>
      );
    }

    // --- paper doll (shown when no portrait art, or when toggled) ----------
    function regionCount(id) { return (equippedBy[id] || []).length; }
    function sp(id) {
      var n = regionCount(id);
      return {
        fill: n === 0 ? "#1a1612" : n === 1 ? "rgba(184,137,59,0.28)" : n === 2 ? "rgba(184,137,59,0.48)" : "rgba(226,184,101,0.7)",
        stroke: regionFocus === id ? C.bloodLit : n ? C.brassLit : "#4a3d2e",
        strokeWidth: regionFocus === id ? 1.8 : 1.1,
      };
    }
    function part(id, el) {
      return <g key={id} onClick={function () { setRegionFocus(regionFocus === id ? null : id); }} style={{ cursor: "pointer" }}>{el}</g>;
    }
    var mainHand = equippedBy["main-hand"] && equippedBy["main-hand"].length;
    var offHand = equippedBy["off-hand"] && equippedBy["off-hand"].length;
    var doll = (
      <svg viewBox="0 0 100 210" width="100%" style={{ display: "block", maxHeight: 260 }}>
        <defs>
          <radialGradient id="dollGlow" cx="50%" cy="40%" r="60%">
            <stop offset="0%" stopColor="#3a2a18" stopOpacity="0.55" />
            <stop offset="100%" stopColor="#000" stopOpacity="0" />
          </radialGradient>
        </defs>
        <ellipse cx="50" cy="96" rx="48" ry="100" fill="url(#dollGlow)" />
        {part("head", <ellipse cx="50" cy="22" rx="12" ry="15" {...sp("head")} />)}
        {part("torso", <path d="M31 42 Q50 36 69 42 L73 66 L69 106 L31 106 L27 66 Z" {...sp("torso")} />)}
        {part("arms", <g><path d="M29 44 L19 52 L13 96 L21 98 L27 64 Z" {...sp("arms")} /><path d="M71 44 L81 52 L87 96 L79 98 L73 64 Z" {...sp("arms")} /></g>)}
        {part("shoulders", <g><ellipse cx="29" cy="45" rx="9" ry="5.5" {...sp("shoulders")} /><ellipse cx="71" cy="45" rx="9" ry="5.5" {...sp("shoulders")} /></g>)}
        {part("hands", <g><circle cx="16" cy="105" r="6" {...sp("hands")} /><circle cx="84" cy="105" r="6" {...sp("hands")} /></g>)}
        {part("legs", <g><path d="M32 108 L49 108 L47 184 L36 184 Z" {...sp("legs")} /><path d="M51 108 L68 108 L64 184 L53 184 Z" {...sp("legs")} /></g>)}
        {part("feet", <g><path d="M35 187 L48 187 L48 197 L28 197 Z" {...sp("feet")} /><path d="M52 187 L65 187 L72 197 L52 197 Z" {...sp("feet")} /></g>)}
        {mainHand ? <path d="M84 100 L96 58 M92 64 L99 66 M81 105 L87 107" stroke={C.bone} strokeWidth="1.6" strokeLinecap="round" fill="none" /> : null}
        {offHand ? <path d="M4 88 L20 84 L22 100 C20 110 12 116 7 117 C4 110 3 100 4 88 Z" fill="rgba(184,137,59,0.35)" stroke={C.brassLit} strokeWidth="1.1" /> : null}
      </svg>
    );
    var showPortrait = !!ART.portrait && !dollOn;
    var focusSlot = regionFocus ? PIECE_SLOTS_panel.filter(function (g) { return g[0] === regionFocus; })[0] : null;

    var panelBox = { position: "relative", border: "1px solid " + C.ruleLit, borderRadius: R.sm, background: MAT.iron, boxShadow: SH.panel };
    function headRow(icon, text, right) {
      return (
        <div style={{ display: "flex", alignItems: "center", gap: 7, padding: "7px 10px", borderBottom: "1px solid " + C.rule,
          background: "linear-gradient(180deg,rgba(255,220,160,0.05),transparent)" }}>
          <span style={{ color: C.brass }}><Icon name={icon} size={15} /></span>
          <span style={{ flex: 1, fontFamily: DISPLAY, fontSize: 10.5, fontWeight: 600, letterSpacing: "0.15em", color: C.brassLit, whiteSpace: "nowrap" }}>{text}</span>
          {right}
        </div>
      );
    }

    function itemRow(x) {
      var on = itId === x.id;
      var w = num_panel(x.weight, 0) * Math.max(1, num_panel(x.qty, 1));
      return (
        <div key={x.id} className="ds-row" onClick={function(){setPick(x.id);}}
          style={{
            display:"grid", gridTemplateColumns:"22px minmax(0,1fr) auto 30px", alignItems:"center", columnGap:8,
            padding:"6px 8px", cursor:"pointer", margin:"0 4px 2px", borderRadius:3,
            background: on ? "linear-gradient(90deg,rgba(226,184,101,0.14),rgba(226,184,101,0.04))" : "transparent",
            border: "1px solid " + (on ? C.brassLit : "transparent"),
            boxShadow: on ? SH.glow : "none",
            borderBottomColor: on ? C.brassLit : "rgba(58,49,40,0.55)",
          }}>
          <span style={{ color: on || x.equipped ? C.brassLit : C.boneDim, display: "flex", justifyContent: "center" }}>
            <Icon name={glyphFor(x)} size={17} stroke={1.5} />
          </span>
          <span style={{ fontSize: 13.5, color: C.bone, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
            {cap1(x.name)}{x.qty > 1 ? <span style={{ color: C.boneFaint }}>{" ×" + x.qty}</span> : null}
          </span>
          <span style={{ fontSize: 11, color: C.boneFaint, whiteSpace: "nowrap", maxWidth: 108, overflow: "hidden", textOverflow: "ellipsis" }}>{slotLabel(x)}</span>
          <span style={{ fontSize: 12.5, color: C.boneDim, textAlign: "right", fontVariantNumeric: "tabular-nums lining-nums" }}>{w.toFixed(1)}</span>
        </div>
      );
    }
    function subHead(icon, text) {
      return (
        <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "7px 10px 5px" }}>
          <span style={{ color: C.brass }}><Icon name={icon} size={13} /></span>
          <span style={{ fontFamily: DISPLAY, fontSize: 9.5, fontWeight: 600, letterSpacing: "0.15em", color: C.brass }}>{text}</span>
        </div>
      );
    }
    var worn = items.filter(function (x) { return x.equipped; });
    var carried = items.filter(function (x) { return !x.equipped; });

    var PROT_ICON = { blunt: "blunt", slash: "slash", pierce: "pierce" };
    var protKeys = Object.keys(protection);

    var durPct = it && typeof it.durability === "number" && typeof it.maxDurability === "number" && it.maxDurability > 0
      ? Math.max(0, Math.min(100, Math.round((it.durability / it.maxDurability) * 100))) : null;
    function cell(icon, label, value, extra) {
      return (
        <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "8px 9px", minWidth: 0, borderLeft: "1px solid " + C.rule, marginLeft: -1 }}>
          {icon ? <span style={{ color: C.boneDim }}><Icon name={icon} size={19} /></span> : null}
          <div style={{ minWidth: 0, flex: 1 }}>
            <div style={{ fontFamily: PROSE, fontSize: 12, color: C.boneFaint }}>{label}</div>
            <div style={{ fontSize: 13, color: C.bone, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{value}</div>
            {extra}
          </div>
        </div>
      );
    }
    var twoCol = { display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(150px,1fr))", columnGap: 16 };
    var handsTxt = it && it.weapon && it.weapon.hands !== undefined ? (Number(it.weapon.hands) >= 2 ? "Yes (2H)" : "No (1H)") : "unknown";

    return (
      <div>
        <div className="ds-kitgrid">
          {/* portrait column */}
          <div style={Object.assign({}, panelBox, { gridArea: "p", overflow: "hidden", background: MAT.leather, minHeight: 230,
            display: "flex", flexDirection: "column" })}>
            <Corners opacity={0.5} len={8} />
            {showPortrait ? (
              <img src={ART.portrait} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />
            ) : (
              <div style={{ flex: 1, display: "flex", alignItems: "center", padding: "10px 6px 0" }}>{doll}</div>
            )}
            <div style={{ position: "relative", marginTop: "auto", padding: "6px", display: "flex", justifyContent: "center",
              background: showPortrait ? "linear-gradient(180deg,transparent,rgba(10,8,7,0.85))" : "transparent" }}>
              {ART.portrait ? (
                <button className="ds-btn" onClick={function () { setDollOn(!dollOn); }}
                  style={{ fontFamily: DISPLAY, fontSize: 8, letterSpacing: "0.14em", padding: "4px 8px", borderRadius: 3, cursor: "pointer",
                    background: "rgba(12,10,9,0.8)", color: C.brassLit, border: "1px solid " + C.ruleLit }}>
                  {dollOn ? "PORTRAIT" : "LAYERS"}
                </button>
              ) : (
                <span style={{ fontFamily: DISPLAY, fontSize: 7.5, letterSpacing: "0.14em", color: C.boneFaint }}>TAP A REGION</span>
              )}
            </div>
          </div>

          {/* armor contributions */}
          <div style={Object.assign({}, panelBox, { gridArea: "a" })}>
            {headRow("shield", "ARMOR CONTRIBUTIONS")}
            <div style={{ padding: "8px 9px 9px" }}>
              {protKeys.length ? (
                <div style={{ display: "grid", gridTemplateColumns: "repeat(" + Math.min(3, protKeys.length) + ",minmax(0,1fr))", gap: 5 }}>
                  {protKeys.map(function (k) {
                    return (
                      <div key={k} style={{ display: "flex", alignItems: "center", gap: 4, padding: "6px 6px", borderRadius: 3,
                        border: "1px solid " + C.ruleLit, background: "linear-gradient(180deg,#221c15,#15110d)", minWidth: 0 }}>
                        <span className="ds-hide-narrow" style={{ color: C.boneDim }}><Icon name={PROT_ICON[k] || "shield"} size={14} /></span>
                        <span style={{ flex: 1, fontSize: 12, color: C.bone, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{cap1(k)}</span>
                        <span style={{ fontSize: 13.5, color: C.brassLit }}>{protection[k]}</span>
                      </div>
                    );
                  })}
                </div>
              ) : <div style={{ fontFamily: PROSE, fontStyle: "italic", fontSize: 13, color: C.boneFaint }}>Nothing worn is turning a blade.</div>}
              <div style={{ fontFamily: PROSE, fontSize: 12, color: C.boneFaint, lineHeight: 1.35, marginTop: 6 }}>
                Actual protection still depends on the struck region, coverage, durability, and attack type.
              </div>
            </div>
          </div>

          {/* load */}
          <div style={Object.assign({}, panelBox, { gridArea: "l" })}>
            {headRow("bags", "CARRIED / PACK",
              <span style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 13.5, color: C.bone }}>
                <span style={{ color: C.boneDim }}><Icon name="weight" size={13} /></span>{load.carried} / {load.comfortable}
              </span>)}
            <div style={{ padding: "9px 10px 8px" }}>
              <div style={{ position: "relative" }}>
                <Band pct={load.max > 0 ? (load.carried / load.max) * 100 : 0} color={bandCol} />
                <span style={{ position: "absolute", top: -2, bottom: -2, left: (load.comfortable / load.max * 100) + "%", width: 1, background: C.boneFaint }} />
                <span style={{ position: "absolute", top: -2, bottom: -2, left: (load.heavy / load.max * 100) + "%", width: 1, background: C.bloodLit }} />
              </div>
              <div style={{ display: "flex", justifyContent: "space-between", marginTop: 6, fontSize: 12 }}>
                <span style={{ color: bandCol }}>{cap1(load.band)}</span>
                <span style={{ color: C.boneFaint }}>Heavy {load.heavy} · Max {load.max}</span>
              </div>
            </div>
          </div>

          {/* worn + carried */}
          <div style={Object.assign({}, panelBox, { gridArea: "list", paddingBottom: 4 })}>
            {subHead("sheet", "WORN EQUIPMENT")}
            {worn.length === 0 ? <div style={{ padding: "0 10px" }}><Empty>Nothing on the body but skin.</Empty></div> : worn.map(itemRow)}
            {subHead("backpack", "PACK & CARRIED")}
            {carried.length === 0 ? <div style={{ padding: "0 10px" }}><Empty>{items.length === 0 ? "Nothing. A dead man's pockets were empty." : "Nothing unworn."}</Empty></div> : carried.map(itemRow)}
          </div>
        </div>

        {focusSlot ? <div style={{ marginTop: 9 }}>{slotCard(focusSlot[0], focusSlot[1])}</div> : null}

        {/* selected item */}
        {it ? (
          <div key={itId} className="ds-in" style={Object.assign({}, panelBox, { marginTop: 10, background: MAT.iron, boxShadow: SH.raised })}>
            <Corners opacity={0.7} />
            <div style={{ display: "flex", gap: 12, padding: 12 }}>
              <div style={{ width: 84, height: 96, flexShrink: 0, borderRadius: R.sm, border: "1px solid " + C.ruleLit,
                background: "radial-gradient(circle at 50% 35%,#2d261d,#0f0c0a 75%)", boxShadow: "inset 0 2px 8px rgba(0,0,0,0.8)",
                display: "flex", alignItems: "center", justifyContent: "center", color: C.bone }}>
                <Icon name={glyphFor(it)} size={52} stroke={1.2} />
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: "flex", alignItems: "flex-start", gap: 8 }}>
                  <div style={{ flex: 1, minWidth: 0, fontFamily: DISPLAY, fontSize: 16.5, fontWeight: 600, letterSpacing: "0.08em", lineHeight: 1.2 }}>{cap1(it.name)}</div>
                  <span style={{ display: "flex", alignItems: "center", gap: 3, fontSize: 13, color: C.boneDim, whiteSpace: "nowrap" }}>
                    <Icon name="weight" size={13} />{it.weight !== undefined ? it.weight : "?"}
                  </span>
                  <span style={{ fontFamily: DISPLAY, fontSize: 8.5, letterSpacing: "0.14em", padding: "3px 7px", borderRadius: 3,
                    border: "1px solid " + (it.equipped ? C.brass : C.rule), color: it.equipped ? C.brassLit : C.boneDim, whiteSpace: "nowrap" }}>
                    {it.equipped ? "WORN" : "CARRIED"}
                  </span>
                </div>
                <div style={{ fontSize: 12, color: C.boneFaint, marginTop: 3, paddingBottom: 6, borderBottom: "1px solid " + C.rule }}>
                  {[cap1(it.quality || it.condition || ""), it.equipped ? "Worn" : "Carried", cap1(it.type)].filter(Boolean).join("  •  ")}
                </div>
                {it.description ? <div style={{ fontFamily: PROSE, fontSize: 14.5, color: C.boneDim, lineHeight: 1.45, marginTop: 7 }}>{it.description}</div> : null}
              </div>
            </div>

            <div style={{ margin: "0 12px", display: "grid", gridTemplateColumns: "repeat(auto-fit,minmax(118px,1fr))",
              border: "1px solid " + C.rule, borderRadius: R.sm, background: "rgba(0,0,0,0.25)", overflow: "hidden" }}>
              {it.weapon && typeof it.weapon === "object" ? cell("sword", "Type", cap1(it.weapon.className || it.weapon.archetype || it.type)) :
                it.armor && typeof it.armor === "object" ? cell("armor", "Type", cap1(it.armor.className || it.armor.archetype || it.type)) :
                cell(glyphFor(it), "Type", cap1(it.type))}
              {it.weapon && typeof it.weapon === "object" ? cell("shield", "Damage", cap1(it.weapon.damageType || "unknown")) :
                it.armor && typeof it.armor === "object" ? cell("shield", "Coverage", Array.isArray(it.armor.coverage) ? it.armor.coverage.join(", ") : "unknown") :
                cell("map", "Place", slotLabel(it))}
              {it.weapon && typeof it.weapon === "object" ? cell("weight", "Two-handed", handsTxt) :
                it.armor && typeof it.armor === "object" && it.armor.block !== undefined ? cell("weight", "Block", it.armor.block) : null}
              {cell(null, "Condition",
                <span style={{ color: durPct !== null && durPct < 35 ? C.bloodLit : C.brassLit }}>{cap1(it.condition || "—")}{durPct !== null ? " (" + durPct + "%)" : ""}</span>,
                durPct !== null ? <div style={{ marginTop: 4 }}><Band pct={durPct} color={durPct < 35 ? C.bloodLit : C.brass} thin /></div> : null)}
            </div>

            <div style={{ padding: "10px 12px 12px" }}>
              <button className="ds-btn" onClick={function () { setFullRec(!fullRec); }}
                style={{ width: "100%", display: "flex", alignItems: "center", gap: 8, padding: "6px 0", background: "none", border: "none",
                  cursor: "pointer", color: C.brassLit, fontFamily: DISPLAY, fontSize: 10, fontWeight: 600, letterSpacing: "0.15em" }}>
                <span style={{ fontSize: 8 }}>{fullRec ? "▼" : "▶"}</span> FULL RECORD
                <span style={{ flex: 1, height: 1, background: "linear-gradient(90deg," + C.brass + "66,transparent)" }} />
              </button>
              {fullRec ? (
                <div>
                  <div style={twoCol}>
                    <Stat label="Condition" value={it.condition||<Unknown/>} dim />
                    <Stat label="Durability" value={it.durability!==undefined ? String(it.durability)+(it.maxDurability!==undefined?" / "+it.maxDurability:"") : <Unknown/>} dim />
                    <Stat label="Weight" value={it.weight!==undefined?it.weight:<Unknown/>} dim />
                    <Stat label="Worth" value={it.value!==undefined?it.value.toLocaleString():<Unknown/>} dim />
                    {it.material?<Stat label="Material" value={String(it.material).toUpperCase()} dim />:null}
                    {it.quality?<Stat label="Craftsmanship" value={it.quality} dim />:null}
                    {it.value!==undefined?<Stat label="Reference value" value={Math.round(it.value).toLocaleString()+" stones"} dim />:null}
                  </div>
                  {it.armor && typeof it.armor==="object" ? (
                    <div>
                      <SectionHead icon="shield">Armor</SectionHead>
                      <div style={twoCol}>
                        <Stat label="Class" value={it.armor.className||it.armor.archetype||<Unknown/>} dim />
                        {it.armor.construction?<Stat label="Construction" value={it.armor.construction} dim />:null}
                        {it.armor.shieldType?<Stat label="Shield type" value={it.armor.shieldType} dim />:null}
                        <Stat label="Coverage" value={Array.isArray(it.armor.coverage)?it.armor.coverage.join(", "):<Unknown/>} dim />
                        {it.armor.block!==undefined?<Stat label="Block" value={it.armor.block} dim />:null}
                        {it.armor.mobility!==undefined?<Stat label="Mobility modifier" value={it.armor.mobility} dim />:null}
                        {it.armor.stamina!==undefined?<Stat label="Stamina modifier" value={it.armor.stamina} dim />:null}
                      </div>
                      {it.armor.protection && typeof it.armor.protection==="object" ?
                        <div style={{display:"flex",flexWrap:"wrap",gap:4,marginTop:6}}>
                          {Object.keys(it.armor.protection).map(function(k){return <Chip key={k}>{k.toUpperCase()} {it.armor.protection[k]}</Chip>;})}
                        </div>:null}
                    </div>
                  ) : null}
                  {it.weapon && typeof it.weapon==="object" ? (
                    <div>
                      <SectionHead icon="slash">Weapon</SectionHead>
                      <div style={twoCol}>
                        <Stat label="Class" value={it.weapon.className||it.weapon.archetype||<Unknown/>} dim />
                        <Stat label="Power" value={it.weapon.power!==undefined?it.weapon.power:<Unknown/>} dim />
                        <Stat label="Damage type" value={it.weapon.damageType||<Unknown/>} dim />
                        <Stat label="Reach" value={it.weapon.reach!==undefined?it.weapon.reach:<Unknown/>} dim />
                        <Stat label="Handling" value={it.weapon.handling!==undefined?it.weapon.handling:<Unknown/>} dim />
                        <Stat label="Speed" value={it.weapon.speed!==undefined?it.weapon.speed:<Unknown/>} dim />
                        <Stat label="Armor penetration" value={it.weapon.armorPenetration!==undefined?it.weapon.armorPenetration:<Unknown/>} dim />
                        <Stat label="Critical bias" value={it.weapon.critBias!==undefined?it.weapon.critBias:<Unknown/>} dim />
                        <Stat label="Stamina use" value={it.weapon.staminaCost!==undefined?it.weapon.staminaCost:<Unknown/>} dim />
                        <Stat label="Hands" value={it.weapon.hands!==undefined?it.weapon.hands:<Unknown/>} dim />
                        {it.weapon.ammoType?<Stat label="Ammunition" value={it.weapon.ammoType} dim />:null}
                      </div>
                    </div>
                  ) : null}
                </div>
              ) : null}
              <div style={{ display: "flex", gap: 6, marginTop: 10, flexWrap: "wrap" }}>
                {isWearable(it.slot) ? <Btn onClick={function(){toggleEquip(itId);}} active={it.equipped}>{it.equipped ? "REMOVE" : "EQUIP"}</Btn> : null}
                <Btn onClick={function(){use(itId);}}>{ingestButtonLabel(it)}</Btn>
                <Btn onClick={function(){drop(itId);}}>DROP</Btn>
              </div>
            </div>
          </div>
        ) : null}

        {/* purse vs pouch */}
        <SectionHead icon="coin">Purse &amp; pouch</SectionHead>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8 }}>
          <div style={{ border: "1px solid " + C.brass + "88", borderRadius: R.sm, padding: "9px 10px", background: "linear-gradient(180deg,#2a2217,#15110c)" }}>
            <div style={{ fontFamily: DISPLAY, fontSize: 9, letterSpacing: "0.14em", color: C.boneDim }}>◆ STONES</div>
            <div style={{ fontSize: 19, color: C.brassLit, marginTop: 2 }}>{stones.toLocaleString()}</div>
            <div style={{ fontFamily: PROSE, fontStyle: "italic", fontSize: 12, color: C.boneFaint }}>Currency. Spendable.</div>
          </div>
          <div style={{ border: "1px dashed " + (pouchN > 0 ? C.bloodLit + "88" : C.rule), borderRadius: R.sm, padding: "9px 10px", background: "linear-gradient(180deg,#1f1512,#120c0a)" }}>
            <div style={{ fontFamily: DISPLAY, fontSize: 9, letterSpacing: "0.14em", color: C.boneDim }}>⛏ MANA STONE POUCH</div>
            <div style={{ fontSize: 19, color: pouchN > 0 ? C.bone : C.boneFaint, marginTop: 2 }}>{pouchN.toLocaleString()}</div>
            <div style={{ fontFamily: PROSE, fontStyle: "italic", fontSize: 12, color: C.boneFaint }}>Loot. Exchange at the Guild.</div>
          </div>
        </div>
        <div style={{ marginTop: 6 }}>
          <Stat label="Tax owed" value={taxOwed.toLocaleString() + " stones"} rule accent={taxOwed > 0 ? C.bloodLit : C.boneFaint} />
          <Stat label="Worn weight" value={wornWeight.toFixed(1)} rule dim />
          <Stat label="Carried weight (all)" value={totalWeight.toFixed(1)} rule dim />
        </div>

        <SectionHead icon="armor">Equipment — one piece per slot</SectionHead>
        <div style={{fontFamily:PROSE,fontStyle:"italic",fontSize:13,color:C.boneFaint,lineHeight:1.45,marginBottom:9}}>
          A finished piece of armor is one object, with its lining and padding built in. Equipping another piece replaces the one in that slot. Ordinary clothes are not armor.
        </div>
        <div style={{border:"1px solid "+C.ruleLit,borderRadius:R.sm,background:MAT.iron,boxShadow:SH.panel,overflow:"hidden"}}>
          {AUX_SLOTS_panel.map(function (r0) { return slotRow(r0[0], r0[1]); })}
          {PIECE_SLOTS_panel.map(function (r0) { return slotRow(r0[0], r0[1]); })}
        </div>

        <SectionHead icon="ring" color={C.bloodLit}>Numbered</SectionHead>
        {numbered.length===0?<Empty>None. Most explorers die never having held one.</Empty>:
          numbered.map(function(x,i){return <div key={i} style={{border:"1px solid "+C.blood,borderRadius:R.sm,background:"linear-gradient(180deg,rgba(142,42,34,0.14),rgba(20,12,10,0.6))",padding:10,marginBottom:6}}>
            <div style={{fontSize:13.5}}><span style={{fontFamily:DISPLAY,color:C.bloodLit,fontVariantNumeric:"tabular-nums lining-nums"}}>No. {x.no}</span>{" "}{x.name}</div>
            {x.disputed?<div style={{marginTop:4}}><Chip color={C.bloodLit} border={C.blood}>{x.disputed==="unnumbered"?"NO VALID NUMBER":"CLAIMED ELSEWHERE"}</Chip></div>:null}
            <div style={{fontSize:11.5,color:C.boneFaint,marginTop:3}}>{x.soulbound?"bound to you · ":""}{x.slot||"unclassified"}{x.equipped?" · worn":""}</div>
            {x.known?<div style={{fontFamily:PROSE,fontSize:14,color:C.boneDim,lineHeight:1.5,marginTop:4}}>{x.known}</div>:
              <div style={{fontFamily:PROSE,fontStyle:"italic",fontSize:13.5,color:C.boneFaint,marginTop:4}}>What it does, you have not finished finding out.</div>}
            {x.slot?<div style={{marginTop:6}}><Btn onClick={function(){toggleTalisman(i);}} active={x.equipped}>{x.equipped?"PUT AWAY":"WEAR"}</Btn></div>:null}
          </div>;})}
      </div>
    );
  }

  function bags() {
    var load=physicalCarryProfile(v,items);
    var containers=items.filter(function(it){return !!storageProfileFor(it);});
    var loose=items.filter(function(it){var p=physicalPlacement(it);return p.kind==="loose"&&!it.equipped&&!storageProfileFor(it);});
    function write(next,msg){api.setVariable("inventory",next);api.setVariable("carry-state",physicalCarryProfile(v,next));api.injectContext("[UI PHYSICAL ACTION — ALREADY APPLIED] "+msg+" Inventory placement is authoritative; do not narrate a duplicate transfer.",{role:"system"});}
    function equipC(id){var target=byId(items,id),sp=storageProfileFor(target);if(!target||!sp)return;var next=items.map(function(it){if(!it)return it;if(it.id===id)return Object.assign({},it,{equipped:true,slot:sp.equipSlot,placement:{kind:"body",slot:sp.equipSlot}});if(it.equipped===true&&it.slot===sp.equipSlot&&storageProfileFor(it))return Object.assign({},it,{equipped:false,placement:{kind:"loose"}});return it;});write(next,"The player equipped "+target.name+".");}
    function unequipC(id){var c=byId(items,id);var next=items.map(function(it){return it&&it.id===id?Object.assign({},it,{equipped:false,placement:{kind:"loose"}}):it;});write(next,"The player removed "+(c?c.name:"the container")+"; its contents stayed inside.");}
    function place(id,cid,sid){var it=byId(items,id),c=byId(items,cid),sp=storageProfileFor(c),sl=sp&&sp.slots.find(function(s){return s.id===sid;});if(!it||!c||!sl)return;var test=canPlaceInContainer(items,it,c,sl);if(!test.ok){api.injectContext("[UI] Cannot stow "+it.name+": "+test.why+".",{role:"system"});return;}var next=items.map(function(x){return x&&x.id===id?Object.assign({},x,{equipped:false,placement:{kind:"container",containerId:cid,slotId:sid}}):x;});write(next,"The player put "+it.name+" into "+c.name+" — "+sl.label+".");setBagPick(null);}
    function retrieve(id){var it=byId(items,id);if(!it)return;var access=itemAccessTier(it,items);var next=items.map(function(x){return x&&x.id===id?Object.assign({},x,{equipped:false,placement:{kind:"loose"}}):x;});write(next,"The player retrieved "+it.name+" from storage ("+access+" access).");}
    function autoStow(id){var it=byId(items,id);if(!it)return;var t=firstAutoStorageSlot(items,it);if(!t){api.injectContext("[UI] No equipped pocket, pouch, compartment or holder can physically take "+it.name+".",{role:"system"});return;}place(id,t.container.id,t.slot.id);}
    return <div>
      <div style={{padding:9,border:"1px solid "+C.rule,background:C.panel,marginBottom:12}}>
        <div style={{fontSize:10,letterSpacing:"0.14em",color:C.boneDim}}>PHYSICAL LOAD</div>
        <Stat label="carried" value={load.carried+" / "+load.comfortable+" comfortable"} rule />
        <Stat label="heavy threshold" value={load.heavy} /><Stat label="practical maximum" value={load.max} />
        <Stat label="burden" value={load.band.toUpperCase()} accent={load.band==="comfortable"?C.bone:C.bloodLit} />
        <div style={{fontSize:9,color:C.boneFaint,lineHeight:1.55,marginTop:6}}>Exact carry formula is simulation-created because canon gives no universal numerical carry-capacity rule. Bags create real storage/access, not infinite capacity.</div>
      </div>
      {containers.length===0?<Empty>No physical bag, pouch, quiver, sheath or scabbard.</Empty>:containers.map(function(c){var sp=storageProfileFor(c);return <div key={c.id} style={{border:"1px solid "+C.rule,marginBottom:10,padding:9,background:C.panel}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",gap:8}}><div><div style={{fontSize:11}}>{c.name}</div><div style={{fontSize:9,color:C.boneFaint}}>{sp.className} · {c.equipped?"WORN":"NOT WORN"}</div></div><Btn onClick={function(){c.equipped?unequipC(c.id):equipC(c.id);}}>{c.equipped?"REMOVE":"WEAR"}</Btn></div>
        {sp.slots.map(function(sl){var occ=containerOccupants(items,c.id,sl.id),ub=storedBulk(items,c.id,sl.id),uw=storedWeight(items,c.id,sl.id);return <div key={sl.id} style={{padding:"7px 0",borderTop:"1px dotted "+C.rule}}>
          <div style={{display:"flex",justifyContent:"space-between",gap:8}}><span style={{fontSize:9,color:C.brassLit}}>{sl.label}</span><span style={{fontSize:9,color:C.boneFaint}}>{sl.access} · bulk {ub}/{sl.bulkCap} · {Math.round(uw*10)/10}/{sl.weightCap} wt</span></div>
          {occ.length?occ.map(function(it){return <div key={it.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginTop:4}}><span style={{fontSize:10}}>{it.name}</span><Btn onClick={function(){retrieve(it.id);}}>TAKE OUT</Btn></div>}):<div style={{fontSize:9,color:C.boneFaint,marginTop:4}}>empty</div>}
          {bagPick&&c.equipped?<div style={{marginTop:5}}><Btn onClick={function(){place(bagPick,c.id,sl.id);}}>PUT SELECTED HERE</Btn></div>:null}
        </div>})}
      </div>})}
      <div style={{marginTop:14,fontSize:10,color:C.boneDim,letterSpacing:"0.12em"}}>LOOSE / UNSTOWED</div>
      {loose.length===0?<Empty>Nothing loose.</Empty>:loose.map(function(it){var isContainer=!!storageProfileFor(it);return <div key={it.id} style={{display:"flex",justifyContent:"space-between",alignItems:"center",padding:"6px 0",borderTop:"1px dotted "+C.rule}}><span style={{fontSize:10}}>{it.name} · {itemBulk(it)} bulk · {Number(it.weight||0)} wt</span>{isContainer?<span style={{fontSize:9,color:C.boneFaint}}>storage gear — wear it above</span>:<div style={{display:"flex",gap:4}}><Btn onClick={function(){setBagPick(it.id);}}>CHOOSE SLOT</Btn><Btn onClick={function(){autoStow(it.id);}}>AUTO-STOW</Btn></div>}</div>})}
      {bagPick?<Empty>Selected: {byId(items,bagPick)?byId(items,bagPick).name:"item"}. Choose a compatible slot above.</Empty>:null}
    </div>;
  }

  function codexList(title, o) {
    var keys = Object.keys(obj_panel(o));
    return (
      <div style={{ marginTop: 12 }}>
        <div style={{ color: C.boneDim, fontSize: 10, letterSpacing: "0.14em" }}>{title}</div>
        {keys.length === 0 ? <Empty>Nothing confirmed.</Empty> : keys.map(function (k) {
          var e = obj_panel(o)[k];
          return (
            <div key={k} style={{ borderTop: "1px dotted " + C.rule, padding: "5px 0" }}>
              <div style={{ fontSize: 11 }}>{k.replace(/-/g, " ")}</div>
              <div style={{ fontSize: 10, color: C.boneDim, lineHeight: 1.7 }}>
                {typeof e === "string" ? e : JSON.stringify(e)}
              </div>
            </div>
          );
        })}
      </div>
    );
  }

  function codex() {
    var killed = arr_panel(v["species-killed"]);
    var humanKills = Math.max(0, num_panel(v["human-kills"], 0));
    var seen = arr_panel(v["floors-seen"]);
    return (
      <div>
        <Empty>
          You remember a game. You do not remember this place. This is only what
          these eyes have actually confirmed.
        </Empty>
        <Stat label="Bestiary species first-killed" value={killed.length} rule />
        <Stat label="Human / explorer-race kills" value={humanKills} rule accent={humanKills > 0 ? C.bloodLit : C.boneFaint} />
        <Stat label="Floors walked" value={seen.length ? seen.join(", ") : "none"} rule />

        <div style={{
          marginTop: 12, padding: 9, border: "1px solid " + C.rule,
          background: humanKills > 0 ? "rgba(125,31,31,0.06)" : C.panel,
        }}>
          <div style={{ color: C.bloodLit, fontSize: 10, letterSpacing: "0.14em" }}>
            HUMAN — KILLED BY YOUR HAND
          </div>
          <div style={{ marginTop: 4, fontSize: 22, color: humanKills > 0 ? C.bone : C.boneFaint }}>
            {humanKills}
          </div>
          <div style={{ marginTop: 3, fontSize: 9, color: C.boneFaint, lineHeight: 1.55 }}>
            Generic person count. Human, Barbarian, Dwarf, Elf, Beastman,
            Draconian and other explorer races all count here. They never enter
            the monster bestiary and never award first-kill achievement points.
          </div>
        </div>

        <div style={{ marginTop: 12, color: C.boneDim, fontSize: 10, letterSpacing: "0.14em" }}>
          BESTIARY — KILLED BY YOUR HAND
        </div>
        {killed.length === 0 ? <Empty>You have not killed anything yet.</Empty> : (
          <div style={{ marginTop: 4 }}>
            {killed.map(function (k, i) { return <Chip key={i}>{k}</Chip>; })}
          </div>
        )}

        {codexList("PLACES", know.locations)}
        {codexList("PEOPLE", know.npcs)}
        {codexList("FACTIONS", know.factions)}
        {codexList("ESSENCE DATA", know.essences)}
        {codexList("NUMBERED ITEMS LEARNED OF", know.items)}

        <div style={{
          marginTop: 16, paddingTop: 8, borderTop: "1px solid " + C.rule,
          fontSize: 10, color: C.boneFaint, lineHeight: 1.7,
        }}>
          Rank nine essence data is free at any library. Anything above that is
          sold through the guild, or not sold at all.
        </div>
      </div>
    );
  }

  return (
    <Screen
      title="CHARACTER"
      onClose={props.onClose}
      tabs={tabsList}
      tab={tab}
      onTab={function (x) { setTab(x); setPick(null); }}
    >
      {tab === "SOUL" ? soul() : null}
      {raceTab && tab === raceTab ? <RacialPanel v={v} /> : null}
      {tab === "BODY" ? body() : null}
      {tab === "KIT" ? kit() : null}
      {tab === "BAGS" ? bags() : null}
      {tab === "CODEX" ? codex() : null}
    </Screen>
  );
}

// ==== shop.tsx ==================================================
// A merchant has a finite crate of stock and rent to pay. Nobody in Kommelby
// carries an infinite catalogue, and every stone that moves here moves in the
// simulation too.

function arr_shop(v) { return Array.isArray(v) ? v : []; }
function obj_shop(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }
function num_shop(v, d) { return typeof v === "number" ? v : d; }
function Shop(props) {
  var api = useYumina();
  var v = api.variables || {};
  var shop = obj_shop(v["shop-state"]);
  // Currency can never be read as negative, whatever the GM wrote.
  var stones = Math.max(0, num_shop(v["mana-stones"], 0));
  // Every screen sees the SAME normalized inventory. Legacy rows (desc/quantity,
  // no id) are read through the canonical shape without being rewritten here.
  var bag = normalizeList(v["inventory"]);

  var t = React.useState("BUY");
  var tab = t[0], setTab = t[1];
  var s = React.useState(null);
  var sel = s[0], setSel = s[1];

  // A different stall is a different crate. Never carry a selection across.
  var sig = String(shop.active === true) + "|" + String(shop.merchantName || "") +
    "|" + String(shop.location || "");
  React.useEffect(function () { setSel(null); setTab("BUY"); }, [sig]);

  // The merchant packs up if the ground moves under the conversation.
  var whereRef = React.useRef(null);
  var here = String(v["location"] || "") + "|" + String(v["current-floor"] || 0);
  React.useEffect(function () {
    if (shop.active !== true) { whereRef.current = null; return; }
    if (whereRef.current === null) { whereRef.current = here; return; }
    if (whereRef.current !== here) {
      whereRef.current = null;
      api.setVariable("shop-state", { active: false });
    }
  }, [shop.active, here]);

  if (shop.active !== true) return null;
  // A live haggle belongs to the chat, not to the counter. The panel stands
  // down for the length of the argument and comes straight back afterwards.
  if (obj_shop(shop.haggling).active === true) return null;

  var stock = arr_shop(shop.items);
  var buys = shop.buys !== false;

  // Sellable is decided by ONE shared rule (items.tsx): never a Numbered Item,
  // never soulbound, never something currently worn, never quest/nosale tagged.
  // Rows carry the item's stable id — not an array position — so a second Iron
  // Dagger can never be sold in place of the first.
  var sellable = [];
  bag.forEach(function (it) {
    if (isSellable(it)) sellable.push({ it: it, id: it.id });
  });

  function offer(it) {
    // A merchant pays a fraction, and says so to your face.
    var base = itemReferenceValue(it) * marketMultiplier(v, economyCategory(it), String(v["location"]||"")) * districtTradeMultiplier(String(v["location"]||""), economyCategory(it));
    var rate = num_shop(shop.buyRate, 0.4);
    if (rate < 0) rate = 0;
    if (rate > 1) rate = 1;
    return Math.max(1, Math.round(base * rate));
  }

  // --- transactions -----------------------------------------------------
  // Both directions are deterministic: currency is clamped at zero, quantity
  // can never go negative, and every mutation targets a stable identity rather
  // than an array position that the world may have shifted underneath us.
  function buy(it, i) {
    var price = economyAsk(v, it, shop);
    // Hard affordability gate. The disabled button is courtesy; this is the law.
    if (price > stones) return;
    // The crate may have been rewritten by the world since this row was picked.
    // Never decrement a row that is no longer the item the player chose.
    var live = stock[i];
    if (!live || live.name !== it.name) { setSel(null); return; }
    var qty = Math.max(0, Math.floor(num_shop(live.qty, 1)));
    if (qty <= 0) { setSel(null); return; }

    var nextStock = stock
      .map(function (x, j) {
        if (j !== i) return x;
        return Object.assign({}, x, { qty: qty - 1 });
      })
      .filter(function (x) { return num_shop(x.qty, 1) > 0; });

    // addItem() owns the stacking decision. Equipment, worn goods, anything
    // with wear state and every Numbered Item stay individual objects; only
    // genuinely interchangeable commodities merge.
    var bought = normalizeItem({
      id: makeId("buy"),
      name: it.name,
      type: it.type || "misc",
      slot: it.slot || "backpack",
      description: it.description || it.desc || "",
      value: price,
      qty: 1,
      equipped: false,
      durability: it.durability,
      maxDurability: it.maxDurability,
      weight: it.weight,
      condition: it.condition,
      quality: it.quality,
      material: it.material || inferMetal(it, it.name),
      tags: it.tags,
      effects: it.effects,
      weapon: it.weapon,
      armor: it.armor,
      container: it.container,
      ammo: it.ammo,
      provenance: it.provenance,
    }, 0);

    api.setVariable("mana-stones", Math.max(0, stones - price));
    api.setVariable("inventory", addItem(bag, bought));
    api.setVariable("shop-state", Object.assign({}, shop, { items: nextStock }));
    api.injectContext(
      "[UI] The player bought " + it.name + " from " +
      (shop.merchantName || "the merchant") + " for " + price +
      " stones (currency). Stones remaining: " + Math.max(0, stones - price) +
      ". Narrate the exchange briefly; the merchant's stock of that item is now " +
      (qty - 1) + "."
    );
    setSel(null);
  }

  function sell(it, id) {
    // Re-check by IDENTITY at the moment of sale. The world can strip an item
    // off the player between the tap and the confirmation, and two objects may
    // share a name — only the id says which one is leaving the pack.
    var idx = indexOfId(bag, id);
    if (idx < 0) { setSel(null); return; }
    var live = bag[idx];
    // The shared rule decides again here, so a row that became equipped or
    // contested since the list was drawn cannot be sold through the counter.
    if (!isSellable(live)) { setSel(null); return; }

    var paid = offer(live);
    var have = live.qty;
    // A stack sells ONE at a time. Paying for one torch and handing over three
    // would be the merchant robbing the player through a rounding error.
    api.setVariable("inventory", removeItem(bag, id, 1));
    api.setVariable("mana-stones", Math.max(0, stones + paid));
    api.injectContext(
      "[UI] The player sold one " + live.name + " to " +
      (shop.merchantName || "the merchant") + " for " + paid +
      " stones (currency)" + (have > 1 ? " (" + (have - 1) + " still carried)" : "") +
      ". The merchant haggled or did not, as suits them."
    );
    setSel(null);
  }

  // --- haggling ---------------------------------------------------------
  // A price is an opinion until somebody argues with it. The panel records
  // what is being argued over, stands down, and hands the floor to the
  // merchant. HaggleWatch closes the loop — the GM never moves money.
  function haggle(it, i, mode) {
    var listed = mode === "BUY" ? economyAsk(v, it, shop) : offer(it);

    api.setVariable("shop-state", Object.assign({}, shop, {
      haggling: {
        active: true,
        mode: mode,
        name: it.name,
        ref: mode === "BUY" ? i : String(i),
        listed: listed,
        returnToShop: true,
      },
      "haggle-result": null,
    }));

    api.injectContext(
      "[UI] HAGGLE OPENED over " + it.name + " with " +
      (shop.merchantName || "the merchant") + ". Listed at " + listed +
      " stones; the player is " + (mode === "BUY" ? "buying" : "selling") +
      ". The shop panel has stood down — play this out as dialogue at the " +
      "counter. This merchant has quota of their own and no reason to lose " +
      "money: they may refuse flatly, meet partway, want something other than " +
      "stones, or take offence and end it. Do not fold immediately, and do not " +
      "invent a price the player did not ask for. " +
      "THREE OUTCOMES, scalars only, no arrays: " +
      "[shop-state.haggle-result: set {\"outcome\":\"countered\",\"price\":N}] " +
      "when they name a middle number instead of answering yes or no — this " +
      "does NOT end the scene, the offer sits on the table and the player " +
      "answers it; " +
      "[shop-state.haggle-result: set {\"outcome\":\"accepted\",\"price\":N}] " +
      "when a number is genuinely agreed; " +
      "[shop-state.haggle-result: set {\"outcome\":\"refused\"}] only when they " +
      "are done and the argument is over. " +
      "A merchant who would rather not lose the sale COUNTERS. Flat refusal is " +
      "for insult, contempt, or a price under their own cost. " +
      "The interface applies the stones and the goods itself — never narrate " +
      "them changing hands, and never state a new purse total.",
      { role: "system" }
    );
    api.sendMessage(
      mode === "BUY"
        ? "[I try to talk " + (shop.merchantName || "the merchant") +
          " down on the " + it.name + ".]"
        : "[I try to talk " + (shop.merchantName || "the merchant") +
          " up on what they will pay for the " + it.name + ".]"
    );
    setSel(null);
    if (props.onClose) props.onClose();
  }

  function leave() {
    api.setVariable("shop-state", { active: false });
    if (props.onClose) props.onClose();
  }

  // --- rows -------------------------------------------------------------
  function Row(o) {
    var it = o.it;
    var price = o.mode === "BUY" ? economyAsk(v, it, shop) : offer(it);
    var afford = o.mode === "SELL" || price <= stones;
    var on = sel && sel.mode === o.mode && sel.i === o.i;
    return (
      <button
        className="ds-btn"
        onClick={function () { setSel(on ? null : { mode: o.mode, i: o.i, it: it }); }}
        style={{
          fontFamily: MONO,
          textAlign: "left",
          width: "100%",
          minHeight: 42,
          padding: "8px 12px",
          borderRadius: R.sm,
          background: on ? C.panelUp : C.panel,
          border: "1px solid " + (on ? C.brass : C.rule),
          boxShadow: on ? "0 0 0 1px " + C.brass + "55" : "none",
          color: afford ? C.bone : C.boneFaint,
          cursor: "pointer",
          display: "flex",
          alignItems: "center",
          gap: 8,
        }}
      >
        <span style={{ flex: 1, fontSize: 11 }}>
          {it.name}
          {num_shop(it.qty, 1) > 1 ? (
            <span style={{ color: C.boneFaint }}> ×{num_shop(it.qty, 1)}</span>
          ) : null}
        </span>
        <span style={{
          fontSize: 11,
          color: o.mode === "BUY" ? (afford ? C.brassLit : C.bloodLit) : C.brassLit,
          fontVariantNumeric: "tabular-nums",
        }}>
          {price.toLocaleString()}
        </span>
      </button>
    );
  }

  // Normalised rows: { it, i } where `i` is whatever the transaction needs to
  // target — the crate INDEX for BUY (the merchant's array is the merchant's),
  // the item's stable ID for SELL (the player's pack is identity-addressed).
  var rows = tab === "BUY"
    ? stock.map(function (it, i) { return { it: it, i: i }; })
    : sellable.map(function (r) { return { it: r.it, i: r.id }; });

  return (
    <div className="ds-scroll" style={{
      position: "absolute", inset: 0, zIndex: 34,
      background: "rgba(8,8,11,0.96)",
      backdropFilter: "blur(2px)",
      display: "flex", flexDirection: "column",
      fontFamily: MONO, color: C.bone,
    }}>
      {/* stall header */}
      <div style={{
        padding: "10px 14px",
        background: "linear-gradient(180deg," + C.panelUp + "," + C.panel + ")",
        borderBottom: "1px solid " + C.rule,
        boxShadow: "0 2px 8px rgba(0,0,0,0.35)",
        display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap",
      }}>
        <div style={{ flex: 1, minWidth: 120 }}>
          <div style={{ fontSize: 11, letterSpacing: "0.14em", color: C.brassLit }}>
            {shop.merchantName || "A STALL"}
          </div>
          <div style={{ fontSize: 9, color: C.boneFaint, letterSpacing: "0.1em" }}>
            {shop.location || v["location"] || ""}
          </div>
        </div>
        <span style={{
          fontSize: 12, color: C.brassLit, fontVariantNumeric: "tabular-nums",
          background: C.void, border: "1px solid " + C.brass, borderRadius: 999, padding: "2px 10px",
        }}>
          ◆ {stones.toLocaleString()}
        </span>
        <button
          className="ds-btn"
          onClick={leave}
          style={{
            fontFamily: MONO, fontSize: 11, padding: "5px 12px",
            borderRadius: R.sm,
            background: C.panel, color: C.boneDim,
            border: "1px solid " + C.rule, cursor: "pointer",
          }}
        >
          LEAVE
        </button>
      </div>

      {shop.mood ? (
        <div style={{
          padding: "8px 12px", fontSize: 10, lineHeight: 1.7,
          color: C.boneDim, borderBottom: "1px solid " + C.rule,
        }}>
          {shop.mood}
        </div>
      ) : null}

      {/* buy / sell */}
      <div style={{ display: "flex", borderBottom: "1px solid " + C.rule, background: C.panel }}>
        {["BUY", "SELL"].map(function (x) {
          var dead = x === "SELL" && !buys;
          var on = tab === x;
          return (
            <button
              key={x}
              className="ds-btn"
              onClick={dead ? undefined : function () { setTab(x); setSel(null); }}
              style={{
                flex: 1, fontFamily: MONO, fontSize: 9, letterSpacing: "0.16em",
                padding: "10px 0", minHeight: 36,
                background: on ? C.panelUp : "transparent",
                color: dead ? C.boneFaint : on ? C.brassLit : C.boneDim,
                border: "none", borderRight: "1px solid " + C.rule,
                boxShadow: on ? "inset 0 -2px 0 " + C.brass : "none",
                cursor: dead ? "not-allowed" : "pointer",
              }}
            >
              {x}
            </button>
          );
        })}
      </div>

      <div className="ds-scroll" style={{ flex: 1, minHeight: 0, overflowY: "auto", padding: 12 }}>
        {rows.length === 0 ? (
          <Empty>
            {tab === "BUY"
              ? "The crate is empty. Stock comes back when a caravan or an explorer brings it, not when you reopen this panel."
              : "Nothing on you they would take."}
          </Empty>
        ) : (
          <div style={{ display: "flex", flexDirection: "column", gap: 5 }}>
            {rows.map(function (r, k) {
              return <Row key={k} it={r.it} i={r.i} mode={tab} />;
            })}
          </div>
        )}
      </div>

      {/* selected item */}
      {sel ? (
        <div style={{
          borderTop: "1px solid " + C.rule,
          background: C.panel,
          boxShadow: "0 -2px 8px rgba(0,0,0,0.3)",
          padding: 12,
        }}>
          <div style={{ fontSize: 11 }}>{sel.it.name}</div>
          <div style={{ marginTop: 4 }}>
            <Chip>{sel.it.type || "misc"}</Chip>
            {sel.it.slot && sel.it.slot !== "backpack" ? <Chip>{sel.it.slot}</Chip> : null}
            {sel.it.weight ? <Chip>{sel.it.weight}</Chip> : null}
          </div>
              <div style={{ marginTop: 6, fontSize: 10, lineHeight: 1.7, color: C.boneDim }}>
                {sel.it.description || sel.it.desc || <Unknown />}
              </div>
          <div style={{ marginTop: 8, display: "flex", gap: 6, alignItems: "stretch" }}>
            <div style={{ flex: 1, minWidth: 0 }}>
              {sel.mode === "BUY" ? (
                <Btn
                  wide
                  disabled={economyAsk(v, sel.it, shop) > stones}
                  onClick={function () { buy(sel.it, sel.i); }}
                >
                  {economyAsk(v, sel.it, shop) > stones
                    ? "NOT ENOUGH STONES"
                    : "BUY — " + economyAsk(v, sel.it, shop).toLocaleString()}
                </Btn>
              ) : (
                <Btn wide onClick={function () { sell(sel.it, sel.i); }}>
                  {"SELL — " + offer(sel.it).toLocaleString()}
                </Btn>
              )}
            </div>
            <button
              className="ds-btn"
              onClick={function () { haggle(sel.it, sel.i, sel.mode); }}
              style={{
                fontFamily: MONO, fontSize: 10, letterSpacing: "0.14em",
                padding: "0 14px", minHeight: 38, borderRadius: R.sm,
                background: C.panelUp, color: C.brassLit,
                border: "1px solid " + C.brass, cursor: "pointer",
                whiteSpace: "nowrap",
              }}
            >
              HAGGLE
            </button>
          </div>
        </div>
      ) : null}

      <div style={{
        borderTop: "1px solid " + C.rule, padding: "6px 10px",
        fontSize: 9, color: C.boneFaint, lineHeight: 1.6,
      }}>
        Pick something and HAGGLE to argue the price at the counter. Credit, and
        anything not on the crate — close this and say it out loud.
      </div>
    </div>
  );
}

// ==== shop-catalog =========================================================
// The novel documents essences and Numbered Items in real depth. It does not
// document a mundane equipment catalog — no ordinary sword ever gets a stat
// block in the source material. So this is necessarily generated content,
// not transcribed canon. What IS canon and what this stays consistent with:
// Iron as the baseline metal, Grade 2 as the next real step up (twice as
// light, twice as strong, expensive), and the fact that nothing sold over
// a counter should ever approach Mystium/Arc tier — that metal exists to
// destroy Numbered Items, not stock a shopfront. Numbered Items and engraved
// essences never appear in this catalog at all; they have their own systems.

function shpId(cat, tier) { return cat + "-t" + tier; }

// ---- piece-based armor generator ---------------------------------------
// Dungeon & Stone treats a finished piece of armor as the item: a greave
// already has its leather lining, a breastplate its padding. So the catalog
// holds FORMS, and a piece is built by rolling, in order:
//   slot -> form -> metal -> craftsmanship -> condition -> stats -> price
// The stats and value come from the same archetype, metal, quality and
// condition machinery every other item in the world already uses. What a
// shop may roll is capped by the district's tier; the best grades are never
// on a shelf, only made to order.
//   cov   coverage override      iron   word for iron in this form's name
//   build how it is put together (canon: greaves are steel over leather)
//   anchor  list price for plain iron/leather, standard quality, sound
var ARMOR_FORMS = [
  // head
  { id: "cap-l", slot: "head", name: "Leather Cap", arch: "leather", tier: 1, anchor: 10000,
    build: "boiled leather over a cloth lining", desc: "Stops a graze from becoming a wound." },
  { id: "helm-o", slot: "head", name: "{m} Open Helm", iron: "Iron", arch: "plate", tier: 1, metal: true, anchor: 280000,
    build: "forged iron cap with a padded leather liner", desc: "Open at the face. You can still see and breathe, which is most of the point." },
  { id: "helm-c", slot: "head", name: "{m} Helm", iron: "Iron", arch: "plate", tier: 2, metal: true, anchor: 550000,
    build: "full forged helm with a padded leather liner", desc: "A real dent already in the crown from somebody else's bad day." },
  { id: "coif-m", slot: "head", name: "{m} Mail Coif", iron: "Iron", arch: "mail", tier: 2, metal: true,
    build: "riveted rings on a leather backing", desc: "Covers the neck the helm leaves open." },
  // shoulders
  { id: "sh-l", slot: "shoulders", name: "Leather Shoulder Guards", arch: "leather", tier: 1,
    build: "boiled leather, strapped across the chest", desc: "Turns a glancing blow off the shoulder." },
  { id: "sh-p", slot: "shoulders", name: "{m} Pauldrons", iron: "Steel", arch: "plate", tier: 2, metal: true,
    build: "steel plates over a leather harness", desc: "Steel over the shoulders. Worth more to a swordsman than they weigh." },
  // torso
  { id: "tor-pad", slot: "torso", name: "Padded Armor", arch: "padded", tier: 1, anchor: 15000,
    build: "quilted linen and wool, stitched in rows", desc: "Better than nothing. That is the entire pitch." },
  { id: "tor-lea", slot: "torso", name: "Boiled Leather Cuirass", arch: "leather", tier: 1, anchor: 90000,
    build: "boiled hard leather, laced at the side", desc: "Smells faintly of the process. Genuinely useful." },
  { id: "tor-vest", slot: "torso", name: "{m} Vest", iron: "Steel", arch: "plate", tier: 1, metal: true, anchor: 360000,
    build: "steel plate over the chest, leather-backed", desc: "What a low-level explorer actually saves up for. Real plate over the chest, not just boiled leather." },
  { id: "tor-band", slot: "torso", name: "Iron-Banded Leather Armor", arch: "brigandine", tier: 2, anchor: 700000,
