// District → which shop types exist there at all, and how good the stock gets.
// Karnon, Bifron and Kiarbis carry nothing deterministic — a commoner has no
// legitimate shop in the first, the second is prohibited, the third is
// residential. Left entirely to the GM if a scene ever needs one there.
var SHOP_DISTRICTS = [
  { match: "kommelby", types: ["weaponsmith", "armorer", "apothecary", "provisioner"], tierCap: 3, condPool: ["new", "sound", "used"] },
  { match: "ravigion", types: ["scavenger-stall"], tierCap: 1, condPool: ["used", "worn", "battered"] },
  { match: "gnome tree", types: ["provisioner", "apothecary"], tierCap: 2, condPool: ["sound", "used"] },
];

function shpDistrictFor(locationStr) {
  var s = String(locationStr || "").toLowerCase();
  for (var i = 0; i < SHOP_DISTRICTS.length; i++) {
    if (s.indexOf(SHOP_DISTRICTS[i].match) >= 0) return SHOP_DISTRICTS[i];
  }
  return null;
}

function shpRng(seed) {
  var s = (seed >>> 0) || 1;
  return function () {
    s ^= s << 13; s >>>= 0;
    s ^= s >> 17;
    s ^= s << 5; s >>>= 0;
    return s / 4294967296;
  };
}
function shpHash(str) {
  var h = 2166136261;
  for (var i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = (h * 16777619) >>> 0; }
  return h;
}

// A scavenger-stall carries a bit of everything at tier 1 only — that IS its
// identity, not a fallback. Every other type sticks to its own category.
function shpPool(shopType, tierCap) {
  if (shopType === "scavenger-stall") {
    return SHOP_CATALOG.filter(function (x) { return x.tier <= 1; });
  }
  return SHOP_CATALOG.filter(function (x) { return x.cat === shopType && x.tier <= tierCap; });
}

function shpResolve(shopType, district, seedStr) {
  var rng = shpRng(shpHash(seedStr));
  var count = 4 + Math.floor(rng() * 4); // 4-7 distinct lines
  var usedForms = {};

  // Armor is built, not listed: a slot, a form for it, a metal, a
  // craftsmanship and a condition, all capped by what this shop can make.
  function armorLines(n, cap) {
    var slots = ["torso", "head", "legs", "feet", "hands", "off-hand", "arms", "shoulders", "waist"];
    var start = Math.floor(rng() * slots.length);
    var out = [];
    for (var a = 0; a < 40 && out.length < n; a++) {
      var slot = a < slots.length ? slots[(start + a) % slots.length] : null;
      var line = genArmorPiece(rng, cap, district.condPool, slot, usedForms) ||
        genArmorPiece(rng, cap, district.condPool, null, usedForms);
      if (line) out.push(line);
    }
    return out;
  }
  if (shopType === "armorer") return armorLines(count, district.tierCap);

  var nArmor = shopType === "scavenger-stall" ? 1 + Math.floor(rng() * 2) : 0;
  var pool = shpPool(shopType, district.tierCap);
  if (!pool.length && !nArmor) return [];
  var want = Math.max(0, count - nArmor);
  var picked = [];
  var used = {};
  var tries = 0;
  while (pool.length && picked.length < Math.min(want, pool.length) && tries < 60) {
    tries++;
    var x = pool[Math.floor(rng() * pool.length)];
    if (used[x.id]) continue;
    used[x.id] = true;
    var variance = 0.85 + rng() * 0.3; // ±15%
    var price = Math.max(1, Math.round(x.price * variance));
    var qty = x.stack ? 2 + Math.floor(rng() * 4) : 1;
    var cond = district.condPool[Math.floor(rng() * district.condPool.length)];
    picked.push({
      name: x.name, type: x.type, slot: x.slot, price: price, qty: qty,
      description: x.desc, condition: cond,
    });
  }
  return picked.concat(armorLines(nArmor, 1));
}

// Silent, mounted always. Closes a haggle the moment the merchant actually
// settles. The GM argues; the interface is what moves stones and goods, so a
// deal struck in prose can never quietly mint an item or skip a payment.
function HaggleWatch() {
  var api = useYumina();
  var v = api.variables || {};
  var shop = obj_shop(v["shop-state"]);
  var hag = obj_shop(shop.haggling);
  var res = obj_shop(shop["haggle-result"]);
  var sig = String(hag.active) + "|" + String(res.outcome || "") + "|" +
    String(res.price === undefined ? "" : res.price);

  React.useEffect(function () {
    var s = obj_shop(v["shop-state"]);
    var h = obj_shop(s.haggling);
    var r = obj_shop(s["haggle-result"]);
    if (h.active !== true) return;
    if (!r.outcome) return;

    var stones = Math.max(0, num_shop(v["mana-stones"], 0));
    var bag = normalizeList(v["inventory"]);
    var stock = arr_shop(s.items);
    var who = s.merchantName || "the merchant";

    // COUNTERED — the merchant met them partway. This is NOT a settlement:
    // the shop stays shut, the scene stays live, and their number sits on the
    // table until the player answers it. Only the standing offer is recorded.
    if (r.outcome === "countered") {
      var offered = num_shop(r.price, -1);
      if (offered < 0) {
        // A counter with no number is not a counter. Discard it and let the
        // argument continue rather than freezing the scene on a null price.
        api.setVariable("shop-state", Object.assign({}, s, {
          "haggle-result": null,
        }));
        return;
      }
      var round = Math.max(0, Math.floor(num_shop(h.round, 0))) + 1;
      api.setVariable("shop-state", Object.assign({}, s, {
        haggling: Object.assign({}, h, { offer: offered, round: round }),
        "haggle-result": null,
      }));
      api.injectContext(
        "[UI] " + who + " countered at " + offered + " stones for " + h.name +
        " (listed " + num_shop(h.listed, 0) + "). No deal yet and nothing has " +
        "changed hands — the offer is on the table and the counter stays shut. " +
        "Hold the scene at the counter and let the player answer it. Do not " +
        "settle on their behalf.",
        { role: "system" }
      );
      return;
    }

    // Refused, or a price that never resolved to a real number: the argument
    // simply ends. Nothing moves, the counter comes back up, the listed price
    // stands exactly where it stood.
    // An "accepted" with no number means they took whatever was last on the
    // table — fall back to the standing counter-offer before giving up.
    var agreed = num_shop(r.price, -1);
    if (agreed < 0) agreed = num_shop(h.offer, -1);
    if (r.outcome !== "accepted" || agreed < 0) {
      api.setVariable("shop-state", Object.assign({}, s, {
        active: h.returnToShop === true ? true : s.active,
        haggling: { active: false }, "haggle-result": null,
      }));
      api.injectContext(
        "[UI] Haggle over " + h.name + " ended with no deal. Nothing changed hands. " +
        "The listed price stands and the counter is open again.",
        { role: "system" }
      );
      return;
    }

    if (h.mode === "BUY") {
      var i = num_shop(h.ref, -1);
      var live = stock[i];
      // The crate may have been rewritten mid-argument. Never decrement a row
      // that is no longer the thing being argued over.
      if (!live || live.name !== h.name) {
        api.setVariable("shop-state", Object.assign({}, s, {
          active: h.returnToShop === true ? true : s.active,
          haggling: { active: false }, "haggle-result": null,
        }));
        return;
      }
      if (agreed > stones) {
        // Agreeing to a price is not the same as having it.
        api.setVariable("shop-state", Object.assign({}, s, {
          active: h.returnToShop === true ? true : s.active,
          haggling: { active: false }, "haggle-result": null,
        }));
        api.injectContext(
          "[UI] " + who + " agreed to " + agreed + " stones for " + h.name +
          " and the player cannot cover it — they hold " + stones + ". " +
          "The deal collapses at the counter over money that is not there. " +
          "Nothing changed hands.",
          { role: "system" }
        );
        return;
      }

      var qty = Math.max(0, Math.floor(num_shop(live.qty, 1)));
      var nextStock = stock
        .map(function (x, j) {
          if (j !== i) return x;
          return Object.assign({}, x, { qty: qty - 1 });
        })
        .filter(function (x) { return num_shop(x.qty, 1) > 0; });

      var bought = normalizeItem({
        id: makeId("buy"),
        name: live.name,
        type: live.type || "misc",
        slot: live.slot || "backpack",
        description: live.description || live.desc || "",
        value: agreed,
        qty: 1,
        equipped: false,
        durability: live.durability,
        weight: live.weight,
        condition: live.condition,
        tags: live.tags,
      }, 0);

      api.setVariable("mana-stones", Math.max(0, stones - agreed));
      api.setVariable("inventory", addItem(bag, bought));
      api.setVariable("shop-state", Object.assign({}, s, {
        items: nextStock, haggling: { active: false }, "haggle-result": null,
      }));
      api.injectContext(
        "[UI] DEAL DONE. The player bought " + live.name + " from " + who +
        " for the haggled price of " + agreed + " stones (listed " +
        num_shop(h.listed, 0) + "). Stones remaining: " +
        Math.max(0, stones - agreed) + ". The item is in their pack and the " +
        "payment is already made — narrate only the handover, state no totals, " +
        "and do not move any stones yourself.",
        { role: "system" }
      );
      return;
    }

    // SELL — identity-addressed, re-checked at the moment the deal lands.
    var idx = indexOfId(bag, String(h.ref));
    if (idx < 0) {
      api.setVariable("shop-state", Object.assign({}, s, {
        active: h.returnToShop === true ? true : s.active,
        haggling: { active: false }, "haggle-result": null,
      }));
      return;
    }
    var sold = bag[idx];
    if (!isSellable(sold)) {
      api.setVariable("shop-state", Object.assign({}, s, {
        active: h.returnToShop === true ? true : s.active,
        haggling: { active: false }, "haggle-result": null,
      }));
      return;
    }
    var had = sold.qty;
    api.setVariable("inventory", removeItem(bag, String(h.ref), 1));
    api.setVariable("mana-stones", Math.max(0, stones + agreed));
    var ledgerSell=npcObj(v["npc-ledger"]),actorKeySell=String(nn.actorId||"");
    if(actorKeySell&&ledgerSell[actorKeySell]){
      var actorSell=normalizeNpcActor(ledgerSell[actorKeySell],actorKeySell,v);
      // Their personal purse is authoritative for casual person-to-person trades.
      // If they cannot actually cover an accepted deal, record debt rather than minting money.
      if(actorSell.personalStones>=agreed)actorSell.personalStones-=agreed;
      else{
        var shortfall=agreed-actorSell.personalStones;actorSell.personalStones=0;
        actorSell.obligations.push({id:"trade-debt-"+stablePartyHash(actorKeySell+"|"+String(v["clock"])+"|"+h.name),
          kind:"debt",title:"Owes "+shortfall+" stones after trade settlement",amount:shortfall,status:"active"});
      }
      actorSell.inventory=addItem(actorSell.inventory,Object.assign({},sold,{qty:1,equipped:false,ownerId:actorKeySell,ownerName:actorSell.name}));
      actorSell=npcRemember(actorSell,"trade","Bought "+String(sold.name)+" from the player for "+agreed+" stones",v["clock"],false);
      var ledgerSellNext=Object.assign({},ledgerSell);ledgerSellNext[actorKeySell]=actorSell;api.setVariable("npc-ledger",ledgerSellNext);
    }
    api.setVariable("shop-state", Object.assign({}, s, {
      haggling: { active: false }, "haggle-result": null,
    }));
    api.injectContext(
      "[UI] DEAL DONE. The player sold one " + sold.name + " to " + who +
      " for the haggled price of " + agreed + " stones (opening offer " +
      num_shop(h.listed, 0) + ")" +
      (had > 1 ? ", " + (had - 1) + " still carried" : "") +
      ". Payment is already made — narrate only the handover, state no totals, " +
      "and do not move any stones yourself.",
      { role: "system" }
    );
    // eslint-disable-next-line
  }, [sig]);

  return null;
}

// Visible ONLY while a merchant's counter-offer is standing. The shop panel is
// down during an argument, so without this the player has a number on the table
// and nothing to press. TAKE IT settles at their price; KEEP PUSHING and WALK
// AWAY are ordinary sentences — the merchant still gets to answer.
function HaggleOffer() {
  var api = useYumina();
  var v = api.variables || {};
  var shop = obj_shop(v["shop-state"]);
  var h = obj_shop(shop.haggling);
  if (h.active !== true) return null;

  var offered = num_shop(h.offer, -1);
  if (offered < 0) return null;

  var listed = num_shop(h.listed, 0);
  var buying = h.mode === "BUY";
  var purse = Math.max(0, num_shop(v["mana-stones"], 0));
  var afford = !buying || offered <= purse;
  // Movement is measured against the number they opened with, in the
  // direction that favours the player.
  var delta = buying ? listed - offered : offered - listed;
  var pct = listed > 0 ? Math.round((delta / listed) * 100) : 0;

  function take() {
    if (!afford) return;
    api.setVariable("shop-state", Object.assign({}, shop, {
      "haggle-result": { outcome: "accepted", price: offered },
    }));
    api.sendMessage("[I take " + (h.name || "it") + " at " + offered + " stones.]");
  }
  function push() {
    api.sendMessage("[I keep pushing — " + offered + " is not good enough.]");
  }
  function walk() {
    api.setVariable("shop-state", Object.assign({}, shop, {
      "haggle-result": { outcome: "refused" },
    }));
    api.sendMessage("[I leave it. No deal.]");
  }

  return (
    <div
      style={{
        position: "fixed", left: 0, right: 0, bottom: 0, zIndex: 60,
        display: "flex", justifyContent: "center",
        padding: "10px 12px calc(10px + env(safe-area-inset-bottom, 0px))",
        pointerEvents: "none",
      }}
    >
      <div
        style={{
          pointerEvents: "auto",
          width: "100%", maxWidth: 520,
          borderRadius: R.md,
          border: "1px solid " + C.brass,
          background: C.panelUp,
          boxShadow: "0 10px 30px rgba(0,0,0,0.55)",
          padding: 12,
        }}
      >
        <div style={{ fontSize: 10, letterSpacing: "0.18em", color: C.boneDim }}>
          {(shop.merchantName || "THE MERCHANT").toUpperCase()} — OFFER ON THE TABLE
        </div>
        <div
          style={{
            display: "flex", alignItems: "baseline", gap: 8,
            marginTop: 6, flexWrap: "wrap",
          }}
        >
          <span style={{ fontSize: 20, color: C.brassLit }}>
            {offered.toLocaleString()}
          </span>
          <span style={{ fontSize: 11, color: C.boneDim }}>
            stones for {h.name}
          </span>
          <span style={{ fontSize: 10, color: C.boneFaint, marginLeft: "auto" }}>
            {buying ? "asked " : "offered "}{listed.toLocaleString()}
            {pct > 0 ? " · " + pct + "% your way" : " · no movement"}
          </span>
        </div>
        {!afford ? (
          <div style={{ fontSize: 10, color: C.bloodLit, marginTop: 6 }}>
            You hold {purse.toLocaleString()}. You cannot cover this.
          </div>
        ) : null}
        <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
          <Btn onClick={take} disabled={!afford} active={afford}>
            TAKE IT
          </Btn>
          <Btn onClick={push}>KEEP PUSHING</Btn>
          <Btn onClick={walk}>WALK AWAY</Btn>
        </div>
      </div>
    </div>
  );
}

// Silent, mounted always. Settles a trade with ANY person {{user}} is talking
// to — not only merchants. Same discipline as HaggleWatch: the GM argues and
// proposes, the interface is the only thing that ever moves stones or goods.
function NpcTradeWatch() {
  var api = useYumina();
  var v = api.variables || {};
  var n = obj_npc(v["current-npc"]);
  var t = obj_npc(n.trade);
  var r = obj_npc(n["trade-result"]);
  var sig = String(t.active) + "|" + String(r.outcome || "") + "|" +
    String(r.price === undefined ? "" : r.price);

  React.useEffect(function () {
    var nn = obj_npc(v["current-npc"]);
    var h = obj_npc(nn.trade);
    var rr = obj_npc(nn["trade-result"]);
    if (h.active !== true) return;
    if (!rr.outcome) return;

    var stones = Math.max(0, Number(v["mana-stones"]) || 0);
    var bag = normalizeList(v["inventory"]);
    var who = nn.name || "them";

    // COUNTERED — not a settlement. The person named a different number and
    // it sits on the table; nothing has moved.
    if (rr.outcome === "countered") {
      var offered = Number(rr.price);
      if (!(offered >= 0)) {
        api.setVariable("current-npc", Object.assign({}, nn, { "trade-result": null }));
        return;
      }
      var round = Math.max(0, Math.floor(Number(h.round) || 0)) + 1;
      api.setVariable("current-npc", Object.assign({}, nn, {
        trade: Object.assign({}, h, { offer: offered, round: round }),
        "trade-result": null,
      }));
      api.injectContext(
        "[UI] " + who + " countered at " + offered + " stones for " + h.name +
        " (opened at " + (Number(h.listed) || 0) + "). No deal yet — hold the " +
        "scene at this moment and let the player answer.",
        { role: "system" }
      );
      return;
    }

    var agreed = Number(rr.price);
    if (!(agreed >= 0)) agreed = Number(h.offer);
    if (rr.outcome !== "accepted" || !(agreed >= 0)) {
      api.setVariable("current-npc", Object.assign({}, nn, {
        trade: { active: false }, "trade-result": null,
      }));
      api.injectContext(
        "[UI] The trade over " + h.name + " with " + who + " ended with no deal. " +
        "Nothing changed hands.",
        { role: "system" }
      );
      return;
    }

    if (h.mode === "BUY") {
      if (agreed > stones) {
        api.setVariable("current-npc", Object.assign({}, nn, {
          trade: { active: false }, "trade-result": null,
        }));
        api.injectContext(
          "[UI] " + who + " agreed to " + agreed + " stones for " + h.name +
          " and the player cannot cover it — they hold " + stones + ". The deal " +
          "collapses over money that is not there. Nothing changed hands.",
          { role: "system" }
        );
        return;
      }
      var bought = normalizeItem({
        id: makeId("buy"),
        name: h.name || "an item",
        type: h.itemType || "misc",
        slot: "backpack",
        description: h.description || "",
        value: agreed,
        qty: 1,
        equipped: false,
      }, 0);
      api.setVariable("mana-stones", Math.max(0, stones - agreed));
      api.setVariable("inventory", addItem(bag, bought));
      var ledgerBuy=npcObj(v["npc-ledger"]),actorKeyBuy=String(nn.actorId||"");
      if(actorKeyBuy&&ledgerBuy[actorKeyBuy]){
        var actorBuy=normalizeNpcActor(ledgerBuy[actorKeyBuy],actorKeyBuy,v);
        actorBuy.personalStones=Math.max(0,Number(actorBuy.personalStones)||0)+agreed;
        var sourceId=String(h.npcItemId||h.ref||"");
        if(sourceId&&indexOfId(actorBuy.inventory,sourceId)>=0)actorBuy.inventory=removeItem(actorBuy.inventory,sourceId,1);
        actorBuy=npcRemember(actorBuy,"trade","Sold "+String(h.name||"an item")+" to the player for "+agreed+" stones",v["clock"],false);
        var ledgerBuyNext=Object.assign({},ledgerBuy);ledgerBuyNext[actorKeyBuy]=actorBuy;api.setVariable("npc-ledger",ledgerBuyNext);
      }
      api.setVariable("current-npc", Object.assign({}, nn, {
        trade: { active: false }, "trade-result": null,
      }));
      api.injectContext(
        "[UI] DEAL DONE. The player bought " + (h.name || "the item") + " from " +
        who + " for " + agreed + " stones. It is in their pack and payment is " +
        "already made — narrate only the handover, state no totals, and do not " +
        "move any stones yourself.",
        { role: "system" }
      );
      return;
    }

    // SELL — identity-addressed, re-checked at the moment the deal lands.
    var idx = indexOfId(bag, String(h.ref));
    if (idx < 0) {
      api.setVariable("current-npc", Object.assign({}, nn, {
        trade: { active: false }, "trade-result": null,
      }));
      return;
    }
    var sold = bag[idx];
    if (!isSellable(sold)) {
      api.setVariable("current-npc", Object.assign({}, nn, {
        trade: { active: false }, "trade-result": null,
      }));
      return;
    }
    var had = sold.qty;
    api.setVariable("inventory", removeItem(bag, String(h.ref), 1));
    api.setVariable("mana-stones", Math.max(0, stones + agreed));
    api.setVariable("current-npc", Object.assign({}, nn, {
      trade: { active: false }, "trade-result": null,
    }));
    api.injectContext(
      "[UI] DEAL DONE. The player sold one " + sold.name + " to " + who +
      " for " + agreed + " stones" +
      (had > 1 ? ", " + (had - 1) + " still carried" : "") +
      ". Payment is already made — narrate only the handover, state no totals, " +
      "and do not move any stones yourself.",
      { role: "system" }
    );
    // eslint-disable-next-line
  }, [sig]);

  return null;
}

