// Silent, mounted always — like Oracle. Fires once per shop scene, the
// instant the GM has named a shopType but the shelf is still unstocked.
// ==== portal search =========================================================
// The claim channel for finding a way down, mirroring kill-log/Oracle exactly.
// portal-progress is engine-owned; the GM cannot set it directly, only push a
// claim here when a genuine search scene was narrated, and this resolves the
// real, floor-scaled, dice-backed gain. Deeper floors take real ground to
// cover — this is precisely what stops "I search for the portal" from being
// a free action, on any floor, ever.

var PORTAL_GAIN = {
  1: [35, 55], 2: [25, 40], 3: [15, 28], 4: [8, 16], 5: [6, 12],
};

// ==== resonant sets =========================================================
// Resonant Noble Phantasms — Numbered Item sets with a real bonus once both
// pieces are actually held. This is a confirmed mechanic, not flavor: the
// bonus is genuinely inert until both numbers are present, and genuinely
// active the instant they are — narrate it as real, not as a maybe.

var SET_BONUSES = [
  {
    id: "necromancer-set",
    name: "Necromancer Set",
    pieces: [7611, 7612],
    effect: "When either piece's effect activates, an additional 50% of the blood spent is recovered.",
  },
];

function SetBonusWatch() {
  var api = useYumina();
  var v = api.variables || {};
  var held = arr_panel(v["numbered-items"]);
  var heldNos = held.map(function (x) { return x && x.no; }).filter(function (n) { return typeof n === "number"; });
  var sig = heldNos.slice().sort(function (a, b) { return a - b; }).join(",");

  React.useEffect(function () {
    var complete = SET_BONUSES.filter(function (set) {
      return set.pieces.every(function (p) { return heldNos.indexOf(p) >= 0; });
    });
    if (!complete.length) return;
    var lines = complete.map(function (s) {
      return s.name + " is complete (" + s.pieces.join(" + ") + "): " + s.effect;
    });
    api.injectContext(
      "[UI] Resonant Noble Phantasm active — " + lines.join(" | ") +
      " This is a real, confirmed bonus, not flavor: treat it as genuinely active " +
      "while both pieces are held, and say so plainly the next time its effect would matter.",
      { role: "system" }
    );
    // eslint-disable-next-line
  }, [sig]);

  return null;
}
// ==== rift cycle =============================================================
// Rift reopening has a real, confirmed rule — minimum 2 cycles closed, usually
// 4-5, guaranteed reopened by 8 — and until now nothing actually rolled it.
// This resolves it with real seeded dice the moment a new monthly cycle
// begins, so "is this rift open" is a fact the GM reads, never decides.

var RIFT_TABLE = [
  { id: "bloody-citadel", name: "Bloody Citadel", floor: 1 },
  { id: "glacial-cave", name: "Glacial Cave", floor: 1 },
  { id: "green-coal-mine", name: "Green Coal Mine", floor: 1 },
  { id: "steel-tomb", name: "Steel Tomb", floor: 1 },
  { id: "gunpo-desert", name: "Gunpo / Rocky Desert", floor: 2 },
  { id: "white-temple", name: "White Temple", floor: 3 },
  { id: "doppelganger-forest", name: "Doppelganger Forest", floor: 4 },
  { id: "fortress-of-souls", name: "Fortress of the Soul", floor: 5 },
  { id: "island-of-paradise", name: "Island of Paradise", floor: 5 },
  { id: "balantis", name: "Balantis", floor: 7 },
  { id: "calhaem", name: "Calhaem, City of Light", floor: 8 },
  { id: "red-dragons-heart", name: "Red Dragon's Heart", floor: 8 },
  { id: "third-archive", name: "Third Archive", floor: 0 },
];

// Reopen chance by cycles-closed. Under 2, impossible. By 8, certain.
var RIFT_REOPEN_ODDS = { 2: 0.05, 3: 0.15, 4: 0.35, 5: 0.55, 6: 0.70, 7: 0.85 };

function riftReopenChance(cyclesClosed) {
  if (cyclesClosed < 2) return 0;
  if (cyclesClosed >= 8) return 1;
  return RIFT_REOPEN_ODDS[cyclesClosed] || 0.5;
}

function RiftCycle() {
  var api = useYumina();
  var v = api.variables || {};
  var month = num_oracle(v["cycle-month"], 1);

  React.useEffect(function () {
    var state = obj_oracle(v["rift-state"]);
    var rng = oracleRng((month * 7919) ^ 104729);
    var next = {};
    var opened = [];

    RIFT_TABLE.forEach(function (r) {
      var prior = state[r.id] || { open: false, lastOpenCycle: 0, cyclesClosed: 99 };
      if (prior.open) {
        // Was open last cycle — a floor's own rift naturally closes out
        // between openings; start counting closed-cycles fresh.
        next[r.id] = { open: false, lastOpenCycle: month, cyclesClosed: 0 };
        return;
      }
      var cyclesClosed = num_oracle(prior.cyclesClosed, 0) + 1;
      var chance = riftReopenChance(cyclesClosed);
      var roll = rng();
      if (roll < chance) {
        next[r.id] = { open: true, lastOpenCycle: month, cyclesClosed: 0, accessibleFromDay: 4 };
        opened.push(r.name + " (Floor " + (r.floor || "B1") + ")");
      } else {
        next[r.id] = { open: false, lastOpenCycle: prior.lastOpenCycle, cyclesClosed: cyclesClosed };
      }
    });

    api.setVariable("rift-state", next);
    if (opened.length) {
      api.injectContext(
        "[UI] Rifts reopened this cycle (real dice, not narrative choice): " + opened.join(", ") +
        ". Each becomes physically findable starting cycle-day 4, matching the 'needs at least " +
        "three real days to generate' rule — don't let a party stumble onto one before then. " +
        "Every other listed rift stays closed this cycle regardless of how convenient it would " +
        "be to narration.",
        { role: "system" }
      );
    }
    // eslint-disable-next-line
  }, [month]);

  return null;
}
function PortalSearch() {
  var api = useYumina();
  var v = api.variables || {};
  var sig = JSON.stringify(arr_oracle(v["search-log"]));

  React.useEffect(function () {
    var claims = arr_oracle(v["search-log"]);
    var ci = -1;
    for (var i = 0; i < claims.length; i++) {
      if (claims[i] && !claims[i].resolved) { ci = i; break; }
    }
    if (ci < 0) return;
    resolve(ci, claims);
    // eslint-disable-next-line
  }, [sig]);

  function resolve(ci, claims) {
    var floor = num_oracle(v["current-floor"], 0);
    var band = PORTAL_GAIN[floor];
    var already = num_oracle(v["portal-progress"], 0);

    // Real ground gets covered faster with the right eyes on the problem.
    // A wayfinding-flagged party member is a deliberate, explicit thing the
    // GM sets when recruiting someone whose actual competence is trail work
    // — never inferred from a class name, never assumed.
    var partyList = arr_oracle(v["party"]);
    var hasScout = partyList.some(function (m) {
      return m && (m.wayfinding === true || arr_oracle(m.skills).some(function (s) { return s && s.name === "Navigation"; }));
    });
    var ownSkills = arr_oracle(v["skills"]);
    if (ownSkills.some(function (s) { return s && s.name === "Navigation"; })) hasScout = true;
    var subs = obj_oracle(v["substats"]);
    var vision = num_oracle(subs.vision, 0);
    var race = String(v["race"] || "");
    var keenSense = race === "Beastman" || race === "Elf";

    var mult = 1;
    if (hasScout) mult += 0.4;
    if (keenSense) mult += 0.2;
    if (vision >= 15) mult += 0.15;

    var nextClaims = claims.slice();
    nextClaims[ci] = Object.assign({}, claims[ci], { resolved: true });
    api.setVariable("search-log", nextClaims);

    if (!band) {
      // Floor 6+ isn't gated by this system at all — structural prerequisites
      // (a boat, a crew) govern it instead, and no roll substitutes for those.
      api.injectContext(
        "[UI] Search claim ignored: floor " + floor + " is not governed by portal-progress. " +
        "Past Floor 5, finding a way down is a structural problem — a boat, a crew, real " +
        "preparation — never a dice roll. Do not advance the floor without that being genuinely " +
        "true in the fiction first.",
        { role: "system" }
      );
      return;
    }

    var rng = oracleRng((Date.now() ^ (ci * 7919) ^ (floor * 131)) & 0x7fffffff);
    var gain = Math.round((band[0] + rng() * (band[1] - band[0])) * mult);
    var next = Math.min(100, already + gain);

    api.setVariable("portal-progress", next);
    api.setVariable("thirst", Math.max(0, num_oracle(v["thirst"], 100) - (6 + Math.round(rng() * 6))));
    api.setVariable("stamina", Math.max(0, num_oracle(v["stamina"], 100) - (8 + Math.round(rng() * 8))));

    var daysLeft = num_oracle(v["floor-days-left"], 0);
    if (daysLeft > 0) api.setVariable("floor-days-left", Math.max(0, daysLeft - 1));

    var note;
    if (next >= 100) {
      note = "[UI] Search resolved: ground covered " + already + " to " + next +
        " out of 100. The portal is genuinely findable now — narrate discovering it, but the " +
        "player still has to choose to take it. This cost real thirst, stamina, and a day off " +
        "the floor's own clock.";
    } else {
      note = "[UI] Search resolved: ground covered " + already + " to " + next +
        " out of 100 — not there yet. Narrate what was ruled out, not a number. This cost real " +
        "thirst, stamina, and a day off the floor's own clock. Reaching 100 on this floor is " +
        "expected to take multiple distinct search actions, not one.";
    }
    api.injectContext(note, { role: "system" });
  }

  return null;
}
function ShopStock() {
  var api = useYumina();
  var v = api.variables || {};
  var shop = obj_shop(v["shop-state"]);
  var sig = String(shop.active) + "|" + String(shop.shopType || "") + "|" +
    String(shop.merchantName || "") + "|" + String(shop.stocked === true);

  React.useEffect(function () {
    var s = obj_shop(v["shop-state"]);
    if (s.active !== true) return;
    if (s.stocked === true) return;
