    var requestedType = String(s.shopType);
    var district2 = district;
    var type2 = requestedType;
    if (!district2) {
      // No modeled district here — fall back to whatever the GM asked for,
      // capped very low, rather than producing nothing at all.
      district2 = { types: [requestedType], tierCap: 1, condPool: ["used", "worn"] };
    } else if (district2.types.indexOf(requestedType) < 0) {
      // The GM asked for a shop type this district doesn't plausibly have —
      // fall back to whatever that district actually supports.
      type2 = district2.types[0];
    }

    var seed = (s.merchantName || "merchant") + "|" + locStr + "|" +
      num_shop(v["cycle-month"], 1);
