// Floors 6+ have no abstracted table. Boats, islands and clan-scale logistics —
// the resolver refuses rather than inventing a grind loop for them.
function poolFor(floor) { return FLOOR_POOL[floor] || null; }

function pickSpecies(pool, rand) {
  var total = 0, i;
  for (i = 0; i < pool.length; i++) total += pool[i].w;
  var r = rand() * total;
  for (i = 0; i < pool.length; i++) {
    r -= pool[i].w;
    if (r <= 0) return pool[i];
  }
  return pool[pool.length - 1];
}

// Intent shapes the day — what makes "grind for stones" and "hunt an essence"
// genuinely different orders rather than reskins of each other.
var INTENTS = {
  stones:  { label: "mana stones",     fights: 1.00, portal: 0.00, party: 0.05, rift: 0.04, risk: 1.00 },
  essence: { label: "an essence",      fights: 1.35, portal: 0.00, party: 0.05, rift: 0.10, risk: 1.25 },
  portal:  { label: "the way down",    fights: 0.55, portal: 1.00, party: 0.08, rift: 0.06, risk: 0.85 },
  plunder: { label: "other explorers", fights: 0.35, portal: 0.00, party: 0.40, rift: 0.03, risk: 1.10 },
  survive: { label: "staying alive",   fights: 0.30, portal: 0.10, party: 0.06, rift: 0.02, risk: 0.55 },
};

// Floor-scaled explorer toughness. Texture only, never a raw rank number —
// the player has no in-world way to know another party's registry rank.
// Shallow floors skew green (Rank 9 barely past registration); deeper floors
// skew hardened; Ranks 1-2 stay vanishingly rare everywhere, matching the
// public registry snapshot (almost nobody sits at the top).
var PARTY_BANDS = [
  { max: 1, w: 70, text: "green, barely past registration, moving like people still new to this" },
  { max: 1, w: 25, text: "competent enough, unremarkable gear, clearly not on their first descent" },
  { max: 1, w: 5,  text: "unusually sharp for how shallow this is — worth being cautious of" },
  { max: 3, w: 45, text: "seasoned, well-kept gear, moves like a party that has lost people before and learned from it" },
  { max: 3, w: 40, text: "green, barely past registration, out of their depth down here" },
  { max: 3, w: 13, text: "hardened, deliberate, the kind of party that picks its fights" },
  { max: 3, w: 2,  text: "frighteningly capable for this floor — the sort that shouldn't need to be here at all" },
  { max: 5, w: 55, text: "hardened, established, clearly clan-backed or long past needing to prove anything" },
  { max: 5, w: 30, text: "competent, cautious, watching {{user}} the same way {{user}} is watching them" },
  { max: 5, w: 12, text: "green and badly out of their depth, a long way from where they should be" },
  { max: 5, w: 3,  text: "apex-tier — the kind of presence that makes the floor itself feel smaller" },
];
function partyToughness(floor, rand) {
  var band = floor <= 1 ? 1 : (floor <= 3 ? 3 : 5);
  var opts2 = PARTY_BANDS.filter(function (b) { return b.max === band; });
  var total = 0, i;
  for (i = 0; i < opts2.length; i++) total += opts2[i].w;
  var r = rand() * total;
  for (i = 0; i < opts2.length; i++) {
    r -= opts2[i].w;
    if (r <= 0) return opts2[i].text;
  }
  return opts2[opts2.length - 1].text;
}

// Whether the player currently READS as worth robbing. Never luck-based —
// plunderers count what they can see: worn armour, a fine weapon, or a
// visibly heavy pouch. Someone who looks poor mostly doesn't draw this,
// unless the other party is just as desperate (handled by the floor skew).
function looksWorthRobbing(opts) {
  var equipVal = 0;
  for (var i = 0; i < opts.inventory.length; i++) {
    var it = opts.inventory[i];
    if (it && it.equipped === true) equipVal += (typeof it.value === "number" ? it.value : 0);
  }
  var rawQty = 0;
  var rawKeys = Object.keys(opts.rawBag || {});
  for (var k = 0; k < rawKeys.length; k++) rawQty += num_oracle2(opts.rawBag[rawKeys[k]] && opts.rawBag[rawKeys[k]].qty, 0);
  return equipVal >= 15000 || opts.walletStones >= 5000 || rawQty >= 15;
}
function num_oracle2(v, d) { return typeof v === "number" ? v : d; }

// Simulated a day at a time so it can stop the instant something demands a
// decision. Everything earned before the stop is kept — an interrupt costs the
// run, never the work.
function resolveRun(opts) {
  var rand = g_rng(opts.seed);
  var pool = opts.pool;
  var cfg = INTENTS[opts.intent] || INTENTS.stones;

  var out = {
    kills: {}, killCount: 0, stones: 0, exp: 0, rawStones: {},
    firstKills: [], newSpecies: [], essences: [],
    riftsSeen: 0, partiesMet: 0, daysSpent: 0, portalGain: 0,
    status: "complete", interrupt: null,
  };

  var killedSet = {};
  for (var k = 0; k < opts.alreadyKilled.length; k++) killedSet[opts.alreadyKilled[k]] = true;

  var condition = opts.condition;
  var thirst = opts.thirst;
  var portal = opts.portal;
  var staminaCur = opts.stamina;
  var spiritCur = opts.spiritCurrent;
  var spiritMax = Math.max(1, opts.spiritMax || 10);

  for (var day = 0; day < opts.days; day++) {
    if (opts.daysLeft - out.daysSpent <= 0) {
      out.status = "aborted";
      out.interrupt = {
        kind: "deadline", what: "the floor is closing",
        detail: "There are no days left on this floor. It is emptying whether or not anyone is finished.",
      };
      break;
    }

    out.daysSpent++;

    var density = 3 + Math.floor(opts.floor * 1.2);
    var encounters = Math.max(0, Math.round((density * cfg.fights) * (0.6 + rand() * 0.8)));

    for (var e = 0; e < encounters; e++) {
      var sp = pickSpecies(pool, rand);

      if (sp.offBand) {
        out.status = "interrupted";
        out.interrupt = {
          kind: "monster", what: sp.name,
          detail: "A " + sp.name + " — rank " + sp.rank + ", far above what this floor is " +
            "supposed to hold. It has not noticed, or it has and does not care.",
        };
        break;
      }

      var first = !killedSet[sp.name];
      var rank = sp.rank;

      out.kills[sp.name] = (out.kills[sp.name] || 0) + 1;
      out.killCount++;
      // Appraisal estimate only. The pouch fills with rock; the Guild decides
      // what the rock is worth when it reaches a counter on the surface.
      out.stones += G_STONES[rank] || G_STONES[9];
      out.rawStones[sp.name] = {
        rank: rank,
        qty: ((out.rawStones[sp.name] && out.rawStones[sp.name].qty) || 0) + 1,
      };

      if (first) {
        killedSet[sp.name] = true;
        out.newSpecies.push(sp.name);
        out.firstKills.push(sp.name);
        out.exp += G_EXP[rank] || 0;
      }

      // The real rate. 0.01% a body, plus Beginner's Luck's flat 5 points on a
      // first kill only. No pity, no scaling for effort, no scene bonus.
      var roll = Math.floor(rand() * 10000) + 1;
      var need = (opts.talisman && first) ? 501 : 1;
      if (roll <= need) {
        out.essences.push({ source: sp.name, rank: rank });
        out.status = "interrupted";
        out.interrupt = {
          kind: "essence", what: sp.name,
          detail: "The corpse does not go the way the others went. A fist-sized orb of light is " +
            "sitting where it fell, and it will be there for thirty minutes and not one minute longer.",
        };
        break;
      }

      condition -= rand() * 4.5 * cfg.risk * (1 + (rank <= 7 ? 0.9 : 0));
      spiritCur = Math.max(0, spiritCur - rand() * 0.6 * cfg.risk);
    }

    if (out.status === "interrupted") break;

    if (cfg.portal > 0) {
      var pBand = PORTAL_GAIN[opts.floor] || [5, 10];
      var pMult = opts.searchMult || 1;
      portal = Math.min(100, portal + (pBand[0] + rand() * (pBand[1] - pBand[0])) * pMult * cfg.portal);
      if (portal >= 100) {
        out.status = "interrupted";
        out.interrupt = {
          kind: "portal", what: "the way down",
          detail: "The portal to the next floor is in front of you. Nothing is stopping you " +
            "walking into it, and nothing is stopping you walking away.",
        };
        break;
      }
    }

    if (rand() < cfg.party) {
      out.partiesMet++;
      out.status = "interrupted";
      var pTough = partyToughness(opts.floor, rand);
      var wantsPlayer = looksWorthRobbing(opts) && rand() < (0.15 + opts.floor * 0.03);
      var pDetail;
      if (opts.intent === "plunder") {
        pDetail = "A party, and they have not seen you yet — " + pTough + ". Count them before you decide anything.";
      } else if (wantsPlayer) {
        pDetail = "Another party on the same trail, " + pTough + ". They have seen what {{user}} is carrying, " +
          "and they have not stopped looking at it.";
      } else {
        pDetail = "Another party on the same trail, " + pTough + ". They have seen {{user}}. Nobody has reached " +
          "for anything yet.";
      }
      out.interrupt = { kind: "party", what: "other explorers", detail: pDetail, sizingUpPlayer: wantsPlayer };
      break;
    }

    if (rand() < cfg.rift) {
      out.riftsSeen++;
      out.status = "interrupted";
      out.interrupt = {
        kind: "rift", what: "a rift",
        detail: "A rift, open, and no one else standing at it. First party to reach one gets " +
          "first crack at the guardian.",
      };
      break;
    }

    thirst -= 9 + rand() * 6;
    staminaCur -= 6 + rand() * 6 * cfg.risk;

    if (thirst <= 20) {
      out.status = "interrupted";
      out.interrupt = {
        kind: "thirst", what: "water",
        detail: "You are far enough into real thirst that it has started making decisions for you.",
      };
      break;
    }
    if (condition <= 35) {
      out.status = "interrupted";
      out.interrupt = {
        kind: "wounded", what: "your condition",
        detail: "Something is wrong enough that continuing is a choice rather than a default.",
      };
      break;
    }
    if (staminaCur <= 15) {
      out.status = "interrupted";
      out.interrupt = {
        kind: "exhausted", what: "your stamina",
        detail: "There is nothing left in the arms or the legs. Whatever happens next, it is not going to be fast.",
      };
      break;
    }
    if (spiritCur <= Math.max(2, spiritMax * 0.15)) {
      out.status = "interrupted";
      out.interrupt = {
        kind: "spent", what: "your spirit",
        detail: "The pool is nearly dry. Whatever comes next is not answered by pulling on the mana anymore.",
      };
      break;
    }
  }

  out.endCondition = Math.max(0, Math.round(condition));
  out.endThirst = Math.max(0, Math.round(thirst));
  out.endPortal = Math.round(portal);
  out.endStamina = Math.max(0, Math.round(staminaCur));
  out.endSpirit = Math.max(0, Math.round(spiritCur));
  return out;
}

// What the GM is handed. Facts only, in the order they happened. No adjectives
// that decide how it felt — that is the narration's job.
function buildNote(run, order) {
  var lines = [];
  lines.push("[UI] Grind resolved — floor " + order.floor + ", hunting " +
    (INTENTS[order.intent] || INTENTS.stones).label + ", " + run.daysSpent + " of " +
    order.days + " in-floor day" + (run.daysSpent === 1 ? "" : "s") + " spent.");

  var names = Object.keys(run.kills);
  if (names.length) {
    var parts = [];
    for (var i = 0; i < names.length; i++) parts.push(names[i] + " x" + run.kills[names[i]]);
    lines.push("Killed: " + parts.join(", ") + " (" + run.killCount + " total).");
  } else {
    lines.push("Killed: nothing. The stretch produced no bodies at all.");
  }

  lines.push("Mana stones cut and pouched — appraisal estimate ~" + run.stones +
    " stones (the currency). NOT money yet: they are mana stones until an " +
    "Explorers' Guild branch on the surface grades and exchanges it, minus their fee. " +
    "Do not narrate the player as having been paid, and do not let anything underground buy it.");
  if (run.firstKills.length) {
    lines.push("First kills: " + run.firstKills.join(", ") + " (+" + run.exp + " achievement).");
  }
  if (!run.essences.length) {
    lines.push("No essence. " + run.killCount + " bodies and not one of them gave anything up.");
  }

  if (run.status === "interrupted" && run.interrupt) {
    lines.push("RUN INTERRUPTED — " + run.interrupt.kind.toUpperCase() + ": " + run.interrupt.detail);
    if (run.interrupt.kind === "essence" && run.essences.length) {
      var es = run.essences[run.essences.length - 1];
      lines.push("The orb is from a " + es.source + " (rank " + es.rank + "). It is on the ground, " +
        "not absorbed. It is theirs only if they take it, and they have thirty minutes.");
    }
    lines.push("Cut to this exact moment in present tense and END THERE, on the decision. Do not " +
      "resolve it. Do not list options. " + (order.days - run.daysSpent) +
      " ordered day(s) remain banked if they choose to resume.");
  } else if (run.status === "aborted") {
    lines.push("RUN ABORTED — " + (run.interrupt ? run.interrupt.detail : "the floor closed."));
  } else {
    lines.push("Run completed as ordered. Narrate the whole stretch as a montage and close on the " +
      "totals. Do not add anything that is not in this note.");
  }

  lines.push("State is already written. Do not re-apply any of it. The haul is mana stones — " +
    "physical loot in a pouch, not money, until an Explorers' Guild counter on the " +
    "surface grades and exchanges it for stones.");
  return lines.join(" ");
}

// Ordering a run is a deliberate act with a cost attached, so it reads like a
// commitment screen and not a vending machine.
function GrindPanel(props) {
  var api = useYumina();
  var v = api.variables || {};
  var floor = g_num(v["current-floor"], 0);
  var daysLeft = g_num(v["floor-days-left"], 0);

  var iS = React.useState("stones");
  var intent = iS[0], setIntent = iS[1];
  var dS = React.useState(3);
  var days = dS[0], setDays = dS[1];

  var pool = poolFor(floor);
  var maxDays = Math.max(1, daysLeft);
  var canRun = floor >= 1 && !!pool && daysLeft > 0;

  function launch() {
    if (!canRun) return;

    var d = Math.max(1, Math.min(days, maxDays));
    var order = { floor: floor, intent: intent, days: d };

    var run = resolveRun({
      seed: (Date.now() ^ (floor * 7919) ^ (d * 131) ^ (intent.length * 31)) & 0x7fffffff,
      floor: floor, intent: intent, days: d, daysLeft: daysLeft, pool: pool,
      alreadyKilled: g_arr(v["species-killed"]),
      talisman: g_arr(v["numbered-items"]).some(function (n) { return n && n.no === 9999; }),
      searchMult: (function () {
        var partyList = g_arr(v["party"]);
        var hasScout = partyList.some(function (m) {
          return m && (m.wayfinding === true || g_arr(m.skills).some(function (s) { return s && s.name === "Navigation"; }));
        });
        var ownSkills = g_arr(v["skills"]);
        if (ownSkills.some(function (s) { return s && s.name === "Navigation"; })) hasScout = true;
        var subs = g_obj(v["substats"]);
        var vision = g_num(subs.vision, 0);
        var race = String(v["race"] || "");
        var keenSense = race === "Beastman" || race === "Elf";
        var mult = 1;
        if (hasScout) mult += 0.4;
        if (keenSense) mult += 0.2;
        if (vision >= 15) mult += 0.15;
        return mult;
      })(),
      condition: g_num(v["condition"], 100),
      thirst: g_num(v["thirst"], 100),
      portal: g_num(v["portal-progress"], 0),
      stamina: g_num(v["stamina"], 100),
      spiritCurrent: g_num(v["spirit-current"], 10),
      spiritMax: g_num(v["spirit"], 10),
      inventory: g_arr(v["inventory"]),
      rawBag: g_obj(v["raw-stones"]),
      walletStones: g_num(v["mana-stones"], 0),
    });

    // Loot is physical. It goes in the pouch, not the purse — the Guild
    // exchange on the surface is the only thing that makes it money.
    var bagRaw = g_obj(v["raw-stones"]);
    var mergedRaw = Object.assign({}, bagRaw);
    var rawKeys = Object.keys(run.rawStones);
    for (var rk = 0; rk < rawKeys.length; rk++) {
      var kName = rawKeys[rk];
      var had = g_obj(mergedRaw[kName]);
      mergedRaw[kName] = {
        rank: run.rawStones[kName].rank,
        qty: g_num(had.qty, 0) + run.rawStones[kName].qty,
      };
    }
    if (rawKeys.length) api.setVariable("raw-stones", mergedRaw);
    if (run.exp) api.setVariable("achievements", g_num(v["achievements"], 0) + run.exp);
    if (run.newSpecies.length) {
      api.setVariable("species-killed", g_arr(v["species-killed"]).concat(run.newSpecies));
    }
    api.setVariable("condition", run.endCondition);
    api.setVariable("thirst", run.endThirst);
    api.setVariable("portal-progress", run.endPortal);
    api.setVariable("stamina", run.endStamina);
    api.setVariable("spirit-current", Math.min(g_num(v["spirit"], 10), run.endSpirit));
    api.setVariable("floor-days-left", Math.max(0, daysLeft - run.daysSpent));
    api.setVariable("labyrinth-days", g_num(v["labyrinth-days"], 0) + run.daysSpent);

    api.setVariable("grind-session", {
      active: run.status === "interrupted",
      floor: floor, intent: intent,
      daysOrdered: d, daysSpent: run.daysSpent,
      daysBanked: Math.max(0, d - run.daysSpent),
      kills: run.kills, stones: run.stones,
      essencesFound: run.essences, firstKills: run.firstKills,
      riftsSeen: run.riftsSeen, partiesMet: run.partiesMet,
      status: run.status, interrupt: run.interrupt,
    });

    api.injectContext(buildNote(run, order), { role: "system" });
    api.sendMessage("[I commit " + d + " day" + (d === 1 ? "" : "s") + " on floor " + floor +
      ", hunting " + (INTENTS[intent] || INTENTS.stones).label + ".]");

    if (props.onClose) props.onClose();
  }

  return (
    <Screen title="COMMIT TIME" onClose={props.onClose}>
      {floor < 1 ? (
        <Empty>You are on the surface. There is nothing here to commit days to.</Empty>
      ) : !pool ? (
        <Empty>
          Floor {floor} does not run on a grind loop. Boats, islands, clan-scale
          logistics — it has to be played through.
        </Empty>
      ) : (
        <div>
          <div style={{ fontSize: 11, color: C.boneDim, lineHeight: 1.8, marginBottom: 14 }}>
            Floor {floor}. {daysLeft} in-floor day{daysLeft === 1 ? "" : "s"} left before it
            empties. Anything that needs a decision stops the run and hands it back to you.
          </div>

          <div style={{ fontSize: 10, letterSpacing: "0.14em", color: C.boneDim, marginBottom: 8 }}>
            HUNTING FOR
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 18 }}>
            {Object.keys(INTENTS).map(function (key) {
              var on = intent === key;
              return (
                <button
                  key={key}
                  className="ds-btn"
                  onClick={function () { setIntent(key); }}
                  style={{
                    padding: "8px 12px", borderRadius: 9, cursor: "pointer",
                    fontSize: 11, fontFamily: "inherit",
                    background: on ? "rgba(201,162,39,0.15)" : C.panel,
                    border: "1px solid " + (on ? C.brass : C.rule),
                    color: on ? C.brass : C.boneDim,
                  }}
                >{INTENTS[key].label}</button>
              );
            })}
          </div>

          <div style={{ fontSize: 10, letterSpacing: "0.14em", color: C.boneDim, marginBottom: 8 }}>
            DAYS — {Math.min(days, maxDays)} OF {maxDays} AVAILABLE
          </div>
          <input
            type="range" min={1} max={maxDays} value={Math.min(days, maxDays)}
            onChange={function (ev) { setDays(parseInt(ev.target.value, 10) || 1); }}
            style={{ width: "100%", accentColor: C.brass, marginBottom: 18 }}
          />

          <button
            className="ds-btn"
            onClick={launch}
            disabled={!canRun}
            style={{
              width: "100%", padding: "13px 0", borderRadius: 10,
              cursor: canRun ? "pointer" : "not-allowed",
              fontSize: 12, letterSpacing: "0.14em", fontFamily: "inherit",
              background: canRun ? "linear-gradient(180deg,#3a2f12 0%,#241c0a 100%)" : C.panel,
              border: "1px solid " + (canRun ? C.brass : C.rule),
              color: canRun ? C.brass : C.boneDim,
            }}
          >
            {daysLeft <= 0 ? "THE FLOOR IS CLOSING" : "GO DOWN AND WORK"}
          </button>

          <div style={{ fontSize: 10, color: C.boneDim, lineHeight: 1.8, marginTop: 14 }}>
            Essence odds are the real ones — 0.01% a body. Most runs give nothing.
            That is what makes the ones that do worth what they are worth.
          </div>
        </div>
      )}
    </Screen>
  );
}

// ==== home.tsx ==================================================
// Property. Canon is thin here — motels at ~9,000 a night, Kiarbis as an old
// noble resort, Bifron as the place people live because there is nowhere else,
// shops tied to clans. So the market below is generated to obey the grammar
// the world already has: district IS status, and every figure is anchored off
// the 20-stone loaf. Once a number is used it is simulation canon.
//
// This panel owns the arithmetic — rent, purchase, sublet income, business
// takings. The GM owns the door, the landlord, and the neighbours who notice
// a body coming home at odd hours.

function h_num(v, d) { return typeof v === "number" && isFinite(v) ? v : d; }
function h_arr(v) { return Array.isArray(v) ? v : []; }
function h_obj(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }

var TABS_home = ["PLACES", "BOARD", "TRADE"];

// Status by district, and what it costs to stand there.
var DISTRICT_MULT = {
  "karnon": 2.2,
  "kommelby": 1.8,
  "kiarbis": 1.4,
  "gnome tree": 1.0,
  "ravigion": 0.8,
  "bifron": 0.4,
};

function districtMult(d) {
  var key = String(d || "").toLowerCase();
  var keys = Object.keys(DISTRICT_MULT);
  for (var i = 0; i < keys.length; i++) {
    if (key.indexOf(keys[i]) !== -1) return DISTRICT_MULT[keys[i]];
  }
  return 0.8;
}

// Realistic trades for Rafdonia specifically — the shop types the city
// actually has, not a generic fantasy list.
var TRADES = [
  { id: "variety", label: "VARIETY STORE", takings: 26000, upkeep: 9000, fit: 120000,
    note: "Loot resale, potions, everyday sundries. Steady, unremarkable, always some trade." },
  { id: "boarding", label: "BOARDING HOUSE", takings: 34000, upkeep: 12000, fit: 180000,
    note: "Beds by the night to explorers who have no address. Full on the 1st, empty by the 20th." },
  { id: "pub", label: "PUB", takings: 42000, upkeep: 18000, fit: 260000,
    note: "Drink, lodging, and loot-splitting tables. The best room in the city for hearing things." },
  { id: "workshop", label: "WORKSHOP", takings: 38000, upkeep: 15000, fit: 300000,
    note: "Alchemy or magic-crafting — reagents and sundries. Needs a licence and a real hand." },
  { id: "smithy", label: "SMITHY STALL", takings: 30000, upkeep: 13000, fit: 240000,
    note: "Repairs and cheap arms. The big smithies are clan-affiliated and will notice you." },
  { id: "bakery", label: "BAKERY", takings: 22000, upkeep: 8000, fit: 90000,
    note: "Bread is the unit the whole economy is measured in. Thin margin, never no customers." },
];

function tradeById(id) {
  for (var i = 0; i < TRADES.length; i++) if (TRADES[i].id === id) return TRADES[i];
  return null;
}

// A month's takings for one fitted trade. Staff cost wages and earn their keep;
// an unattended shop still opens, just badly.
function monthTakings(prop, rand) {
  var b = h_obj(prop.business);
  var t = tradeById(b.trade);
  if (!t) return { gross: 0, upkeep: 0, net: 0, staff: 0 };
  var staff = Math.max(0, Math.floor(h_num(b.staff, 0)));
  var swing = 0.75 + rand() * 0.5;
  var gross = t.takings * districtMult(prop.district) * (1 + staff * 0.12) * swing;
  if (staff === 0) gross *= 0.55;
  var upkeep = t.upkeep + staff * 4500;
  return {
    gross: Math.round(gross),
    upkeep: Math.round(upkeep),
    net: Math.round(gross - upkeep),
    staff: staff,
  };
}

function Home(props) {
  var api = useYumina();
  var v = api.variables || {};

  var purse = h_num(v["mana-stones"], 0);
  var props_ = h_arr(v["properties"]);
  var homeId = String(v["home-current"] || "");
  var market = h_obj(v["property-market"]);
  var listings = h_arr(market.listings);
  var loc = String(v["location"] || "").toLowerCase();
  var floor = h_num(v["current-floor"], 0);

  var tS = React.useState("PLACES");
  var tab = tS[0], setTab = tS[1];
  var pS = React.useState(null);
  var pick = pS[0], setPick = pS[1];
  var rS = React.useState("");
  var subRaw = rS[0], setSub = rS[1];

  var underground = floor >= 1;

  // A board is a physical place: the district administrative agency, a notice
  // wall, a broker's front room. Not something reachable from a cave.
  var atBoard = !underground && (
    loc.indexOf("agency") !== -1 || loc.indexOf("administrat") !== -1 ||
    loc.indexOf("kommelby") !== -1 || loc.indexOf("ravigion") !== -1 ||
    loc.indexOf("kiarbis") !== -1 || loc.indexOf("gnome") !== -1
  );

  function say(line, note) {
    api.injectContext("[UI] " + note, { role: "system" });
    api.sendMessage(line);
    if (props.onClose) props.onClose();
  }

  function propById(id) {
    for (var i = 0; i < props_.length; i++) {
      if (String(h_obj(props_[i]).id) === String(id)) return h_obj(props_[i]);
    }
    return null;
  }

  // Standing in the same district as a place you hold. You cannot sleep in a
  // room in Ravigion from a table in Kommelby.
  function atProperty(p) {
    if (!p || underground) return false;
    var d = String(p.district || "").toLowerCase();
    if (!d) return false;
    var head = d.split(" ")[0];
    return loc.indexOf(head) !== -1 || loc.indexOf(String(p.name || "").toLowerCase()) !== -1;
  }

  function takeListing(l, mode) {
    if (underground) return;
    var cost = mode === "buy" ? h_num(l.price, 0) : h_num(l.rent, 0);
    if (cost <= 0 || cost > purse) return;

    var entry = {
      id: String(l.id || ("prop-" + Date.now())),
      name: String(l.name || "a place"),
      district: String(l.district || ""),
      kind: l.kind === "commercial" ? "commercial" : "residence",
      tenure: mode === "buy" ? "owned" : "rented",
      rent: mode === "buy" ? 0 : h_num(l.rent, 0),
      price: mode === "buy" ? h_num(l.price, 0) : 0,
      condition: String(l.condition || "sound"),
      notes: String(l.notes || ""),
      tenantRent: 0,
      business: null,
    };

    api.setVariable("mana-stones", purse - cost);
    api.setVariable("properties", props_.concat([entry]));

    // First place, and somewhere you can actually sleep — move in by default.
    var moveIn = entry.kind === "residence" && !homeId;
    if (moveIn) api.setVariable("home-current", entry.id);

    var rest = [];
    for (var i = 0; i < listings.length; i++) {
      if (String(h_obj(listings[i]).id) !== entry.id) rest.push(listings[i]);
    }
    api.setVariable("property-market", { boardActive: rest.length > 0, source: market.source || "", listings: rest });

    say(
      mode === "buy"
        ? "[I buy " + entry.name + " in " + entry.district + " outright, for " + cost + " stones.]"
        : "[I take " + entry.name + " in " + entry.district + ", at " + cost + " stones a month.]",
      "The player " + (mode === "buy" ? "BOUGHT" : "RENTED") + " " + entry.name + " in " +
        entry.district + " — " + entry.kind + ", " + entry.condition + ". Paid " + cost +
        " stones now; purse is " + (purse - cost) + ". " +
        (mode === "rented" || mode === "rent" ? "Rent of " + entry.rent + " falls due every month and the engine collects it. " : "") +
        (moveIn ? "This is now where they sleep. " : "") +
        "Narrate the handover — the landlord or the agent, the key, the stair, what the room smells like, " +
        "who on that street watched them arrive. Money and paperwork are already applied."
    );
  }

  function liveHere(p) {
    if (!p || p.kind !== "residence" || h_num(p.tenantRent, 0) > 0) return;
    api.setVariable("home-current", p.id);
    say(
      "[I move into " + p.name + ".]",
      "The player's address is now " + p.name + " in " + p.district + " (" + p.condition + "). " +
        "Resting there is free from here on. Narrate the move, briefly."
    );
  }

  // Sleeping somewhere that is yours. Free, and better than a motel — a real
  // bed, a door that locks, and nobody counting your nights.
  function restHere(p) {
    if (!p) return;
    var cond = h_num(v["condition"], 100);
    var stam = h_num(v["stamina"], 100);
    var pool = h_num(v["spirit"], 10);
    var day = h_num(v["cycle-day"], 1);

    api.setVariable("stamina", 100);
    api.setVariable("spirit-current", pool);
    api.setVariable("condition", Math.min(100, cond + 14));
    api.setVariable("clock", 420);
    api.setVariable("cycle-day", day + 1);

    say(
      "[I sleep the night at " + p.name + ".]",
      "The player slept at " + p.name + " (" + p.district + ", " + p.condition + "). A full night — " +
        "stamina restored, mana pool full, condition +14 (now " + Math.min(100, cond + 14) + "). " +
        "It is now the morning of day " + (day + 1) + ", 07:00. Persistent injuries do NOT heal from " +
        "sleep alone — a wound that needs a church or a physician still needs one. Narrate the night " +
        "and the waking, and anything that happened on that street while they were asleep. Already applied."
    );
  }

  function sublet(p) {
    var amt = Math.max(0, Math.floor(h_num(parseInt(subRaw, 10), 0)));
    if (!p || amt <= 0) return;
    var next = props_.map(function (x) {
      var o = h_obj(x);
      if (String(o.id) !== String(p.id)) return o;
      var c = {};
      for (var k in o) if (Object.prototype.hasOwnProperty.call(o, k)) c[k] = o[k];
      c.tenantRent = amt;
      return c;
    });
    api.setVariable("properties", next);
    if (homeId === p.id) api.setVariable("home-current", "");
    setSub("");
    say(
      "[I let " + p.name + " out to a tenant for " + amt + " stones a month.]",
      "The player has let " + p.name + " to a tenant at " + amt + " stones a month; the engine " +
        "collects it monthly" + (h_num(p.rent, 0) > 0 ? " against the " + p.rent + " they still owe on it" : "") + ". " +
        (homeId === p.id ? "They no longer live there and have no fixed address. " : "") +
        "Decide WHO the tenant is and narrate the arrangement. A tenant is a person with eyes, " +
        "a person who talks to neighbours, and a person who will notice if their landlord never ages."
    );
  }

  function letGo(p) {
    if (!p) return;
    var next = [];
    for (var i = 0; i < props_.length; i++) {
      if (String(h_obj(props_[i]).id) !== String(p.id)) next.push(props_[i]);
    }
    api.setVariable("properties", next);
    if (homeId === p.id) api.setVariable("home-current", "");
    setPick(null);

    var owned = p.tenure === "owned";
    var back = owned ? Math.round(h_num(p.price, 0) * 0.82) : 0;
    if (back > 0) api.setVariable("mana-stones", purse + back);

    say(
      owned
        ? "[I sell " + p.name + ".]"
        : "[I give up the lease on " + p.name + ".]",
      owned
        ? "The player SOLD " + p.name + " for " + back + " stones (82% of what they paid — a quick sale " +
          "is never a good one). Purse is now " + (purse + back) + ". Already applied."
        : "The player gave up the lease on " + p.name + ". Nothing comes back; a deposit never does. " +
          (homeId === p.id ? "They now have no fixed address — motels or worse. " : "") +
          "Narrate the landlord and the empty room."
    );
  }

  function openTrade(p, trade) {
    if (!p || p.kind !== "commercial" || !trade) return;
    if (trade.fit > purse) return;
    var next = props_.map(function (x) {
      var o = h_obj(x);
      if (String(o.id) !== String(p.id)) return o;
      var c = {};
      for (var k in o) if (Object.prototype.hasOwnProperty.call(o, k)) c[k] = o[k];
      c.business = { trade: trade.id, staff: 0, upkeep: trade.upkeep, takings: 0, notes: "" };
      return c;
    });
    api.setVariable("mana-stones", purse - trade.fit);
    api.setVariable("properties", next);
    say(
      "[I fit out " + p.name + " as a " + trade.label.toLowerCase() + " and open for trade.]",
      "The player spent " + trade.fit + " stones fitting out " + p.name + " in " + p.district +
        " as a " + trade.label.toLowerCase() + ". Purse is now " + (purse - trade.fit) + ". " +
        "It has NO STAFF yet, which means it only opens when the player is standing in it — " +
        "takings will be poor while they are down a hole for three weeks of the month. " +
        "The engine settles takings and upkeep monthly. Narrate the fitting-out, the licence if the " +
        "trade needs one, and whichever clan-affiliated competitor down the street noticed."
    );
  }

  function hire(p, delta) {
    if (!p) return;
    var b = h_obj(p.business);
    var t = tradeById(b.trade);
    if (!t) return;
    var staff = Math.max(0, Math.floor(h_num(b.staff, 0)) + delta);
    var next = props_.map(function (x) {
      var o = h_obj(x);
      if (String(o.id) !== String(p.id)) return o;
      var c = {};
      for (var k in o) if (Object.prototype.hasOwnProperty.call(o, k)) c[k] = o[k];
      var nb = {};
      for (var k2 in b) if (Object.prototype.hasOwnProperty.call(b, k2)) nb[k2] = b[k2];
      nb.staff = staff;
      c.business = nb;
      return c;
    });
    api.setVariable("properties", next);
    say(
      delta > 0
        ? "[I take on another hand at " + p.name + ".]"
        : "[I let one of the hands at " + p.name + " go.]",
      "Staff at " + p.name + " is now " + staff + " (wages 4,500 each a month, collected by the engine). " +
        "Name them and give them something — a reason they took the work, an opinion about the owner. " +
        "Staff are the reason the shop earns anything while the player is in the Labyrinth."
    );
  }

  function askBoard() {
    if (!atBoard || underground) return;

    // Passive property lookup: generate listings in-panel and keep the panel open.
    var district = "Ravigion";
    if (loc.indexOf("bifron") !== -1) district = "Bifron";
    else if (loc.indexOf("kommelby") !== -1) district = "Kommelby";
    else if (loc.indexOf("kiarbis") !== -1) district = "Kiarbis";
    else if (loc.indexOf("gnome") !== -1) district = "Gnome Tree";
    else if (loc.indexOf("ravigion") !== -1) district = "Ravigion";

    var ranges = {
      "Bifron": [800, 2000],
      "Ravigion": [3000, 9000],
      "Gnome Tree": [4000, 11000],
      "Kiarbis": [15000, 40000],
      "Kommelby": [18000, 60000],
    };
    var range = ranges[district] || ranges["Ravigion"];

    function seeded(seed) {
      var x = seed >>> 0;
      return function () {
        x = (x * 1664525 + 1013904223) >>> 0;
        return x / 4294967296;
      };
    }

    var seed = ((h_num(v["cycle-month"], 1) * 104729) ^
      (h_num(v["cycle-day"], 1) * 7919) ^
      (district.length * 131) ^
      (String(v["race"] || "").length * 37)) >>> 0;
    var rnd = seeded(seed);

    var residenceNames = {
      "Bifron": ["Back-Alley Room", "Tanner's Loft", "Shared Courtyard Room", "Old Gate Tenement"],
      "Ravigion": ["Stone-Stair Room", "East Wall Flat", "Two-Room Walkup", "Market Lane Rooms"],
      "Gnome Tree": ["Rootside Room", "Workshop Loft", "Canal-Side Flat", "Upper Gallery Room"],
      "Kiarbis": ["Lamp District Flat", "Broker's Court Rooms", "South Arcade Apartment", "Second-Floor Suite"],
      "Kommelby": ["Merchant Row Apartment", "Quiet Courtyard Suite", "Canal View Rooms", "Guildward Flat"],
    };
    var badNotes = [
      "Damp in the back wall; the landlord insists it is seasonal.",
      "Cheap because the downstairs tannery works before dawn.",
      "The lock has been replaced twice this month.",
      "One room has no window and the roof leaks when it rains.",
    ];
    var goodNotes = [
      "Sound walls, private lock, nothing remarkable.",
      "Close to ordinary shops and foot traffic.",
      "Small, clean, and better kept than the price suggests.",
      "A plain place with enough room for gear and a bed.",
    ];

    var count = 3 + Math.floor(rnd() * 4);
    var rows = [];
    for (var i = 0; i < count; i++) {
      var commercial = i === count - 1 && rnd() < 0.45;
      var baseRent = Math.round(range[0] + rnd() * (range[1] - range[0]));
      var rent = commercial ? Math.round(baseRent * (1.5 + rnd() * 1.2)) : baseRent;
      var months = 90 + Math.floor(rnd() * 41);
      var price = Math.round(rent * months);
      var isBad = i === 0;
      var names = residenceNames[district] || residenceNames["Ravigion"];
      var nm = names[Math.floor(rnd() * names.length)];
      if (commercial) nm = district + " Streetfront Unit";

      rows.push({
        id: "listing-m" + h_num(v["cycle-month"], 1) + "d" + h_num(v["cycle-day"], 1) + "-" + district + "-" + i,
        name: nm,
        district: district,
        kind: commercial ? "commercial" : "residence",
        rent: rent,
        price: price,
        condition: isBad ? "poor" : (rnd() < 0.28 ? "worn" : "sound"),
        notes: isBad
          ? badNotes[Math.floor(rnd() * badNotes.length)]
          : goodNotes[Math.floor(rnd() * goodNotes.length)],
      });
    }

    if (String(v["race"] || "") === "Barbarian" && district === "Kommelby" && rows.length > 3) {
      rows = rows.slice(0, Math.max(2, rows.length - 2));
    }

    api.setVariable("property-market", {
      boardActive: true,
      source: district + " property board",
      generatedAt: "m" + h_num(v["cycle-month"], 1) + "d" + h_num(v["cycle-day"], 1),
      listings: rows,
    });
    api.injectContext(
      "[UI] Refreshed the " + district + " property board. " +
      rows.length + " eligible listings are now visible in the PROPERTY panel. " +
      "No narrated scene was consumed."
    );
  }

  var chosen = pick ? propById(pick) : null;
  var homeProp = homeId ? propById(homeId) : null;

  // Everything owed and everything earned, next settlement.
  var owed = 0, income = 0;
  for (var i = 0; i < props_.length; i++) {
    var p = h_obj(props_[i]);
    owed += h_num(p.rent, 0);
    income += h_num(p.tenantRent, 0);
    var b = h_obj(p.business);
    if (tradeById(b.trade)) {
      var t = tradeById(b.trade);
      owed += t.upkeep + Math.max(0, h_num(b.staff, 0)) * 4500;
    }
  }

  return (
    <Screen title="PROPERTY" onClose={props.onClose}>
      <div style={{ display: "flex", gap: 6, marginBottom: 12, flexWrap: "wrap" }}>
        {TABS_home.map(function (t) {
          return (
            <Btn key={t} on={tab === t} onClick={function () { setTab(t); setPick(null); }}>
              {t}
            </Btn>
          );
        })}
      </div>

      <div style={{ marginBottom: 12 }}>
        <Stat label="on you" value={purse + " stones"} accent={C.brass} rule />
        <Stat
          label="you sleep"
          value={homeProp ? homeProp.name + ", " + homeProp.district : "nowhere fixed"}
          dim={!homeProp}
          rule
        />
        <Stat label="due each month" value={owed > 0 ? owed + " stones" : "nothing"} dim={owed === 0} rule />
        <Stat label="coming in" value={income > 0 ? income + " stones" : "nothing"} dim={income === 0} />
      </div>

      {!homeProp ? (
        <div
          style={{
            marginBottom: 12, padding: "9px 11px", borderRadius: 8,
            border: "1px dashed " + C.brass, background: "rgba(150,110,45,0.07)",
            fontSize: 10, lineHeight: 1.7, color: C.boneDim,
          }}
        >
          <span style={{ color: C.brassLit, letterSpacing: "0.12em" }}>NO FIXED ADDRESS</span>
          <div style={{ marginTop: 4 }}>
            Motels run about 9,000 a night in Kommelby, less and worse further
            out. A month of that costs more than most rooms cost to rent — and
            a clerk who asks where you live and gets no answer remembers it.
          </div>
        </div>
      ) : null}

      {tab === "PLACES" ? (
        <div>
          {props_.length === 0 ? (
            <Empty>
              You hold nothing. Everywhere you have slept so far, you paid for
              by the night.
            </Empty>
          ) : (
            props_.map(function (raw) {
              var p = h_obj(raw);
              var isHome = String(p.id) === homeId;
              var sel = String(p.id) === String(pick);
              var b = h_obj(p.business);
              var t = tradeById(b.trade);
              return (
                <div
                  key={p.id}
                  className="ds-panel"
                  style={{
                    border: "1px solid " + (isHome ? C.brass : C.rule),
                    borderRadius: R.md,
                    background: isHome ? "rgba(201,162,39,0.06)" : C.panel,
                    boxShadow: SH.panel,
                    padding: 10,
                    marginBottom: 8,
                    cursor: "pointer",
                  }}
                  onClick={function () { setPick(sel ? null : p.id); }}
                >
                  <div style={{ display: "flex", alignItems: "baseline", gap: 8 }}>
                    <span style={{ fontSize: 12, color: isHome ? C.brassLit : C.bone }}>
                      {p.name || "—"}
                    </span>
                    <span style={{ flex: 1 }} />
                    <span style={{ fontSize: 10, color: C.boneFaint }}>
                      {p.tenure === "owned" ? "owned" : p.rent + "/mo"}
                    </span>
                  </div>
                  <div style={{ marginTop: 6 }}>
                    <Chip>{p.district || "—"}</Chip>
                    <Chip>{p.kind === "commercial" ? "commercial" : "residence"}</Chip>
                    <Chip>{p.condition || "—"}</Chip>
                    {isHome ? <Chip color={C.brass} border={C.brass}>you live here</Chip> : null}
                    {h_num(p.tenantRent, 0) > 0 ? <Chip>let out — {p.tenantRent}/mo</Chip> : null}
                    {t ? <Chip color={C.brass} border={C.brass}>{t.label.toLowerCase()}</Chip> : null}
                  </div>
                  {p.notes ? (
                    <div style={{ fontSize: 10, lineHeight: 1.6, color: C.boneDim, marginTop: 6 }}>
                      {p.notes}
                    </div>
                  ) : null}

                  {sel ? (
                    <div style={{ marginTop: 10 }} onClick={function (e) { e.stopPropagation(); }}>
                      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 8 }}>
                        {p.kind === "residence" && !isHome && h_num(p.tenantRent, 0) === 0 ? (
                          <Btn onClick={function () { liveHere(p); }}>LIVE HERE</Btn>
                        ) : null}
                        {isHome ? (
                          <Btn
                            onClick={function () { restHere(p); }}
                            disabled={!atProperty(p)}
                          >
                            {atProperty(p) ? "SLEEP THE NIGHT" : "YOU ARE NOT THERE"}
                          </Btn>
                        ) : null}
                        <Btn onClick={function () { letGo(p); }}>
                          {p.tenure === "owned" ? "SELL IT" : "GIVE UP THE LEASE"}
                        </Btn>
                      </div>

                      {h_num(p.tenantRent, 0) === 0 ? (
                        <Frame title="LET IT OUT">
                          <div style={{ fontSize: 10, lineHeight: 1.7, color: C.boneDim, marginBottom: 8 }}>
                            Somebody else pays you to live here. You cannot sleep
                            in a room you have let, and a tenant is a person with
                            eyes.
                          </div>
                          <input
                            value={subRaw}
                            onChange={function (e) { setSub(e.target.value.replace(/[^0-9]/g, "")); }}
                            inputMode="numeric"
                            placeholder="stones a month"
                            style={{
                              width: "100%", boxSizing: "border-box", fontFamily: MONO,
                              fontSize: 12, padding: "8px 11px", borderRadius: R.sm,
                              background: C.void, color: C.bone,
                              border: "1px solid " + C.rule, outline: "none", marginBottom: 8,
                            }}
                          />
                          <Btn wide onClick={function () { sublet(p); }} disabled={!subRaw}>
                            TAKE A TENANT
                          </Btn>
                        </Frame>
                      ) : null}
                    </div>
                  ) : null}
                </div>
              );
            })
          )}
        </div>
      ) : null}

      {tab === "BOARD" ? (
        <div>
          {underground ? (
            <Empty>
              You are underground. Nobody down here is letting rooms.
            </Empty>
          ) : listings.length === 0 ? (
            <div>
              <Empty>
                Nothing in front of you. Property gets found at a district
                agency, on a notice wall, or by asking somebody who knows a
                landlord.
              </Empty>
              <div style={{ marginTop: 10 }}>
                <Btn wide onClick={askBoard} disabled={!atBoard}>
                  {atBoard ? "GO LOOKING FOR SOMEWHERE" : "NOT SOMEWHERE YOU CAN ASK"}
                </Btn>
              </div>
            </div>
          ) : (
            <div>
              {market.source ? (
                <div style={{ fontSize: 10, color: C.boneFaint, marginBottom: 10 }}>
                  {market.source}
                </div>
              ) : null}
              {listings.map(function (raw) {
                var l = h_obj(raw);
                var rent = h_num(l.rent, 0);
                var price = h_num(l.price, 0);
                return (
                  <Frame key={l.id} title={String(l.name || "a place")}>
                    <div style={{ marginBottom: 6 }}>
                      <Chip>{l.district || "—"}</Chip>
                      <Chip>{l.kind === "commercial" ? "commercial" : "residence"}</Chip>
                      <Chip>{l.condition || "—"}</Chip>
                    </div>
                    {l.notes ? (
                      <div style={{ fontSize: 10, lineHeight: 1.7, color: C.boneDim, marginBottom: 8 }}>
                        {l.notes}
                      </div>
                    ) : null}
                    <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                      {rent > 0 ? (
                        <Btn
                          onClick={function () { takeListing(l, "rent"); }}
                          disabled={rent > purse}
                        >
                          {rent > purse ? "CANNOT COVER " + rent : "TAKE IT — " + rent + "/MO"}
                        </Btn>
                      ) : null}
                      {price > 0 ? (
                        <Btn
                          onClick={function () { takeListing(l, "buy"); }}
                          disabled={price > purse}
                        >
                          {price > purse ? "CANNOT COVER " + price : "BUY IT — " + price}
                        </Btn>
                      ) : null}
                    </div>
                  </Frame>
                );
              })}
              <div style={{ marginTop: 10 }}>
                <Btn wide onClick={askBoard}>LOOK SOMEWHERE ELSE</Btn>
              </div>
            </div>
          )}
        </div>
      ) : null}

      {tab === "TRADE" ? (
        <div>
          {(function () {
            var comm = [];
            for (var j = 0; j < props_.length; j++) {
              var q = h_obj(props_[j]);
              if (q.kind === "commercial") comm.push(q);
            }
            if (comm.length === 0) {
              return (
                <Empty>
                  A business needs a commercial unit. Find one on the board
                  first — they run 1.5 to 3 times a residence of the same size,
                  and the district decides everything about what walks past the
                  door.
                </Empty>
              );
            }
            return comm.map(function (p) {
              var b = h_obj(p.business);
              var t = tradeById(b.trade);
              return (
                <Frame key={p.id} title={String(p.name || "unit") + " — " + String(p.district || "")}>
                  {t ? (
                    <div>
                      <div style={{ marginBottom: 6 }}>
                        <Chip color={C.brass} border={C.brass}>{t.label.toLowerCase()}</Chip>
                        <Chip>{h_num(b.staff, 0)} staff</Chip>
