                                disabled={tr.fit > purse}
                              >
                                {tr.label} — {tr.fit > purse ? "NEEDS " + tr.fit : "FIT OUT, " + tr.fit}
                              </Btn>
                              <div style={{ fontSize: 9, lineHeight: 1.6, color: C.boneFaint, marginTop: 3 }}>
                                {tr.note}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </Frame>
              );
            });
          })()}
        </div>
      ) : null}
    </Screen>
  );
}

// Settles property once per month: rent owed, upkeep and wages out, tenant
// rent and takings in. Runs on the month rolling over, never on a turn, and
// records the month it settled so it cannot charge twice.
function PropertyClock() {
  var api = useYumina();
  var v = api.variables || {};
  var month = h_num(v["cycle-month"], 1);
  var props_ = h_arr(v["properties"]);
  var ledger = h_obj(v["property-ledger"]);
  var busy = React.useRef(false);

  React.useEffect(function () {
    if (busy.current) return;
    if (props_.length === 0) return;
    if (h_num(ledger.lastSettledMonth, 0) === month) return;

    busy.current = true;

    var seed = ((month * 7919) ^ (props_.length * 131)) & 0x7fffffff;
    var s = seed || 1;
    function rand() {
      s ^= s << 13; s >>>= 0;
      s ^= s >> 17;
      s ^= s << 5; s >>>= 0;
      return s / 4294967296;
    }

    var costs = 0, income = 0;
    var lines = [];

    var next = props_.map(function (raw) {
      var p = h_obj(raw);
      var c = {};
      for (var k in p) if (Object.prototype.hasOwnProperty.call(p, k)) c[k] = p[k];

      var rent = h_num(p.rent, 0);
      if (rent > 0) { costs += rent; lines.push(p.name + " rent -" + rent); }

      var tr = h_num(p.tenantRent, 0);
      if (tr > 0) { income += tr; lines.push(p.name + " tenant +" + tr); }

      var t = tradeById(h_obj(p.business).trade);
      if (t) {
        var m = monthTakings(p, rand);
        income += m.gross;
        costs += m.upkeep;
        var nb = {};
        var b = h_obj(p.business);
        for (var k2 in b) if (Object.prototype.hasOwnProperty.call(b, k2)) nb[k2] = b[k2];
        nb.takings = m.gross;
        nb.upkeep = m.upkeep;
        c.business = nb;
        lines.push(p.name + " " + t.label.toLowerCase() + " +" + m.gross + " / -" + m.upkeep +
          (m.staff === 0 ? " (unattended)" : ""));
      }
      return c;
    });

    var purse = h_num(v["mana-stones"], 0);
    var netted = purse + income - costs;
    var short = netted < 0;

    api.setVariable("properties", next);
    api.setVariable("mana-stones", Math.max(0, netted));
    api.setVariable("property-ledger", {
      lastCosts: costs, lastIncome: income, lastSettledMonth: month,
    });

    api.injectContext(
      "[UI] PROPERTY SETTLED for month " + month + ". " + lines.join("; ") + ". " +
      "Total in " + income + ", total out " + costs + ". Purse is now " + Math.max(0, netted) + ". " +
      (short
        ? "THEY COULD NOT COVER IT — they were short by " + Math.abs(netted) + " stones. A landlord " +
          "who is not paid does not wait quietly: play the demand, the lock changed, the tenancy ended, " +
          "or the staff who turn up and find no wages. This is a real problem and it should cost them " +
          "something more than money."
        : "Work whichever of these matters into the month's texture — a landlord at the door, a good " +
          "month on the counter, a tenant with a complaint. Do not re-apply any of it.") ,
      { role: "system" }
    );

    busy.current = false;
  }, [month, props_.length]);

  return null;
}

// Sets the floor's clock the first time someone sets foot on it, and clears the
// portal search when they move. Never the GM's to remember.
//
// It also holds the door shut. The Labyrinth is one-way: there is no exit portal,
// and the only thing that ends a trip is the floor's own close-date arriving. A
// GM that narrates the player back to the surface on day 2 has broken the single
// load-bearing pressure of the whole simulation, so the engine refuses the move
// and tells it so. Legitimate expulsion still works, because by then daysLeft is 0.
function GrindClock() {
  var api = useYumina();
  var v = api.variables || {};
  var floor = g_num(v["current-floor"], 0);
  var daysLeft = g_num(v["floor-days-left"], 0);
  var lastRef = React.useRef(null);
  var daysRef = React.useRef(0);
  daysRef.current = daysLeft;

  React.useEffect(function () {
    if (lastRef.current === floor) return;
    var prev = lastRef.current;

    // Illegal surfacing: inside a floor whose clock has not run out.
    if (prev !== null && prev >= 1 && floor === 0 && daysRef.current > 0) {
      api.setVariable("current-floor", prev);
      api.injectContext(
        "[UI] REFUSED — the Labyrinth is one way. The player is still on floor " + prev +
        " with " + daysRef.current + " in-floor day(s) left before it closes, and there is no exit " +
        "portal anywhere in the Labyrinth. The rift they came through does not go home. Nobody " +
        "walks out early: the floor expels its survivors on its own close-date and not one hour " +
        "sooner. current-floor has been reset to " + prev + ". Do not narrate the surface, the " +
        "Dimensional Square, Rafdonia, or any shortcut out. If they tried to leave, narrate the " +
        "wall — the Square they arrived at is bare rock now, and the only way through the next " +
        (daysRef.current) + " day(s) is to survive them.",
        { role: "system" }
      );
      return;
    }

    lastRef.current = floor;
    if (prev === null) return;

    api.setVariable("floor-days-left", (floor >= 1 && FLOOR_DAYS[floor]) ? FLOOR_DAYS[floor] : 0);
    api.setVariable("portal-progress", 0);
  }, [floor]);

  return null;
}

