function NarrativeIngestWatch() {
  var api=useYumina();
  var v=api.variables||{};
  var reqs=Array.isArray(v["ingest-requests"])?v["ingest-requests"]:[];
  var sig=JSON.stringify(reqs);

  React.useEffect(function(){
    var current=Array.isArray(v["ingest-requests"])?v["ingest-requests"]:[];
    var ri=-1;
    for(var i=0;i<current.length;i++){
      if(current[i]&&current[i].status==="pending"){ri=i;break;}
    }
    if(ri<0)return;

    var r=current[ri]||{},items=normalizeList(v["inventory"]);
    var id=String(r.itemId||"");
    if(!id&&r.itemName){
      var want=String(r.itemName).toLowerCase();
      var matches=items.filter(function(it){return it&&String(it.name||"").toLowerCase()===want;});
      if(matches.length===1)id=matches[0].id;
      else {
        matches=items.filter(function(it){return it&&String(it.name||"").toLowerCase().indexOf(want)>=0;});
        if(matches.length===1)id=matches[0].id;
      }
    }

    var result=resolveIngestState(v,items,id,String(r.action||""));
    var nextReq=current.slice();
    if(!result.ok){
      nextReq[ri]=Object.assign({},r,{status:"refused",reason:result.reason||"could not resolve"});
      api.setVariable("ingest-requests",nextReq);
      // Only failures need hidden context so narration does not falsely claim success.
      api.injectContext("[INGEST ENGINE] Typed "+String(r.action||"consume")+" could not be applied: "+String(result.reason||"unknown reason")+". Do not narrate successful consumption.",{role:"system"});
      return;
    }

    api.setVariable("inventory",result.items);
    (result.changed||[]).forEach(function(ch){api.setVariable(ch.var,Math.max(0,Math.min(100,Number(ch.value||0))));});
    var ledger=Array.isArray(v["item-use-ledger"])?v["item-use-ledger"]:[];
    api.setVariable("item-use-ledger",ledger.concat([{
      itemId:result.item.id,itemName:result.item.name,
      effects:(result.changed||[]).map(function(ch){return ch.var+" -> "+Math.round(ch.value);}),
      source:"typed "+result.kind,clock:v["clock"]
    }]).slice(-30));
    nextReq[ri]=Object.assign({},r,{status:"resolved",itemId:result.item.id,itemName:result.item.name});
    api.setVariable("ingest-requests",nextReq.slice(-40));
    // Success is silent. The user's own typed action is already the narration.
    // eslint-disable-next-line
  },[sig]);

  return null;
}


function PartyCombatEventWatch(){
  var api=useYumina();
  var v=api.variables||{};
  var sig=JSON.stringify(Array.isArray(v["party-combat-events"])?v["party-combat-events"]:[]);
  React.useEffect(function(){
    var events=Array.isArray(v["party-combat-events"])?v["party-combat-events"]:[];
    var roster=Array.isArray(v["party"])?v["party"]:[];
    var changed=false, nextRoster=roster.map(function(m,i){return normalizePartyCombatMember(m,i);});
    var nextEvents=events.map(function(e,ei){
      if(!e||e.resolved===true)return e;
      var idx=nextRoster.findIndex(function(m){
        if(e.memberId&&String(m.id)===String(e.memberId))return true;
        return e.memberName&&String(m.name||"")===String(e.memberName);
      });
      if(idx<0)return Object.assign({},e,{resolved:true,refused:true,reason:"party member not found"});
      var m=Object.assign({},nextRoster[idx]), c=Object.assign({},m.combat||{});
      var amt=Math.max(0,Number(e.amount)||0), typ=String(e.type||"").toLowerCase();
      if(typ==="damage"){
        c.condition=Math.max(0,(Number(c.condition)||0)-amt);
        if(c.condition<=0)c.status="down";
      }else if(typ==="heal"){
        c.condition=Math.min(Number(c.conditionMax)||100,(Number(c.condition)||0)+amt);
        if(c.condition>0&&String(c.status).toLowerCase()==="down")c.status="ready";
      }else if(typ==="death"){
        c.condition=0;c.status="dead";
      }else if(typ==="status"){
        c.status=String(e.status||c.status||"ready");
      }else if(typ==="recover"){
        c.stamina=Math.min(Number(c.staminaMax)||100,(Number(c.stamina)||0)+amt);
        if(e.manaAmount!=null)c.mana=Math.min(Number(c.manaMax)||0,(Number(c.mana)||0)+Math.max(0,Number(e.manaAmount)||0));
      }else if(typ==="injury"){
        var inj=String(e.injury||e.status||"injury");
        c.injuries=Array.isArray(c.injuries)?c.injuries.slice():[];
        if(inj&&c.injuries.indexOf(inj)<0)c.injuries.push(inj);
        if(amt>0)c.condition=Math.max(0,(Number(c.condition)||0)-amt);
        if(c.condition<=0)c.status="down";
      }
      m.combat=c;nextRoster[idx]=m;changed=true;
      return Object.assign({},e,{resolved:true});
    });
    if(changed)api.setVariable("party",nextRoster);
    if(JSON.stringify(nextEvents)!==JSON.stringify(events))api.setVariable("party-combat-events",nextEvents);
  },[sig]);
  return null;
}


function PartyProgressionWatch(){
  var api=useYumina(),v=api.variables||{};
  var sig=JSON.stringify(Array.isArray(v["party-progression-events"])?v["party-progression-events"]:[]);
  React.useEffect(function(){
    var events=Array.isArray(v["party-progression-events"])?v["party-progression-events"]:[];
    var roster=Array.isArray(v["party"])?v["party"]:[];
    var next=roster.map(function(m,i){return normalizePartyCombatMember(m,i);}), changed=false;
    var ne=events.map(function(e){
      if(!e||e.resolved===true)return e;
      var ix=next.findIndex(function(m){return (e.memberId&&String(m.id)===String(e.memberId))||(e.memberName&&String(m.name)===String(e.memberName));});
      if(ix<0)return Object.assign({},e,{resolved:true,refused:true,reason:"party member not found"});
      var m=normalizePartyCombatMember(next[ix],ix), typ=String(e.type||"").toLowerCase();
      if(typ==="item-gain"&&e.item){
        m.inventory=addItem(m.inventory,e.item);changed=true;
      }else if(typ==="item-loss"){
        var iid=e.itemId||(e.item&&e.item.id);
        if(iid){m.inventory=removeItem(m.inventory,iid,Math.max(1,Number(e.amount)||1));changed=true;}
      }else if(typ==="essence-capacity"){
        m.essenceCapacity=Math.max(1,(Number(m.essenceCapacity)||1)+(Number(e.amount)||0));changed=true;
      }else if(typ==="essence-erase"){
        var src=String(e.source||"").toLowerCase();
        var es=(m.essences||[]).slice(), ei=es.findIndex(function(x){return x&&String(x.source||x.name||"").toLowerCase()===src;});
        if(ei>=0){es.splice(ei,1);m.essences=es;changed=true;}
      }else if(typ==="essence-absorb"&&e.essence){
        var es2=(m.essences||[]).slice(), cap=Math.max(1,Number(m.essenceCapacity)||1);
        var used=partyEssenceTotals(es2).weight, add=partyEssenceWeight(e.essence);
        if(used+add<=cap){
          es2.push(e.essence);m.essences=es2;changed=true;
        }else{
          return Object.assign({},e,{resolved:true,refused:true,reason:"essence capacity exceeded"});
        }
      }
      next[ix]=normalizePartyCombatMember(m,ix);
      return Object.assign({},e,{resolved:true});
    });
    if(changed)api.setVariable("party",next);
    if(JSON.stringify(ne)!==JSON.stringify(events))api.setVariable("party-progression-events",ne);
  },[sig]);
  return null;
}


function PartySurfaceLifeWatch(){
  var api=useYumina(),v=api.variables||{};
  var floor=Number(v["current-floor"]||0),loc=String(v["location"]||"").toLowerCase();
  var ordinal=companionDayOrdinal(v);
  var sig=String(ordinal)+"|"+floor+"|"+loc+"|"+JSON.stringify(arr_party(v["party"]).map(function(m){return [m&&m.id,m&&m.lifeState&&m.lifeState.lastProcessedOrdinal];}));
  React.useEffect(function(){
    if(floor>0||/labyrinth|floor [1-9]|rift/.test(loc))return;
    var roster=arr_party(v["party"]); if(!roster.length)return;
    var changed=false, publicNotes=[];
    var next=roster.map(function(raw,i){
      var m=normalizePartyCombatMember(raw,i),ls=normalizeCompanionLife(m);
      if(ls.available===false||String(m.combat&&m.combat.status||"").toLowerCase()==="dead")return m;
      var last=Number(ls.lastProcessedOrdinal||0);
      if(last<=0){ls.lastProcessedOrdinal=ordinal-1;m.lifeState=ls;last=ordinal-1;}
      var gap=Math.max(0,ordinal-last);
      // Event-driven LOD: process at most 30 meaningful day slices per catch-up; aggregate older idle span.
      var begin=Math.max(last+1,ordinal-29);
      if(gap>30){
        ls.history.push({ordinal:begin-1,private:true,summary:"Lived "+(gap-30)+" additional surface days through ordinary work, rest, relationships and obligations (aggregated LOD)."});
        m.lifeState=ls;
      }
      for(var d=begin;d<=ordinal;d++)m=processCompanionLifeDay(m,v,d);
      if(gap>0){changed=true;
        var latest=m.lifeState.history[m.lifeState.history.length-1];
        if(latest&&!latest.private)publicNotes.push(m.name+": "+latest.summary);
      }
      return normalizePartyCombatMember(m,i);
    });
    if(changed){
      api.setVariable("party",next);
      api.injectContext("[HIDDEN COMPANION CATCH-UP — ALREADY APPLIED] Persistent companion lives advanced through elapsed surface time. "+
        "Private history is NOT player knowledge. Reveal only what {{user}} could observe, be told, or plausibly learn. Do not duplicate purchases, earnings, obligations, or goal progress.",{role:"system"});
    }
  },[sig]);
  return null;
}


