      if(typ==="goal-add"){ls.goals.push(Object.assign({id:"goal-"+stablePartyHash(JSON.stringify(d)),status:"active",progress:0,priority:50},d));changed=true;}
      else if(typ==="goal-complete"){ls.goals=ls.goals.map(function(g){return (d.id&&g.id===d.id)||(!d.id&&d.title&&g.title===d.title)?Object.assign({},g,{status:"complete",progress:100}):g;});changed=true;}
      else if(typ==="obligation-add"){ls.obligations.push(Object.assign({id:"obl-"+stablePartyHash(JSON.stringify(d)),status:"active"},d));changed=true;}
      else if(typ==="relationship"){var who=String(d.person||d.name||"unknown");ls.relationships[who]=Object.assign({},ls.relationships[who]||{},d);changed=true;}
      else if(typ==="availability"){ls.available=d.available!==false;ls.unavailableReason=String(d.reason||"");changed=true;}
      else if(typ==="private-knowledge"){ls.privateKnowledge.push(d);changed=true;}
      else if(typ==="knowledge-reveal"){ls.knownToPlayer.push(d);changed=true;}
      m.lifeState=ls;roster[ix]=normalizePartyCombatMember(m,ix);
      return Object.assign({},e,{resolved:true});
    });
    if(changed)api.setVariable("party",roster);
    if(JSON.stringify(ne)!==JSON.stringify(ev))api.setVariable("companion-life-directives",ne);
  },[sig]);
  return null;
}



