function mtNum(x:any,d:number){ var n=Number(x); return Number.isFinite(n)?n:d; }
function mtClock(raw:any){
  var n=Math.floor(mtNum(raw,0));
  n=((n%1440)+1440)%1440;
  return {minuteOfDay:n,hour:Math.floor(n/60),minute:n%60};
}

function mtSurface(v:any){
  var old=v["surface-time"]||{}, lc=mtClock(v["clock"]);
  var year=mtNum(old.year,1), month=mtNum(v["cycle-month"],mtNum(old.month,1)), day=mtNum(v["cycle-day"],mtNum(old.day,1));
  var hour=lc.hour, minute=lc.minute;
  var absoluteMinute=((((year*13)+month)*40+day)*1440)+lc.minuteOfDay;
  return {year:year,month:month,day:day,hour:hour,minute:minute,minuteOfDay:lc.minuteOfDay,absoluteMinute:absoluteMinute,source:"master-timekeeper"};
}

function mtPortal(st:any){
  var mod=st.hour*60+st.minute, open=(st.day===1 && mod>=0 && mod<60), closing=(st.day===1 && mod>=50 && mod<60);
  return {state:open?(closing?"CLOSING":"OPEN"):"CLOSED",exists:open,acceptsEntry:open,surfaceYear:st.year,surfaceMonth:st.month,surfaceDay:st.day,surfaceMinuteOfDay:mod,opensAt:"00:00",closesAtApprox:"01:00",closeTimeAuthority:"strong-simulation-inference"};
}

