  if (region === "clothes" || region === "waist" || region === "back" || region === "accessory" || region === "weapon") return [];
  return region ? [region] : [];
}

function coverageScale(coverage) {
  var c = Array.isArray(coverage) ? coverage.length : 1;
  if (c <= 1) return 1.0;
  if (c === 2) return 1.45;
  if (c === 3) return 1.85;
  return 2.25;
}

function conditionValueMult(raw) {
  var s = String((raw || {}).condition || "").toLowerCase();
  if (/broken|ruined|destroyed/.test(s)) return 0.10;
  if (/damaged|poor|cracked|bent/.test(s)) return 0.45;
  if (/worn|used|dented/.test(s)) return 0.70;
  if (/fair|serviceable/.test(s)) return 0.85;
  if (/good|sharp|maintained/.test(s)) return 0.95;
  return 1.00;
}

function craftsmanshipValueMult(raw) {
  var q = String((raw || {}).quality || "").toLowerCase();
  if (/masterwork|masterpiece/.test(q)) return 10.0;
  if (/exceptional/.test(q)) return 5.0;
  if (/superior|high[- ]quality/.test(q)) return 2.5;
  if (/fine/.test(q)) return 1.5;
  if (/crude|poor/.test(q)) return 0.65;
  return 1.0;
}

function materializeArmorStats(name, type, slot, raw) {
  var r = raw || {};
  var shieldArch = inferShieldArchetype(name, type, r);
  var arch = shieldArch ? "" : inferArmorArchetype(name, type, slot, r);
  var custom = r.armor && typeof r.armor === "object" ? r.armor : {};
  var mp = weaponMaterialMods(r, name);

  if (shieldArch && SHIELD_ARCHETYPES_items[shieldArch]) {
    var sb = SHIELD_ARCHETYPES_items[shieldArch];
    var so = Object.assign({}, sb, custom);
    so.shieldType = shieldArch;
    so.archetype = "shield";
    so.className = custom.className || sb.className;
    so.coverage = Array.isArray(custom.coverage) ? custom.coverage.slice() : sb.coverage.slice();

    if (custom.protection === undefined) {
      so.protection = {};
      Object.keys(sb.protection).forEach(function (k) {
        so.protection[k] = Math.max(0, sb.protection[k] + mp.protection);
      });
    }
    if (custom.block === undefined) so.block = Math.max(0, sb.block + mp.block);
    if (custom.mobility === undefined) so.mobility = sb.mobility;
    if (custom.stamina === undefined) so.stamina = sb.stamina;
    return so;
  }

  if (!arch || !ARMOR_ARCHETYPES_items[arch]) {
    return r.armor && typeof r.armor === "object" ? r.armor : null;
  }

  var base = ARMOR_ARCHETYPES_items[arch];
  var out = Object.assign({}, base, custom);
  out.archetype = arch;
  out.className = custom.className || base.className;
  out.coverage = Array.isArray(custom.coverage)
    ? custom.coverage.slice()
    : coverageForSlot(slot, name, arch);

  if (custom.protection === undefined) {
    out.protection = {};
    Object.keys(base.protection).forEach(function (k) {
      out.protection[k] = Math.max(0, base.protection[k] + mp.protection);
    });
  }
  if (custom.mobility === undefined) out.mobility = base.mobility;
  if (custom.stamina === undefined) out.stamina = base.stamina;
  return out;
}

var WEAPON_BASE_VALUE_items = {
  dagger:25000, sword:100000, greatsword:180000, axe:45000, greataxe:140000,
  mace:65000, warhammer:100000, spear:35000, polearm:90000, bow:70000,
  crossbow:160000, staff:18000, club:12000, fist:0
};

function weaponReferenceBase(name, arch) {
  var n = String(name || "").toLowerCase();
  var base = WEAPON_BASE_VALUE_items[arch] || 0;
  if (arch === "sword") {
    if (/shortsword|short sword/.test(n)) base = 60000;
    else if (/longsword|long sword/.test(n)) base = 145000;
    else if (/rapier/.test(n)) base = 120000;
  }
  if (arch === "axe" && /hand axe|handaxe|hatchet/.test(n)) base = 45000;
  return base;
}

function equipmentReferenceValue(raw) {
  var r = raw || {};
  var name = String(r.name || r.title || "");
  var type = String(r.type || r.kind || "");
  var rawSlot = String(r.slot || r.equipSlot || "backpack");
  var slot = inferLayerSlot(name, type, rawSlot, r);
  var mp = weaponMaterialMods(r, name);
  var materialMult = mp.priceMult || 1;
  var qualityMult = craftsmanshipValueMult(r);
  var conditionMult = conditionValueMult(r);

  var wArch = inferWeaponArchetype(name, type, r);
  if (wArch && wArch !== "fist") {
    return Math.max(1, Math.round(
      weaponReferenceBase(name, wArch) * materialMult * qualityMult * conditionMult
    ));
  }

  var sArch = inferShieldArchetype(name, type, r);
  if (sArch && SHIELD_ARCHETYPES_items[sArch]) {
    return Math.max(1, Math.round(
      SHIELD_ARCHETYPES_items[sArch].baseValue * materialMult * qualityMult * conditionMult
    ));
  }

  var aArch = inferArmorArchetype(name, type, slot, r);
  if (aArch && ARMOR_ARCHETYPES_items[aArch]) {
    var cov = (r.armor && Array.isArray(r.armor.coverage))
      ? r.armor.coverage
      : coverageForSlot(slot, name, aArch);
    var regionMult = 1.0;
    var region = slotRegion(slot);
    if (region === "head") regionMult = 0.55;
    else if (region === "hands") regionMult = 0.30;
    else if (region === "feet") regionMult = 0.35;
    else if (region === "arms") regionMult = 0.50;
    else if (region === "legs") regionMult = 0.60;
    else if (region === "torso") regionMult = 1.00;
    else if (region === "shoulders") regionMult = 0.35;
    else if (region === "waist") regionMult = 0.15;

    return Math.max(1, Math.round(
      ARMOR_ARCHETYPES_items[aArch].baseValue *
      regionMult * coverageScale(cov) *
      materialMult * qualityMult * conditionMult
    ));
  }
  return 0;
}

function defaultPhysicalItemWeight(name,type,slot,raw) {
  var r=raw||{}, n=(String(name||"")+" "+String(type||"")+" "+String(slot||"")).toLowerCase();
  var sp=storageProfileFor(Object.assign({},r,{name:name,type:type,slot:slot}));
  if(sp) return Math.max(0.1,Number(sp.emptyWeight||0.5));

  // Simulation weights where canon supplies no exact mass. Units are the
  // inventory's abstract weight units, approximately pound-like for intuition.
  if(/rope/.test(n)){
    var ft=50, m=String(name||"").match(/(\d+)\s*ft/i); if(m)ft=Math.max(1,Number(m[1]));
    return Math.round((5.0*(ft/50))*10)/10;
  }
  if(/waterskin/.test(n)){
    var c=r.container&&typeof r.container==="object"?r.container:{};
    var current=Number(c.current===undefined?(/full/.test(n)?100:0):c.current);
    var capacity=Math.max(1,Number(c.capacity||100));
    return Math.round((0.35+2.2*Math.max(0,Math.min(1,current/capacity)))*10)/10;
  }
  if(/bottle|flask/.test(n)) return /full|potion|tonic|draught|water/.test(n)?1.1:0.4;
  if(/loaf|bread/.test(n)) return 1.0;
  if(/ration/.test(n)) return 0.8;
  if(/torch/.test(n)) return 1.0;
  if(/bedroll/.test(n)) return 4.0;
  if(/blanket/.test(n)) return 3.0;
  if(/flint|tinder/.test(n)) return 0.3;
  if(/bandage/.test(n)) return 0.2;
  if(/potion|tonic|draught|salve|antidote/.test(n)) return 0.8;
  if(/pickaxe|pick axe/.test(n)) return 5.0;
  if(/hammer/.test(n)) return 2.5;
  if(/shovel|spade/.test(n)) return 4.0;
  if(/lantern/.test(n)) return 2.0;
  if(/book|journal/.test(n)) return 1.0;
  if(/coin pouch|stone pouch/.test(n)) return 0.3;
  return null;
}

function defaultEquipmentWeight(name, type, slot, raw) {
  var r = raw || {};
  var mp = weaponMaterialMods(r, name);
  var wm = mp.weightMult || 1;

  var wArch = inferWeaponArchetype(name, type, r);
  var weaponWeights = {
    dagger:1, sword:3, greatsword:7, axe:3, greataxe:8, mace:4,
    warhammer:5, spear:5, polearm:8, bow:3, crossbow:7, staff:4, club:3
  };
  if (wArch && weaponWeights[wArch]) return Math.max(0.5, weaponWeights[wArch] * wm);

  var sArch = inferShieldArchetype(name, type, r);
  if (sArch && SHIELD_ARCHETYPES_items[sArch])
    return Math.max(0.5, SHIELD_ARCHETYPES_items[sArch].baseWeight * wm);

  var aArch = inferArmorArchetype(name, type, slot, r);
  if (aArch && ARMOR_ARCHETYPES_items[aArch]) {
    var region = slotRegion(slot);
    var rm = region === "torso" ? 1 : region === "legs" ? 0.65 :
      region === "head" ? 0.45 : region === "arms" ? 0.50 :
      region === "hands" ? 0.25 : region === "feet" ? 0.30 :
      region === "shoulders" ? 0.35 : region === "waist" ? 0.20 : 0.5;
    return Math.max(0.5, ARMOR_ARCHETYPES_items[aArch].baseWeight * rm * wm);
  }
  return null;
}

function defaultEquipmentDurability(name, type, slot, raw) {
  var r = raw || {};
  var mp = weaponMaterialMods(r, name);
  var dm = mp.durabilityMult || 1;

  var wArch = inferWeaponArchetype(name, type, r);
  var wd = {
    dagger:70, sword:90, greatsword:105, axe:95, greataxe:115, mace:110,
    warhammer:120, spear:80, polearm:100, bow:65, crossbow:90, staff:60, club:55
  };
  if (wArch && wd[wArch]) return Math.round(wd[wArch] * dm);

  var sArch = inferShieldArchetype(name, type, r);
  if (sArch && SHIELD_ARCHETYPES_items[sArch])
    return Math.round(SHIELD_ARCHETYPES_items[sArch].baseDurability * dm);

  var aArch = inferArmorArchetype(name, type, slot, r);
  if (aArch && ARMOR_ARCHETYPES_items[aArch])
    return Math.round(ARMOR_ARCHETYPES_items[aArch].baseDurability * dm);

  return null;
}

function armorGameplayProfile(it) {
  if (!it) return null;
  var a = it.armor && typeof it.armor === "object"
    ? it.armor
    : materializeArmorStats(it.name, it.type, it.slot, it);
  if (!a) return null;
  return {
    id:String(it.id || ""),
    name:String(it.name || "armor"),
    archetype:String(a.archetype || ""),
    className:String(a.className || a.archetype || "Armor"),
    shieldType:String(a.shieldType || ""),
    coverage:Array.isArray(a.coverage) ? a.coverage.slice() : [],
    protection:a.protection && typeof a.protection === "object"
      ? Object.assign({}, a.protection) : {},
    block:Number(a.block || 0),
    mobility:Number(a.mobility || 0),
    stamina:Number(a.stamina || 0),
    material:String(it.material || ""),
    weight:Number(it.weight || 0),
    durability:it.durability !== undefined ? Number(it.durability) : null,
    maxDurability:it.maxDurability !== undefined ? Number(it.maxDurability) : null,
  };
}


var ECONOMY_BASELINES_items = {
  // These are simulation baselines where canon supplies no exact number.
  // Exact canon prices/fees always override them through canonValue/valueLocked.
  food:       {unit:350,   elasticity:0.55, scarcity:0.85},
  water:      {unit:80,    elasticity:0.35, scarcity:0.55},
  lodging:    {unit:2500,  elasticity:0.45, scarcity:0.70},
  clothing:   {unit:6000,  elasticity:0.40, scarcity:0.55},
  tools:      {unit:12000, elasticity:0.45, scarcity:0.65},
  medicine:   {unit:18000, elasticity:0.70, scarcity:0.95},
  weapons:    {unit:25000, elasticity:0.55, scarcity:0.80},
  armor:      {unit:30000, elasticity:0.55, scarcity:0.80},
  metals:     {unit:10000, elasticity:0.80, scarcity:1.10},
  monster_materials:{unit:15000,elasticity:0.85,scarcity:1.15},
  services:   {unit:5000,  elasticity:0.45, scarcity:0.70},
  transport:  {unit:3000,  elasticity:0.50, scarcity:0.80},
  property:   {unit:250000,elasticity:0.40, scarcity:0.70},
  labor:      {unit:3000,  elasticity:0.55, scarcity:0.80}
};

function economyCategory(raw) {
  var r = raw || {};
  var n = (String(r.name||"")+" "+String(r.type||"")+" "+String(r.description||"")).toLowerCase();
  if (inferWeaponArchetype(r.name,r.type,r)) return "weapons";
  if (inferShieldArchetype(r.name,r.type,r) || inferArmorArchetype(r.name,r.type,r.slot||"",r)) return "armor";
  if (inferMetal(r,r.name)) return "metals";
  if (/ration|bread|meat|fish|fruit|vegetable|meal|food|grain|flour|cheese|stew/.test(n)) return "food";
  if (/water|drink|waterskin refill/.test(n)) return "water";
  if (/inn|room|bed|lodging|night stay/.test(n)) return "lodging";
  if (/shirt|tunic|pants|trouser|cloak|dress|clothing|garment/.test(n)) return "clothing";
  if (/potion|tonic|draught|salve|bandage|antidote|medicine|healing/.test(n)) return "medicine";
  if (/rope|torch|pickaxe|hammer|chisel|tool|bedroll|flint|pack|backpack/.test(n)) return "tools";
  if (/monster|hide|fang|claw|bone|core|byproduct|carapace|venom|organ/.test(n)) return "monster_materials";
  if (/ferry|carriage|wagon|transport|porter|guide/.test(n)) return "transport";
  return String(r.economyCategory||"").toLowerCase() || "tools";
}

function clampEconomy(n, lo, hi) {
  n = Number(n);
  if (!isFinite(n)) n = 1;
  return Math.max(lo, Math.min(hi, n));
}

function marketMultiplier(v, category, district) {
  var mi = obj_shop(v["market-index"]);
  var g = obj_shop(mi.global);
  var gm = clampEconomy(g[category] === undefined ? 1 : g[category], 0.35, 4.0);
  var ds = obj_shop(mi.districts);
  var d = obj_shop(ds[String(district||"").toLowerCase()]);
  var dm = clampEconomy(d[category] === undefined ? 1 : d[category], 0.45, 3.0);
  return gm * dm;
}

function districtTradeMultiplier(location, category) {
  var s = String(location||"").toLowerCase();
  var m = 1;
  // Simulation inference from district role; not a claim of exact canon prices.
  if (/karnon/.test(s)) {
    if (category==="property" || category==="lodging" || category==="services") m *= 1.35;
    if (category==="weapons" || category==="armor") m *= 1.12;
  } else if (/kommelby/.test(s)) {
    if (category==="weapons" || category==="armor" || category==="tools") m *= 0.95;
  } else if (/gnome tree/.test(s)) {
    if (category==="food") m *= 0.82;
    if (category==="transport") m *= 1.08;
  }
  return m;
}

function itemReferenceValue(raw) {
  var r = raw || {};
  if ((r.canonValue===true || r.valueLocked===true) && r.value!==undefined)
    return Math.max(0, Number(r.value)||0);

  var gear = equipmentReferenceValue(r);
  if (gear > 0) return gear;

  var cat = economyCategory(r);
  var b = ECONOMY_BASELINES_items[cat] || ECONOMY_BASELINES_items.tools;
  var q = Math.max(1, Number(r.qty||1));
  var quality = craftsmanshipValueMult(r);
  var condition = conditionValueMult(r);
  var explicit = Math.max(0, Number(r.value||r.price||0));

  // Existing authored price remains a useful baseline for non-equipment.
  var base = explicit > 0 ? explicit : b.unit;
  return Math.max(1, Math.round(base * quality * condition));
}

function economyAsk(v, raw, shop) {
  var r = raw || {};
  var cat = economyCategory(r);
  var ref = itemReferenceValue(r);
  if ((r.canonPrice===true || r.canonValue===true || r.valueLocked===true) && (r.price!==undefined || r.value!==undefined))
    return Math.max(0, Number(r.price!==undefined?r.price:r.value)||0);

  var location = String(v["location"]||"");
  var market = marketMultiplier(v,cat,location);
  var district = districtTradeMultiplier(location,cat);
  var merchant = clampEconomy(Number(shop && shop.priceScale || 1),0.5,2.5);
  return Math.max(1,Math.round(ref*market*district*merchant));
}

function economySellValue(v, raw, venueFactor) {
  var r = raw || {};
  var cat = economyCategory(r);
  var location = String(v["location"]||"");
  var market = marketMultiplier(v,cat,location);
  var district = districtTradeMultiplier(location,cat);
  var liquidity = clampEconomy(venueFactor===undefined?0.45:venueFactor,0.05,1.5);
  return Math.max(0,Math.round(itemReferenceValue(r)*market*district*liquidity));
}

function serviceReferencePrice(kind, opts) {
  var o = opts || {};
  var baseMap = {
    common_labor:3000, skilled_labor:10000, porter:5000, guide:12000,
    mercenary:20000, smith_repair:8000, smith_commission:25000,
    healer:15000, priest:20000, appraiser:300000, storage:2000,
    transport:3000
  };
  var base = baseMap[kind] || 5000;
  var time = Math.max(0.25,Number(o.timeUnits||1));
  var skill = clampEconomy(Number(o.skillMult||1),0.5,10);
  var risk = clampEconomy(Number(o.riskMult||1),0.5,10);
  var materials = Math.max(0,Number(o.materialCost||0));
  return Math.max(1,Math.round(base*time*skill*risk+materials));
}

function propertyReferencePrice(opts) {
  var o = opts || {};
  var base = Math.max(10000,Number(o.base||250000));
  var size = clampEconomy(Number(o.sizeMult||1),0.25,20);
  var quality = clampEconomy(Number(o.qualityMult||1),0.25,10);
  var security = clampEconomy(Number(o.securityMult||1),0.5,5);
  var prestige = clampEconomy(Number(o.prestigeMult||1),0.5,10);
  var supply = clampEconomy(Number(o.marketMult||1),0.4,4);
  return Math.round(base*size*quality*security*prestige*supply);
}

function economyShock(api, v, category, delta, district, cause) {
  var mi = obj_shop(v["market-index"]);
  var next = JSON.parse(JSON.stringify(mi||{}));
  if (!next.global) next.global = {};
  if (!next.districts) next.districts = {};
  var cat = String(category||"tools");
  var d = String(district||"").toLowerCase();
  var amount = Math.max(-0.75,Math.min(2.0,Number(delta)||0));

  if (d) {
    if (!next.districts[d]) next.districts[d] = {};
    var cur = next.districts[d][cat]===undefined?1:Number(next.districts[d][cat]);
    next.districts[d][cat] = Math.round(clampEconomy(cur+amount,0.45,3)*1000)/1000;
  } else {
    var gcur = next.global[cat]===undefined?1:Number(next.global[cat]);
    next.global[cat] = Math.round(clampEconomy(gcur+amount,0.35,4)*1000)/1000;
  }
  api.setVariable("market-index",next);

  var led = arr_shop(v["commodity-ledger"]).slice(-79);
  led.push({
    category:cat,direction:amount>0?"shortage/demand":"surplus/supply",
    magnitude:Math.abs(amount),locality:d||"global",
    cause:String(cause||"economic flow"),day:Number(v["economy-day"]||0)
  });
  api.setVariable("commodity-ledger",led);
}

function meanRevertMarket(api, v) {
  var mi = obj_shop(v["market-index"]);
  var next = JSON.parse(JSON.stringify(mi||{}));
  function revertObj(o) {
    Object.keys(o||{}).forEach(function(k) {
      if (typeof o[k]==="number") o[k] = Math.round((1+(o[k]-1)*0.92)*1000)/1000;
    });
  }
  revertObj(next.global||{});
  Object.keys(next.districts||{}).forEach(function(k){revertObj(next.districts[k]);});
  next.updatedDay = Number(v["economy-day"]||0);
  api.setVariable("market-index",next);
}

function shopEquipmentAsk(raw, shop) {
  var derived = equipmentReferenceValue(raw);
  if (derived <= 0) return Math.max(0, num_shop(raw && raw.price, 0));
  var scale = num_shop(shop && shop.priceScale, 1);
  if (scale < 0.5) scale = 0.5;
  if (scale > 2.5) scale = 2.5;
  return Math.max(1, Math.round(derived * scale));
}


