function ledgerKey(no) { return "n" + Math.floor(num_items(no, 0)); }

// Read a number's record from either half of the ledger. `discovered` wins:
// it is the live record, `known` is the canon baseline.
function ledgerEntry(ledger, no) {
  if (!validNumber(no)) return null;
  var L = obj_items(ledger);
  var k = ledgerKey(no);
  var d = obj_items(L.discovered)[k];
  var c = LEDGER_KNOWN[k]; // static canon baseline — never part of the live variable
  if (d) return Object.assign({}, c || {}, d);
  return c || null;
}

// Who the world believes is holding it. null = unrecorded / loose.
function ledgerHolder(ledger, no) {
  var e = ledgerEntry(ledger, no);
  if (!e) return null;
  var h = e.holder !== undefined ? e.holder : e.holderRecord;
  return h === undefined || h === null || h === "" ? null : String(h);
}

function isPlayerHolder(h, who) {
  if (!h) return false;
  var a = String(h).toLowerCase();
  var b = String(who || "").toLowerCase();
  return a === "player" || a === "the player" || (b && a === b) ||
    (b && a.indexOf(b) >= 0);
}

// Classify a claimed number against the ledger. This is the gate everything
// else asks before treating a Numbered Item as real.
//   "invalid"   — outside the namespace, or unparseable. Never legitimate.
//   "free"      — no record anywhere. A legitimate discovery may claim it.
//   "held"      — the ledger already records the holder as the player. Fine.
//   "conflict"  — the ledger records SOMEONE ELSE physically holding it.
function claimStatus(ledger, no, who) {
  if (!validNumber(no)) return "invalid";
  var e = ledgerEntry(ledger, no);
  if (!e) return "free";
  var h = ledgerHolder(ledger, no);
  if (h === null) return "free";
  return isPlayerHolder(h, who) ? "held" : "conflict";
}

// Record a transfer. Returns a NEW ledger. Writes into `discovered` so the
// canon `known` baseline is preserved underneath and never overwritten.
function ledgerTransfer(ledger, no, holder, patch) {
  if (!validNumber(no)) return obj_items(ledger);
  var L = obj_items(ledger);
  var k = ledgerKey(no);
  var prev = ledgerEntry(L, no) || {};
  var rec = Object.assign({}, prev, obj_items(patch), {
    number: Math.floor(num_items(no, 0)),
    holder: holder === null || holder === undefined ? null : String(holder),
  });
  if (!rec.name) rec.name = obj_items(patch).name || "unidentified Numbered Item";
  var discovered = Object.assign({}, obj_items(L.discovered));
  discovered[k] = rec;
  return Object.assign({}, L, { discovered: discovered });
}

// Reconcile what the player is carrying against what the world records.
// Deterministic and non-destructive: it never deletes loot, it quarantines
// contested rows and reports them so the GM can settle it.
//
// Returns { items, duplicates, conflicts, invalid, changed }
function reconcileNumbered(held, ledger, who) {
  var seen = {};
  var items = [];
  var duplicates = [];
  var conflicts = [];
  var invalid = [];
  var changed = false;

  arr_items(held).forEach(function (raw, i) {
    var x = obj_items(raw);
    var no = x.no !== undefined ? x.no : x.number;

    if (!validNumber(no)) {
      invalid.push(x.name || "unnamed");
      items.push(Object.assign({}, x, { disputed: "unnumbered" }));
      if (x.disputed !== "unnumbered") changed = true;
      return;
    }

    var n = Math.floor(num_items(no, 0));
    var k = ledgerKey(n);

    // The same physical number cannot be in your pockets twice.
    if (seen[k]) {
      duplicates.push(n);
      changed = true;
      return;
    }
    seen[k] = true;

    var status = claimStatus(ledger, n, who);
    var entry = ledgerEntry(ledger, n);
    var next = Object.assign({}, x, { no: n });

    // Canon name wins over whatever the narration called it in the moment.
    if (entry && entry.name && !x.name) next.name = entry.name;

    if (status === "conflict") {
      next.disputed = "held-elsewhere";
      next.disputedBy = ledgerHolder(ledger, n);
      next.equipped = false;                     // contested kit cannot be worn
      conflicts.push({ no: n, name: next.name, holder: next.disputedBy });
      if (x.disputed !== "held-elsewhere") changed = true;
    } else if (x.disputed) {
      delete next.disputed;
      delete next.disputedBy;
      changed = true;
    }

    items.push(next);
  });

  // One talisman at a time, enforced on read as well as on click.
  var wornTalisman = false;
  items = items.map(function (x) {
    if (x.equipped && x.slot === "talisman") {
      if (wornTalisman) { changed = true; return Object.assign({}, x, { equipped: false }); }
      wornTalisman = true;
    }
    return x;
  });

  return {
    items: items,
    duplicates: duplicates,
    conflicts: conflicts,
    invalid: invalid,
    changed: changed,
  };
}

