function guildLooksMonsterRelated(n){
  var s=guildText([n.kind,n.category,n.title,n.detail,n.cause,n.targetType,n.targetSpecies,n.species].filter(Boolean).join(" "));
  return s.indexOf("monster")>=0||s.indexOf("ghoul")>=0||s.indexOf("goblin")>=0||s.indexOf("orc")>=0||s.indexOf("troll")>=0||s.indexOf("blade wolf")>=0||s.indexOf("mana stone")>=0;
}
function guildIncidentAllows(n,incidents){
  var species=guildText(n.targetSpecies||n.species||n.title||n.detail),loc=guildText(n.locality||n.location||n.district||n.title||n.detail);
  return (Array.isArray(incidents)?incidents:[]).some(function(x){
    if(!x||String(x.status||"active")!=="active"||!String(x.cause||"").trim())return false;
    var xs=guildText(x.species),xl=guildText(x.location);
