// ==== vault.tsx =================================================
// Alminus Bank. The only place in this city where money is genuinely out of
// reach of whatever happens to the body carrying it. A purse can be cut off a
// corpse on floor three; a vault balance cannot.
//
// Two account shapes, both canon, and the choice between them is a real one:
// a REGISTERED account is filed under a name and can be willed to an heir —
// and is also a record with that name on it. An UNREGISTERED box needs only a
// password and no identity at all, which is exactly why it is deniable and
// exactly why losing the password loses the money.

function num_vault(v, d) { return typeof v === "number" && isFinite(v) ? v : d; }
function obj_vault(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }

// ==== fence ================================================================
// Optional. Selling gear already works by walking into a shop and arguing, and
// that path is untouched. This screen exists for the one case prose handles
// badly: a piece taken off a person, where the question is not "what is it
// worth" but "who is willing to not ask." It quotes each venue, states plainly
// what each one costs you in questions, and then hands off to the SAME haggle
// machinery a merchant uses — it never settles a sale itself.
function f_num(v, d) { return typeof v === "number" && isFinite(v) ? v : d; }
function f_obj(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }
function f_arr(v) { return Array.isArray(v) ? v : []; }

var FENCE_VENUES = [
  {
    id: "smithy",
    label: "SMITHY",
    who: "the smith",
    place: "Kommelby smithy",
    where: ["kommelby", "smith", "ravigion"],
