    aggression:n(0),caution:n(3),discipline:n(6),altruism:n(9),
    independence:n(12),frugality:n(15),ambition:n(18),loyalty:n(21),
    sociability:n(2),patience:n(5),honesty:n(8),curiosity:n(11)
