  if(/merchant|shop|trader|clerk/.test(r)){p.patience=Math.max(50,p.patience);p.frugality=Math.max(45,p.frugality);}
  if(/guard|soldier|explorer|fighter/.test(r)){p.discipline=Math.max(50,p.discipline);}
  if(/priest|healer|medic/.test(r)){p.altruism=Math.max(60,p.altruism);}
  return p;
}
