  var rp=partyRankPower(rank);
  function stat(shift,base){return Math.max(1,base+((seed>>>shift)%9)-4);}
  var martial=/explorer|fighter|guard|soldier|mercenary|hunter|warrior|barbar|knight/.test(String(role||"").toLowerCase());
  var social=/merchant|clerk|broker|innkeeper|noble|official/.test(String(role||"").toLowerCase());
  return {
    strength:stat(0,martial?10+rp:7),flexibility:stat(4,martial?10:8),
    vision:stat(8,9),smell:stat(12,7),accuracy:stat(16,martial?10+Math.floor(rp/2):7),
    spirit:Math.max(0,stat(20,/mage|wizard|priest|healer|caster/.test(String(role||"").toLowerCase())?10+rp:4)),
    socialPresence:stat(24,social?11:7)
