  if(/explorer|fighter|mercenary|hunter/.test(role))goals.push({id:"survive-and-improve",kind:"survival",title:"Survive and improve their prospects",priority:70,status:"active",progress:0});
  if(Number(p.ambition||0)>=60)goals.push({id:"advance",kind:"ambition",title:"Improve status, wealth, or capability",priority:55+Number(p.ambition||0)*.25,status:"active",progress:0});
