  var items = normalizeList(v["inventory"]);
  var numbered = arr_panel(v["numbered-items"]);
  var ledger = obj_panel(v["numbered-item-ledger"]);

  // --- migration --------------------------------------------------------
  // Old saves hold rows with no id, `desc` instead of `description`, or an
  // equipped flag on a backpack good. Stamp permanent ids on them ONCE and
  // write the canonical shape back. Deterministic, and it never drops an item.
  React.useEffect(function () {
    var raw = arr_panel(v["inventory"]);
    if (!raw.length) return;
    if (!needsMigration(raw)) return;
    api.setVariable("inventory", migrateInventory(raw).list);
  }, [v["inventory"]]);

  // --- numbered item reconciliation ------------------------------------
  // The ledger is authoritative about who physically holds a number. If the
  // pack claims a number the ledger records elsewhere, the row is flagged
  // disputed and un-equipped rather than deleted — the GM settles it in
  // fiction. A number carried twice is impossible and the copy is dropped.
  React.useEffect(function () {
    var held = arr_panel(v["numbered-items"]);
    if (!held.length) return;
    var r = reconcileNumbered(held, ledger, v["char-name"]);
    if (!r.changed) return;
    api.setVariable("numbered-items", r.items);
    var notes = [];
    if (r.duplicates.length) {
      notes.push("Duplicate Numbered Item numbers were carried and the copies removed: " +
        r.duplicates.join(", ") + ". Only one physical instance of a number exists.");
    }
    if (r.conflicts.length) {
      notes.push(r.conflicts.map(function (c) {
        return "No. " + c.no + " (" + c.name + ") is recorded as held by " +
          (c.holder || "someone else") + ", not the player";
      }).join("; ") + ". Treat the player's as unverified — a forgery, a mistake, " +
        "or a transfer the record has not caught up with. Resolve it in fiction; " +
        "do not simply let two exist.");
    }
    if (r.invalid.length) {
      notes.push("Carried as a Numbered Item without a valid 1-10000 number: " +
        r.invalid.join(", ") + ". It is not one.");
    }
    if (notes.length) api.injectContext("[UI/LEDGER] " + notes.join(" "));
  }, [v["numbered-items"], v["numbered-item-ledger"]]);
  var ess = arr_panel(v["essences"]);
  var cap = num_panel(v["essence-capacity"], 3);
  var weight = ess.reduce(function (a, e) { return a + num_panel(e.weight, 1); }, 0);
  var lvl = num_panel(v["level"], 0);
  var ach = num_panel(v["achievements"], 0);
  var nextT = THRESH[lvl] || null;
  var cond = num_panel(v["condition"], 100);
  var stones = num_panel(v["mana-stones"], 0);
  var hurt = arr_panel(v["injuries"]);
  var know = obj_panel(v["knowledge"]);

  // --- real state mutation ---------------------------------------------
  // Equipping is a physical act. Write the array, then tell the GM it
  // happened so narration and state never disagree.
  function commit(next, note) {
    api.setVariable("inventory", next);
    if (note) api.injectContext(note);
  }

  // Equip/unequip is a FLAG REWRITE on the one existing object — it never
  // concats, so no path here can produce a second copy. setEquipped() owns the
  // one-per-slot rule (accessories take two, oldest yields).
  function toggleEquip(id) {
    var it = byId(items, id);
    if (!it || !it.slot || it.slot === "backpack") return;
    var wasOn = it.equipped === true;
    commit(
      setEquipped(items, id, !wasOn),
      wasOn
        ? "[UI] The player removed their " + it.name + "."
        : "[UI] The player equipped their " + it.name + " in " +
          it.slot + "."
