    // equipped item comes off the body as it leaves the pack; removeItem drops
    // the object entirely, so no ghost equipped copy can survive it.
    var dropped=Object.assign({},it,{qty:1,equipped:false,placement:{kind:"world",location:String(v["location"]||"unknown")}});
    api.setVariable("ground-items",arr_panel(v["ground-items"]).concat([dropped]).slice(-120));
    commit(removeItem(items,id,1),
      "[UI PHYSICAL ACTION — ALREADY APPLIED] The player dropped one "+it.name+" at "+String(v["location"]||"the current location")+
      ". The exact object is now in ground-items and no longer follows the player.");
