var ARMOR_COVERAGE = {
  head: ["head"], shoulders: ["shoulders"], torso: ["torso"], arms: ["arms"], hands: ["hands"],
  legs: ["legs"], feet: ["feet"], waist: [],
};

// What a shop at a given tier may roll. Tier 1 is a scavenger's table, tier 3
// is the best armorer in Kommelby. Masterwork and exceptional work, and every
// metal above Moonstone, are not on any shelf.
function armorMetalsFor(tierCap) {
  return tierCap >= 3 ? [["iron", 9], ["moonstone", 1]] : [["iron", 1]];
}
function armorQualitiesFor(tierCap) {
  if (tierCap >= 3) return [["standard", 4], ["fine", 4], ["superior", 2]];
  if (tierCap === 2) return [["crude", 1], ["standard", 6], ["fine", 3]];
  return [["crude", 3], ["standard", 7]];
}
function armorPick(rng, weighted) {
  var total = weighted.reduce(function (t, w) { return t + w[1]; }, 0);
  var r = rng() * total;
  for (var i = 0; i < weighted.length; i++) {
    r -= weighted[i][1];
    if (r < 0) return weighted[i][0];
  }
  return weighted[weighted.length - 1][0];
}

// A finished, priced piece of armor as a shop line.
function buildArmorPiece(form, metalId, quality, cond, rng) {
  var mName = "";
  if (form.metal) {
    mName = metalId === "iron" ? (form.iron || "Iron") : METAL_PROFILES_items[metalId].name;
  }
  var base = form.name.indexOf("{m}") >= 0 ? form.name.replace("{m}", mName) : form.name;
  var q = quality === "crude" ? "Crude " : quality === "fine" ? "Fine " : quality === "superior" ? "Superior " : "";
  var name = q + base;
  var isShield = form.type === "shield";
  var armor = isShield ? { shieldType: form.shield, construction: form.build } : { archetype: form.arch, construction: form.build };
  var cov = ARMOR_COVERAGE[form.slot];
  if (!isShield && cov) armor.coverage = cov.slice();
  var probe = {
    name: name, type: isShield ? "shield" : "armour", slot: form.slot, quality: quality, condition: cond,
    material: form.metal ? metalId : "", armor: armor,
  };
  var price = form.anchor
    ? form.anchor * (form.metal ? (weaponMaterialMods(probe, name).priceMult || 1) : 1) *
      craftsmanshipValueMult(probe) * conditionValueMult(probe)
    : equipmentReferenceValue(probe);
  price = Math.max(1, Math.round(price * (0.9 + rng() * 0.2)));
  var out = {
    name: name, type: probe.type, slot: form.slot, price: price, qty: 1, condition: cond, quality: quality,
    description: form.desc + " Built as " + form.build + ".", armor: armor,
  };
  if (form.metal) out.material = metalId;
  return out;
}

// One piece for a given district cap, optionally from a given slot.
function genArmorPiece(rng, tierCap, condPool, slot, usedIds) {
  var pool = ARMOR_FORMS.filter(function (f) {
    return f.tier <= tierCap && (!slot || f.slot === slot) && !(usedIds && usedIds[f.id]);
  });
  if (!pool.length) return null;
  var form = pool[Math.floor(rng() * pool.length)];
  if (usedIds) usedIds[form.id] = true;
  var metalId = form.metal ? armorPick(rng, armorMetalsFor(tierCap)) : "";
  var quality = armorPick(rng, armorQualitiesFor(tierCap));
  var cond = condPool[Math.floor(rng() * condPool.length)];
  return buildArmorPiece(form, metalId, quality, cond, rng);
}

