// District → which shop types exist there at all, and how good the stock gets.
// Karnon, Bifron and Kiarbis carry nothing deterministic — a commoner has no
// legitimate shop in the first, the second is prohibited, the third is
// residential. Left entirely to the GM if a scene ever needs one there.
var SHOP_DISTRICTS = [
  { match: "kommelby", types: ["weaponsmith", "armorer", "apothecary", "provisioner"], tierCap: 3, condPool: ["new", "sound", "used"] },
  { match: "ravigion", types: ["scavenger-stall"], tierCap: 1, condPool: ["used", "worn", "battered"] },
  { match: "gnome tree", types: ["provisioner", "apothecary"], tierCap: 2, condPool: ["sound", "used"] },
];

function shpDistrictFor(locationStr) {
  var s = String(locationStr || "").toLowerCase();
  for (var i = 0; i < SHOP_DISTRICTS.length; i++) {
    if (s.indexOf(SHOP_DISTRICTS[i].match) >= 0) return SHOP_DISTRICTS[i];
  }
  return null;
}

function shpRng(seed) {
  var s = (seed >>> 0) || 1;
  return function () {
    s ^= s << 13; s >>>= 0;
    s ^= s >> 17;
    s ^= s << 5; s >>>= 0;
    return s / 4294967296;
  };
}
function shpHash(str) {
  var h = 2166136261;
  for (var i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = (h * 16777619) >>> 0; }
  return h;
}

// A scavenger-stall carries a bit of everything at tier 1 only — that IS its
// identity, not a fallback. Every other type sticks to its own category.
function shpPool(shopType, tierCap) {
  if (shopType === "scavenger-stall") {
    return SHOP_CATALOG.filter(function (x) { return x.tier <= 1; });
  }
  return SHOP_CATALOG.filter(function (x) { return x.cat === shopType && x.tier <= tierCap; });
}

function shpResolve(shopType, district, seedStr) {
  var rng = shpRng(shpHash(seedStr));
  var count = 4 + Math.floor(rng() * 4); // 4-7 distinct lines
  var usedForms = {};

  // Armor is built, not listed: a slot, a form for it, a metal, a
  // craftsmanship and a condition, all capped by what this shop can make.
  function armorLines(n, cap) {
    var slots = ["torso", "head", "legs", "feet", "hands", "off-hand", "arms", "shoulders", "waist"];
    var start = Math.floor(rng() * slots.length);
    var out = [];
    for (var a = 0; a < 40 && out.length < n; a++) {
      var slot = a < slots.length ? slots[(start + a) % slots.length] : null;
      var line = genArmorPiece(rng, cap, district.condPool, slot, usedForms) ||
        genArmorPiece(rng, cap, district.condPool, null, usedForms);
      if (line) out.push(line);
    }
    return out;
  }
  if (shopType === "armorer") return armorLines(count, district.tierCap);

  var nArmor = shopType === "scavenger-stall" ? 1 + Math.floor(rng() * 2) : 0;
  var pool = shpPool(shopType, district.tierCap);
  if (!pool.length && !nArmor) return [];
  var want = Math.max(0, count - nArmor);
  var picked = [];
  var used = {};
  var tries = 0;
  while (pool.length && picked.length < Math.min(want, pool.length) && tries < 60) {
    tries++;
    var x = pool[Math.floor(rng() * pool.length)];
    if (used[x.id]) continue;
    used[x.id] = true;
    var variance = 0.85 + rng() * 0.3; // ±15%
    var price = Math.max(1, Math.round(x.price * variance));
    var qty = x.stack ? 2 + Math.floor(rng() * 4) : 1;
    var cond = district.condPool[Math.floor(rng() * district.condPool.length)];
    picked.push({
      name: x.name, type: x.type, slot: x.slot, price: price, qty: qty,
      description: x.desc, condition: cond,
    });
  }
  return picked.concat(armorLines(nArmor, 1));
}

// Silent, mounted always. Closes a haggle the moment the merchant actually
// settles. The GM argues; the interface is what moves stones and goods, so a
// deal struck in prose can never quietly mint an item or skip a payment.
function HaggleWatch() {
  var api = useYumina();
  var v = api.variables || {};
  var shop = obj_shop(v["shop-state"]);
  var hag = obj_shop(shop.haggling);
  var res = obj_shop(shop["haggle-result"]);
  var sig = String(hag.active) + "|" + String(res.outcome || "") + "|" +
    String(res.price === undefined ? "" : res.price);

  React.useEffect(function () {
    var s = obj_shop(v["shop-state"]);
    var h = obj_shop(s.haggling);
    var r = obj_shop(s["haggle-result"]);
    if (h.active !== true) return;
    if (!r.outcome) return;

    var stones = Math.max(0, num_shop(v["mana-stones"], 0));
    var bag = normalizeList(v["inventory"]);
    var stock = arr_shop(s.items);
    var who = s.merchantName || "the merchant";

    // COUNTERED — the merchant met them partway. This is NOT a settlement:
    // the shop stays shut, the scene stays live, and their number sits on the
    // table until the player answers it. Only the standing offer is recorded.
    if (r.outcome === "countered") {
      var offered = num_shop(r.price, -1);
      if (offered < 0) {
        // A counter with no number is not a counter. Discard it and let the
        // argument continue rather than freezing the scene on a null price.
        api.setVariable("shop-state", Object.assign({}, s, {
          "haggle-result": null,
        }));
        return;
      }
      var round = Math.max(0, Math.floor(num_shop(h.round, 0))) + 1;
      api.setVariable("shop-state", Object.assign({}, s, {
        haggling: Object.assign({}, h, { offer: offered, round: round }),
        "haggle-result": null,
      }));
      api.injectContext(
        "[UI] " + who + " countered at " + offered + " stones for " + h.name +
        " (listed " + num_shop(h.listed, 0) + "). No deal yet and nothing has " +
        "changed hands — the offer is on the table and the counter stays shut. " +
        "Hold the scene at the counter and let the player answer it. Do not " +
        "settle on their behalf.",
        { role: "system" }
      );
      return;
    }

    // Refused, or a price that never resolved to a real number: the argument
    // simply ends. Nothing moves, the counter comes back up, the listed price
    // stands exactly where it stood.
    // An "accepted" with no number means they took whatever was last on the
    // table — fall back to the standing counter-offer before giving up.
    var agreed = num_shop(r.price, -1);
    if (agreed < 0) agreed = num_shop(h.offer, -1);
    if (r.outcome !== "accepted" || agreed < 0) {
      api.setVariable("shop-state", Object.assign({}, s, {
        active: h.returnToShop === true ? true : s.active,
        haggling: { active: false }, "haggle-result": null,
      }));
      api.injectContext(
        "[UI] Haggle over " + h.name + " ended with no deal. Nothing changed hands. " +
        "The listed price stands and the counter is open again.",
        { role: "system" }
      );
      return;
    }

    if (h.mode === "BUY") {
      var i = num_shop(h.ref, -1);
      var live = stock[i];
      // The crate may have been rewritten mid-argument. Never decrement a row
      // that is no longer the thing being argued over.
      if (!live || live.name !== h.name) {
        api.setVariable("shop-state", Object.assign({}, s, {
          active: h.returnToShop === true ? true : s.active,
          haggling: { active: false }, "haggle-result": null,
        }));
        return;
      }
      if (agreed > stones) {
        // Agreeing to a price is not the same as having it.
        api.setVariable("shop-state", Object.assign({}, s, {
          active: h.returnToShop === true ? true : s.active,
          haggling: { active: false }, "haggle-result": null,
        }));
        api.injectContext(
          "[UI] " + who + " agreed to " + agreed + " stones for " + h.name +
          " and the player cannot cover it — they hold " + stones + ". " +
          "The deal collapses at the counter over money that is not there. " +
          "Nothing changed hands.",
          { role: "system" }
        );
        return;
      }

      var qty = Math.max(0, Math.floor(num_shop(live.qty, 1)));
      var nextStock = stock
        .map(function (x, j) {
          if (j !== i) return x;
          return Object.assign({}, x, { qty: qty - 1 });
        })
        .filter(function (x) { return num_shop(x.qty, 1) > 0; });

      var bought = normalizeItem({
        id: makeId("buy"),
        name: live.name,
        type: live.type || "misc",
        slot: live.slot || "backpack",
        description: live.description || live.desc || "",
        value: agreed,
        qty: 1,
        equipped: false,
        durability: live.durability,
        weight: live.weight,
        condition: live.condition,
        tags: live.tags,
      }, 0);

      api.setVariable("mana-stones", Math.max(0, stones - agreed));
      api.setVariable("inventory", addItem(bag, bought));
      api.setVariable("shop-state", Object.assign({}, s, {
        items: nextStock, haggling: { active: false }, "haggle-result": null,
      }));
      api.injectContext(
        "[UI] DEAL DONE. The player bought " + live.name + " from " + who +
        " for the haggled price of " + agreed + " stones (listed " +
        num_shop(h.listed, 0) + "). Stones remaining: " +
        Math.max(0, stones - agreed) + ". The item is in their pack and the " +
        "payment is already made — narrate only the handover, state no totals, " +
        "and do not move any stones yourself.",
        { role: "system" }
      );
      return;
    }

    // SELL — identity-addressed, re-checked at the moment the deal lands.
    var idx = indexOfId(bag, String(h.ref));
    if (idx < 0) {
      api.setVariable("shop-state", Object.assign({}, s, {
        active: h.returnToShop === true ? true : s.active,
        haggling: { active: false }, "haggle-result": null,
      }));
      return;
    }
    var sold = bag[idx];
    if (!isSellable(sold)) {
      api.setVariable("shop-state", Object.assign({}, s, {
        active: h.returnToShop === true ? true : s.active,
        haggling: { active: false }, "haggle-result": null,
      }));
