          addable.push({ source: name, rank: rank || "?", weight: wC, abilities: [] });
          usedC += wC;
        }
      }
      if (addable.length) {
        api.setVariable("essences", eList.concat(addable));
        cnote.push(addable.length + " essence" + (addable.length === 1 ? "" : "s") +
          " dropped and absorbed at index " + addedIdxC.join(", ") +
          (rank ? " — rank " + rank + "." : ".") +
          (guardian ? " Guardian essence: carries every active skill the source has, all at once, stats ~1.5x an ordinary essence." : "") +
          " AUTHOR ITS ABILITIES NOW, this same turn: [essences." + addedIdxC[0] +
          ": merge {\"abilities\":[\"(P) ...\",\"(A) ...\"],\"statBoost\":\"...\",\"statMods\":{\"strength\":0}}] — " +
          "consistent with the source monster's established traits, or generated once and held fixed if " +
          "undocumented. statMods bonuses are live and only count while this row exists — erasing it later " +
          "removes them automatically.");
      }
      if (addable.length < essHits) {
        cnote.push("Another essence dropped but there is no room left in the soul to hold it — " +
          "it presses and slides off, unclaimed.");
      }
    } else if (guardian && altKind === "numbered") {
      cnote.push("The guardian yielded no essence, but a Numbered Item surfaced. Report it and let " +
        "the ledger panel record the number — do not invent a number yourself.");
    } else if (guardian) {
      cnote.push("The guardian dropped a rift stone. No essence.");
    } else {
      cnote.push("No essence. There almost never is.");
    }

    markClaim(ci, claims);
    api.injectContext(cnote.join(" "), { role: "system" });
  }

  // ---- general repair channel ----------------------------------------------
  // kill-log fixes kills. This fixes EVERYTHING ELSE the GM cannot write itself:
  // engine-owned currency, pouches, progress counters, ledgers, property, party.
  // Same principle — the GM files a claim, the engine applies it and reports back.
  var REPAIR_NUM = {
    "mana-stones": 1, "bank-balance": 1, "achievements": 1, "portal-progress": 1,
    "floor-days-left": 1, "criminal-witnesses": 1, "labyrinth-days": 1,
    "labyrinth-entry-day": 1, "soul-power": 1, "essence-capacity": 1, "level": 1,
    "spirit-current": 1, "explorer-rank": 1, "tax-owed": 1, "fame": 1, "suspicion": 1, "human-kills": 1,
  };
  var REPAIR_ARR = {
    "inventory": 1, "vault-items": 1, "properties": 1, "party": 1, "species-killed": 1,
    "essences": 1, "hot-goods": 1, "numbered-items": 1, "injuries": 1, "quest-log": 1,
    "floors-seen": 1, "ground-items": 1, "world-needs": 1, "guild-request-ledger": 1, "monster-loot-ledger": 1,
  };
  var REPAIR_OBJ = {
    "raw-stones": 1, "bank-account": 1, "reputation": 1, "knowledge": 1, "map-knowledge": 1, "monster-drop-catalog": 1,
  };
  var REPAIR_STR = { "home-current": 1, "location": 1, "citizen-status": 1, "char-name": 1 };

  var repairSig = JSON.stringify(arr_oracle(v["repair-log"] || []));

  React.useEffect(function () {
    var reps = arr_oracle(v["repair-log"]);
    var ri = -1;
    for (var i = 0; i < reps.length; i++) {
      if (reps[i] && !reps[i].resolved && reps[i].target) { ri = i; break; }
    }
    if (ri < 0) return;
    resolveRepair(ri, reps);
    // eslint-disable-next-line
  }, [repairSig]);

  function markRepair(ri, reps, note) {
    var next = reps.slice();
    next[ri] = Object.assign({}, reps[ri], { resolved: true }, note ? { note: note } : {});
    api.setVariable("repair-log", next);
  }

  function resolveRepair(ri, reps) {
    var r = reps[ri] || {};
    var target = String(r.target || "").trim();
    var op = String(r.op || "add").trim().toLowerCase();
    var val = r.value;
    var why = String(r.reason || "").trim();
    var done = "";

    if (REPAIR_NUM[target]) {
      var cur = num_oracle(v[target], 0);
      var n = num_oracle(val, 0);
      var out = op === "set" ? n : (op === "subtract" ? cur - n : cur + n);
      if (out < 0) out = 0;
      if (target === "portal-progress" && out > 100) out = 100;
      if ((target === "suspicion" || target === "fame") && out > 100) out = 100;
      if (target === "explorer-rank" && out > 9) out = 9;
      api.setVariable(target, out);
      done = target + ": " + cur + " \u2192 " + out;

    } else if (REPAIR_ARR[target]) {
      var list = arr_oracle(v[target]).slice();
      if (op === "remove") {
        var key = typeof val === "string" ? val : ((val && (val.id || val.name)) || "");
        var kl = String(key).toLowerCase();
        var before = list.length;
        list = list.filter(function (x) {
          if (typeof x === "string") return x.toLowerCase() !== kl;
          return String((x && (x.id || x.name)) || "").toLowerCase() !== kl;
        });
        api.setVariable(target, list);
        var gone = before - list.length;
        done = target + ": removed " + gone + " entr" + (gone === 1 ? "y" : "ies");
      } else if (op === "set" && Array.isArray(val)) {
        api.setVariable(target, val);
        done = target + ": replaced with " + val.length + " entr" + (val.length === 1 ? "y" : "ies");
      } else {
        var items = Array.isArray(val) ? val : [val];
        for (var a = 0; a < items.length; a++) {
          var it = items[a];
          if (it && typeof it === "object") {
            it = Object.assign({}, it);
            if (!it.id) it.id = "repair-" + ri + "-" + a + "-" + Date.now();
          }
          list.push(it);
        }
        api.setVariable(target, list);
        done = target + ": +" + items.length;
      }

    } else if (REPAIR_OBJ[target]) {
      var base = obj_oracle(v[target]);
      if (target === "raw-stones" && val && typeof val === "object" && val.name) {
        var nb = Object.assign({}, base);
        var pv = obj_oracle(nb[val.name]);
        var addQ = Math.max(0, Math.floor(num_oracle(val.qty, 1)));
        nb[val.name] = {
          rank: num_oracle(val.rank, num_oracle(pv.rank, 9)),
          qty: op === "set" ? addQ : num_oracle(pv.qty, 0) + addQ,
        };
        api.setVariable("raw-stones", nb);
        done = "raw-stones." + val.name + " \u2192 " + nb[val.name].qty;
      } else if (val && typeof val === "object") {
        api.setVariable(target, op === "set" ? val : Object.assign({}, base, val));
        done = target + ": merged";
      } else {
        markRepair(ri, reps, "bad value");
        api.injectContext(
          "[UI] Oracle: repair claim on " + target + " needs an object value. Nothing changed.",
          { role: "system" }
        );
        return;
      }

    } else if (REPAIR_STR[target]) {
      api.setVariable(target, String(val == null ? "" : val));
      done = target + " set";

    } else {
      markRepair(ri, reps, "unknown target");
      api.injectContext(
        "[UI] Oracle: repair claim refused \u2014 \"" + target + "\" is not a repairable field. " +
        "Kills go through kill-log. Ordinary AI-writable state (condition, thirst, clock, " +
        "cycle-day, shop-state, current-npc, encounter-state) takes a normal directive instead.",
        { role: "system" }
      );
      return;
    }

    markRepair(ri, reps);
    api.injectContext(
      "[UI] Oracle: repair applied \u2014 " + done + (why ? " (" + why + ")" : "") +
      ". The books are corrected. Acknowledge it as a correction, never narrate it as a new event.",
      { role: "system" }
    );
  }

  function resolve(idx, list) {
    var e = list[idx];
    var name = String(e.name || "").trim();

    if (e.isPerson === true) {
      // A person, not a monster — no essence, no mana stone, no first-kill EXP.
      var lootItems = arr_oracle(e.loot);
      var lootStones = Math.max(0, num_oracle(e.lootStones, 0));
      var eventKey = oraclePersonEventKey(e, idx);
      var prior = oracleLedgerGet(v, eventKey);
      var isKilled = oraclePersonKilled(e);
      var isRobbed = e.robbed === true;
      var pnote = [];

      var transferred = { added: [], skipped: [] };
      var paidStones = 0;

      // Loot is paid at most once for this physical person event. The item-level
      // id guard separately prevents the same physical object from appearing twice.
      if ((isRobbed || isKilled) && prior.loot !== true) {
        transferred = oracleTransferLootOnce(api, v, eventKey, lootItems);
        oracleLedgerSet(api, v, eventKey, { loot: true });
      } else if (isRobbed || isKilled) {
        transferred.skipped = lootItems.slice();
      }

      prior = Object.assign({}, prior, oracleLedgerGet(v, eventKey));
      if ((isRobbed || isKilled) && lootStones > 0 && prior.stones !== true) {
        api.setVariable("mana-stones", num_oracle(v["mana-stones"], 0) + lootStones);
        oracleLedgerSet(api, v, eventKey, { stones: true });
        paidStones = lootStones;
      }

      prior = Object.assign({}, prior, oracleLedgerGet(v, eventKey));
      var countedKill = false;
      if (isKilled && prior.kill !== true) {
        api.setVariable("human-kills", num_oracle(v["human-kills"], 0) + 1);
        oracleLedgerSet(api, v, eventKey, { kill: true });
        countedKill = true;
        pnote.push("[UI] Oracle: \"" + (name || "the explorer") +
          "\" is dead. Human/person kill count +1. No essence, mana stone, achievement, or bestiary credit.");
      } else if (isRobbed && prior.loot !== true) {
        pnote.push("[UI] Oracle: \"" + (name || "the explorer") + "\" was searched and left alive.");
      }

      if (transferred.added.length) {
        pnote.push("Took " + transferred.added.length + " unique item" +
          (transferred.added.length === 1 ? "" : "s") + " off them.");
      }
      if (transferred.skipped.length) {
        pnote.push(transferred.skipped.length + " duplicate/already-owned physical item" +
          (transferred.skipped.length === 1 ? " was" : "s were") + " not copied.");
      }
      if (paidStones > 0) pnote.push("+" + paidStones + " stones lifted off them.");
      if ((isRobbed || isKilled) && !lootItems.length && lootStones <= 0) {
        pnote.push("They had nothing worth taking.");
      }

      // Witness risk applies only once to a living robbery.
      var witnessResolved = e.witnessResolved === true;
      if (isRobbed && !isKilled && !witnessResolved) {
        var wRng = oracleRng((Date.now() ^ (idx * 104729) ^ (name.length * 257)) & 0x7fffffff);
        var sawFace = wRng() < 0.55;
        if (sawFace) {
          api.setVariable("criminal-witnesses", num_oracle(v["criminal-witnesses"], 0) + 1);
          pnote.push("They were left alive and got a clear enough look. This is a loose end now, not a resolved one.");
        } else {
          pnote.push("Left alive, but dazed, turned away, or too rattled to have gotten a good look.");
        }
      }

      var pList = list.slice();
      pList[idx] = Object.assign({}, e, {
        lootEventId: e.lootEventId || eventKey,
        lootResolved: oracleLedgerGet(v, eventKey).loot === true || isRobbed || isKilled,
        witnessResolved: witnessResolved || (isRobbed && !isKilled),
        killCounted: oracleLedgerGet(v, eventKey).kill === true || isKilled,
        resolved: isKilled ? true : false,
      });
      api.setVariable("encounter-state", Object.assign({}, obj_oracle(v["encounter-state"]), {
        enemies: pList,
      }));

      if (pnote.length) api.injectContext(pnote.join(" "), { role: "system" });
      return;
    }

    var guardian = e.guardian === true;
    var rank = ORACLE_RANK.hasOwnProperty(name) ? ORACLE_RANK[name] : null;

    var rng = oracleRng((Date.now() ^ (idx * 7919) ^ (name.length * 131) ^
      (guardian ? 0x5bd1e995 : 0)) & 0x7fffffff);

    var killed = arr_oracle(v["species-killed"]);
    var firstKill = !!(rank !== null && rank > 0 && name && killed.indexOf(name) < 0);
    var talisman = arr_oracle(v["numbered-items"]).some(function (n) { return n && n.no === 9999; });

    var stones = ORACLE_STONES.hasOwnProperty(rank) ? ORACLE_STONES[rank] : ORACLE_STONES[9];
    var exp = firstKill ? (ORACLE_EXP[rank] || 0) : 0;

    var essenceDrop = false, kind = null;

    if (guardian) {
      var g = Math.floor(rng() * 100) + 1;
      var eTop = (talisman && firstKill) ? 38 : 33;
      var iTop = (talisman && firstKill) ? 69 : 66;
      if (g <= eTop) { essenceDrop = true; kind = "essence"; }
      else if (g <= iTop) { kind = "numbered"; }
      else { kind = "riftstone"; }
    } else {
      var n = Math.floor(rng() * 10000) + 1;
      var need = (talisman && firstKill) ? 501 : 1;
      if (n <= need) essenceDrop = true;
    }

    // A corpse pays in mana stones, not currency. They go into the pouch as
    // physical loot keyed by species; only a Guild counter turns them into stones.
    var rawBag = obj_oracle(v["raw-stones"]);
    var rawKey = name || "Unknown";
    var rawPrev = obj_oracle(rawBag[rawKey]);
    var nextRaw = Object.assign({}, rawBag);
    nextRaw[rawKey] = {
      rank: rank || 9,
      qty: num_oracle(rawPrev.qty, 0) + 1,
    };
    api.setVariable("raw-stones", nextRaw);

    if (firstKill) {
      api.setVariable("species-killed", killed.concat([name]));
      if (exp) api.setVariable("achievements", num_oracle(v["achievements"], 0) + exp);
    }

    var note = ["[UI] Oracle: \"" + name + "\"" + (guardian ? " (Rift Guardian)" : "") +
      " is dead. Cut out its mana stone — into the pouch, unprocessed, worth ~" +
      stones + " stones at a Guild counter and nothing at all until then" +
      (exp ? ". First kill of that species (+" + exp + " achievement)" : "") + "."];

    var monsterEventKey=oracleMonsterEventKey(e,idx,name);
    var monsterLootLedger=arr_oracle(v["monster-loot-ledger"]);
    var monsterLootDone=monsterLootLedger.some(function(x){return x&&x.eventKey===monsterEventKey&&x.harvested===true;});
    var byproducts=oracleMonsterByproducts(e,name,monsterEventKey);
    if(!monsterLootDone&&byproducts.length){
      var invBefore=normalizeList(v["inventory"]),owned={};invBefore.forEach(function(x){if(x&&x.id)owned[x.id]=true;});
      var add=byproducts.filter(function(x){return x&&x.id&&!owned[x.id];}),merged=physicalStowNewItems(invBefore.concat(add),add.map(function(x){return x.id;}));
      api.setVariable("inventory",merged);api.setVariable("carry-state",physicalCarryProfile(v,merged));
      api.setVariable("monster-loot-ledger",monsterLootLedger.concat([{eventKey:monsterEventKey,species:name,harvested:true,itemIds:add.map(function(x){return x.id;}),clock:v["clock"]}]).slice(-120));
      if(add.length)note.push("Harvested "+add.length+" physical species/corpse byproduct item"+(add.length===1?"":"s")+". They were stowed only where a real equipped container fit; otherwise they remain loose and count toward carried mass.");
    } else if(monsterLootDone&&byproducts.length){note.push("This corpse's byproducts were already harvested; nothing was duplicated.");}
    if (essenceDrop) {
      var essList = arr_oracle(v["essences"]);
      var cap = num_oracle(v["essence-capacity"], 3);
      var used = essList.reduce(function (a, x) { return a + num_oracle(x.weight, 1); }, 0);
      var w = essenceWeight(rank, guardian);
      if (used + w <= cap) {
        var newIdx = essList.length;
        api.setVariable("essences", essList.concat([{
          source: name, rank: rank || "?", weight: w, abilities: [],
        }]));
        note.push("An essence dropped and was absorbed at index " + newIdx +
          (rank ? " — rank " + rank + "." : ".") +
          (guardian ? " Guardian essence: carries every active skill the source has, all at once, stats ~1.5x an ordinary essence." : "") +
          " AUTHOR ITS ABILITIES NOW, this same turn: [essences." + newIdx +
          ": merge {\"abilities\":[\"(P) ...\",\"(A) ...\"],\"statBoost\":\"...\",\"statMods\":{\"strength\":0}}] — " +
          "consistent with the source monster's established traits, or generated once and held fixed if " +
          "undocumented. statMods bonuses are live and only count while this row exists — erasing it later " +
          "removes them automatically.");
      } else {
        note.push("An essence dropped but there is no room left in the soul to hold it — " +
          "it presses and slides off, unclaimed.");
      }
    } else if (kind === "numbered") {
      var ledger = obj_oracle(v["numbered-item-ledger"]);
      var discovered = obj_oracle(ledger.discovered);
      var picked = null;
      for (var tries = 0; tries < 50 && !picked; tries++) {
        var cand = Math.floor(rng() * 10000) + 1;
        var key = "n" + cand;
        var rec = discovered[key] || LEDGER_KNOWN[key]; // static baseline, not a variable read
        if (rec && rec.holder && rec.holder !== null && rec.holder !== "player") continue;
        picked = { number: cand, key: key, rec: rec };
      }
      if (picked) {
        var existingName = picked.rec && (picked.rec.name);
        var nd = Object.assign({}, discovered);
        nd[picked.key] = Object.assign({}, picked.rec, {
          number: picked.number, holder: "player", location: "player", status: "held",
        });
        api.setVariable("numbered-item-ledger", Object.assign({}, ledger, { discovered: nd }));
        api.setVariable("numbered-items", arr_oracle(v["numbered-items"]).concat([{
          no: picked.number, name: existingName || null, equipped: false,
          soulbound: false, known: !!existingName,
        }]));
        note.push(existingName
          ? "A Numbered Item surfaced: No. " + picked.number + ", " + existingName + "."
          : "A Numbered Item surfaced: No. " + picked.number + ". It has never been catalogued " +
            "— invent a setting-consistent name, effect and origin now, and it is canon from this line on.");
      } else {
        note.push("It should have yielded a Numbered Item, but no free number turned up. " +
          "Treat this as a rift stone instead.");
      }
    } else if (kind === "riftstone") {
      note.push("It dropped a rift stone.");
    } else if (!guardian) {
      note.push("No essence. Any physical byproducts are governed separately by this species/corpse; do not invent a generic bonus drop.");
    }

    var nextList = list.slice();
    nextList[idx] = Object.assign({}, e, { resolved: true });
    api.setVariable("encounter-state", Object.assign({}, obj_oracle(v["encounter-state"]), {
      enemies: nextList,
    }));

    api.injectContext(note.join(" "), { role: "system" });
  }

  return null;
}

// ==== grind ==================================================================
// Retail kill-by-kill play cannot pay a 700,000-stone tax inside a turn-based
// text game, so a stretch of days can be committed at once and resolved here,
// in code, at the real rates. This owns encounter frequency, which species turn
// up, stones, per-kill essence checks, rifts, parties, thirst, wounds, in-floor
// days burned and portal ground covered. It does NOT own what any of it means.

function g_arr(v) { return Array.isArray(v) ? v : []; }
function g_num(v, d) { return typeof v === "number" && isFinite(v) ? v : d; }
function g_obj(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }

function g_rng(seed) {
  var s = (seed >>> 0) || 1;
  return function () {
    s ^= s << 13; s >>>= 0;
    s ^= s >> 17;
    s ^= s << 5; s >>>= 0;
    return s / 4294967296;
  };
}

// Kept deliberately in step with the Oracle's own curve.
var G_STONES = {
  0: 1, 9: 20, 8: 100, 7: 420, 6: 1300, 5: 4200,
  4: 15000, 3: 50000, 2: 210000, 1: 850000,
