// Floors 6+ have no abstracted table. Boats, islands and clan-scale logistics —
// the resolver refuses rather than inventing a grind loop for them.
function poolFor(floor) { return FLOOR_POOL[floor] || null; }

function pickSpecies(pool, rand) {
  var total = 0, i;
  for (i = 0; i < pool.length; i++) total += pool[i].w;
  var r = rand() * total;
  for (i = 0; i < pool.length; i++) {
    r -= pool[i].w;
    if (r <= 0) return pool[i];
  }
  return pool[pool.length - 1];
}

// Intent shapes the day — what makes "grind for stones" and "hunt an essence"
// genuinely different orders rather than reskins of each other.
var INTENTS = {
  stones:  { label: "mana stones",     fights: 1.00, portal: 0.00, party: 0.05, rift: 0.04, risk: 1.00 },
  essence: { label: "an essence",      fights: 1.35, portal: 0.00, party: 0.05, rift: 0.10, risk: 1.25 },
  portal:  { label: "the way down",    fights: 0.55, portal: 1.00, party: 0.08, rift: 0.06, risk: 0.85 },
  plunder: { label: "other explorers", fights: 0.35, portal: 0.00, party: 0.40, rift: 0.03, risk: 1.10 },
  survive: { label: "staying alive",   fights: 0.30, portal: 0.10, party: 0.06, rift: 0.02, risk: 0.55 },
};

// Floor-scaled explorer toughness. Texture only, never a raw rank number —
// the player has no in-world way to know another party's registry rank.
// Shallow floors skew green (Rank 9 barely past registration); deeper floors
// skew hardened; Ranks 1-2 stay vanishingly rare everywhere, matching the
// public registry snapshot (almost nobody sits at the top).
var PARTY_BANDS = [
  { max: 1, w: 70, text: "green, barely past registration, moving like people still new to this" },
  { max: 1, w: 25, text: "competent enough, unremarkable gear, clearly not on their first descent" },
  { max: 1, w: 5,  text: "unusually sharp for how shallow this is — worth being cautious of" },
  { max: 3, w: 45, text: "seasoned, well-kept gear, moves like a party that has lost people before and learned from it" },
  { max: 3, w: 40, text: "green, barely past registration, out of their depth down here" },
  { max: 3, w: 13, text: "hardened, deliberate, the kind of party that picks its fights" },
  { max: 3, w: 2,  text: "frighteningly capable for this floor — the sort that shouldn't need to be here at all" },
  { max: 5, w: 55, text: "hardened, established, clearly clan-backed or long past needing to prove anything" },
  { max: 5, w: 30, text: "competent, cautious, watching {{user}} the same way {{user}} is watching them" },
  { max: 5, w: 12, text: "green and badly out of their depth, a long way from where they should be" },
  { max: 5, w: 3,  text: "apex-tier — the kind of presence that makes the floor itself feel smaller" },
];
function partyToughness(floor, rand) {
  var band = floor <= 1 ? 1 : (floor <= 3 ? 3 : 5);
  var opts2 = PARTY_BANDS.filter(function (b) { return b.max === band; });
  var total = 0, i;
  for (i = 0; i < opts2.length; i++) total += opts2[i].w;
  var r = rand() * total;
  for (i = 0; i < opts2.length; i++) {
    r -= opts2[i].w;
    if (r <= 0) return opts2[i].text;
  }
  return opts2[opts2.length - 1].text;
}

// Whether the player currently READS as worth robbing. Never luck-based —
// plunderers count what they can see: worn armour, a fine weapon, or a
// visibly heavy pouch. Someone who looks poor mostly doesn't draw this,
// unless the other party is just as desperate (handled by the floor skew).
function looksWorthRobbing(opts) {
  var equipVal = 0;
  for (var i = 0; i < opts.inventory.length; i++) {
    var it = opts.inventory[i];
    if (it && it.equipped === true) equipVal += (typeof it.value === "number" ? it.value : 0);
  }
  var rawQty = 0;
  var rawKeys = Object.keys(opts.rawBag || {});
  for (var k = 0; k < rawKeys.length; k++) rawQty += num_oracle2(opts.rawBag[rawKeys[k]] && opts.rawBag[rawKeys[k]].qty, 0);
  return equipVal >= 15000 || opts.walletStones >= 5000 || rawQty >= 15;
}
function num_oracle2(v, d) { return typeof v === "number" ? v : d; }

// Simulated a day at a time so it can stop the instant something demands a
// decision. Everything earned before the stop is kept — an interrupt costs the
// run, never the work.
function resolveRun(opts) {
  var rand = g_rng(opts.seed);
  var pool = opts.pool;
  var cfg = INTENTS[opts.intent] || INTENTS.stones;

  var out = {
    kills: {}, killCount: 0, stones: 0, exp: 0, rawStones: {},
    firstKills: [], newSpecies: [], essences: [],
    riftsSeen: 0, partiesMet: 0, daysSpent: 0, portalGain: 0,
    status: "complete", interrupt: null,
  };

  var killedSet = {};
  for (var k = 0; k < opts.alreadyKilled.length; k++) killedSet[opts.alreadyKilled[k]] = true;

  var condition = opts.condition;
  var thirst = opts.thirst;
  var portal = opts.portal;
  var staminaCur = opts.stamina;
  var spiritCur = opts.spiritCurrent;
  var spiritMax = Math.max(1, opts.spiritMax || 10);

  for (var day = 0; day < opts.days; day++) {
    if (opts.daysLeft - out.daysSpent <= 0) {
      out.status = "aborted";
      out.interrupt = {
        kind: "deadline", what: "the floor is closing",
        detail: "There are no days left on this floor. It is emptying whether or not anyone is finished.",
      };
      break;
    }

    out.daysSpent++;

    var density = 3 + Math.floor(opts.floor * 1.2);
    var encounters = Math.max(0, Math.round((density * cfg.fights) * (0.6 + rand() * 0.8)));

    for (var e = 0; e < encounters; e++) {
      var sp = pickSpecies(pool, rand);

      if (sp.offBand) {
        out.status = "interrupted";
        out.interrupt = {
          kind: "monster", what: sp.name,
          detail: "A " + sp.name + " — rank " + sp.rank + ", far above what this floor is " +
            "supposed to hold. It has not noticed, or it has and does not care.",
        };
        break;
      }

      var first = !killedSet[sp.name];
      var rank = sp.rank;

      out.kills[sp.name] = (out.kills[sp.name] || 0) + 1;
      out.killCount++;
      // Appraisal estimate only. The pouch fills with rock; the Guild decides
      // what the rock is worth when it reaches a counter on the surface.
      out.stones += G_STONES[rank] || G_STONES[9];
      out.rawStones[sp.name] = {
        rank: rank,
        qty: ((out.rawStones[sp.name] && out.rawStones[sp.name].qty) || 0) + 1,
      };

      if (first) {
        killedSet[sp.name] = true;
        out.newSpecies.push(sp.name);
        out.firstKills.push(sp.name);
        out.exp += G_EXP[rank] || 0;
      }

      // The real rate. 0.01% a body, plus Beginner's Luck's flat 5 points on a
      // first kill only. No pity, no scaling for effort, no scene bonus.
      var roll = Math.floor(rand() * 10000) + 1;
      var need = (opts.talisman && first) ? 501 : 1;
      if (roll <= need) {
        out.essences.push({ source: sp.name, rank: rank });
        out.status = "interrupted";
        out.interrupt = {
          kind: "essence", what: sp.name,
          detail: "The corpse does not go the way the others went. A fist-sized orb of light is " +
            "sitting where it fell, and it will be there for thirty minutes and not one minute longer.",
        };
        break;
      }

      condition -= rand() * 4.5 * cfg.risk * (1 + (rank <= 7 ? 0.9 : 0));
      spiritCur = Math.max(0, spiritCur - rand() * 0.6 * cfg.risk);
    }

    if (out.status === "interrupted") break;

    if (cfg.portal > 0) {
      var pBand = PORTAL_GAIN[opts.floor] || [5, 10];
      var pMult = opts.searchMult || 1;
      portal = Math.min(100, portal + (pBand[0] + rand() * (pBand[1] - pBand[0])) * pMult * cfg.portal);
      if (portal >= 100) {
        out.status = "interrupted";
        out.interrupt = {
          kind: "portal", what: "the way down",
          detail: "The portal to the next floor is in front of you. Nothing is stopping you " +
            "walking into it, and nothing is stopping you walking away.",
        };
        break;
      }
    }

    if (rand() < cfg.party) {
      out.partiesMet++;
      out.status = "interrupted";
      var pTough = partyToughness(opts.floor, rand);
      var wantsPlayer = looksWorthRobbing(opts) && rand() < (0.15 + opts.floor * 0.03);
      var pDetail;
      if (opts.intent === "plunder") {
        pDetail = "A party, and they have not seen you yet — " + pTough + ". Count them before you decide anything.";
      } else if (wantsPlayer) {
        pDetail = "Another party on the same trail, " + pTough + ". They have seen what {{user}} is carrying, " +
          "and they have not stopped looking at it.";
      } else {
        pDetail = "Another party on the same trail, " + pTough + ". They have seen {{user}}. Nobody has reached " +
          "for anything yet.";
      }
      out.interrupt = { kind: "party", what: "other explorers", detail: pDetail, sizingUpPlayer: wantsPlayer };
      break;
    }

    if (rand() < cfg.rift) {
      out.riftsSeen++;
      out.status = "interrupted";
      out.interrupt = {
        kind: "rift", what: "a rift",
        detail: "A rift, open, and no one else standing at it. First party to reach one gets " +
          "first crack at the guardian.",
      };
      break;
    }

    thirst -= 9 + rand() * 6;
    staminaCur -= 6 + rand() * 6 * cfg.risk;

    if (thirst <= 20) {
      out.status = "interrupted";
      out.interrupt = {
        kind: "thirst", what: "water",
        detail: "You are far enough into real thirst that it has started making decisions for you.",
      };
      break;
    }
    if (condition <= 35) {
      out.status = "interrupted";
      out.interrupt = {
        kind: "wounded", what: "your condition",
        detail: "Something is wrong enough that continuing is a choice rather than a default.",
      };
      break;
    }
    if (staminaCur <= 15) {
      out.status = "interrupted";
      out.interrupt = {
        kind: "exhausted", what: "your stamina",
        detail: "There is nothing left in the arms or the legs. Whatever happens next, it is not going to be fast.",
      };
      break;
    }
    if (spiritCur <= Math.max(2, spiritMax * 0.15)) {
      out.status = "interrupted";
      out.interrupt = {
        kind: "spent", what: "your spirit",
        detail: "The pool is nearly dry. Whatever comes next is not answered by pulling on the mana anymore.",
      };
      break;
    }
  }

  out.endCondition = Math.max(0, Math.round(condition));
  out.endThirst = Math.max(0, Math.round(thirst));
  out.endPortal = Math.round(portal);
  out.endStamina = Math.max(0, Math.round(staminaCur));
  out.endSpirit = Math.max(0, Math.round(spiritCur));
  return out;
}

// What the GM is handed. Facts only, in the order they happened. No adjectives
// that decide how it felt — that is the narration's job.
function buildNote(run, order) {
  var lines = [];
  lines.push("[UI] Grind resolved — floor " + order.floor + ", hunting " +
    (INTENTS[order.intent] || INTENTS.stones).label + ", " + run.daysSpent + " of " +
    order.days + " in-floor day" + (run.daysSpent === 1 ? "" : "s") + " spent.");

  var names = Object.keys(run.kills);
  if (names.length) {
    var parts = [];
    for (var i = 0; i < names.length; i++) parts.push(names[i] + " x" + run.kills[names[i]]);
    lines.push("Killed: " + parts.join(", ") + " (" + run.killCount + " total).");
  } else {
    lines.push("Killed: nothing. The stretch produced no bodies at all.");
  }

  lines.push("Mana stones cut and pouched — appraisal estimate ~" + run.stones +
    " stones (the currency). NOT money yet: they are mana stones until an " +
    "Explorers' Guild branch on the surface grades and exchanges it, minus their fee. " +
    "Do not narrate the player as having been paid, and do not let anything underground buy it.");
  if (run.firstKills.length) {
    lines.push("First kills: " + run.firstKills.join(", ") + " (+" + run.exp + " achievement).");
  }
  if (!run.essences.length) {
    lines.push("No essence. " + run.killCount + " bodies and not one of them gave anything up.");
  }

  if (run.status === "interrupted" && run.interrupt) {
    lines.push("RUN INTERRUPTED — " + run.interrupt.kind.toUpperCase() + ": " + run.interrupt.detail);
    if (run.interrupt.kind === "essence" && run.essences.length) {
      var es = run.essences[run.essences.length - 1];
      lines.push("The orb is from a " + es.source + " (rank " + es.rank + "). It is on the ground, " +
        "not absorbed. It is theirs only if they take it, and they have thirty minutes.");
    }
    lines.push("Cut to this exact moment in present tense and END THERE, on the decision. Do not " +
      "resolve it. Do not list options. " + (order.days - run.daysSpent) +
      " ordered day(s) remain banked if they choose to resume.");
  } else if (run.status === "aborted") {
    lines.push("RUN ABORTED — " + (run.interrupt ? run.interrupt.detail : "the floor closed."));
  } else {
    lines.push("Run completed as ordered. Narrate the whole stretch as a montage and close on the " +
      "totals. Do not add anything that is not in this note.");
  }

  lines.push("State is already written. Do not re-apply any of it. The haul is mana stones — " +
    "physical loot in a pouch, not money, until an Explorers' Guild counter on the " +
    "surface grades and exchanges it for stones.");
  return lines.join(" ");
}

// Ordering a run is a deliberate act with a cost attached, so it reads like a
// commitment screen and not a vending machine.
function GrindPanel(props) {
  var api = useYumina();
  var v = api.variables || {};
  var floor = g_num(v["current-floor"], 0);
  var daysLeft = g_num(v["floor-days-left"], 0);

  var iS = React.useState("stones");
  var intent = iS[0], setIntent = iS[1];
  var dS = React.useState(3);
  var days = dS[0], setDays = dS[1];

  var pool = poolFor(floor);
  var maxDays = Math.max(1, daysLeft);
  var canRun = floor >= 1 && !!pool && daysLeft > 0;

  function launch() {
    if (!canRun) return;

    var d = Math.max(1, Math.min(days, maxDays));
    var order = { floor: floor, intent: intent, days: d };

    var run = resolveRun({
      seed: (Date.now() ^ (floor * 7919) ^ (d * 131) ^ (intent.length * 31)) & 0x7fffffff,
      floor: floor, intent: intent, days: d, daysLeft: daysLeft, pool: pool,
      alreadyKilled: g_arr(v["species-killed"]),
      talisman: g_arr(v["numbered-items"]).some(function (n) { return n && n.no === 9999; }),
      searchMult: (function () {
        var partyList = g_arr(v["party"]);
        var hasScout = partyList.some(function (m) {
          return m && (m.wayfinding === true || g_arr(m.skills).some(function (s) { return s && s.name === "Navigation"; }));
        });
        var ownSkills = g_arr(v["skills"]);
        if (ownSkills.some(function (s) { return s && s.name === "Navigation"; })) hasScout = true;
        var subs = g_obj(v["substats"]);
        var vision = g_num(subs.vision, 0);
        var race = String(v["race"] || "");
        var keenSense = race === "Beastman" || race === "Elf";
        var mult = 1;
        if (hasScout) mult += 0.4;
        if (keenSense) mult += 0.2;
        if (vision >= 15) mult += 0.15;
        return mult;
      })(),
      condition: g_num(v["condition"], 100),
      thirst: g_num(v["thirst"], 100),
      portal: g_num(v["portal-progress"], 0),
      stamina: g_num(v["stamina"], 100),
      spiritCurrent: g_num(v["spirit-current"], 10),
      spiritMax: g_num(v["spirit"], 10),
      inventory: g_arr(v["inventory"]),
      rawBag: g_obj(v["raw-stones"]),
      walletStones: g_num(v["mana-stones"], 0),
    });

    // Loot is physical. It goes in the pouch, not the purse — the Guild
    // exchange on the surface is the only thing that makes it money.
    var bagRaw = g_obj(v["raw-stones"]);
    var mergedRaw = Object.assign({}, bagRaw);
    var rawKeys = Object.keys(run.rawStones);
    for (var rk = 0; rk < rawKeys.length; rk++) {
      var kName = rawKeys[rk];
      var had = g_obj(mergedRaw[kName]);
      mergedRaw[kName] = {
        rank: run.rawStones[kName].rank,
        qty: g_num(had.qty, 0) + run.rawStones[kName].qty,
      };
    }
    if (rawKeys.length) api.setVariable("raw-stones", mergedRaw);
    if (run.exp) api.setVariable("achievements", g_num(v["achievements"], 0) + run.exp);
    if (run.newSpecies.length) {
      api.setVariable("species-killed", g_arr(v["species-killed"]).concat(run.newSpecies));
    }
    api.setVariable("condition", run.endCondition);
    api.setVariable("thirst", run.endThirst);
    api.setVariable("portal-progress", run.endPortal);
    api.setVariable("stamina", run.endStamina);
    api.setVariable("spirit-current", Math.min(g_num(v["spirit"], 10), run.endSpirit));
    api.setVariable("floor-days-left", Math.max(0, daysLeft - run.daysSpent));
    api.setVariable("labyrinth-days", g_num(v["labyrinth-days"], 0) + run.daysSpent);

    api.setVariable("grind-session", {
      active: run.status === "interrupted",
      floor: floor, intent: intent,
      daysOrdered: d, daysSpent: run.daysSpent,
      daysBanked: Math.max(0, d - run.daysSpent),
      kills: run.kills, stones: run.stones,
      essencesFound: run.essences, firstKills: run.firstKills,
      riftsSeen: run.riftsSeen, partiesMet: run.partiesMet,
      status: run.status, interrupt: run.interrupt,
    });

    api.injectContext(buildNote(run, order), { role: "system" });
    api.sendMessage("[I commit " + d + " day" + (d === 1 ? "" : "s") + " on floor " + floor +
      ", hunting " + (INTENTS[intent] || INTENTS.stones).label + ".]");

    if (props.onClose) props.onClose();
  }

  return (
    React.createElement(Screen, { title: "COMMIT TIME" , onClose: props.onClose,}
      , floor < 1 ? (
        React.createElement(Empty, null, "You are on the surface. There is nothing here to commit days to."            )
      ) : !pool ? (
        React.createElement(Empty, null, "Floor "
           , floor, " does not run on a grind loop. Boats, islands, clan-scale logistics — it has to be played through."

        )
      ) : (
        React.createElement('div', null
          , React.createElement('div', { style: { fontSize: 11, color: C.boneDim, lineHeight: 1.8, marginBottom: 14 },}, "Floor "
             , floor, ". " , daysLeft, " in-floor day"  , daysLeft === 1 ? "" : "s", " left before it empties. Anything that needs a decision stops the run and hands it back to you."

          )

          , React.createElement('div', { style: { fontSize: 10, letterSpacing: "0.14em", color: C.boneDim, marginBottom: 8 },}, "HUNTING FOR"

          )
          , React.createElement('div', { style: { display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 18 },}
            , Object.keys(INTENTS).map(function (key) {
              var on = intent === key;
              return (
                React.createElement('button', {
                  key: key,
                  className: "ds-btn",
                  onClick: function () { setIntent(key); },
                  style: {
                    padding: "8px 12px", borderRadius: 9, cursor: "pointer",
                    fontSize: 11, fontFamily: "inherit",
                    background: on ? "rgba(201,162,39,0.15)" : C.panel,
                    border: "1px solid " + (on ? C.brass : C.rule),
                    color: on ? C.brass : C.boneDim,
                  },}
, INTENTS[key].label)
              );
            })
          )

          , React.createElement('div', { style: { fontSize: 10, letterSpacing: "0.14em", color: C.boneDim, marginBottom: 8 },}, "DAYS — "
              , Math.min(days, maxDays), " OF "  , maxDays, " AVAILABLE"
          )
          , React.createElement('input', {
            type: "range", min: 1, max: maxDays, value: Math.min(days, maxDays),
            onChange: function (ev) { setDays(parseInt(ev.target.value, 10) || 1); },
            style: { width: "100%", accentColor: C.brass, marginBottom: 18 },}
          )

          , React.createElement('button', {
            className: "ds-btn",
            onClick: launch,
            disabled: !canRun,
            style: {
              width: "100%", padding: "13px 0", borderRadius: 10,
              cursor: canRun ? "pointer" : "not-allowed",
              fontSize: 12, letterSpacing: "0.14em", fontFamily: "inherit",
              background: canRun ? "linear-gradient(180deg,#3a2f12 0%,#241c0a 100%)" : C.panel,
              border: "1px solid " + (canRun ? C.brass : C.rule),
              color: canRun ? C.brass : C.boneDim,
            },}

            , daysLeft <= 0 ? "THE FLOOR IS CLOSING" : "GO DOWN AND WORK"
          )

          , React.createElement('div', { style: { fontSize: 10, color: C.boneDim, lineHeight: 1.8, marginTop: 14 },}, "Essence odds are the real ones — 0.01% a body. Most runs give nothing. That is what makes the ones that do worth what they are worth."


          )
        )
      )
    )
  );
}

// ==== home.tsx ==================================================
// Property. Canon is thin here — motels at ~9,000 a night, Kiarbis as an old
// noble resort, Bifron as the place people live because there is nowhere else,
// shops tied to clans. So the market below is generated to obey the grammar
// the world already has: district IS status, and every figure is anchored off
// the 20-stone loaf. Once a number is used it is simulation canon.
//
// This panel owns the arithmetic — rent, purchase, sublet income, business
// takings. The GM owns the door, the landlord, and the neighbours who notice
// a body coming home at odd hours.

function h_num(v, d) { return typeof v === "number" && isFinite(v) ? v : d; }
function h_arr(v) { return Array.isArray(v) ? v : []; }
function h_obj(v) { return v && typeof v === "object" && !Array.isArray(v) ? v : {}; }

var TABS_home = ["PLACES", "BOARD", "TRADE"];

// Status by district, and what it costs to stand there.
var DISTRICT_MULT = {
  "karnon": 2.2,
  "kommelby": 1.8,
  "kiarbis": 1.4,
  "gnome tree": 1.0,
  "ravigion": 0.8,
  "bifron": 0.4,
};

function districtMult(d) {
  var key = String(d || "").toLowerCase();
  var keys = Object.keys(DISTRICT_MULT);
  for (var i = 0; i < keys.length; i++) {
    if (key.indexOf(keys[i]) !== -1) return DISTRICT_MULT[keys[i]];
  }
  return 0.8;
}

// Realistic trades for Rafdonia specifically — the shop types the city
// actually has, not a generic fantasy list.
var TRADES = [
  { id: "variety", label: "VARIETY STORE", takings: 26000, upkeep: 9000, fit: 120000,
    note: "Loot resale, potions, everyday sundries. Steady, unremarkable, always some trade." },
  { id: "boarding", label: "BOARDING HOUSE", takings: 34000, upkeep: 12000, fit: 180000,
    note: "Beds by the night to explorers who have no address. Full on the 1st, empty by the 20th." },
  { id: "pub", label: "PUB", takings: 42000, upkeep: 18000, fit: 260000,
    note: "Drink, lodging, and loot-splitting tables. The best room in the city for hearing things." },
  { id: "workshop", label: "WORKSHOP", takings: 38000, upkeep: 15000, fit: 300000,
    note: "Alchemy or magic-crafting — reagents and sundries. Needs a licence and a real hand." },
  { id: "smithy", label: "SMITHY STALL", takings: 30000, upkeep: 13000, fit: 240000,
    note: "Repairs and cheap arms. The big smithies are clan-affiliated and will notice you." },
  { id: "bakery", label: "BAKERY", takings: 22000, upkeep: 8000, fit: 90000,
    note: "Bread is the unit the whole economy is measured in. Thin margin, never no customers." },
];

function tradeById(id) {
  for (var i = 0; i < TRADES.length; i++) if (TRADES[i].id === id) return TRADES[i];
  return null;
}

// A month's takings for one fitted trade. Staff cost wages and earn their keep;
// an unattended shop still opens, just badly.
function monthTakings(prop, rand) {
  var b = h_obj(prop.business);
  var t = tradeById(b.trade);
  if (!t) return { gross: 0, upkeep: 0, net: 0, staff: 0 };
  var staff = Math.max(0, Math.floor(h_num(b.staff, 0)));
  var swing = 0.75 + rand() * 0.5;
  var gross = t.takings * districtMult(prop.district) * (1 + staff * 0.12) * swing;
  if (staff === 0) gross *= 0.55;
  var upkeep = t.upkeep + staff * 4500;
  return {
    gross: Math.round(gross),
    upkeep: Math.round(upkeep),
    net: Math.round(gross - upkeep),
    staff: staff,
  };
}

