function NarrativeIngestWatch() {
  var api=useYumina();
  var v=api.variables||{};
  var reqs=Array.isArray(v["ingest-requests"])?v["ingest-requests"]:[];
  var sig=JSON.stringify(reqs);

  React.useEffect(function(){
    var current=Array.isArray(v["ingest-requests"])?v["ingest-requests"]:[];
    var ri=-1;
    for(var i=0;i<current.length;i++){
      if(current[i]&&current[i].status==="pending"){ri=i;break;}
    }
    if(ri<0)return;

    var r=current[ri]||{},items=normalizeList(v["inventory"]);
    var id=String(r.itemId||"");
    if(!id&&r.itemName){
      var want=String(r.itemName).toLowerCase();
      var matches=items.filter(function(it){return it&&String(it.name||"").toLowerCase()===want;});
      if(matches.length===1)id=matches[0].id;
      else {
        matches=items.filter(function(it){return it&&String(it.name||"").toLowerCase().indexOf(want)>=0;});
        if(matches.length===1)id=matches[0].id;
      }
    }

    var result=resolveIngestState(v,items,id,String(r.action||""));
    var nextReq=current.slice();
    if(!result.ok){
      nextReq[ri]=Object.assign({},r,{status:"refused",reason:result.reason||"could not resolve"});
      api.setVariable("ingest-requests",nextReq);
      // Only failures need hidden context so narration does not falsely claim success.
      api.injectContext("[INGEST ENGINE] Typed "+String(r.action||"consume")+" could not be applied: "+String(result.reason||"unknown reason")+". Do not narrate successful consumption.",{role:"system"});
      return;
    }

    api.setVariable("inventory",result.items);
    (result.changed||[]).forEach(function(ch){api.setVariable(ch.var,Math.max(0,Math.min(100,Number(ch.value||0))));});
    var ledger=Array.isArray(v["item-use-ledger"])?v["item-use-ledger"]:[];
    api.setVariable("item-use-ledger",ledger.concat([{
      itemId:result.item.id,itemName:result.item.name,
      effects:(result.changed||[]).map(function(ch){return ch.var+" -> "+Math.round(ch.value);}),
      source:"typed "+result.kind,clock:v["clock"]
    }]).slice(-30));
    nextReq[ri]=Object.assign({},r,{status:"resolved",itemId:result.item.id,itemName:result.item.name});
    api.setVariable("ingest-requests",nextReq.slice(-40));
    // Success is silent. The user's own typed action is already the narration.
    // eslint-disable-next-line
  },[sig]);

  return null;
}


function PartyCombatEventWatch(){
  var api=useYumina();
  var v=api.variables||{};
  var sig=JSON.stringify(Array.isArray(v["party-combat-events"])?v["party-combat-events"]:[]);
  React.useEffect(function(){
    var events=Array.isArray(v["party-combat-events"])?v["party-combat-events"]:[];
    var roster=Array.isArray(v["party"])?v["party"]:[];
    var changed=false, nextRoster=roster.map(function(m,i){return normalizePartyCombatMember(m,i);});
    var nextEvents=events.map(function(e,ei){
      if(!e||e.resolved===true)return e;
      var idx=nextRoster.findIndex(function(m){
        if(e.memberId&&String(m.id)===String(e.memberId))return true;
        return e.memberName&&String(m.name||"")===String(e.memberName);
      });
      if(idx<0)return Object.assign({},e,{resolved:true,refused:true,reason:"party member not found"});
      var m=Object.assign({},nextRoster[idx]), c=Object.assign({},m.combat||{});
      var amt=Math.max(0,Number(e.amount)||0), typ=String(e.type||"").toLowerCase();
      if(typ==="damage"){
        c.condition=Math.max(0,(Number(c.condition)||0)-amt);
        if(c.condition<=0)c.status="down";
      }else if(typ==="heal"){
        c.condition=Math.min(Number(c.conditionMax)||100,(Number(c.condition)||0)+amt);
        if(c.condition>0&&String(c.status).toLowerCase()==="down")c.status="ready";
      }else if(typ==="death"){
        c.condition=0;c.status="dead";
      }else if(typ==="status"){
        c.status=String(e.status||c.status||"ready");
      }else if(typ==="recover"){
        c.stamina=Math.min(Number(c.staminaMax)||100,(Number(c.stamina)||0)+amt);
        if(e.manaAmount!=null)c.mana=Math.min(Number(c.manaMax)||0,(Number(c.mana)||0)+Math.max(0,Number(e.manaAmount)||0));
      }else if(typ==="injury"){
        var inj=String(e.injury||e.status||"injury");
        c.injuries=Array.isArray(c.injuries)?c.injuries.slice():[];
        if(inj&&c.injuries.indexOf(inj)<0)c.injuries.push(inj);
        if(amt>0)c.condition=Math.max(0,(Number(c.condition)||0)-amt);
        if(c.condition<=0)c.status="down";
      }
      m.combat=c;nextRoster[idx]=m;changed=true;
      return Object.assign({},e,{resolved:true});
    });
    if(changed)api.setVariable("party",nextRoster);
    if(JSON.stringify(nextEvents)!==JSON.stringify(events))api.setVariable("party-combat-events",nextEvents);
  },[sig]);
  return null;
}


