      var last=Number(ls.lastProcessedOrdinal||0);
      if(last<=0){ls.lastProcessedOrdinal=ordinal-1;m.lifeState=ls;last=ordinal-1;}
      var gap=Math.max(0,ordinal-last);
      // Event-driven LOD: process at most 30 meaningful day slices per catch-up; aggregate older idle span.
      var begin=Math.max(last+1,ordinal-29);
