function mtNum(x,d){ var n=Number(x); return Number.isFinite(n)?n:d; }
function mtClock(raw){
  var n=Math.floor(mtNum(raw,0));
  n=((n%1440)+1440)%1440;
  return {minuteOfDay:n,hour:Math.floor(n/60),minute:n%60};
}

function mtSurface(v){
  var old=v["surface-time"]||{}, lc=mtClock(v["clock"]);
  var year=mtNum(old.year,1), month=mtNum(v["cycle-month"],mtNum(old.month,1)), day=mtNum(v["cycle-day"],mtNum(old.day,1));
  var hour=lc.hour, minute=lc.minute;
  var absoluteMinute=((((year*13)+month)*40+day)*1440)+lc.minuteOfDay;
  return {year:year,month:month,day:day,hour:hour,minute:minute,minuteOfDay:lc.minuteOfDay,absoluteMinute:absoluteMinute,source:"master-timekeeper"};
}

function mtPortal(st){
