  return {state:open?(closing?"CLOSING":"OPEN"):"CLOSED",exists:open,acceptsEntry:open,surfaceYear:st.year,surfaceMonth:st.month,surfaceDay:st.day,surfaceMinuteOfDay:mod,opensAt:"00:00",closesAtApprox:"01:00",closeTimeAuthority:"strong-simulation-inference"};
