// ---- one-time upgrade for characters made before racial tracks ----------
// Runs once per old save. It never touches a character whose racial state
// already exists, so new characters are safe, and it never overwrites a
// choice the player already made: it only reads race + path and builds what
// the newer systems need.
function migrateRacial(race, path) {
  var p = String(path || "").toLowerCase();
  if (race === "Barbarian") {
    return { race: "Barbarian", ceremonyWeapon: /shield/.test(p) ? "shield" : null,
      imprint: { path: null, stage: 0, log: [] }, quenching: { done: false }, succession: { used: false }, swim: false, migrated: true };
  }
  if (race === "Human") {
    var aura = /aura/.test(p);
    return { race: "Human",
      training: /wizard/.test(p) ? "wizard" : /acolyte|priest/.test(p) ? "priest" : /elemental/.test(p) ? "spiritist" : null,
      // Every character made under the old rules gets the talent: they were offered aura as
      // a plain choice. Those who picked "Aura user" already have it awake; the rest still
      // have to find it by trying with a sword.
      aura: { talent: true, revealed: aura, colour: null },
      migrated: true };
  }
  if (race === "Dwarf") {
    return { race: "Dwarf", blessingOfArms: true, trade: /smith/.test(p) ? "smith" : "explorer", migrated: true };
  }
  if (race === "Elf") {
    var el = /fire/.test(p) ? "fire" : /earth/.test(p) ? "earth" : /wind/.test(p) ? "wind" : /water/.test(p) ? "water" : null;
    return { race: "Elf", contracts: el ? [{ spirit: el, tier: "lesser" }] : [], maxHeld: 4, migrated: true };
  }
  if (race === "Beastman") {
    var kind = /summon/.test(p) ? "summon" : /blessing/.test(p) ? "blessing" : /reinforce|empower/.test(p) ? "reinforcement" : null;
    var pickedContract = /contracted/.test(p) && !/uncontracted/.test(p);
    // Every old Beastman is chosen: the old rules let anyone take a contract path. Those who
    // already picked one have it revealed; the rest are discovered in a scene.
    return { race: "Beastman", soulTree: { chosen: true, revealed: pickedContract, kind: pickedContract ? kind : null, beast: null, stage: 0 }, migrated: true };
  }
  return { race: race, migrated: true };
}

function App() {
  var api = useYumina();
  var v = api.variables || {};

  // Old saves: bring them onto the racial system once. The delay lets a
  // brand-new character finish writing its own state first, and the check
  // is repeated against the live variables before anything is written.
  var apiRef = React.useRef(api);
  apiRef.current = api;

  // Armor is pieces now. An old save's layered slots are mapped onto pieces
  // and any slot holding two worn pieces keeps the better one.
  React.useEffect(function () {
    var inv = v["inventory"];
    if (!Array.isArray(inv) || !inv.length) return;
    if (!needsMigration(inv)) return;
    var mig = migrateInventory(inv);
    apiRef.current.setVariable("inventory", mig.list);
    if (mig.taken.length) {
      apiRef.current.injectContext("[UI] Equipment was reorganised into pieces: one armor piece per slot, and ordinary clothes no longer count as armor. " +
        "Taken off and now carried instead: " + mig.taken.join(", ") + ".");
    }
  }, [v["inventory"]]);
  React.useEffect(function () {
    if (v["character-created"] !== true) return;
    var timer = setTimeout(function () {
      var live = (apiRef.current && apiRef.current.variables) || {};
      if (live["character-created"] !== true) return;
      var r0 = live["racial"];
      var hasRacial = r0 && typeof r0 === "object" && !Array.isArray(r0) && r0.race;
      var raceNow = String(live["race"] || "");
      // Fairy is Elf now. Name only; nothing else about the character changes.
      if (raceNow === "Fairy") { apiRef.current.setVariable("race", "Elf"); raceNow = "Elf"; }
      if (hasRacial || !raceNow || raceNow === "unset") return;
      apiRef.current.setVariable("racial", migrateRacial(raceNow, live["path"]));
    }, 900);
    return function () { clearTimeout(timer); };
  }, [v["character-created"], v["race"], v["racial"] && v["racial"].race]);

  var made = v["character-created"] === true;
  var dead = v["alive"] === false;
  var enc = v["encounter-state"];
  var fighting = !!(enc && enc.active === true);

